declare(strict_types=1);
namespace Buildwars\GWSkillData;
final class SkillLangSpanish extends SkillData{
public const string LANG = Lang::ES;
protected const array ID2DESC = [
0=>['No Skill','Empty skill slot','Empty slot'],
1=>['Sello de curación','Sello. Ganas 82...172 de salud. Tendrás -40 de armadura cuando uses esta habilidad.','Sello. Ganas 82...172 de salud. Tienes -40 de armadura cuando uses esta habilidad.'],
2=>['Sello de resurrección','Sello. Resucitas a un aliado, que regresa a la vida con 100% de salud y 25% de energía. Este sello sólo volverá a estar activado cuando consigas un aumento de moral.','Sello. Resucitas a un aliado (100% de salud y 25% de energía). Este sello sólo volverá a estar activado cuando consigas un aumento de moral.'],
3=>['Sello de captura','Sello. Escoges una habilidad de un jefe muerto cercano de tu profesión. Sustituirá de forma permanente al Sello de captura. Si la habilidad es de élite ganarás 250 PE por cada nivel que seas.','Sello. Escoges una habilidad de un jefe muerto cercano de tu profesión. Sustituirá de forma permanente al Sello de captura. Si la habilidad es de élite ganarás 250 PE por cada nivel que seas.'],
5=>['Bloqueo de poder','Conjuro de élite. Si el enemigo objetivo está lanzando un conjuro o cántico, se cancelará, y esa habilidad y todas las del mismo atributo quedarán anuladas durante 1...12 segundos.','Conjuro de élite. Si el enemigo objetivo está lanzando un conjuro o cántico, se cancelará, y esa habilidad y todas las del mismo atributo quedarán anuladas (1...12 segundos).'],
6=>['Mantra de la tierra','Actitud. Durante 30...90 segundos, siempre que recibas daño de tierra, el daño se reduce en un 26...50% y ganas 2 de energía.','Actitud. (30...90 segundos). Reduce el daño de tierra en un 26...50%. Ganas 2 de energía al recibir daño de tierra.'],
7=>['Mantra de la llama','Actitud. Durante 30...90 segundos, siempre que recibas daño de fuego, el daño se reduce en un 26...50% y ganas 2 de energía.','Actitud. (30...90 segundos). Reduce el daño de fuego en un 26...50%. Ganas 2 de energía al recibir daño de fuego.'],
8=>['Mantra del frío','Actitud. Durante 30...90 segundos, siempre que recibas daño frío, el daño se reduce en un 26...50% y ganas 2 de energía.','Actitud. (30...90 segundos). Reduce el daño frío en un 26...50%. Ganas 2 de energía al recibir daño frío.'],
9=>['Mantra del relámpago','Actitud. Durante 30...90 segundos, siempre que recibas daño de relámpago, el daño se reduce en un 26...50% y ganas 2 de energía.','Actitud. (30...90 segundos). Reduce el daño de relámpago en un 26...50%. Ganas 2 de energía al recibir daño de relámpago.'],
10=>['Destructor de maleficios','Actitud. Durante 5...80 segundos, la próxima vez que seas la víctima de un maleficio, éste no tendrá efecto y el que te ataque recibirá 10...46 de daño.','Actitud. (5...80 segundos). El siguiente conjuro contra ti falla y el atacante recibe 10...46 de daño.'],
11=>['Distorsión','Actitud. Durante 1...5 segundos, tendrás un 75% de posibilidades de bloquear ataques. Siempre que bloquees un ataque de esta forma, pierdes 2 de energía o la Distorsión finalizará.','Actitud. (1...5 segundos). Tienes 75% de posibilidades de bloquear. Coste del bloqueo: pierdes 2 de energía o la Distorsión acaba.'],
13=>['Mantra de recuperación','Actitud de élite. Durante 5...20 segundos, los conjuros que lances se recargarán un 33% más rápido.','Actitud de élite. (5...20 segundos). Tus conjuros se recargan un 33% más rápido.'],
14=>['Mantra de persistencia','Actitud. Durante 5...25 segundos, cualquier maleficio de magia de ilusión que lances durará un 10...40% más.','Actitud. (5...25 segundos). Los maleficios de ilusión que lances duran un 10...40% más.'],
15=>['Mantra de inscripciones','Actitud. Durante 5...25 segundos, los sellos que actives mientras mantengas esta actitud se recargan un 10...40% más rápido.','Actitud. (5...25 segundos.) Los sellos que actives mientras mantengas esta actitud se recargan un 10...40% más rápido.'],
16=>['Mantra de concentración','Actitud. Durante 1...38 segundos, no se te podrá interrumpir la próxima vez que lo intenten.','Actitud. Durante 1...38 segundos, no se te podrá interrumpir la próxima vez que lo intenten.'],
17=>['Mantra de determinación','Actitud. Durante 30...90 segundos no podrás ser interrumpido, pero cada vez que se te hubiera podido interrumpir, perderás 10...4 de energía o el Mantra de determinación finalizará.','Actitud. (30...90 segundos). Impide que te interrumpan. Coste: pierdes 10...4 de energía o el Mantra de determinación acaba.'],
18=>['Mantra de sellos','Actitud. Durante 10...40 segundos, tienes +3 de armadura por cada sello que lleves. Cada vez que utilizas un sello, ganas 5...60 de salud.','Actitud. (10...40 segundos). Tienes +3 de armadura por cada sello. Ganas 5...60 de salud cada vez que utilizas un sello.'],
19=>['Fragilidad','Conjuro con maleficio. Durante 8...20 segundos, el enemigo objetivo y los que le rodeen recibirán 5...20 de daño cada vez que sufran o se recuperen de una nueva condición.','Conjuro con maleficio. También afecta a los enemigos cercanos al objetivo (8...20 segundos). Estos enemigos reciben 5...20 de daño cada vez que ganen o pierdan una condición.'],
21=>['Encantamiento inspirado','Conjuro. Quitas un encantamiento del enemigo objetivo y obtienes 3...15 de energía. Durante 20 segundos, el Encantamiento inspirado será sustituido por el encantamiento que se haya quitado al enemigo.','Conjuro. Elimina un encantamiento del enemigo objetivo. Efecto de la eliminación: ganas 3...15 de energía; este conjuro se sustituye por el encantamiento (20 segundos).'],
22=>['Maleficio inspirado','Conjuro. Se elimina un maleficio del objetivo (un aliado o tú mismo) y obtienes 4...10 de energía. Durante 20 segundos, el Maleficio inspirado será sustituido por el maleficio que hayas quitado.','Conjuro. Elimina un maleficio del aliado objetivo. Efecto de la eliminación: ganas 4...10 de energía; este conjuro se sustituye por el maleficio (20 segundos).'],
23=>['Punzada de poder','Conjuro. Si el enemigo objetivo está lanzando un conjuro o cántico, éste se interrumpirá y el enemigo recibirá 30...120 de daño.','Conjuro. Interrumpe un conjuro o cántico. Efecto de interrupción: hace 30...120 de daño.'],
24=>['Pérdida de poder','Conjuro. Si el enemigo objetivo está lanzando un conjuro o cántico, éste se interrumpirá y el enemigo objetivo perderá 3...17 de energía.','Conjuro. Interrumpe un conjuro o cántico. Efecto de interrupción: pérdida de 3...17 de energía.'],
25=>['Drenaje de poder','Conjuro. Si el enemigo objetivo está lanzando un conjuro o cántico, éste se interrumpirá y ganarás 1...31 de energía.','Conjuro. Interrumpe un conjuro o cántico. Efecto de la interrupción: ganas 1...31 de energía.'],
26=>['Empatía','Conjuro con maleficio. Durante 5...15 segundos, siempre que el enemigo objetivo ataque, éste recibirá 10...55 de daño y hará 1...15 menos de daño.','Conjuro con maleficio. (5...15 segundos). Los ataques del enemigo objetivo hacen 1...15 menos de daño y ese enemigo recibe 10...55 de daño con cada ataque.'],
27=>['Destruir ilusiones','Conjuro. Quitas un maleficio de hipnotizador al enemigo objetivo. Si lo haces, el enemigo recibe 15...75 de daño y todos los adyacentes sufren un 75 % de ese daño.','Conjuro. Quita un maleficio de hipnotizador del enemigo objetivo. Efecto de eliminación: hace 15...75 de daño al objetivo y un 75 % de ese daño a todos los enemigos adyacentes.'],
28=>['Detonación','Conjuro con maleficio. Durante 10 segundos, siempre que el enemigo objetivo lance un conjuro, ese enemigo recibirá 35...140 de daño.','Conjuro con maleficio. (10 segundos). El enemigo recibe 35...140 de daño cada vez que lance un conjuro.'],
29=>['Suspensión','Habilidad. Durante 2...8 segundos, se desactivan todas las habilidades del enemigo al que toques, al igual que todas las tuyas por 5 segundos.','Habilidad de toque. (2...8 segundos). Desactiva habilidades. Tus habilidades quedan desactivadas (5 segundos).'],
30=>['Distracción','Conjuro con maleficio. Durante 6 segundos, la próxima vez que el enemigo objetivo utilice una habilidad tardará 10...56 segundos adicionales en recargarse.','Conjuro con maleficio. (6 segundos). La siguiente habilidad del enemigo objetivo tarda +10...56 segundos en recargarse.'],
31=>['Conjurar fantasma','Conjuro con maleficio. Durante 4...18 segundos, el enemigo objetivo sufre una degeneración de salud de -5.','Conjuro con maleficio. (4...18 segundos). Causa -5 de degeneración de salud.'],
32=>['Ilusión de debilidad','Conjuro con encantamiento. Pierdes 50...240 de salud. La Ilusión de debilidad finalizará si tu salud pasa a estar por debajo del 25% del máximo. Cuando termine esta habilidad, recuperarás 50...240 de salud.','Conjuro con encantamiento. Pierdes 50...240 de salud. Efecto final: ganas 50...240 de salud. Acaba si el daño te hace perder salud por debajo del 25% del máximo.'],
33=>['Armamento irreal','Conjuro con encantamiento de élite. Durante 30 segundos, tus ataques cuerpo a cuerpo no impactan ni fallan. En su lugar, el Armamento irreal hace 20...60 de daño a los objetivos con cada ataque cuerpo a cuerpo. Tienes +5 de armadura por cada habilidad de magia de ilusión equipada.','Conjuro con encantamiento de élite. (30 segundos). Hace 20...60 de daño a enemigos en lugar de otros daños o efectos de los ataques cuerpo a cuerpo. Tienes +5 de armadura por cada habilidad de magia de ilusión equipada. Tus ataques cuerpo a cuerpo no impactan ni fallan.'],
34=>['Semblante cordial','Conjuro con encantamiento. Durante 4...10 segundos, siempre que el objetivo (un aliado o tú mismo) sea golpeado en un ataque cuerpo a cuerpo, todos los enemigos cercanos pierden su adrenalina y 3 de energía.','Conjuro con encantamiento. (4...10 segundos). Todos los enemigos adyacentes pierden su adrenalina y 3 de energía cada vez que el objetivo (un aliado o tú mismo) sea golpeado por un ataque cuerpo a cuerpo.'],
35=>['Ignorancia','Conjuro con maleficio. Durante 8...20 segundos, el enemigo objetivo no puede utilizar sellos.','Conjuro con maleficio. (8...20 segundos). El enemigo objetivo no puede utilizar sellos.'],
36=>['Acertijo arcano','Conjuro con maleficio. Durante 5...15 segundos, el enemigo objetivo y los adyacentes necesitarán el doble de tiempo para lanzar conjuros. Cuando este maleficio acabe, ganas 1...7 de energía.','Conjuro con maleficio. También afecta a los enemigos cercanos al objetivo (5...15 segundos). Dobla el tiempo de lanzamiento. Efecto final: ganas 1...7 de energía.'],
37=>['Ilusión de velocidad','Conjuro con encantamiento. Durante 5...11 segundos no estarás lisiado y podrás moverte un 33% más rápido. Cuando termine la Ilusión de velocidad, estarás lisiado durante 3 segundos.','Conjuro con encantamiento. (5...11 segundos.) Te mueves un 33% más rápido. Efecto inicial: elimina la condición de lisiado. Efecto final: causa lisiadura (3 segundos).'],
38=>['Canalización','Conjuro con encantamiento. Durante 8...56 segundos, siempre que lances un conjuro, ganas 1 de energía por cada enemigo en la zona.','Conjuro con encantamiento. (8...56 segundos). Ganas 1 de energía por cada enemigo que haya en la zona cuando lances un conjuro.'],
39=>['Sobretensión de energía','Conjuro de élite. El enemigo objetivo pierde 1...10 de energía. Por cada punto de energía que pierda, ese enemigo recibe 7 de daño y todos los enemigos cercanos sufren un 75 % de ese daño.','Conjuro de élite. Causa 1...10 de pérdida de energía. Hace 7 de daño al objetivo por cada punto de energía perdido y un 75 % de ese daño a los enemigos cercanos.'],
40=>['Festín de éter','Conjuro. El enemigo objetivo pierde 3 de energía. Te curas 20...65 de salud por cada punto de energía perdido.','Conjuro. Causa 3 de pérdida de energía. Ganas 20...65 de salud por cada punto de energía perdido.'],
41=>['Señor del éter','Conjuro con maleficio. Pierdes toda tu energía. Durante 5...10 segundos, el enemigo objetivo sufre una degeneración de energía de -1...3 y tú obtienes una regeneración de energía de +1...3.','Conjuro con maleficio. Pierdes toda la energía. El enemigo objetivo tiene -1...3 de degeneración de energía y tú +1...3 de regeneración (5...10 segundos).'],
42=>['Quemadura de energía','Conjuro. El enemigo objetivo pierde 1...10 de energía y recibe 9 de daño por cada punto de energía que pierda.','Conjuro. Causa 1...10 de pérdida de energía. Hace 9 de daño por cada punto de energía perdido.'],
43=>['Torpeza','Conjuro con maleficio. Durante 4 segundos, el enemigo objetivo y los adyacentes tienen el maleficio Torpeza. La próxima vez que alguno de ellos ataque, éste se interrumpe y el enemigo recibe 10...80 de daño.','Conjuro con maleficio. (4 segundos). También afecta a los enemigos adyacentes. Interrumpe el siguiente ataque. Efecto de la interrupción: 10...80 de daño.'],
44=>['Dolor fantasma','Conjuro con maleficio. Durante 10 segundos, el enemigo objetivo sufre una degeneración de -1...4 de salud. Cuando finalice el Dolor fantasma, ese enemigo sufrirá una herida grave, lo que reducirá su salud máxima en un 20% durante 5...20 segundos.','Conjuro con maleficio. (10 segundos). Causa -1...4 de degeneración de salud. Efecto final: causa una herida grave (5...20 segundos).'],
45=>['Carga etérea','Conjuro con maleficio. Durante 6...12 segundos, el enemigo objetivo se moverá un 50% más lento. Cuando la Carga etérea finalice, ganarás 10...18 de energía.','Conjuro con maleficio. (6...12 segundos). El enemigo objetivo se mueve un 50% más lento. Efecto final: ganas 10...18 de energía.'],
46=>['Culpa','Conjuro con maleficio. Durante 6 segundos, la próxima vez que el enemigo objetivo lance un conjuro sobre un enemigo, el conjuro fallará y le robarás un máximo de 5...14 de energía.','Conjuro con maleficio. (6 segundos). El siguiente conjuro del enemigo objetivo falla y robas 5...14 de energía. No tiene efecto a menos que el conjuro del enemigo objetivo sea contra uno de tus aliados.'],
47=>['Ineptitud','Conjuro con maleficio de élite. Durante 4 segundos, la próxima vez que el enemigo objetivo y cualquier enemigo adyacente a él ataque, recibirán 30...135 de daño y se quedarán cegados durante 10 segundos.','Conjuro con maleficio de élite. (4 segundos). También lanza un maleficio a los enemigos adyacentes al objetivo. Hace 30...135 de daño. Causa ceguera (10 segundos). Sin efecto salvo en los ataques a los enemigos con maleficio.'],
48=>['Espíritu del fracaso','Conjuro con maleficio. Durante 30 segundos, el enemigo objetivo tiene un 25% de posibilidades de fallar en sus ataques. Ganas 1...3 de energía por cada fallo.','Conjuro con maleficio. (30 segundos). El enemigo objetivo tiene un 25% de probabilidades de fallar. Ganas 1...3 de energía si este enemigo falla.'],
49=>['Sacudida mental','Conjuro con maleficio. Durante 5...40 segundos, cuando este enemigo es el objetivo de cualquiera de tus habilidades de Hipnotizador que no sean un maleficio, pierde 1 de energía y recibe 5...25 de daño por cada punto de energía perdido. Si el enemigo objetivo pierde toda su energía, la Sacudida mental acaba y dicho enemigo recibe 15...100 de daño.','Conjuro con maleficio. (5...40 segundos.) Causa 1 de pérdida de energía cada vez que el enemigo es el objetivo de tus habilidades que no sean maleficios de Hipnotizador. Causa 5...25 de daño por cada punto de energía perdido. Si el enemigo objetivo pierde toda su energía, recibe 15...100 de daño y la Sacudida mental acaba.'],
50=>['Preocupación del gandul','Conjuro con maleficio. Después de 3 segundos, el enemigo objetivo recibe 20...100 de daño y todos los adyacentes sufren un 75 % de ese daño. Si ese enemigo utiliza una habilidad con éxito, la Preocupación del gandul finalizará prematuramente y no hará ningún daño.','Conjuro con maleficio. (3 segundos). Efecto final: hace 20...100 de daño al enemigo objetivo y un 75 % de ese daño a los enemigos adyacentes. No tiene ningún efecto y termina antes de lo previsto si el enemigo objetivo utiliza una habilidad.'],
51=>['Vergüenza','Conjuro con maleficio. Durante 6 segundos, la próxima vez que el enemigo objetivo lance un conjuro sobre un aliado, el conjuro fallará y le robarás un máximo de 5...14 de energía.','Conjuro con maleficio. (6 segundos). El siguiente conjuro del enemigo objetivo falla y robas 5...14 de energía. No tiene efecto a menos que el conjuro de este enemigo apunte a uno de sus aliados.'],
52=>['Pánico','Conjuro con maleficio de élite. Durante 1...10 segundos, el enemigo objetivo y los enemigos cercanos sufren el maleficio del Pánico. Cuando un enemigo con el maleficio del Pánico utiliza una habilidad con éxito, se interrumpe la acción de todos los enemigos cercanos a él.','Conjuro con maleficio de élite. También se aplica el maleficio a los enemigos cercanos al objetivo (1...10 segundos). Interrumpe la acción de los enemigos cercanos cuando un enemigo con maleficio activa una habilidad con éxito.'],
53=>['Migraña','Conjuro con maleficio de élite. Durante 5...20 segundos, el enemigo objetivo sufre una degeneración de salud de -1...8 y tardará un 100% más en activar sus habilidades.','Conjuro con maleficio de élite. (5...20 segundos). Causa -1...8 de degeneración de salud y dobla el tiempo de activación de habilidades.'],
54=>['Angustia agobiante','Conjuro con maleficio de élite. Durante 5...20 segundos, el enemigo objetivo se mueve y ataca un 50% más lento y sufre una degeneración de salud de -1...8.','Conjuro con maleficio de élite. (5...20 segundos). El enemigo objetivo ataca un 50% más lento y tiene -1...8 de degeneración de salud.'],
55=>['Sueños febriles','Conjuro con maleficio de élite. Durante 10...25 segundos, siempre que el objetivo enemigo sufra una nueva condición, todos los enemigos de la zona también sufrirán la misma. Si el enemigo objetivo tiene dos o más condiciones, queda aturdido durante 1...3 segundos.','Conjuro con maleficio de élite. (10...25 segundos). Los enemigos de la zona también padecen las nuevas condiciones que el enemigo objetivo adquiera. Causa aturdimiento (1...3 segundos) si ese enemigo tiene dos o más condiciones.'],
56=>['Imágenes relajantes','Conjuro con maleficio. Durante 8...20 segundos, el enemigo objetivo y los adyacentes no pueden ganar adrenalina.','Conjuro con maleficio. También afecta a los enemigos cercanos al objetivo (8...20 segundos). Dichos enemigos no pueden ganar adrenalina.'],
57=>['Grito de frustración','Conjuro. Si el enemigo objetivo está utilizando una habilidad, ese enemigo y todos los de la zona serán interrumpidos. El enemigo recibe 15...75 de daño y todos los enemigos cercanos sufren un 75 % de ese daño.','Conjuro. Si el enemigo objetivo está utilizando una habilidad, ese enemigo y todos los de la zona serán interrumpidos. El enemigo recibe 15...75 de daño y todos los enemigos cercanos sufren un 75 % de ese daño.'],
58=>['Sello de la medianoche','Sello de élite. Tú y el enemigo al que toques pasareis a estar ciegos durante 15 segundos.','Sello de élite de toque. (15 segundos). Causa ceguera. Sufres ceguera (15 segundos).'],
59=>['Sello del cansancio','Sello. El enemigo objetivo y los cercanos a él pierden 3...8 de energía y quedan debilitados durante 1...12 segundos.','Sello. También alcanza a los enemigos cercanos a tu objetivo. Causa 3...8 de pérdida de energía y debilita (1...12 segundos).'],
61=>['Sello de la sanguijuela','Sello. Interrumpe la acción del enemigo objetivo. Si la acción era un conjuro, ganarás 3...15 de energía.','Sello. Interrumpe una acción. Efecto de la interrupción: ganas 3...15 de energía si la acción era un conjuro.'],
62=>['Sello de la humildad','Sello. La habilidad de élite del enemigo objetivo se desactiva durante 1...16 segundos. Tus habilidades que no sean de Hipnotizador se desactivan durante 4 segundos.','Sello. Desactiva la habilidad de élite (1...16 segundos). Desactiva tus habilidades que no sean de Hipnotizador (4 segundos).'],
63=>['Sello de la piedra angular','Sello de élite. Todos tus otros sellos excepto el Sello de la piedra angular se recargarán. Durante 20 segundos, las próximas 0...6 veces que utilices un sello que alcance a un enemigo, todos los enemigos adyacentes a tu objetivo reciben 15...60 de daño y se interrumpe su acción.','Sello de élite. (20 segundos). Tus próximos 0...6 sellos interrumpen la acción de los enemigos adyacentes a tu objetivo y les hacen 15...60 de daño. Efecto inicial: recarga todos tus demás sellos.'],
65=>['Imitación arcana','Conjuro. Durante 20 segundos, dispondrás de la habilidad de élite del aliado objetivo (siempre que no sea una forma).','Conjuro. Esta habilidad se convierte en la habilidad de élite del aliado objetivo (20 segundos). No se puede usar con uno mismo. No tiene efecto si la habilidad de élite es una transformación.'],
66=>['Grilletes espirituales','Conjuro con maleficio. Durante 5...20 segundos, el enemigo objetivo perderá 5 de energía siempre que ataque.','Conjuro con maleficio. (5...20 segundos). El enemigo objetivo pierde 5 de energía cada vez que ataque.'],
67=>['Destruir maleficio','Conjuro. Se elimina un maleficio del objetivo (un aliado o tú mismo). Si se quita un maleficio, los enemigos cercanos a ese aliado reciben 30...120 de daño.','Conjuro. Elimina un maleficio del objetivo (un aliado o tú mismo). Efecto de la eliminación: 30...120 de daño a los enemigos cercanos a este aliado.'],
68=>['Drenar encantamiento','Conjuro. Quitas un encantamiento del enemigo objetivo. Si se quita un encantamiento, ganarás 8...17 de energía y 40...120 de salud.','Conjuro. Elimina un encantamiento del enemigo objetivo. Efecto de la eliminación: ganas 8...17 de energía y 40...120 de salud.'],
69=>['Destruir encantamiento','Conjuro. Quita un encantamiento del enemigo objetivo. Si se quita un encantamiento, ese enemigo recibirá 14...100 de daño.','Conjuro. Elimina un encantamiento del enemigo objetivo. Efecto de la eliminación: 14...100 de daño.'],
72=>['Resistencia elemental','Actitud. Durante 30...90 segundos, ganarás +40 de armadura contra daño elemental, pero perderás 24...12 contra daño físico.','Actitud. (30...90 segundos). Ganas +40 de armadura contra daño de los elementos. Tienes -24...12 de armadura contra daño físico.'],
73=>['Resistencia física','Actitud. Durante 30...90 segundos, ganarás +40 de armadura contra daño físico, pero perderás 24...12 contra daño elemental.','Actitud. (30...90 segundos). Ganas +40 de armadura contra daño físico. Tienes -24...12 de armadura contra daño de los elementos.'],
74=>['Eco','Conjuro con encantamiento de élite. Durante 30 segundos, el Eco se reemplaza por la siguiente habilidad que utilices. El Eco funciona como esta habilidad durante 30 segundos.','Conjuro con encantamiento de élite. (30 segundos). El eco se transforma en la siguiente habilidad que uses (30 segundos).'],
75=>['Eco arcano','Conjuro con encantamiento. Si lanzas un conjuro en los siguientes 20 segundos, el Eco arcano es reemplazado por ese conjuro durante 20 segundos. Finalizará antes de tiempo si utilizas una habilidad que no sea un conjuro.','Conjuro con encantamiento. (20 segundos). El eco arcano se transforma en el siguiente conjuro que uses (20 segundos).Este encantamiento termina si usas una habilidad que no sea conjuro.'],
76=>['Carga imaginaria','Conjuro con maleficio. Durante 8...20 segundos, el enemigo objetivo se moverá un 50% más lento.','Conjuro con maleficio. (8...20 segundos). El enemigo objetivo se mueve un 50% más despacio.'],
77=>['Tormenta del caos','Conjuro. Creas una Tormenta del caos en la ubicación del enemigo objetivo que dura 10 segundos. Cada segundos, los enemigos adyacentes a su ubicación recibirán 5...25 de daño y perderán 0...2 de energía.','Conjuro. Hace 5...25 de daño y causa 0...2 de pérdida de energía por segundo (10 segundos). Alcanza a los enemigos adyacentes a la ubicación inicial del objetivo.'],
78=>['Epidemia','Conjuro. Propagas a todos los enemigos adyacentes a tu objetivo todas las condiciones negativas que éste tenga con el tiempo que les quede para que terminen.','Conjuro. Las condiciones del enemigo objetivo se transfieren a los adyacentes.'],
79=>['Drenaje de energía','Conjuro de élite. El enemigo objetivo pierde 2...9 de energía. Tú ganas 3 puntos de energía por cada uno perdido.','Conjuro de élite. Causa 2...9 de pérdida de energía. Ganas 3 de energía por cada punto de energía perdido.'],
80=>['Grifo de energía','Conjuro. El enemigo objetivo pierde 4...7 de energía y tú ganas 2 puntos de energía por cada uno perdido.','Conjuro. Causa 4...7 de pérdida de energía. Ganas 2 de energía por cada punto de energía perdido.'],
81=>['Robo arcano','Conjuro. Durante 5...35 segundos, un conjuro aleatorio del enemigo objetivo se desactiva y el Robo arcano es sustituido por ese conjuro.','Conjuro. (5...35 segundos). Desactiva un conjuro al azar. Esta habilidad se convierte en ese conjuro.'],
82=>['Mantra del recuerdo','Conjuro con encantamiento de élite. Durante 20 segundos, no obtendrás beneficio de él. Ganarás 10...25 de energía cuando el Mantra del recuerdo finalice.','Conjuro con encantamiento de élite. (20 segundos). Efecto final: ganas 10...25 de energía.'],
83=>['Animar horror de hueso','Conjuro. Explotas al cadáver más cercano para crear un Horror de Hueso de nivel 1...17.','Conjuro. Creas un horror de hueso de nivel 1...17. Explotas un cadáver.'],
84=>['Animar demonio de hueso','Conjuro. Explotas al cadáver más cercano para crear un Demonio de Hueso de nivel 1...17, que podrá atacar a distancia.','Conjuro. Creas un demonio de hueso de nivel 1...17 que puede atacar a distancia. Explotas un cadáver.'],
85=>['Animar siervos de hueso','Conjuro. Explotas al cadáver más cercano para crear dos Siervos de Hueso de nivel 0...12.','Conjuro. Creas 2 siervos de hueso de nivel 0...12. Explotas un cadáver.'],
86=>['Balanza de Grenth','Conjuro de élite. Si el enemigo objetivo tiene más salud, ganarás la mitad de la diferencia (o hasta que se llene del todo tu barra de salud) y éste la perderá. Si el enemigo tiene menos salud que tú, perderás la mitad de la diferencia, y él ganará la misma cantidad.','Conjuro de élite. Ganas salud igual a la mitad de la diferencia entre la tuya y la del objetivo, que perderá esa cantidad. Si el enemigo objetivo tiene menos salud, pierdes la mitad de la diferencia y él ganará la misma cantidad.'],
87=>['Mirada de Verata','Conjuro. Si el muerto viviente enemigo objetivo tiene un maestro, se romperá el vínculo con éste, lo que lo convertirá en hostil para las demás criaturas. Si no tiene maestro, pasarás a serlo tú y lo curarás por valor de 60...80. (50 % de posibilidades de fallo con magia de muerte 4 o inferior).','Conjuro. Hace que el siervo objetivo no tenga maestro. Si ya estaba sin él, pasarás a serlo tú y lo curarás por valor de 60...80. 50 % de probabilidades de fallo con magia de muerte inferior a 5.'],
88=>['Aura de Verata','Conjuro con encantamiento. Todos los muertos vivientes hostiles del área pasarán a estar vinculados contigo. El Aura de Verata acaba a los 120...300 segundos. Cuando finalice, perderás el vínculo que tengas con los muertos vivientes. (50% de posibilidades de fallo con Magia de muerte 4 o inferior).','Conjuro con encantamiento. (120...300 segundos). Te conviertes en el maestro de todos los siervos hostiles de la zona. Efecto final: tus siervos se quedan sin maestro. 50% de probabilidades de fallar con magia de muerte inferior a 5.'],
89=>['Escalofrío de muerte','Conjuro. El enemigo objetivo recibe 5...50 de daño frío. Si la salud de ese enemigo está por encima del 50%, le haces 5...50 de daño de sombra adicional.','Conjuro. Hace +5...50 de daño frío. Hace +5...50 de daño extra si el enemigo objetivo está por encima del 50% de salud.'],
90=>['Sacrificio de Verata','Conjuro. Durante 5...10 segundos, tus muertos vivientes aliados recuperan +10 de salud y todas las condiciones desaparecen de ellos y pasan a ti. Si este conjuro tiene éxito y controlas 3 siervos o menos, se recargará de forma inmediata.','Conjuro. (5...10 segundos). 10 siervos aliados ganan +10 de regeneración de salud. Se recarga al instante si controlas a 3 o menos siervos. Transfieres todas las condiciones de esos siervos a ti.'],
91=>['Pozo de poder','Conjuro de pozo de élite. Explotas el cadáver más cercano o sacrificas un 66 % de salud para crear un Pozo de poder en esa ubicación. Durante 10...30 segundos, los aliados dentro de la zona del Pozo de poder regenerarán +1...6 de salud y +2 de energía.','Conjuro de pozo de élite. (10...30 segundos). Los aliados en este pozo ganan +1...6 de regeneración de salud y +2 de regeneración de energía. Explotas un cadáver reciente o sacrificas un 66 % de salud.'],
92=>['Pozo de sangre','Conjuro de pozo. Explotas el cadáver más cercano o sacrificas un 66 % de salud para crear un Pozo de sangre en esa ubicación. Durante 8...20 segundos, los aliados que haya en el área ganarán +1...6 de regeneración de salud.','Conjuro de pozo. (8...20 segundos). Los aliados en este pozo ganan +1...6 de regeneración de salud. Explotas un cadáver reciente o sacrificas un 66 % de salud.'],
93=>['Pozo de sufrimiento','Conjuro de pozo. Explotas el cadáver más cercano o sacrificas un 66 % de salud para crear un Pozo de sufrimiento en esa ubicación. Durante 10...30 segundos, los enemigos que se encuentren en esa zona sufren -1...6 de degeneración de salud.','Conjuro de pozo. (10...30 segundos). Los enemigos en este pozo sufren -1...6 de degeneración de salud. Explotas un cadáver reciente o sacrificas un 66 % de salud.'],
94=>['Pozo del profano','Conjuro de pozo. Explotas el cadáver más cercano o sacrificas un 66 % de salud para crear un Pozo del profano en esa ubicación. Durante 8...20 segundos, los enemigos del área se librarán de todos los encantamientos y no podrán ser objetivo de otros encantamientos. (50 % de probabilidad de fallar con magia de muerte 4 o inferior).','Conjuro de pozo. (8...20 segundos). Los enemigos en este pozo se liberan de todos los encantamientos y no pueden ser objetivo de otros encantamientos. Explotas un cadáver reciente o sacrificas un 66 % de salud. 50 % de probabilidades de fallar a no ser que se utilice magia de muerte de nivel 5 o superior.'],
95=>['Explosión de putrefacción','Conjuro. El cadáver más cercano al objetivo explota, enviando una onda expansiva que hará 24...120 de daño a todos los enemigos cercanos.','Conjuro. Explotas un cadáver, que hace 24...120 de daño a los enemigos cercanos Explotas un cadáver.'],
96=>['Festín de almas','Conjuro. Explotas al cadáver más cercano para ganar 50...280 de salud.','Conjuro. Ganas 50...280 de salud. Explotas un cadáver.'],
97=>['Travesía necrótica','Conjuro. Explotas un cadáver cualquiera o sacrificas 30...20 % de salud para teletransportarte a la ubicación de tu enemigo. Caes enfermo[f:"enferma"] durante 6 segundos y todos los enemigos cercanos quedan envenenados durante 5...20 segundos.','Conjuro. Explotas un cadáver cualquiera o sacrificas 30...20 % de salud para teletransportarte a la ubicación de tu enemigo. Caes enfermo[f:"enferma"] durante 6 segundos y todos los enemigos cercanos quedan envenenados durante 5...20 segundos.'],
98=>['Consumir cadáver','Conjuro. Explotas un cadáver cualquiera para teletransportarte a esa ubicación y conseguir 25...100 de salud y 5...20 de energía.','Conjuro. Te teletransportas hasta la ubicación de un cadáver. Ganas 25...100 de salud y 5...20 de energía. Explotas un cadáver.'],
99=>['Vínculo parasitario','Conjuro con maleficio. Durante 20 segundos, el enemigo objetivo sufre una degeneración de salud de -1. Te curarás 30...120 de salud cuando finalice el Vínculo parasitario.','Conjuro con maleficio. (20 segundos.) Causa -1 de degeneración de salud. Efecto final: ganas 30...120 de salud.'],
100=>['Púas del alma','Conjuro con maleficio. Durante 30 segundos, el enemigo objetivo recibe 15...30 de daño cuando se lance un encantamiento o maleficio sobre él.','Conjuro con maleficio. (30 segundos). Hace 15...30 de daño cuando se lance un encantamiento o maleficio sobre el enemigo objetivo.'],
101=>['Púas','Conjuro con maleficio. Durante 30 segundos, el enemigo objetivo recibe 4...16 de daño cuando reciba daño físico.','Conjuro con maleficio. (30 segundos). El enemigo recibe 4...16 de daño cada vez que reciba daño físico.'],
102=>['Golpe de las sombras','Conjuro. El enemigo objetivo recibe 12...48 de daño de sombra. Si la salud de ese enemigo está por encima del 50%, le robarás 12...48 de salud.','Conjuro. Hace 12...48 de daño. Roba 12...48 de salud si la del enemigo objetivo está por encima del 50%.'],
103=>['Precio del fracaso','Conjuro con maleficio. Durante 30 segundos, el enemigo objetivo tendrá un 25% de posibilidades de fallar sus ataques y recibirá 1...46 de daño siempre que falle.','Conjuro con maleficio. (30 segundos). 25% de probabilidades de fallar. El enemigo objetivo recibe 1...46 de daño cuando falle.'],
104=>['Nova de muerte','Conjuro con encantamiento. Durante 30 segundos, si el objetivo (un aliado o tú mismo) muere, todos los enemigos cercanos recibirán 26...100 de daño y estarán envenenados durante 15 segundos.','Conjuro con encantamiento. (30 segundos). Hace 26...100 de daño y causa envenenamiento (15 segundos) a los enemigos adyacentes si el objetivo muere.'],
105=>['Enjambre mortal','Conjuro. El Enjambre mortal sobrevolará lentamente un máximo de tres objetivos en la zona y les hará 30...90 de daño de frío.','Conjuro. El enjambre mortal vuela lentamente y hace 30...90 de daño frío. Alcanza a 2 enemigos más en la zona.'],
106=>['Carne pútrida','Conjuro. El enemigo de carne objetivo queda enfermo durante 10...25 segundos y perderá salud lentamente.','Conjuro. Causa enfermedad (10...25 segundos).'],
107=>['Virulencia','Conjuro de élite. Si el enemigo objetivo ya tenía una condición, ese enemigo pasará a estar enfermo, envenenado y debilitado durante 3...15 segundos.','Conjuro de élite. Causa enfermedad, envenenamiento y debilitamiento (3...15 segundos). No tiene efecto a menos que el enemigo objetivo ya sufra una condición.'],
108=>['Sufrimiento','Conjuro con maleficio. Durante 6...30 segundos, el enemigo objetivo y todos los enemigos cercanos sufrirán -0...3 de degeneración de salud.','Conjuro con maleficio. También afecta a los enemigos cercanos al objetivo (6...30 segundos). Éstos sufren -0...3 de degeneración de salud.'],
109=>['Grifo de vida','Conjuro con maleficio. Durante 12...24 segundos, el enemigo objetivo sufrirá una degeneración de salud de - 1...3, y tú obtendrás una regeneración de salud de +1...3.','Conjuro con maleficio. (12...24 segundos). El enemigo objetivo tiene -1...3 de degeneración de salud. Ganas +1...3 de regeneración de salud.'],
110=>['Festín impío','Conjuro. Robas 10...65 de salud de hasta 1...4 enemigos en la zona.','Conjuro. Robas 10...65 de salud de 1...4 enemigos de la zona.'],
111=>['Despertar la sangre','Conjuro con encantamiento. Durante 20...44 segundos, ganas +2 de magia de sangre y +2 de maldiciones, pero siempre que sacrifiques salud, sacrificarás un 50% más de lo normal.','Conjuro con encantamiento. (20...44 segundos). Tienes +2 de magia de sangre y de maldiciones. Sacrificas un 50% más de salud de lo normal.'],
112=>['Profanación de encantamientos','Conjuro. El enemigo objetivo y todos los enemigos cercanos reciben 6...60 de daño de sombra y 4...20 de daño de sombra por cada encantamiento que tengan.','Conjuro. Hace 6...60 de daño al enemigo objetivo y los cercanos. Hace 4...20 de daño extra por encantamiento que tengan.'],
113=>['Carne infectada','Conjuro con encantamiento de élite. Durante 20...44 segundos, los aliados de la zona son inmunes a enfermedades, y todo el que le golpee en combate cuerpo a cuerpo pasará a estar enfermo durante 3...15 segundos.','Conjuro con encantamiento de élite. (20...44 segundos). Los enemigos que golpeen cuerpo a cuerpo a aliados quedarán enfermos (3...15 segundos). Este aliado es inmune a la enfermedad.'],
114=>['Aura del liche','Conjuro con encantamiento de élite. Explotas a todos los cadáveres al alcance del oído para animar a un horror de hueso de nivel 1...17 además de uno por cada cadáver explotado de esta manera. Durante 5...45 segundos, tu atributo magia de muerte aumenta +1.','Conjuro con encantamiento de élite. Explotas a todos los cadáveres al alcance del oído. Animas un horror de hueso de nivel 1...17, además de uno por cada cadáver explotado. Tienes +1 de magia de muerte (5...45 segundos).'],
115=>['Renovación de la sangre','Conjuro con encantamiento. Durante 7 segundos, ganas +3...6 de regeneración de salud. Cuando la Renovación de la sangre acabe, ganas 40...190 de salud.','Conjuro con encantamiento. (7 segundos). Tienes +3...6 de regeneración de salud. Efecto final: te curas 40...190 de salud.'],
116=>['Aura oscura','Conjuro con encantamiento. Durante 30 segundos, siempre que el objetivo (un aliado o tú mismo) sacrifique salud, el Aura oscura hará 5...50 de daño a los enemigos adyacentes y perderás 5...20 de salud.','Conjuro con encantamiento. (30 segundos). Hace 5...50 de daño a los enemigos adyacentes siempre que el objetivo (un aliado o tú mismo) sacrifique salud. Coste del daño: pierdes 5...20 de salud.'],
117=>['Debilitar','Conjuro. El objetivo estará debilitado durante 10...30 segundos.','Conjuro. Causa debilitamiento (10...30 segundos).'],
118=>['Sangre debilitante','Conjuro. El enemigo objetivo y los cercanos a él quedarán debilitados durante 5...20 segundos.','Conjuro. Causa debilitamiento (5...20 segundos) al enemigo objetivo y los cercanos.'],
119=>['La sangre es poder','Conjuro con encantamiento de élite. Durante 10 segundos, el aliado objetivo ganará +3...6 de regeneración de energía.','Conjuro con encantamiento de élite. (10 segundos). +3...6 de regeneración de energía. No te puedes apuntar a ti mismo.'],
120=>['Sangre del maestro','Conjuro. Todos tus muertos vivientes recuperan 30...116 de salud. Sacrificarás además un 2% de tu salud máxima por cada siervo que se cure así.','Conjuro. Cura a tus siervos muertos vivientes 30...116 de salud. Coste de la curación: +2% de sacrificio de salud por siervo curado.'],
121=>['Espíritu rencoroso','Conjuro con maleficio de élite. Durante 10...25 segundos, siempre que el enemigo objetivo ataque o utilice una habilidad, el Espíritu rencoroso hará 15...45 de daño de sombra a ese enemigo y a todos los enemigos adyacentes a él.','Conjuro con maleficio de élite. (10...25 segundos). Hace 15...45 de daño al enemigo objetivo y los adyacentes cuando ataque o use una habilidad.'],
122=>['Intervención maligna','Conjuro con maleficio. Durante 5...20 segundos, el enemigo objetivo se beneficia un 20% menos de las curaciones. Si éste muere mientras tenga la Intervención maligna encima, se creará a un Horror de hueso sin maestro de nivel 1...17.','Conjuro con maleficio. (5...20 segundos). El enemigo objetivo se beneficia un 20% menos de las curaciones. Si muere mientras tenga este maleficio, se invoca un horror de hueso sin maestro de nivel 1...17.'],
123=>['Parásito insidioso','Conjuro con maleficio. Durante 5...15 segundos, cada vez que el enemigo objetivo golpee al atacar, le robarás hasta 15...45 de salud.','Conjuro con maleficio. (5...15 segundos). Roba 15...45 de salud cada vez que el enemigo objetivo ataque.'],
124=>['Escalofríos','Conjuro con maleficio. Durante 10...40 segundos, cada vez que el enemigo objetivo reciba daño de frío al usar una habilidad, ese enemigo será interrumpido y tú perderás 8...3 de energía o finalizarán los Escalofríos.','Conjuro con maleficio. (10...40 segundos). Interrumpe las habilidades del enemigo objetivo si recibe daño frío. Coste de la interrupción: pierdes 8...3 de energía o los Escalofríos acaban.'],
125=>['Marchitar','Conjuro con maleficio de élite. Durante 5...35 segundos, el enemigo objetivo sufre una degeneración de -2...4 de salud y de -1 de energía. Si la energía del enemigo objetivo llega a 0, Marchitar finalizará y el enemigo recibirá 15...75 de daño.','Conjuro con maleficio de élite. (5...35 segundos). Causa -2...4 de degeneración de salud y -1 de degeneración de energía. Hace 15...75 de daño si la energía del enemigo objetivo cae a 0. Acaba si la energía del enemigo objetivo cae a 0.'],
126=>['Transferencia de vida','Conjuro con maleficio de élite. Durante 6...12 segundos, el enemigo objetivo y los adyacentes sufrirán una degeneración de salud de -3...8, que ganarás como regeneración de salud.','Conjuro con maleficio de élite. También afecta a los enemigos adyacentes al objetivo (6...12 segundos). Causa -3...8 de degeneración de salud. Tienes +3...8 de regeneración de salud.'],
127=>['Marca de subversión','Conjuro con maleficio. Durante 6 segundos, la próxima vez que el enemigo objetivo lance un conjuro sobre un aliado suyo, éste fallará y le robarás hasta 10...92 de salud.','Conjuro con maleficio. (6 segundos). El siguiente conjuro del enemigo objetivo falla y robas 10...92 de salud. No tiene efecto a menos que el conjuro del enemigo objetivo apunte a uno de tus aliados.'],
128=>['Sanguijuela del alma','Conjuro con maleficio de élite. Durante 10 segundos, siempre que el enemigo objetivo lance un conjuro, le robarás hasta 16...80 de salud.','Conjuro con maleficio de élite. (10 segundos). Roba 16...80 de salud cuando el enemigo objetivo lance un conjuro.'],
129=>['Profanar la carne','Conjuro con maleficio. Durante 5...35 segundos, el enemigo objetivo se beneficiará sólo dos tercios de las curaciones.','Conjuro con maleficio. (5...35 segundos). Reduce la curación sobre el enemigo objetivo un 33%. Sólo están afectadas las habilidades con la palabra "curar".'],
130=>['Carne demoníaca','Conjuro con encantamiento. Durante 30...60 segundos, siempre que uses una habilidad sobre un enemigo, haces 5...20 de daño de sombra a todos los demás enemigos que tengas adyacentes.','Conjuro con encantamiento. (30...60 segundos). Siempre que uses una habilidad sobre un enemigo, haces 5...20 de daño de sombra a todos los demás enemigos que tengas adyacentes.'],
131=>['Sello de espinas','Sello. Causas hemorragia durante 3...15 segundos al enemigo objetivo y a todos los adyacentes.','Sello. El objetivo y los enemigos adyacentes sufren hemorragia durante (3...15 segundos).'],
132=>['Sello pestilente','Sello de élite. Transfiere todas tus condiciones negativas con un 100...200% de la duración restante al enemigo objetivo. (50% de posibilidades de fallar con Maldiciones de nivel 4 o inferior.)','Sello de élite. Transfiere todas tus condiciones con un 100...200% de la duración restante al enemigo objetivo. 50% de probabilidades de fallar a no ser que se utilicen Maldiciones de nivel 5 o superior.'],
133=>['Pacto oscuro','Conjuro. Haces 20...60 de daño de sombra al enemigo objetivo.','Conjuro. Hace 20...60 de daño.'],
134=>['Orden del dolor','Conjuro con encantamiento. Durante 5 segundos, siempre que un miembro del grupo golpee a un enemigo con daño físico, ese miembro causará +3...16 de daño adicional.','Conjuro con encantamiento. Encanta a todos los miembros del grupo (5 segundos). 3...16 de daño extra cada vez que alguno haga daño físico.'],
135=>['Miedo visceral','Conjuro con maleficio. Durante los próximos 4...18 segundos, la velocidad de ataque del enemigo objetivo se reduce en un 50% y ese enemigo sufrirá una degeneración de salud de -1...3.','Conjuro con maleficio. (4...18 segundos). El enemigo objetivo ataca un 50% más lento y tiene -1...3 de degeneración de salud.'],
136=>['Sombra del miedo','Conjuro con maleficio. El enemigo objetivo y todos los enemigos adyacentes atacarán un 50% más lento de lo normal durante los próximos 5...30 segundos.','Conjuro con maleficio. También afecta a los enemigos adyacentes al objetivo (5...30 segundos). Atacan un 50% más despacio.'],
137=>['Rigor mortis','Conjuro con maleficio. Durante 8...20 segundos, el enemigo objetivo no puede bloquear ataques.','Conjuro con maleficio. (8...20 segundos). El enemigo objetivo no puede bloquear ataques.'],
138=>['Vínculo oscuro','Conjuro con encantamiento. Durante los próximos 30...60 segundos, siempre que recibas daños, el 75% de ese daño lo sufrirá tu siervo más cercano.','Conjuro con encantamiento. (30...60 segundos). Transfieres el 75% de los daños que recibas a tu siervo más cercano.'],
139=>['Infundir condición','Conjuro con encantamiento. Durante los próximos 15...60 segundos, cuando recibas una condición la sufrirá tu siervo más cercano.','Conjuro con encantamiento. (15...60 segundos). Cuando recibas una condición, la transfieres a tu siervo más cercano.'],
140=>['Malestar','Conjuro con maleficio. Durante 5...35 segundos, el enemigo objetivo sufre una degeneración de -1 de energía y tú una degeneración de -1 de salud. Si la energía del enemigo objetivo llega a 0, el Malestar finalizará y el enemigo recibirá 5...50 de daño.','Conjuro con maleficio. (5...35 segundos). Causa -1 de degeneración de energía. Hace 5...50 de daño si la energía del enemigo objetivo cae a 0. Tienes -1 de degeneración de salud. Acaba si la energía del enemigo objetivo cae a 0.'],
141=>['Desgarrar encantamientos','Conjuro. Eliminas 5...9 encantamientos del enemigo objetivo. Por cada encantamiento de Monje eliminado, perderás 55...25 de salud.','Conjuro. Elimina 5...9 encantamientos del enemigo objetivo. Coste de la eliminación: pierdes 55...25 de salud por cada encantamiento de Monje eliminado.'],
142=>['Maldición persistente','Conjuro con maleficio de élite. Durante 6...30 segundos, el enemigo objetivo y todos los enemigos cercanos sufrirán -1...4 de degeneración de salud y se beneficiarán un 25% menos de las curaciones.','Conjuro con maleficio de élite. (6...30 segundos). El enemigo objetivo y los cercanos sufren -1...4 de degeneración de salud y se benefician un 25% menos de las curaciones.'],
143=>['Quitar encantamiento','Conjuro. Elimina 0...2 encantamientos del enemigo objetivo. Si se quita un encantamiento, robas 5...65 de salud.','Conjuro. Elimina 0...2 encantamientos del enemigo objetivo. Efecto de la eliminación: robas 5...65 de salud.'],
144=>['Sabañones','Conjuro. Pasarás a estar envenenado durante 10 segundos. Los enemigos dentro de la zona de tu objetivo recibirán 10...44 de daño de frío y perderán 1...2 encantamientos.','Conjuro. Hace 10...44 de daño frío a todos los enemigos de la zona de tu objetivo. Elimina 1...2 encantamientos de esos enemigos. Quedas envenenado (10 segundos).'],
145=>['Sello de la agonía','Sello. Sufres una hemorragia durante 25 segundos. Todos los enemigos cercanos reciben 10...70 de daño.','Sello. Hace 10...70 de daño a los enemigos cercanos. Sufres una hemorragia (25 segundos).'],
146=>['Ofrenda de sangre','Conjuro de élite. Ganas 8...20 de energía.','Conjuro de élite. Ganas 8...20 de energía.'],
147=>['Furia oscura','Conjuro con encantamiento. Durante 5 segundos, cada vez que un miembro del grupo golpee a alguien, ganará uno de adrenalina (50% de probabilidades de fallar con magia de sangre 4 o inferior).','Conjuro con encantamiento. Encanta a los miembros del grupo (5 segundos), que ganan uno de adrenalina cada vez que hagan un ataque. 50% de probabilidades de fallar con magia de sangre inferior a 5.'],
148=>['Orden del vampiro','Conjuro con encantamiento de élite. Durante 5 segundos, siempre que un miembro del grupo que no esté bajo los efectos de otro encantamiento de Nigromante golpee a un enemigo con daño físico, robará hasta 3...16 de salud.','Conjuro con encantamiento de élite. Encanta a todos los miembros del grupo (5 segundos), que roban 3...16 de salud por cada ataque con daño físico que hagan. No tiene efecto en los miembros del grupo que tengan otro encantamiento de Nigromante.'],
149=>['Envío pestilente','Conjuro. Transfieres 1...3 condición[f:"condiciones"] negativas tuyas al enemigo objetivo y los adyacentes, que durarán el tiempo que le quedaba para terminar.','Conjuro. Transfieres 1...3 condición[f:"condiciones"] al enemigo objetivo y los adyacentes, que durarán el tiempo que les quedaba para terminar.'],
150=>['Marca del dolor','Conjuro con maleficio. Durante 30 segundos, siempre que el enemigo objetivo reciba daño físico, la Marca del dolor hará 10...40 de daño de sombra a los enemigos adyacentes.','Conjuro con maleficio. (30 segundos). Hace 10...40 de daño a los enemigos adyacentes cada vez que el enemigo objetivo reciba daño físico.'],
151=>['Festín de corrupción','Conjuro de élite. El enemigo objetivo y los enemigos adyacentes recibirán 16...80 de daño de sombra. Robas hasta 8...40 de salud a cada enemigo que golpees que tenga un maleficio.','Conjuro de élite. Hace 16...80 de daño al enemigo objetivo y los adyacentes. Roba 8...40 de salud de cada enemigo que tenga un maleficio.'],
152=>['Sabor de la muerte','Conjuro. Robas hasta 100...400 de salud de un muerto viviente aliado.','Conjuro. Roba 100...400 de salud de un siervo aliado.'],
153=>['Mirada vampírica','Conjuro. Robas hasta 18...60 de salud del enemigo objetivo.','Conjuro. Roba 18...60 de salud.'],
154=>['Toque pestilente','Habilidad. Transfieres 1...3 condición[f:"condiciones"] negativas tuyas al enemigo que toques, que durarán el tiempo que le quedaba para terminar.','Habilidad de toque. Transfiere 1...3 condiciones tuyas al enemigo objetivo.'],
155=>['Toque vil','Habilidad. El enemigo objetivo al que toques recibe 20...65 de daño.','Habilidad de toque. Hace 20...65 de daño.'],
156=>['Toque vampírico','Habilidad. Toca a un enemigo para robarle hasta 29...74 de salud.','Habilidad de toque. Roba 29...74 de salud.'],
157=>['Ritual de sangre','Conjuro con encantamiento. Durante 8...14 segundos, el aliado al que toques gana +3 de regeneración de energía. No se puede usar el Ritual de sangre sobre uno mismo.','Conjuro con encantamiento. (8...14 segundos). +3 de regeneración de energía. No te puedes apuntar a ti mismo.'],
158=>['Toque de agonía','Habilidad. El enemigo objetivo tocado recibe 20...58 de daño de sombra.','Habilidad de toque. Hace 20...58 de daño.'],
159=>['Debilitar armadura','Conjuro. El enemigo objetivo y los adyacentes tienen la armadura rota durante 5...20 segundos.','Conjuro. También afecta a los enemigos adyacentes. Causa armadura rota (5...20 segundos).'],
160=>['Velocidad del viento','Conjuro con encantamiento. Durante 5...13 segundos, el objetivo (un aliado o tú mismo) se moverá el 33% más rápido de lo normal.','Conjuro con encantamiento. (5...13 segundos). El objetivo aliado se mueve un 33% más rápido.'],
162=>['Vendaval','Conjuro. Derriba al enemigo objetivo durante 2 segundos. (50% de posibilidades de fallar con magia de aire 4 o inferior).','Conjuro. Causa derribo. 50% de posibilidades de fallar a menos que tengas magia de aire 5 o superior.'],
163=>['Torbellino','Conjuro. Todos los enemigos adyacentes reciben 15...75 de daño frío. Derriba a los enemigos atacantes alcanzados por Torbellino. Si estás sobrelanzando, este conjuro golpea a los enemigos cercanos en vez de a los adyacentes.','Conjuro. Golpea a los enemigos adyacentes a ti. Hace 15...75 de daño frío. Derriba a los enemigos atacantes. Golpea a los cercanos en vez de a los adyacentes si estás sobrelanzando.'],
164=>['Sintonía con los elementos','Conjuro con encantamiento de élite. Durante 25...60 segundos estás en sintonía con el aire, el fuego, el agua y la tierra, y obtienes +1...2 a estos atributos. Ganas 1 de energía más un 50 % del coste base de energía de la habilidad cada vez que utilices magia asociada a cualquiera de estos elementos.','Conjuro con encantamiento de élite. (25...60 segundos). Tus atributos de los elementos aumentan en +1...2. Ganas 1 de energía más un 50 % del coste base de energía de cualquier habilidad de magia de aire, tierra, fuego y agua que uses.'],
165=>['Armadura de tierra','Conjuro con encantamiento. Durante 30 segundos, ganas 24...60 de armadura, pero te mueves un 50...14% más lento.','Conjuro con encantamiento. (30 segundos.) Tienes +24...60 de armadura. Te mueves un 50...14% más lento.'],
166=>['Armadura cinética','Conjuro con encantamiento. Durante 12 segundos, ganas +20...80 de armadura. Siempre que lances un conjuro, la Armadura cinética se renueva durante 12 segundos.','Conjuro con encantamiento. (12 segundos). Tienes +20...80 de armadura. Extra de renovación: lanzar un conjuro.'],
167=>['Erupción','Conjuro. Creas una Erupción en la ubicación del enemigo objetivo. Cada segundo durante 5, los enemigos cercanos a esa ubicación recibirán 10...40 de daño de tierra y quedarán cegados durante 10 segundos.','Conjuro. Hace 10...40 de daño de tierra por segundo (5 segundos). Alcanza a los enemigos cercanos a la ubicación inicial del objetivo. Causa ceguera (10 segundos).'],
168=>['Aura magnética','Conjuro con encantamiento. Durante 1...8 segundos, bloqueas el siguiente ataque dirigido a ti y haces 10...50 de daño a tu atacante. Si estás sobrelanzando, todos los miembros del grupo al alcance del oído también quedan encantados.','Conjuro con encantamiento. (1...8 segundos.) Bloquea el siguiente ataque contra ti y refleja 10...50 de daño hacia el atacante. Si estás sobrelanzando, encanta a los miembros del grupo al alcance del oído.'],
169=>['Sintonía con la tierra','Conjuro con encantamiento. Durante 36...60 segundos, estarás en sintonía con la tierra Ganas 1 de energía además de un 30% del coste base de la habilidad en energía cada vez que utilices magia de tierra.','Conjuro con encantamiento. (36...60 segundos). Ganas 1 de energía más el 30% del coste de energía cuando uses una habilidad de magia de tierra.'],
170=>['Terremoto','Conjuro. Creas un Terremoto en la ubicación del enemigo objetivo. Todos los enemigos cercanos a esta ubicación son derribados y reciben 26...100 de daño de tierra.','Conjuro. Causa 26...100 de daño de tierra. También afecta a los enemigos cercanos al objetivo. Causa derribo.'],
171=>['Pedrada','Conjuro. Lanzas una piedra grande, que hace 45...105 de daño de tierra al enemigo objetivo si le da. Si Pedrada alcanza a un enemigo que esté sufriendo debilitamiento, lo derribarás.','Conjuro. Proyectil: causa 45...105 de daño de tierra. Causa derribo si el enemigo objetivo sufre debilitamiento.'],
172=>['Dagas de piedra','Conjuro. Arrojas dos dagas de piedra. Si impactan, cada una hace 8...33 de daño de tierra al enemigo objetivo. Si estás sobrelanzando, cada proyectil causa hemorragia durante 1...5 segundos.','Conjuro. Dos proyectiles: cada uno causa 8...33 de daño de tierra. Si estás sobrelanzando, causa hemorragia durante 1...5 segundos'],
173=>['Presa de la tierra','Conjuro con maleficio. Durante 5...20 segundos, todos los enemigos cercanos se moverán un 50% más lento de lo normal.','Conjuro con maleficio. También afecta a los enemigos cercanos a ti (5...20 segundos). Estos enemigos se moverán un 50% más despacio.'],
174=>['Descarga de respuesta','Conjuro. Los enemigos cercanos reciben 15...85 de daño de tierra. Los enemigos derribados reciben 15...85 de daño de tierra adicional.','Conjuro. Hace 15...85 de daño de tierra a los enemigos cercanos. Hace 15...85 más de daño de tierra a los enemigos derribados.'],
175=>['Protección contra los elementos','Conjuro de protección. Creas una Protección contra los elementos en tu ubicación actual. Durante 8...20 segundos, los aliados que no sean espíritus de esta zona ganan +24 de armadura contra daño de los elementos.','Conjuro de protección. (8...20 segundos). Los aliados dentro de esta protección tienen +24 de armadura contra daño de los elementos. No afecta a los espíritus.'],
176=>['Protección ataques cuerpo a cuerpo','Conjuro de protección. Creas una Protección ataques cuerpo a cuerpo en tu ubicación actual. Durante 5...20 segundos, los aliados no espíritus que haya en el área tendrán un 50% de posibilidades de bloquear ataques cuerpo a cuerpo.','Conjuro de protección. (5...20 segundos). Los aliados dentro de esta protección tienen un 50% de posibilidades de bloquear ataques cuerpo a cuerpo. No afecta a los aliados espíritus.'],
177=>['Protección contra enemigos','Conjuro de protección. Creas una Protección contra enemigos en tu ubicación actual. Durante 8...20 segundos, los enemigos no espíritus en esta zona se mueven un 50% más lento.','Conjuro de protección. (8...20 segundos). Los enemigos dentro de la protección se mueven un 50% más lento.'],
178=>['Prodigio de éter','Conjuro con encantamiento de élite. Pierdes todos los encantamientos. Durante 8...20 segundos, tienes +6 de regeneración de energía. Cuando finalice el Prodigio de éter, perderás 2 de salud por cada punto de energía que tengas.','Conjuro con encantamiento de élite. (8...20 segundos). Tienes +6 de regeneración de energía. Efecto final: pierdes 2 de salud por cada punto de energía que tengas. Pierdes todos los encantamientos.'],
179=>['Vínculos incendiarios','Conjuro con maleficio. Tras 3 segundos, el enemigo objetivo y todos los cercanos reciben 20...80 de daño de fuego y arden durante 1...3 segundos. Se activa antes si el enemigo objetivo muere.','Conjuro con maleficio. (3 segundos.) Efecto final: hace 20...80 de daño de fuego y causa quemadura (1...3 segundos) a los enemigos cercanos al objetivo. También se activa si el enemigo muere.'],
180=>['Aura de restauración','Conjuro con encantamiento. Durante 60 segundos, ganas 0...1 de energía y te curas un 200...500% del coste de energía cada vez que lances un conjuro.','Conjuro con encantamiento. (60 segundos.) Ganas 0...1 de energía y te curas un 200...500% del coste de energía cada vez que lances un conjuro.'],
181=>['Renovación de éter','Conjuro con encantamiento de élite. Durante 5...20 segundos, cada vez que lances un conjuro, ganas 1...4 de energía y 5...20 de salud por cada encantamiento que tengas.','Conjuro con encantamiento de élite. (5...20 segundos). Cada vez que lances un conjuro, ganas 1...4 de energía y 5...20 de salud por cada encantamiento que tengas.'],
182=>['Conjurar llama','Conjuro con encantamiento. Durante 60 segundos, si llevas un arma de fuego, tus ataques hacen 5...20 de daño de fuego adicional.','Conjuro con encantamiento. (60 segundos.) Tus ataques hacen +5...20 de daño de fuego. No tiene efecto si no llevas un arma de fuego.'],
183=>['Infierno','Conjuro. Los enemigos adyacentes reciben 30...135 de daño de fuego.','Conjuro. Hace 30...135 de daño de fuego a los enemigos adyacentes a ti.'],
184=>['Sintonía con el fuego','Conjuro con encantamiento. Durante 36...60 segundos, estarás en sintonía con el fuego. Ganas 1 de energía además de un 30% del coste base de la habilidad en energía cada vez que utilices magia de fuego.','Conjuro con encantamiento. (36...60 segundos). Ganas 1 de energía más el 30% del coste de energía cuando uses una habilidad de magia de fuego.'],
185=>['Quemadura mental','Conjuro de élite. El enemigo objetivo y los adyacentes reciben 15...60 de daño de fuego. Si tienes más energía que el enemigo objetivo, ese enemigo y todos los adyacentes reciben 15...60 de daño de fuego adicional y arden durante 1...10 segundos.','Conjuro de élite. Hace 15...60 de daño de fuego. Si tienes más energía que el enemigo objetivo, hace 15...60 más de daño de fuego y causa quemadura (1...10 segundos). También alcanza a los enemigos cercanos.'],
186=>['Bola de fuego','Conjuro. Lanzas una bola de fuego que hace 7...112 de daño de fuego al enemigo objetivo y a todos los enemigos cercanos.','Conjuro. Proyectil: Hace 7...112 de daño de fuego al enemigo objetivo y los enemigos cercanos.'],
187=>['Meteoro','Conjuro. El enemigo objetivo y todos los adyacentes son derribados y reciben 7...112 de daño de fuego.','Conjuro. Hace 7...112 de daño de fuego y causa derribo. También afecta a los enemigos adyacentes al enemigo objetivo.'],
188=>['Llamaradas','Conjuro. Los enemigos cercanos reciben 15...120 de daño de fuego.','Conjuro. Hace 15...120 de daño de fuego a todos los enemigos cercanos.'],
189=>['Invocación de Rodgort','Conjuro. El enemigo objetivo y todos los enemigos cercanos reciben 15...120 de daño de fuego y arden durante 1...3 segundos.','Conjuro. Hace 15...120 de daño de fuego. También alcanza a los enemigos cercanos a tu objetivo. Causa quemadura (1...3 segundos).'],
190=>['Marca de Rodgort','Conjuro con maleficio. Tanto el objetivo enemigo como todos los cercanos quedan malditos con la Marca de Rodgort. Durante 10...35 segundos, cada vez que alguno de ellos reciba daño de fuego, arderá durante 1...4 segundos.','Conjuro con maleficio. También afecta a los enemigos cercanos al objetivo (10...35 segundos). Causa quemadura (1...4 segundos) cuando esos enemigos reciben daño de fuego.'],
191=>['Inmolación','Conjuro. El enemigo objetivo recibe 20...75 de daño de fuego y arde durante 1...3 segundos.','Conjuro. Hace 20...75 de daño de fuego. Causa quemadura (1...3 segundos).'],
192=>['Lluvia de meteoros','Conjuro. Creas una Lluvia de meteoros en la ubicación del enemigo objetivo. Durante 9 segundos, los enemigos adyacentes a la zona reciben 7...112 de daño de fuego y son derribados cada 3 segundos.','Conjuro. Hace 7...112 de daño de fuego y causa derribos cada 3 segundos (9 segundos). Alcanza a los enemigos adyacentes a la ubicación inicial del objetivo.'],
193=>['Fénix','Conjuro. Un fénix envuelto en llamas surge en tu ubicación y se dirige hacia tu objetivo, explotando al impactar. La explosión alcanzará al enemigo objetivo y los adyacentes y les hará 10...60 de daño de fuego. Si estás sobrelanzando, los aliados en el radio de la explosión reciben 20...80 de salud.','Conjuro. Proyectil: hace 10...60 de daño de fuego al objetivo y a los enemigos cercanos. Cura 20...80 a los aliados si estás sobrelanzando.'],
194=>['Bengala','Conjuro. Lanzas una bengala que hará 20...65 de daño de fuego al enemigo. Si estás sobrelanzando, la bengala también golpea a los enemigos adyacentes.','Conjuro. Proyectil: hace 20...65 de daño de fuego. Si estás sobrelanzando, golpea a los adyacentes.'],
195=>['Fuente de lava','Conjuro. Durante 5 segundos, los enemigos adyacentes al lugar donde se lanzó el conjuro recibirán 5...50 de daño de fuego por segundo. Si estás sobrelanzando, este conjuro golpea a los enemigos cercanos en vez de a los adyacentes.','Conjuro. Hace 5...50 de daño de fuego por segundo (5 segundos). Alcanza a los enemigos adyacentes a tu ubicación inicial. Si estás sobrelanzando, se aumenta el alcance a los cercanos.'],
196=>['Calor abrasador','Conjuro. Creas Calor abrasador en la ubicación del enemigo objetivo. Durante 5 segundos, los enemigos adyacentes a la zona reciben 10...40 de daño de fuego por segundo. Cuando el Calor abrasador finalice, los enemigos del área de efecto empezarán a arder durante 3 segundos.','Conjuro. Hace 10...40 de daño de fuego por segundo (5 segundos). Alcanza a los enemigos cercanos a la ubicación inicial del objetivo. Efecto final: causa quemadura (3 segundos).'],
197=>['Tormenta de fuego','Conjuro. Creas una Tormenta de fuego en la ubicación del enemigo objetivo. Durante 10 segundos, los enemigos adyacentes a la zona reciben 5...35 de daño de fuego por segundo.','Conjuro. Hace 5...35 de daño de fuego por segundo (10 segundos). Alcanza a los enemigos adyacentes a la ubicación inicial del objetivo.'],
198=>['Glifo de poder elemental','Glifo. Durante 25 segundos, tus atributos de los elementos se aumentan en 2 para tus próximos 10 conjuros.','Glifo. (25 segundos.) Aumenta tus atributos de los elementos en +2 para tus próximos 10 conjuros.'],
199=>['Glifo de energía','Glifo de élite. Tus siguientes 1...3 conjuros no causan sobrelanzamiento y lanzarlos cuesta 10...25 menos de energía. Tus atributos de los elementos aumentan en 1...2.','Glifo de élite. Tus siguientes 1...3 conjuros no causan sobrelanzamiento y cuestan 10...25 menos de energía. Ganas 1...2 en todos los atributos de los elementos.'],
200=>['Glifo de energía menor','Glifo. Durante 15 segundos, te costará 10...18 menos de energía lanzar tus próximos 2 conjuros.','Glifo. (15 segundos.) tus próximos 2 conjuros cuestan 10...18 menos de energía.'],
201=>['Glifo de concentración','Glifo. Durante 15 segundos, tus próximos conjuros (1) no se pueden interrumpir ni causan aturdimiento.','Glifo. (15 segundos.) Tus próximos 1 conjuros no se pueden interrumpir y no les afecta aturdimiento.'],
202=>['Glifo de sacrificio','Glifo. Durante 15 segundos, tu próximo conjuro se lanza de forma instantánea, pero tardará 30 segundos más en recargarse. Termina prematuramente si utilizas una habilidad que no sea un conjuro.','Glifo. (15 segundos.) Tu próximo conjuro se lanza de forma instantánea, pero tardará 30 segundos más en recargarse. Termina si utilizas una habilidad que no sea un conjuro.'],
203=>['Glifo de renovación','Glifo de élite. Durante 15 segundos, tu siguiente conjuro se recargará de forma instantánea.','Glifo de élite. (15 segundos.) Tu siguiente conjuro se recargará instantáneamente.'],
204=>['Óxido','Conjuro con maleficio. Hace 10...85 de daño frío al enemigo objetivo y los adyacentes. Durante 5...20 segundos, el enemigo objetivo y todos los adyacentes tardarán el doble en activar sellos. Si estás sobrelanzando, los sellos de los enemigos impactados con Óxido quedan interrumpidos y desactivados durante 1...10 segundos.','Conjuro con maleficio. Hace 10...85 de daño frío al enemigo objetivo y los adyacentes. Maldice a los enemigos adyacentes (5...20 segundos). Duplica el tiempo de activación de sellos. Interrumpe y desactiva los sellos durante 1...10 segundos si estás sobrelanzando.'],
205=>['Oleada de relámpagos','Conjuro con maleficio de élite. Tras 3 segundos, derriba al objetivo enemigo, le hace 14...100 de daño de relámpago y tiene la armadura rota durante 5...20 segundos. Este conjuro tiene un 25% de penetración de armadura.','Conjuro con maleficio de élite. (3 segundos.) Efecto final: hace 14...100 de daño de relámpago, derriba y causa armadura rota (5...20 segundos). 25% de penetración de armadura.'],
206=>['Armadura de escarcha','Conjuro con encantamiento. Durante 10...34 segundos, ganas +40 de armadura contra daño físico y tienes +1 magia de agua.','Conjuro con encantamiento. (10...34 segundos). Ganas +40 de armadura contra daño físico y tienes +1 magia de agua.'],
207=>['Conjurar escarcha','Conjuro con encantamiento. Durante 60 segundos, si llevas un arma de frío, tus ataques hacen 5...20 de daño frío adicional.','Conjuro con encantamiento. (60 segundos.) Tus ataques hacen +5...20 de daño frío. No tiene efecto si no llevas un arma de daño frío.'],
208=>['Sintonía con el agua','Conjuro con encantamiento. Durante 36...60 segundos, estarás en sintonía con el agua. Ganas 1 de energía además de un 30% del coste base de la habilidad en energía cada vez que utilices magia de agua.','Conjuro con encantamiento. (36...60 segundos). Ganas 1 de energía más el 30% del coste de energía cuando uses una habilidad de magia de agua.'],
209=>['Congelar mente','Conjuro con maleficio de élite. El enemigo objetivo recibe 10...60 de daño frío. Si tienes más energía que el enemigo objetivo, ese enemigo recibe 10...60 de daño frío adicional y se mueve un 90% más despacio durante 1...5 segundos.','Conjuro con maleficio de élite. Hace 10...60 de daño frío. Si tienes más energía que el enemigo objetivo, hace 10...60 de daño frío y causa una reducción del 90% en el movimiento (1...5 segundos).'],
210=>['Prisión de hielo','Conjuro con maleficio. Durante 8...20 segundos, las piernas del enemigo objetivo estarán atrapadas en hielo y se moverá un 66% más lento.','Conjuro con maleficio. (8...20 segundos). El enemigo objetivo se mueve un 66% más despacio.'],
211=>['Púas de hielo','Conjuro con maleficio. El enemigo objetivo y los adyacentes reciben 20...80 de daño frío y se mueven un 66% más lentos durante 2...6 segundos.','Conjuro con maleficio. También afecta a los enemigos cercanos al objetivo (2...6 segundos). Estos enemigos se moverán un 66% más despacio. Efecto inicial: hace 20...80 de daño frío.'],
212=>['Estallido helado','Conjuro con maleficio. Todos los enemigos cercanos reciben 10...85 de daño frío y se mueven un 66% más lentos durante 3...8 segundos.','Conjuro con maleficio. Afecta a los enemigos cercanos a ti. Estos enemigos se moverán un 66% más despacio (3...8 segundos). Efecto inicial: hace 10...85 de daño frío a los enemigos cercanos.'],
213=>['Tormenta de fragmentos','Conjuro con maleficio. Lanzas un témpano de hielo que causará 10...85 de daño frío al enemigo y hará que se mueva un 66% más lento durante 2...6 segundos.','Conjuro con maleficio. Proyectil: hace 10...85 de daño frío. El enemigo objetivo se mueve un 66% más despacio (2...6 segundos).'],
214=>['Lanza de hielo','Conjuro con encantamiento. Tiras una lanza de hielo, que hace 10...60 de daño frío al enemigo objetivo si acierta. Si estás sobrelanzando, obtienes +1...4 de regeneración de salud durante 5 segundos.','Conjuro con encantamiento. Proyectil: hace 10...60 de daño frío. Obtienes +1...4 de regeneración de salud durante 5 segundos si estás sobrelanzando.'],
215=>['Vorágine','Conjuro. Creas una Vorágine en la ubicación del enemigo objetivo. Durante 10 segundos, los enemigos adyacentes a la zona reciben 10...25 de daño frío por segundo. Vorágine interrumpe el lanzamiento de conjuros cuando impacta.','Conjuro. Hace 10...25 de daño frío e interrumpe conjuros cada segundo (10 segundos). Alcanza a los enemigos adyacentes a la ubicación inicial del objetivo.'],
216=>['Niebla de hierro','Conjuro con encantamiento. Durante 8...15 segundos, tienes +15 de armadura. Tus conjuros de magia de aire que hagan objetivo a un enemigo se activan y recargan un 33 % más rápido, pero tienes 2 puntos de sobrelanzamiento.','Conjuro con encantamiento. (8...15 segundos) Ganas +15 de armadura. Los conjuros de magia de aire que hagan objetivo a un enemigo se activan y recargan un 33 % más rápido, pero tienes 2 puntos de sobrelanzamiento.'],
217=>['Ola de cristales','Conjuro. Los enemigos adyacentes reciben 10...70 de daño, pero se curan de toda condición negativa. Cada condición eliminada causa 5...15 de daño.','Conjuro. Hace 10...70 de daño a todos los enemigos adyacentes a ti. Esos enemigos pierden todas las condiciones y reciben 5...15 de daño por cada condición eliminada.'],
218=>['Carne de obsidiana','Conjuro con encantamiento de élite. Durante 8...20 segundos, ganas +20 de armadura y no puedes ser objetivo de conjuros enemigos, pero no puedes atacar y tienes -2 de degeneración de energía.','Conjuro con encantamiento de élite. (8...20 segundos). Tienes +20 de armadura y no puedes ser objetivo de conjuros enemigos. No puedes atacar y tienes -2 de degeneración de energía.'],
219=>['Llama de obsidiana','Conjuro. Hace 22...112 de daño al enemigo objetivo. Este conjuro ignora la armadura.','Conjuro. Causa 22...112 de daño.'],
220=>['Destello cegador','Conjuro. El enemigo objetivo se queda ciego durante 3...8 segundos.','Conjuro. Causa ceguera (3...8 segundos).'],
221=>['Conjurar relámpago','Conjuro con encantamiento. Durante 60 segundos, si llevas un arma de relámpago, tus ataques hacen 5...20 de daño de relámpago adicional.','Conjuro con encantamiento. (60 segundos.) Tus ataques hacen +5...20 de daño de relámpago. No tiene efecto si no llevas un arma de daño de relámpago.'],
222=>['Ataque de relámpago','Conjuro con maleficio. Alcanzas al enemigo objetivo con 10...60 de daño de relámpago. Este conjuro tiene un 25% de penetración de armadura. Si estás sobrelanzando, ese enemigo queda maldito con Ataque de relámpago durante 3 segundos. Cuando este maleficio acabe, el enemigo recibirá 20...40 de daño de relámpago.','Conjuro con maleficio. Causa 10...60 de daño de relámpago. 25% de penetración de armadura. Maldito durante 3 segundos si estás sobrelanzando. Efecto final: causa 20...40 de daño de relámpago.'],
223=>['Relámpago encadenado','Conjuro. El enemigo objetivo y otros dos enemigos que se encuentren cerca recibirán 10...85 de daño de relámpago. Este conjuro tiene un 25% de penetración de armadura.','Conjuro. Causa 10...85 de daño de relámpago. También alcanza a dos enemigos cercanos a tu objetivo. 25% de penetración de armadura.'],
224=>['Carga debilitante','Conjuro. El enemigo objetivo recibe 25...50 de daño de relámpago y está debilitado durante 5...20 segundos. Este conjuro tiene un 25% de penetración de armadura.','Conjuro. Causa 25...50 de daño de relámpago. Causa debilitamiento (5...20 segundos). 25% de penetración de armadura.'],
225=>['Sintonía con el aire','Conjuro con encantamiento. Durante 36...60 segundos, estarás en sintonía con el aire. Ganas 1 de energía además de un 30% del coste base de la habilidad en energía cada vez que utilices magia de aire.','Conjuro con encantamiento. (36...60 segundos). Ganas 1 de energía más el 30% del coste de energía cuando uses una habilidad de magia de aire.'],
226=>['Impacto mental','Conjuro de élite. El enemigo objetivo recibe 10...50 de daño de relámpago. Si tienes más energía que el enemigo objetivo, éste recibe 10...50 más de daño de relámpago y es derribado. Este conjuro tiene un 25% de penetración de armadura.','Conjuro de élite. Causa 10...50 de daño de relámpago. Si tienes más energía que el enemigo objetivo, hace +10...50 de daño de relámpago y provoca derribo. 25% de penetración de armadura.'],
227=>['Marca atenuada','Conjuro con maleficio de élite. Durante 10 segundos, el enemigo objetivo y todos los enemigos adyacentes reciben 5...25 de daño por segundo. Los enemigos que estén utilizando habilidades de ataque quedan cegados durante 3 segundos. Este maleficio acaba si usas una habilidad que apunte a este objetivo.','Conjuro con maleficio de élite. (10 segundos). Hace 5...25 de daño cada segundo al enemigo objetivo y los adyacentes. Causa ceguera a los enemigos que estén utilizando habilidades de ataque. Acaba si usas una habilidad que apunte a este objetivo.'],
228=>['Trueno','Conjuro de élite. Creas una onda expansiva enorme en la ubicación del enemigo objetivo. Hace 10...50 de daño de relámpago al enemigo objetivo y a los enemigos cercanos. Interrumpe a los enemigos alcanzados y sufren debilitamiento y armadura rota durante 5...20 segundos. Este conjuro tiene un 25 % de penetración de armadura.','Conjuro de élite. Causa 10...50 de daño de relámpago. También alcanza a los enemigos cercanos. Causa armadura rota y debilitamiento (5...20 segundos). Interrumpe. 25 % de penetración de armadura.'],
229=>['Esfera de relámpago','Conjuro. Lanzas una Esfera de relámpago que hace 10...100 de daño de relámpago al enemigo objetivo. Este conjuro tiene un 25% de penetración de armadura.','Conjuro. Proyectil: causa 10...100 de daño de relámpago. 25% de penetración de armadura.'],
230=>['Jabalina de relámpago','Conjuro. Lanzas una Jabalina de relámpago que hace 15...50 de daño de relámpago al enemigo objetivo si le alcanza. Jabalina de relámpago interrumpe a los enemigos que estén atacando. Este conjuro tiene un 25% de penetración de armadura y golpea a todos los enemigos entre tu objetivo y tú.','Conjuro. Proyectil: causa 15...50 de daño de relámpago. Interrumpe si tu objetivo está atacando. 25% de penetración de armadura. Golpea a todos los enemigos entre tu objetivo y tú.'],
231=>['Descarga','Habilidad. El enemigo objetivo alcanzado es derribado y recibe 10...60 de daño de relámpago. Esta habilidad tiene un 25% de penetración de armadura.','Habilidad de toque. Causa 10...60 de daño de relámpago. Causa derribo. 25% de penetración de armadura.'],
232=>['Toque de relámpago','Habilidad. El enemigo que toques y los enemigos adyacentes reciben 10...60 de daño de relámpago, quedan cegados durante 1...4 segundos y tienen la armadura rota durante 1...10 segundos. Esta habilidad tiene un 25% de penetración de armadura.','Habilidad de toque. Causa 10...60 de daño de relámpago. También golpea a los enemigos adyacentes al objetivo. Causa ceguera (1...4 segundos) y armadura rota (1...10 segundos) a todos los enemigos alcanzados. 25% de penetración de armadura.'],
233=>['Torbellino de aura','Conjuro con encantamiento. Durante 3...7 segundos, quedas encantado con Torbellino de aura y tienes 1...6 de regeneración de salud y un 50% de probabilidad de bloquear proyectiles. Si estás sobrelanzando cuando lanzas este conjuro, todos los miembros del grupo que estén al alcance del oído quedan también afectados por el encantamiento.','Conjuro con encantamiento. (3...7 segundos.) Otorga 1...6 de regeneración de salud y un 50% de probabilidad de bloquear. Si estás sobrelanzando, también encanta a los miembros del grupo al alcance del oído.'],
234=>['Congelación','Conjuro con maleficio. Invocas una Congelación en la ubicación del enemigo. Todos los que estén en el área reciben 10...85 de daño frío y su velocidad se reduce un 66% durante 10 segundos.','Conjuro con maleficio. También afecta a los enemigos en la zona del objetivo (10 segundos). Estos enemigos se moverán un 66% más despacio. Efecto inicial: hace 10...85 de daño frío.'],
235=>['Visión borrosa','Conjuro con maleficio. Durante 4...10 segundos, el enemigo objetivo y todos los adyacentes recibirán el maleficio Visión borrosa. Mientras éste dure, tendrán un 50% de posibilidades de fallar en sus ataques.','Conjuro con maleficio. También afecta a los enemigos cercanos al objetivo (4...10 segundos). Tienes un 50% de posibilidades de fallar.'],
236=>['Forma de niebla','Conjuro con encantamiento de élite. Durante 10...45 segundos, recibes un 33% menos de daño de los enemigos que estén bajo el efecto de maleficios de magia de agua. Cada vez que lances un conjuro de los elementos, todos aliados no espíritus al alcance del oído se curarán un 50...250% del coste de energía del conjuro.','Conjuro con encantamiento de élite. (10...45 segundos). Recibes un 33% menos de daño de los enemigos que estén bajo el efecto de maleficios de magia de agua. Cura a los aliados no espíritus al alcance del oído un 50...250% del coste de energía de tus conjuros de los elementos.'],
237=>['Tridente de agua','Conjuro de élite. Arrojas un Tridente de agua al enemigo objetivo, que hace 10...90 de daño frío si impacta al enemigo objetivo y a otros dos enemigos cercanos. Si este ataque impacta a un enemigo en movimiento, lo derriba.','Conjuro de élite. Proyectil veloz: hace 10...90 de daño frío y derriba a los enemigos en movimiento. Lanza 2 proyectiles adicionales a enemigos adyacentes.'],
238=>['Armadura de niebla','Conjuro con encantamiento. Durante 8...20 segundos, ganas +10...40 de armadura y te mueves un 33% más rápido.','Conjuro con encantamiento. (8...20 segundos). Tienes +10...40 de armadura y te mueves un 33% más rápido.'],
239=>['Protección contra daños','Conjuro de protección de élite. Creas una Protección contra daños en esta ubicación. Durante 5...15 segundos, los aliados no espíritus de la zona tienen +1...3 de regeneración de salud, +12...24 de armadura y un +12...24 adicional de armadura contra daño de los elementos. Este conjuro queda desactivado durante 20 segundos.','Conjuro de protección de élite. (5...15 segundos). Los aliados dentro de esta protección tienen +1...3 de regeneración de salud, +12...24 de armadura y un +12...24 adicional de armadura contra daño de los elementos. No afecta a los espíritus. Este conjuro queda desactivado durante 20 segundos.'],
240=>['Golpe','Conjuro. Este ataque hace 10...55 de daño sagrado. Además, si el objetivo está atacando recibe 10...35 de daño sagrado extra.','Conjuro. Hace 10...55 de daño sagrado. 10...35 de daño sagrado extra si el objetivo está atacando.'],
241=>['Vínculo de vida','Conjuro con encantamiento. Mientras mantengas este encantamiento, siempre que el aliado objetivo reciba daño de un ataque, la mitad de éste lo recibes tú. El daño que recibas de esta forma se reduce en 3...30.','Conjuro con encantamiento. La mitad del daño que hagan al aliado objetivo se traspasa a ti. El daño recibido se reduce en 3...30. No se puede usar con uno mismo.'],
242=>['Espíritu de Balthazar','Conjuro con encantamiento. Mientras mantengas este encantamiento, el objetivo (un aliado o tú mismo) ganará adrenalina y energía siempre que reciba daño (la cantidad de adrenalina dependerá del nivel de plegarias de ataques que se tenga).','Conjuro con encantamiento. El objetivo (un aliado o tú mismo) gana adrenalina y 1 de energía al recibir daño.'],
243=>['Fuerza del honor','Conjuro con encantamiento. Mientras mantengas este encantamiento, el objetivo (un aliado o tú mismo) hace 5...25 más de daño en ataques cuerpo a cuerpo.','Conjuro con encantamiento. El objetivo (un aliado o tú mismo) hace 5...25 más de daño en ataques cuerpo a cuerpo.'],
244=>['Sintonía con la vida','Conjuro con encantamiento. Mientras mantengas este encantamiento, el objetivo (un aliado o tú mismo) hace un 30% menos de daño, pero gana un 14...50% más de salud cuando se cura.','Conjuro con encantamiento. El objetivo (un aliado o tú mismo) gana un 14...50% más de salud al curarse. Este objetivo hace 30% menos de daño al atacar.'],
245=>['Espíritu protector','Conjuro con encantamiento. Durante 5...23 segundos, el objetivo (un aliado o tú mismo) no puede perder más de un 10% del máximo de salud como resultado de un ataque o un conjuro.','Conjuro con encantamiento. (5...23 segundos). El daño que el objetivo (un aliado o tú mismo) reciba se reduce en un 10% de su máximo de salud.'],
246=>['Intervención divina','Conjuro con encantamiento. Durante 10 segundos, la próxima vez que el objetivo (un aliado o tú mismo) reciba daño que podría ser letal, el daño es bloqueado y recupera 26...240 de salud.','Conjuro con encantamiento. (10 segundos). Impide el siguiente ataque al objetivo (un aliado o tú mismo) sea crítico. Efecto: cura 26...240 de salud.'],
247=>['Símbolo de la ira','Conjuro. Creas un símbolo de ira en la ubicación del enemigo objetivo. Durante 5 segundos, los enemigos adyacentes reciben su efecto y sufren 10...40 de daño sagrado por segundo.','Conjuro. Hace 10...40 de daño sagrado por segundo (5 segundos). Alcanza a los enemigos adyacentes a la ubicación inicial del enemigo objetivo.'],
248=>['Retribución','Conjuro con encantamiento. Mientras mantengas este encantamiento, siempre que el objetivo (un aliado o tú mismo) reciba daño al ser atacado, se devolverá un 33% del daño al que lo ha causado (5...20 como máximo).','Conjuro con encantamiento. Hace que el 33% de cada daño vuelva al atacante (máximo 5...20).'],
249=>['Ira sagrada','Conjuro con encantamiento. Durante 10...30 segundos, las siguientes veces (1...10) que el aliado objetivo reciba daño de ataques, este conjuro devuelve un 66% del daño al que lo ha causado (5...50 como máximo).','Conjuro con encantamiento. (10...30 segundos). Hace que el 66% de cada daño vuelva al atacante (máximo 5...50). Acaba después de recibir daño 1...10 veces. No te puedes apuntar a ti mismo.'],
250=>['Vínculo de esencia','Conjuro con encantamiento. Mientras mantengas este encantamiento, siempre que el objetivo (un aliado o tú mismo) reciba daño físico o elemental, ganas 1 de energía.','Conjuro con encantamiento. Ganas 1 de energía cuando el objetivo (un aliado o tú mismo) reciba daño físico o de los elementos.'],
251=>['Castigar curación','Conjuro con maleficio. Durante 30 segundos, cada vez que el enemigo objetivo sea sanado, el que lo cure recibirá 15...80 de daño sagrado.','Conjuro con maleficio. (30 segundos). Cada vez que el enemigo objetivo sea curado, el que lo haga recibirá 15...80 de daño sagrado.'],
252=>['Desvanecer','Conjuro. El enemigo objetivo recibe 20...65 de daño sagrado. Este conjuro hace el doble de daño a las criaturas invocadas.','Conjuro. Hace 20...65 de daño sagrado. Doble de daño a criaturas invocadas.'],
253=>['Castigar sacrificio','Conjuro con maleficio. Durante 8...20 segundos, cuando el enemigo objetivo y los adyacentes sacrifiquen vida, sacrificarán el doble de lo normal.','Conjuro con maleficio. También afecta a los enemigos adyacentes al objetivo (8...20 segundos). Dobla el sacrificio de salud.'],
254=>['Espíritu vigoroso','Conjuro con encantamiento. Durante 30 segundos, cada vez que el objetivo (un aliado o tú mismo) ataque o lance un conjuro, éste se curará 5...20 de salud.','Conjuro con encantamiento. (30 segundos). Cura 5...20 cada vez que el objetivo (un aliado o tú mismo) ataque o lance un conjuro.'],
255=>['Espíritu guardián','Conjuro con encantamiento. Mientras mantengas este encantamiento, el objetivo (un aliado o tú mismo) ganará +2 de regeneración de salud. Ese aliado se curará en 30...180 de salud cuando el Espíritu guardián termine.','Conjuro con encantamiento. +2 de regeneración de salud. Efecto final: cura 30...180 de salud.'],
256=>['Aura bendita','Conjuro con encantamiento. Mientras mantengas este encantamiento, los encantamientos de Monje que lances durarán un 10...35% más de lo normal.','Conjuro con encantamiento. Los encantamientos de Monje que lances duran un 10...35% más.'],
257=>['Égida','Conjuro con encantamiento. Durante 6...15 segundos, todos tus compañeros al alcance del oído tendrán un 50% de posibilidades de bloquear ataques.','Conjuro con encantamiento. Encanta a todos los miembros del grupo al alcance del oído (6...15 segundos.) 50% de posibilidades de bloquear.'],
258=>['Guardián','Conjuro con encantamiento. Durante 2...7 segundos, el objetivo (un aliado o tú mismo) tendrá un 50% de posibilidades de bloquear ataques.','Conjuro con encantamiento. (2...7 segundos). 50% de probabilidades de bloquear.'],
259=>['Escudo desviador','Conjuro con encantamiento de élite. Durante 3...10 segundos, el objetivo (un aliado o tú mismo) tiene un 75% de posibilidades de bloquear ataques y gana 15...30 de armadura.','Conjuro con encantamiento de élite. (3...10 segundos). 75% de probabilidades de bloquear. +15...30 de armadura.'],
260=>['Aura de fe','Conjuro con encantamiento de élite. Durante 3 segundos, el objetivo (un aliado o tú mismo) gana un 50...100% más de salud de las curaciones y recibe 5...50% menos de daño.','Conjuro con encantamiento de élite. (3 segundos). El objetivo (un aliado o tú mismo) gana un 50...100% más de salud de las curaciones y recibe 5...50% menos de daño.'],
261=>['Escudo de regeneración','Conjuro con encantamiento de élite. Durante 5...13 segundos, el aliado marcado gana +3...10 de regeneración de salud y 20...45 de armadura.','Conjuro con encantamiento de élite. (5...13 segundos). +3...10 de regeneración de salud y +20...45 de armadura.'],
262=>['Escudo del juicio','Conjuro con encantamiento de élite. Durante 8...20 segundos, todo el que golpee al objetivo (un aliado o tú mismo) será derribado y sufrirá 5...50 de daño sagrado.','Conjuro con encantamiento de élite. (8...20 segundos). Hace 5...50 de daño sagrado a los enemigos que ataquen al objetivo (un aliado o tú mismo). Causa derribo.'],
263=>['Vínculo de protección','Conjuro con encantamiento. Mientras mantengas este encantamiento, el objetivo (un aliado o tú mismo) no podrá perder más del 5% de salud máxima de un solo ataque o conjuro. Siempre que el Vínculo de protección evite daños, pierdes 6...3 de energía o el conjuro termina.','Conjuro con encantamiento. El objetivo (un aliado o tú mismo) no puede perder más del 5% del máximo de salud de un solo ataque o conjuro. Cada vez que se absorba daño, pierdes 6...3 de energía o este conjuro acaba.'],
264=>['Pacifismo','Conjuro con maleficio. Durante 4...8 segundos, el enemigo objetivo no puede atacar. Los efectos desaparecerán si el objetivo recibe daño.','Conjuro con maleficio. (4...8 segundos). El enemigo objetivo no puede atacar. Acaba si este enemigo recibe daño.'],
265=>['Concordia','Conjuro con maleficio de élite. Durante 4...12 segundos, los enemigos adyacentes no pueden atacar. La Concordia acabará para cada enemigo cuando éste reciba daño.','Conjuro con maleficio de élite. (4...12 segundos). Los enemigos adyacentes a tu ubicación no pueden atacar. Acaba en los enemigos que reciban daño.'],
266=>['Paz y armonía','Conjuro con encantamiento de élite. El aliado objetivo pierde 0...9 condición["condiciones"] y maleficios. Durante 1...3 segundos, las condiciones y maleficios que ese aliado tenga acaban un 90% antes. Todas tus plegarias de ataque quedan desactivadas durante 20 segundos.','Conjuro con encantamiento de élite. El aliado objetivo pierde 0...9 condición["condiciones"] y maleficios. Las condiciones y maleficios que ese aliado tenga acaban un 90% antes (1...3 segundos). Se desactivan tus plegarias de ataque (20 segundos).'],
267=>['Perspicacia del juez','Conjuro con encantamiento. Durante 8...20 segundos, los ataques del objetivo (un aliado o tú mismo) sólo hacen daño sagrado y tienen un +20% de penetración de armadura.','Conjuro con encantamiento. (8...20 segundos). Convierte los ataques del objetivo (un aliado o tú mismo) a daño sagrado y añade +20% de penetración de armadura.'],
268=>['Aura de persistencia','Conjuro con encantamiento de élite. Mientras mantengas este encantamiento, tus conjuros de Monje curan un +15...60% más de salud. Cuando este encantamiento acabe, un miembro muerto al azar del grupo resucita con toda la salud y energía y se teletransporta a tu ubicación.','Conjuro con encantamiento de élite. Tus conjuros de Monje curan un +15...60% más de salud. Efecto final: un miembro del grupo al azar resucita con toda la salud y energía y es teletransportado a tu ubicación.'],
269=>['Marca de protección','Conjuro con encantamiento de élite. Durante 10 segundos, siempre que el objetivo (un aliado o tú mismo) debería haber recidido daño, en lugar de eso se curará en esa cantidad de daño, siendo el máximo 6...60. Todas tus Plegarias de protección estarán desactivadas durante 5 segundos.','Conjuro con encantamiento de élite. (10 segundos). El daño recibido se convierte en curación (máximo 6...60). Todas tus plegarias de protección se desactivan (5 segundos).'],
270=>['Barrera de vida','Conjuro con encantamiento de élite. Mientras mantengas este encantamiento, el daño que el aliado objetivo reciba se reduce al 20...50%. Si tu salud está por debajo del 50% cuando ese aliado reciba daño, la Barrera de vida terminará.','Conjuro con encantamiento de élite. Reduce el daño un 20...50%. No se puede usar con uno mismo. Si tu salud está por debajo del 50% cuando el objetivo reciba daño, la Barrera de vida acaba.'],
271=>['Fuego del zelote','Conjuro con encantamiento. Durante 60 segundos, siempre que utilices una habilidad sobre un aliado, todos los enemigos adyacentes a dicho aliado reciben 5...35 de daño de fuego y tú pierdes 1 de energía.','Conjuro con encantamiento. (60 segundos). Siempre que utilices una habilidad con un aliado, todos los enemigos adyacentes a él reciben 5...35 de daño de fuego. Coste del daño: pierdes 1 de energía.'],
272=>['Aura de Balthazar','Conjuro con encantamiento. Durante 8 segundos, los enemigos adyacentes al objetivo (un aliado o tú mismo) recibirán 10...30 de daño sagrado por segundo.','Conjuro con encantamiento. (8 segundos). Hace 10...30 de daño sagrado por segundo a los enemigos adyacentes al objetivo aliado.'],
273=>['Rompeconjuros','Conjuro con encantamiento de élite. Durante 5...17 segundos, el aliado objetivo no puede ser objetivo de conjuros enemigos.','Conjuro con encantamiento de élite. (5...17 segundos). El enemigo no puede echar conjuros al objetivo (un aliado o tú mismo).'],
274=>['Semilla de curación','Conjuro con encantamiento. Si el aliado objetivo recibe daño durante los próximos 10 segundos, ese aliado y todos los adyacentes ganan 3...30 de salud.','Conjuro con encantamiento. (10 segundos). El objetivo y los aliados adyacentes ganan 3...30 de salud cada vez que este aliado reciba daño. No se puede usar con uno mismo.'],
275=>['Arreglar condición','Conjuro. Quita una condición (veneno, enfermedad, ceguera, aturdimiento, hemorragia, lisiadura, quemadura, debilidad, armadura rota o herida grave) del aliado objetivo. Si se quita una condición, el aliado recibe 5...70 de salud.','Conjuro. Elimina una condición. Efecto: cura 5...70 de salud. No te puedes apuntar a ti mismo.'],
276=>['Restaurar condición','Conjuro de élite. Quita todas las condiciones (veneno, enfermedad, ceguera, aturdimiento, hemorragia, lisiadura, quemadura, debilidad, armadura rota y herida grave) del aliado objetivo, que recuperará 10...70 de salud por cada una.','Conjuro de élite. Elimina todas las condiciones. Efecto: cura 10...70 de salud por cada condición eliminada. No te puedes apuntar a ti mismo.'],
277=>['Curar mal','Conjuro. Quita una condición (veneno, enfermedad, ceguera, aturdimiento, hemorragia, lisiadura, quemadura, debilidad, armadura rota o herida grave) del objetivo (otro aliado o tú mismo), que recuperará 5...70 de salud por cada condición que aún le quede.','Conjuro. Elimina una condición. Efecto de la eliminación: cura 5...70 de salud por cada condición restante.'],
278=>['Curar condiciones','Conjuro. Quita todas las condiciones (veneno, enfermedad, ceguera, aturdimiento, hemorragia, lisiadura, quemadura, debilidad, armadura rota y herida grave) del aliado objetivo.','Conjuro. Elimina todas las condiciones.'],
279=>['Curación divina','Conjuro. Tanto tú como los miembros del grupo al alcance del oído os curáis 15...60 de salud.','Conjuro. Tú y los miembros del grupo al alcance del oído os curáis 15...60 de salud.'],
280=>['Curar área','Conjuro. Tanto tú como todas las criaturas adyacentes os curáis 30...180 de salud.','Conjuro. Tú y los aliados y enemigos adyacentes os curáis 30...180 de salud.'],
281=>['Letanía de curación','Conjuro. Curas 30...80 de salud al objetivo (un aliado o tú mismo).','Conjuro. Cura 30...80 de salud.'],
282=>['Palabra de curación','Conjuro de élite. Curas 5...100 de salud al objetivo (un aliado o tú mismo). Curas 30...115 adicionales si la salud del aliado está por debajo del 50%.','Conjuro de élite. Cura 5...100 de salud. Cura 30...115 de salud extra si el objetivo (un aliado o tú mismo) está por debajo del 50% de salud.'],
283=>['Beso de Dwayna','Conjuro. Curas 20...65 de salud al aliado objetivo y 15...40 extra por cada encantamiento o maleficio que ése tenga.','Conjuro. Cura 20...65 de salud. 15...40 extra por cada encantamiento o maleficio que tenga el aliado objetivo. No te puedes apuntar a ti mismo.'],
284=>['Ayuda divina','Conjuro con encantamiento. Mientras mantengas este encantamiento, siempre que lances un conjuro de plegaria de protección o favor divino sobre un aliado, éste recuperará 15...60 de salud y tú perderás 1 de energía.','Conjuro con encantamiento. Cada vez que lances un conjuro de plegaria de protección o favor divino sobre un aliado, éste recuperará 15...60 de salud. Coste de la curación: perderás 1 de energía.'],
285=>['Manos sanadoras','Conjuro con encantamiento de élite. Durante 10 segundos, el aliado objetivo se curará en 5...35 de salud siempre que reciba daño.','Conjuro con encantamiento de élite. (10 segundos). Cura 5...35 de salud cada vez que el objetivo reciba daño.'],
286=>['Curar a otro','Conjuro. Curas 35...180 de salud al aliado objetivo.','Conjuro. Cura 35...180 de salud. No te puedes apuntar a ti mismo.'],
287=>['Curar grupo','Conjuro. Curas 30...75 de salud a todo el grupo.','Conjuro. Cura 30...75 de salud a todo el grupo.'],
288=>['Brisa curativa','Conjuro con encantamiento. Durante 15 segundos, el objetivo (un aliado o tú mismo) gana +4...9 de regeneración de salud.','Conjuro con encantamiento. (15 segundos). +4...9 de regeneración de salud.'],
289=>['Bendición vital','Conjuro con encantamiento. Mientras mantengas este encantamiento, el objetivo (un aliado o tú mismo) tendrá +40...200 de salud máxima.','Conjuro con encantamiento. +40...200 de máximo de salud.'],
290=>['Curación','Conjuro con encantamiento. Mientras mantengas este encantamiento, el objetivo (un aliado o tú mismo) ganará +1...4 de regeneración de salud.','Conjuro con encantamiento. +1...4 de regeneración de salud'],
291=>['Transferencia de salud','Conjuro con encantamiento. Mientras mantengas este encantamiento, siempre que el aliado objetivo golpee a un enemigo ganarás 2...17 de salud.','Conjuro con encantamiento. Ganas 2...17 de salud siempre que el objetivo (un aliado o tú mismo) golpee a un enemigo.'],
292=>['Infundir salud','Conjuro. Pierdes la mitad de tu salud actual. El aliado objetivo se cura el 100...136% de la cantidad que hayas perdido.','Conjuro. Cura el 100...136% de la mitad de tu salud actual. Pierdes la mitad de tu salud actual. No te puedes apuntar a ti mismo.'],
293=>['Sello de devoción','Sello. Curas 20...120 de salud al objetivo (un aliado o tú mismo).','Sello. Cura 20...120 de salud.'],
294=>['Sello del juicio','Sello de élite. Derribas al enemigo objetivo. Ese enemigo y todos los adyacentes reciben 15...75 de daño sagrado.','Sello de élite. Derriba al objetivo. Hace 15...75 de daño sagrado al enemigo objetivo y los adyacentes.'],
295=>['Sello de purga','Sello. Se quitan todos los maleficios y condiciones del objetivo (un aliado o tú mismo). Pierdes 10 de energía por cada maleficio y condición eliminada.','Sello. Elimina todos los maleficios y condiciones. Coste de la eliminación: 10 de energía cada una.'],
296=>['Sello de pesadilla','Sello. El enemigo objetivo recibe 30...60 de daño sagrado. Si estaba atacando, es derribado.','Sello. Hace 30...60 de daño sagrado. Causa derribo si el enemigo objetivo está atacando.'],
297=>['Sello bendito','Sello. Por cada encantamiento que mantengas, ganas 3 de energía. No puedes ganar más de 3...24 de energía de este modo.','Sello. Ganas 3 de energía por cada encantamiento que estés manteniendo. No puedes ganar más de 3...24 de energía de este modo.'],
298=>['Mártir','Conjuro de élite. Transfieres todas las condiciones de los aliados a ti mismo, que durarán el tiempo que les quedaba para terminar.','Conjuro de élite. Recibes todas las condiciones que tengan los aliados.'],
299=>['Manos protectoras','Conjuro con encantamiento. Durante 8 segundos, el daño y el robo de salud recibido por el aliado objetivo se reduce en 3...18. Cuando finaliza el efecto de Manos protectoras, el aliado recibe 5...50 de salud.','Conjuro con encantamiento. (8 segundos.) Reduce el daño y el robo de salud recibido en 3...18. Efecto final: cura 5...50 de salud.'],
300=>['Contemplación de pureza','Habilidad. Pierdes todos los encantamientos. Por cada uno que se pierda, ganas 0...80 de salud y pierdes un maleficio y una condición (máximo 1...8 maleficios y condiciones).','Habilidad. Ganas 0...80 de salud y pierdes un maleficio y una condición por cada encantamiento que tengas (máximo 1...8 maleficios y condiciones . Pierdes todos los encantamientos.'],
301=>['Quitar maleficio','Conjuro. Quita un maleficio del objetivo (un aliado o tú mismo).','Conjuro. Quita un maleficio del objetivo (un aliado o tú mismo).'],
302=>['Deshacer maleficio','Conjuro. Eliminas un maleficio del objetivo (un aliado o tú mismo). Al hacerlo, los enemigos en la zona sufren 10...85 de daño sagrado.','Conjuro. Elimina un maleficio del objetivo (un aliado o tú mismo). Efecto de la eliminación: 10...85 de daño sagrado a los enemigos dentro de la zona del objetivo.'],
303=>['Convertir maleficios','Conjuro. Quita todos los maleficios del aliado objetivo. Durante 8...20 segundos, ese aliado gana +10 de armadura por cada maleficio de Nigromante quitado.','Conjuro. Elimina todos los maleficios; +10 de armadura por cada maleficio de Nigromante eliminado (8...20 segundos). No te puedes apuntar a ti mismo.'],
304=>['Luz de Dwayna','Conjuro. Resucita a todos los miembros del grupo muertos de la zona. Vuelven a la vida con el 25% de salud y 0 puntos de energía.','Conjuro. Resucita a todos los miembros del grupo muertos de la zona (25% de salud y 0 de energía).'],
305=>['Resurrección','Conjuro. Resucita a un aliado, que vuelve a la vida con el 25% de salud y 0 puntos de energía.','Conjuro. Resucita al miembro del equipo (25% de salud, 0 de energía).'],
306=>['Renacimiento','Conjuro. Resucitas a un aliado con el 25% de salud y 0 puntos de energía, y lo teletransportas además a tu ubicación actual. Todas sus habilidades estarán desactivadas durante 10...3 segundos. Este conjuro utilizará el resto de tu energía.','Conjuro. Resucita al miembro del equipo objetivo (25% de salud, 0 de energía). Teletransportas al objetivo hasta tu ubicación. Desactiva sus habilidades (10...3 segundoss). Pierdes toda la energía.'],
307=>['Inversión de la fortuna','Conjuro con encantamiento. Durante 8 segundos, la próxima vez que al objetivo (un aliado o tú mismo) le hubieran hecho daño o robado vida, éste ganará esa cantidad de salud en lugar de perderla (máximo 15...80).','Conjuro con encantamiento. (8 segundos.) Convierte el siguiente daño o robo de salud recibido (máximo 15...80) en curación.'],
308=>['Auxilio','Conjuro con encantamiento. Mientras mantengas este encantamiento, el aliado objetivo ganará una regeneración de +1 de salud y de energía, pero perderás 1 de energía cada vez que ese aliado lance un conjuro.','Conjuro con encantamiento. +1 de regeneración de salud y +1 de regeneración de energía. No te puedes apuntar a ti mismo. Pierdes 1 de energía cada vez que el aliado objetivo lance un conjuro.'],
309=>['Velo sagrado','Conjuro con encantamiento. Mientras mantengas este encantamiento, los maleficios que echen sobre el objetivo (un aliado o tú mismo) tardarán el doble en invocarse. Cuando finalice el Velo sagrado, se quita un maleficio del objetivo.','Conjuro con encantamiento. Dobla el tiempo de lanzamiento de los maleficios sobre el objetivo (un aliado o tú mismo). Efecto final: elimina un maleficio.'],
310=>['Espíritu divino','Conjuro con encantamiento. Durante 1...14 segundos, lanzar conjuros de Monje te costará 5 menos de energía. (Coste mínimo: 1 de energía).','Conjuro con encantamiento. (1...14 segundos). Los conjuros de Monje te cuestan 5 menos de energía. Coste mínimo: 1 de energía.'],
311=>['Robar condiciones','Conjuro. Todas las condiciones negativas se transferirán del aliado objetivo a ti. Por cada condición que adquieras, ganas 6...26 de salud.','Conjuro. Transfiere todas las condiciones del aliado objetivo a ti mismo. Efecto: ganas 6...26 de salud por condición. No te puedes apuntar a ti mismo.'],
312=>['Golpe sagrado','Habilidad. El enemigo al que toques recibe 10...55 de daño sagrado. Si está derribado, recibirá 10...55 de daño sagrado extra.','Habilidad de toque. Hace 10...55 de daño sagrado. 10...55 de daño sagrado extra si el objetivo está derribado.'],
313=>['Toque curativo','Conjuro. Curas 20...80 de salud al aliado que toques. La salud recuperada con el Favor divino se dobla gracias a este conjuro.','Conjuro de toque. Cura 20...80 de salud. La salud recuperada con el favor divino se dobla para este conjuro.'],
314=>['Restaurar vida','Conjuro. Toca el cuerpo de un miembro caído del grupo. El miembro del grupo volverá a la vida con un 20...65% de salud y un 42...90% de energía.','Conjuro de toque. Resucita al miembro del equipo objetivo (20...65% de salud, 42...90% de energía).'],
315=>['Venganza','Conjuro con encantamiento. Devuelve la vida al aliado objetivo con la salud y energía al máximo. Durante 30 segundos, ese aliado hará un 25% más de daño pero morirá cuando este encantamiento termine. No se penalizará por resucitar si se muere bajo sus efectos.','Conjuro con encantamiento. (30 segundos). Resucita al miembro del equipo objetivo (con toda la salud y energía). Este aliado hace 25% más de daño y no sufre penalización por morir. Efecto final: este aliado muere.'],
316=>['¡Hasta el límite!','Grito. Por cada enemigo al alcance del oído (un máximo de 1...6), ganas un golpe de adrenalina. Durante 10...20 segundos, tu máximo de salud aumenta en 10...60.','Grito. (10...20 segundos). Tienes +10...60 de máximo de salud. Efecto inicial: ganas un golpe de adrenalina por cada enemigo al alcance del oído (máximo 1...6).'],
317=>['Furia de batalla','Actitud de élite. Durante 5...20 segundos, te mueves un 33% más rápido y ganas el doble de adrenalina de los ataques. La Furia de batalla termina si utilizas alguna habilidad que no sea de adrenalina.','Actitud de élite. (5...20 segundos). Te mueves un 33% más rápido y ganas el doble de adrenalina de tus ataques. Acaba si usas una habilidad que no sea de adrenalina.'],
318=>['Desafiar al dolor','Habilidad de élite. Durante 20 segundos, tienes 90...300 de salud adicional, 20 de armadura adicional y recibes -1...10 de daño.','Habilidad de élite. (20 segundos). Tienes +90...300 de salud máxima, +20 de armadura y recibes -1...10 menos de daño.'],
319=>['Aceleración','Actitud. Corres un 25% más rápido durante 8...20 segundos.','Actitud. (8...20 segundos). Te mueves un 25% más rápido.'],
320=>['Cortar tendón','Ataque con espada. Si este ataque impacta, tu objetivo pasará a estar lisiado durante 3...15 segundos, lo que reducirá su movimiento.','Ataque con espada. Causa lisiadura (3...15 segundos).'],
321=>['Golpe violento','Ataque cuerpo a cuerpo. Se pierde toda la adrenalina. Si impacta, este ataque será un golpe crítico y cualquier actitud que estaba usando el enemigo terminará. No se puede bloquear.','Ataque cuerpo a cuerpo. Siempre un golpe crítico. Elimina una actitud. No se puede bloquear. Pierdes toda la adrenalina.'],
322=>['Ataque poderoso','Ataque cuerpo a cuerpo. Este ataque hace +10...40 de daño si impacta.','Ataque cuerpo a cuerpo. Hace +10...40 de daño.'],
323=>['Golpe desesperado','Ataque cuerpo a cuerpo. Si este ataque impacta, harás +10...40 de daño y tu objetivo sufrirá una de las siguientes condiciones: herida grave (durante 20 segundos), debilidad (20 segundos), hemorragia (25 segundos) o lisiadura (15 segundos). Después del Golpe desesperado, caerás al suelo.','Ataque cuerpo a cuerpo. Hace +10...40 de daño. Causa una de estas condiciones al azar: herida grave (20 segundos), debilitamiento (20 segundos), hemorragia (25 segundos) o lisiadura (15 segundos). Eres derribado.'],
324=>['Emoción de la victoria','Ataque cuerpo a cuerpo. Si este ataque impacta, hace +20...40 de daño. Si tienes más salud que el enemigo objetivo, ganas 1...2 golpes de adrenalina.','Ataque cuerpo a cuerpo. Hace +20...40 de daño. Si tienes más salud que tu objetivo, ganas 1...2 de adrenalina.'],
325=>['Golpe de distracción','Ataque cuerpo a cuerpo. Golpeas con tu arma al objetivo, sin hacer daño pero interrumpiendo la acción que esté realizando (y las de los enemigos adyacentes).','Ataque cuerpo a cuerpo. También ataca a los enemigos adyacentes a tu objetivo. Interrumpe una acción. No haces daño.'],
326=>['Golpe del protector','Ataque cuerpo a cuerpo. Si este ataque golpea a un enemigo en movimiento, le harás 10...40 de daño adicional.','Ataque cuerpo a cuerpo. Hace +10...40 de daño si el objetivo se está moviendo.'],
327=>['Barrido del grifo','Ataque cuerpo a cuerpo. Si este ataque impacta, harás +5...20 de daño. Si se bloquea este ataque, tu objetivo es derribado y sufre 10...34 de daño.','Ataque cuerpo a cuerpo. Hace +5...20 de daño. Causa derribo y hace 10...34 de daño si se bloquea.'],
328=>['Golpe puro','Ataque con espada. Si el Golpe puro impacta, harás +1...30 de daño. Si no estás utilizando una actitud, no se podrá bloquear.','Ataque con espada. Hace +1...30 de daño. No se puede bloquear a menos que mantengas una actitud.'],
329=>['Rompecráneos','Ataque cuerpo a cuerpo de élite. Si este ataque impacta, interrumpirás la acción del enemigo objetivo. Si está lanzando un conjuro, quedará atontado durante 15 segundos.','Ataque cuerpo a cuerpo de élite. Interrumpe una acción. Causa la Atontamiento (15 segundos) si el objetivo está lanzando un conjuro.'],
330=>['Hacha ciclón','Ataque con hacha. Realizas un ataque de hacha giratorio contra todos los oponentes adyacentes que causa +4...12 de daño.','Ataque con hacha. Hace +4...12 de daño a todos los enemigos adyacentes.'],
331=>['Martillazo','Ataque con martillo. Se pierde toda la adrenalina. Si el Martillazo impacta, tu objetivo es derribado.','Ataque con martillo. Causa derribo. Pierdes toda la adrenalina.'],
332=>['Golpe del toro','Ataque cuerpo a cuerpo. Si este ataque impacta a un enemigo en movimiento, le harás +5...30 de daño y caerá al suelo.','Ataque cuerpo a cuerpo. Hace +5...30 daño. Causa derribo si el enemigo objetivo está en movimiento.'],
333=>['¡Os vengaré!','Grito. Por cada aliado muerto, durante 10 segundos la salud se regenera en +3...7 y atacas un 25% más deprisa.','Grito. Tienes +3...7 de regeneración de salud y atacas un 25% más deprisa (10 segundos por cada aliado muerto).'],
334=>['Barrido de hacha','Ataque con hacha. Si este ataque impacta a un enemigo que tenga una herida grave, harás +4...16 de daño, y ese enemigo quedará lisiado durante 15 segundos.','Ataque con hacha. Hace +4...16 de daño y causa lisiadura (15 segundos) si el enemigo objetivo tiene una herida grave.'],
335=>['Partir en dos','Ataque con hacha de élite. Si este ataque impacta, inflige +10...40 de daño y alcanza a 1...2 enemigos adyacentes provocándoles 10...40 de daño cortante.','Ataque con hacha de élite. Inflige +10...40 de daño y alcanza a 1...2 enemigos adyacentes provocándoles 10...40 de daño cortante.'],
336=>['Golpe del ejecutor','Ataque con hacha. Este ataque hace +15...45 de daño si impacta.','Ataque con hacha. Hace +15...45 de daño.'],
337=>['Desmembrar','Ataque con hacha. Si impacta, este hachazo causará una herida grave al enemigo objetivo, lo que reducirá la salud máxima de ese objetivo en 20% durante 5...20 segundos.','Ataque con hacha. Causa una herida grave (5...20 segundos).'],
338=>['Eviscerar','Ataque con hacha de élite. Si impacta, haces +10...45 de daño y causarás una herida grave, lo que reducirá el máximo de salud de tu objetivo en 20% durante 5...20 segundos.','Ataque con hacha de élite. Hace +10...45 de daño. Causa herida grave (5...20 segundos).'],
339=>['Golpe penetrante','Ataque con hacha. Si impacta, harás +10...25 de daño. Este ataque de hacha tiene un 20% de penetración de armadura.','Ataque con hacha. Hace +10...25 de daño. 20% de penetración de armadura.'],
340=>['Hachazo desbaratador','Ataque con hacha. Si impacta, este ataque interrumpe la acción actual del objetivo. Si esa acción era una habilidad, estará desactivada durante 20 segundos.','Ataque con hacha. Interrumpe una acción. Efecto: la habilidad interrumpida está desactivada durante +20 segundos.'],
341=>['Hachazo rápido','Ataque con hacha. Este ataque hace +1...20 de daño si impacta. Si se bloquea Hachazo rápido, el enemigo objetivo recibe 1...20 de daño y sufre una herida grave durante 20 segundos.','Ataque con hacha. Hace +1...20 de daño. 1...20 de daño y causa herida grave (20 segundos) si se bloquea.'],
342=>['Giro y hachazo','Ataque con hacha. Si este ataque impacta a un enemigo que tenga una herida grave, harás 5...25 más de daño y ese enemigo pasará a estar débil durante 20 segundos.','Ataque con hacha. Hace +5...25 de daño y causa debilitamiento (20 segundos) si el enemigo objetivo tiene una herida grave.'],
343=>['¡Por la justicia!','Grito. Durante 20 segundos, ganas un 100% más de adrenalina.','Grito. (20 segundos). Ganas 100% más de adrenalina.'],
344=>['Ráfaga','Actitud. Durante 5 segundos, tu velocidad de ataque se aumenta en un 33%, pero haces 25% menos de daño.','Actitud. (5 segundos). Atacas un 33% más deprisa. Haces un 25% menos de daño.'],
345=>['Actitud defensiva','Actitud. Durante 1...5 segundos, tienes un 75% de posibilidades de bloquear ataques cuerpo a cuerpo y proyectiles. Cuando la Actitud defensiva acabe, ganas un golpe de adrenalina por cada habilidad de ataque cuerpo a cuerpo que tengas (máximo 0...4).','Actitud. (1...5 segundos). Tienes un 75% de probabilidades de bloquear. Efecto final: ganas un golpe de adrenalina por cada habilidad de ataque cuerpo a cuerpo que tengas (máximo 0...4).'],
346=>['Frenesí','Actitud. Durante 8 segundos, atacas un 33 % más rápido, pero recibes 175...125 % de daño.','Actitud. (8 segundos). Atacas un 33 % más rápido. Recibes 175...125 % de daño.'],
347=>['Soportar el dolor','Habilidad. Durante 7...18 segundos tienes 90...300 de salud adicional.','Habilidad. (7...18 segundos). Tienes 90...300 de salud máxima.'],
348=>['¡Cuidado!','Grito. Los miembros del grupo al alcance del oído ganan +5...25 de armadura durante 10 segundos. Este grito acaba después de 10 ataques recibidos.','Grito. (10 segundos). Los miembros del grupo al alcance del oído tienen +5...25 de armadura. Acaba después de 10 ataques recibidos.'],
349=>['Propulsión','Actitud. Corres un 25% más rápido durante 8...14 segundos.','Actitud. (8...14 segundos). Te mueves un 25% más rápido.'],
350=>['Golpe de barriga','Ataque con martillo. Si este ataque golpea a un enemigo que esté derribado, la nube de polvo resultante cegará a los enemigos adyacentes durante 3...7 segundos.','Ataque con martillo. Causa ceguera a los enemigos adyacentes (3...7 segundos) si el enemigo objetivo está derribado.'],
351=>['Golpe poderoso','Ataque con martillo. Este ataque hace +10...40 de daño si impacta.','Ataque con martillo. Hace +10...40 de daño.'],
352=>['Golpe aplastante','Ataque con martillo. Si este ataque impacta, harás +1...20 de daño. Si golpeas a un enemigo caído, le harás una herida grave, lo que reducirá el máximo de salud de tu objetivo en un 20% durante 5...20 segundos.','Ataque con martillo. Hace +1...20 de daño. Causa herida grave si el enemigo objetivo está derribado (5...20 segundos).'],
353=>['Tajo brutal','Ataque con martillo. Ataca a todos los enemigos adyacentes. Cada enemigo al que alcances recibe +1...20 de daño.','Ataque con martillo. Hace +1...20 de daño a todos los enemigo adyacentes.'],
354=>['Temblor de tierra','Ataque con martillo de élite. El enemigo objetivo y todos los adyacentes caen al suelo. (50% de posibilidades de fallo con dominio del martillo 4 o inferior).','Ataque con martillo de élite. Causa derribo al enemigo objetivo y los adyacentes. 50% de probabilidades de fallar con un nivel de dominio del martillo inferior a 5.'],
355=>['Martillo devastador','Ataque con martillo de élite. Si el Martillo devastador impacta, tu objetivo es derribado y sufrirá debilidad durante 5...20 segundos.','Ataque con martillo de élite. Causa derribo. Causa debilitamiento (5...20 segundos).'],
356=>['Golpe brutal','Ataque con martillo. Si este ataque impacta, harás +5...20 de daño. Si se bloquea este ataque, tu objetivo es derribado y sufre 5...20 de daño.','Ataque con martillo. Hace +5...20 de daño. Hace 5...20 de daño y causa derribo si se bloquea.'],
357=>['Contraataque de martillo','Ataque con martillo. Si este ataque impacta a un objetivo que esté atacando, éste es derribado.','Ataque con martillo. Causa derribo si el enemigo objetivo está atacando.'],
358=>['Rompespaldas','Ataque con martillo de élite. Si el Rompespaldas impacta, haces +1...20 de daño y tu objetivo es derribado. Si tienes un nivel de fuerza 8 o superior, el derribo dura 4 segundos.','Ataque con martillo de élite. Hace +1...20 de daño. Causa derribo. Éste dura 4 segundos si tienes fuerza 8 o superior.'],
359=>['Golpe duro','Ataque con martillo. Se pierde toda la adrenalina. Si este ataque impacta a un enemigo que sufra debilidad, ese enemigo es derribado y harás +1...30 de daño.','Ataque con martillo. Hace +1...30 de daño y causa derribo si el enemigo objetivo está debilitado. Pierdes toda la adrenalina.'],
360=>['Golpe de desequilibrio','Ataque con martillo. Si este martillazo impacta, tu objetivo sufrirá debilidad durante 5...20 segundos.','Ataque con martillo. Causa debilitamiento (5...20 segundos).'],
361=>['Sello de Dolyak','Sello. Durante 8...20 segundos, tienes +10...40 de armadura y no te pueden derribar, pero tu movimiento se reduce en un 75%.','Sello. (8...20 segundos). Tienes +10...40 de armadura y no se te puede derribar. Te mueves un 75% más despacio.'],
362=>['Astucia del Guerrero','Habilidad. Durante 5...11 segundos, tus ataques de combate cuerpo a cuerpo no se pueden bloquear.','Habilidad. (5...11 segundos). Tus ataques cuerpo a cuerpo no se pueden bloquear.'],
363=>['Golpe de escudo','Habilidad. Durante 5...11 segundos, si estás llevando un escudo, bloquearás la siguiente habilidad de ataque cuerpo a cuerpo contra ti, tu atacante caerá derribado y esa habilidad quedará desactivada durante 15 segundos adicionales.','Habilidad. (5...11 segundos). Bloqueas la siguiente habilidad de ataque cuerpo a cuerpo. Causa derribo y +15 segundos de recarga. No funciona si no llevas un escudo.'],
364=>['¡Carga!','Grito de élite. Todos los aliados al alcance del oído dejan de estar lisiados. Durante 5...13 segundos, estos aliados se mueven un 33% más rápido.','Grito de élite. (5...13 segundos). Los aliados al alcance del oído se mueven un 33% más rápido. Efecto inicial: estos aliados dejan de estar lisiados.'],
365=>['¡La victoria es mía!','Grito de élite. Ganas 10...68 de salud y 3...7 de energía por cada condición que sufra el enemigo objetivo.','Grito de élite. Ganas 10...68 de salud y 3...7 de energía por cada condición que sufra el enemigo objetivo.'],
366=>['¡Temedme!','Grito. Todos los enemigos cercanos pierden 2...6 de energía. Durante 1...15 segundoss, tus ataques cuerpo a cuerpo tienen +5...30% de probabilidades de dar un golpe crítico contra enemigos parados.','Grito. (1...15 segundos). Tienes +5...30% de probabilidades de hacer un golpe crítico con ataques cuerpo a cuerpo contra enemigos parados. Efecto inicial: los enemigos cercanos pierden 2...6 de energía.'],
367=>['¡Alzad los escudos!','Grito. Durante 5...11 segundos, tú y los miembros del equipo al alcance del oído ganan +60 de armadura contra ataques con proyectil.','Grito. (5...11 segundos). Los miembros del equipo al alcance del oído tienen +60 de armadura contra ataques con proyectil.'],
368=>['¡Sobreviviré!','Grito. Ganas +3 de regeneración de salud por cada condición que sufras. Esta regeneración finaliza a los 5...11 segundos.','Grito. (5...11 segundos). Tienes +3 de regeneración de salud por cada condición que tengas.'],
370=>['Actitud berserker','Actitud. Durante 8...14 segundos, atacas un 33% más rápido y ganas un 100 % más de adrenalina. La Actitud Berserker finaliza si usas una habilidad.','Actitud. (8...14 segundos). Atacas un 33% más deprisa y ganas 100 % más de adrenalina. Acaba si usas una habilidad.'],
371=>['Actitud equilibrada','Actitud. Durante 8...20 segundos, no puedes ser derribado ni recibir daño extra de un ataque crítico.','Actitud. (8...20 segundos). No puedes ser derribado ni recibir daño extra de golpes críticos.'],
372=>['Defensa del gladiador','Actitud de élite. Durante 5...11 segundos, tienes un 75% de posibilidades de bloquear los ataques que te hagan. Siempre que bloquees de este modo un ataque cuerpo a cuerpo, el atacante sufrirá 5...35 de daño.','Actitud de élite. (5...11 segundos). Tienes un 75% de posibilidades de bloquear. Tu atacante recibe 5...35 de daño cuando bloquees un ataque cuerpo a cuerpo de esta forma.'],
373=>['Desviar flechas','Actitud. Durante 1...6 segundos, tienes un 75% de posibilidades de bloquear ataques. Si bloqueas un ataque con proyectil, los enemigos adyacentes sufren una hemorragia durante 5...15 segundos.','Actitud. (1...6 segundos). Tienes un 75% de probabilidades de bloquear ataques. Los enemigos adyacentes sufren una hemorragia (5...15 segundos) si bloqueas un ataque con proyectil.'],
374=>['Fortaleza del Guerrero','Habilidad de élite. Durante 5...35 segundos, ganas 3 de energía cada vez que golpees cuerpo a cuerpo. La Fortaleza del Guerrero no puede aumentar tu energía por encima de 10...25.','Habilidad de élite. (5...35 segundos). Ganas 3 de energía cada vez que golpees en combate cuerpo a cuerpo.No ganas energía si tienes más de 10...25.'],
375=>['Actitud de batalla de enano','Actitud de élite. Durante 5...11 segundos, si llevas un martillo, atacas un 33% más deprisa, ganas +40 de armadura y tus habilidades de ataque interrumpen a los enemigos si los alcanzas.','Actitud de élite. (5...11 segundos). Atacas un 33% más deprisa, ganas +40 de armadura y tus habilidades de ataque interrumpen acciones. No tiene efecto a menos que lleves un martillo.'],
376=>['Actitud disciplinada','Actitud. Durante 1...4 segundos, ganas +10 de armadura y tienes un 75% de probabilidades de bloquear ataques. La Actitud disciplinada finaliza si utilizas una habilidad de adrenalina.','Actitud. (1...4 segundos.) Tienes un 75% de probabilidades de bloquear y +10 de armadura. Termina si utilizas una habilidad de adrenalina.'],
377=>['Actitud precavida','Actitud. Durante 1...6 segundos, bloqueas todas las habilidades de ataque que se utilicen contra ti. Por cada una que detengas, ganas adrenalina y 5 de energía. La Actitud precavida finaliza si utilizas una habilidad.','Actitud. (1...6 segundos). Bloqueas habilidades de ataque. Ganas adrenalina y 5 de energía por cada bloqueo. Acaba si usas una habilidad.'],
378=>['Actitud protectora','Actitud. Durante 1...6 segundos, mientras lleves un escudo, tienes un 75% de probabilidades de bloquear y el daño se reduce en 2 por cada rango de fuerza (15 de reducción máxima de daño).','Actitud. (1...6 segundos). Tienes un 75% de probabilidades de bloquear. El daño se reduce en 2 por cada rango de fuerza (15 de reducción máxima de daño). No tiene efecto a menos que lleves un escudo.'],
379=>['Carga de toro','Actitud de élite. Durante 1...7 segundos, te mueves un 50 % más rápido y, si golpeas a un enemigo en movimiento cuerpo a cuerpo, será derribado. La Carga de toro finaliza si utilizas una habilidad.','Actitud de élite. (1...7 segundos). Te mueves un 50 % más deprisa. Causa derribo si golpeas cuerpo a cuerpo a un enemigo moviéndose. Acaba si usas una habilidad.'],
380=>['Defensa de Bonetti','Actitud. Durante 5...11 segundos, tienes un 75% de posibilidades de bloquear ataques cuerpo a cuerpo y con proyectiles. Ganas 5 de energía por cada ataque cuerpo a cuerpo bloqueado. La Defensa de Bonetti finaliza si utilizas una habilidad.','Actitud. (5...11 segundos). Tienes un 75% de probabilidades de bloquear. Ganas 5 de energía por cada ataque cuerpo a cuerpo bloqueado. Acaba si usas una habilidad.'],
381=>['Cien espadas','Habilidad de élite. Durante 15 segundos, siempre que ataques con una espada, todos los enemigos adyacentes reciben 10...35 de daño perforante.','Habilidad de élite. (15 segundos.) Hace 10...35 de daño cortante a todos los enemigos que se encuentren a tu alrededor al atacar con una espada.'],
382=>['Cortar arteria','Ataque con espada. Si este ataque impacta, el oponente sufrirá una hemorragia durante 5...25 segundos, lo que le hará ir perdiendo salud.','Ataque con espada. Causa hemorragia (5...25 segundos).'],
383=>['Tajo de Galrath','Ataque con espada. Este ataque hace +1...40 de daño si impacta.','Ataque con espada. Hace +1...40 de daño.'],
384=>['Corte profundo','Ataque con espada. Si este ataque impacta a un enemigo con una hemorragia, haces 5...20 más de daño y el enemigo sufrirá una herida grave, lo que reducirá el máximo de su salud en 20% durante 5...20 segundos.','Ataque con espada. Hace +5...20 de daño y causa una herida grave (5...20 segundos) si el objetivo sufre hemorragia.'],
385=>['Estocada final','Ataque con espada. Se pierde toda la adrenalina. Si la Estocada final impacta, harás 5...40 más de daño. El daño se dobla si el objetivo tenía menos del 50% de salud.','Ataque con espada. Hace +5...40 de daño. +5...40 de daño extra si el enemigo objetivo está por debajo del 50% de salud. Pierdes toda la adrenalina.'],
386=>['Cuchillada precisa','Ataque con espada. Si este ataque impacta, harás +1...20 de daño. Si se bloquea este ataque, tu objetivo sufrirá una hemorragia durante 25 segundos y recibirá 1...20 de daño.','Ataque con espada. Hace +1...20 de daño. Hace 1...20 de daño y causa hemorragia (25 segundos) si se bloquea.'],
387=>['Estocada','Habilidad. Durante 8 segundos, mientras empuñes una espada, bloquearás el próximo ataque cuerpo a cuerpo contra ti, y tu atacante recibirá 20...80 de daño.','Habilidad. (8 segundos). Bloqueas el próximo ataque cuerpo a cuerpo contra ti y tu atacante recibe 20...80 de daño. No funciona si no llevas una espada.'],
388=>['Estocada mortal','Habilidad. Durante 8 segundos, mientras empuñes una espada, bloquearás el próximo ataque cuerpo a cuerpo contra ti, y tu atacante sufrirá 15...90 de daño y una hemorragia durante 3...25 segundos.','Habilidad. (8 segundos). Bloqueas el próximo ataque cuerpo a cuerpo contra ti y tu atacante recibe 15...90 de daño. Causa hemorragia (3...25 segundos). No funciona si no llevas una espada.'],
389=>['Blandir','Habilidad de élite. Todas tus habilidades de ataque pasarán a estar recargadas. Ganas 2...7 de energía por cada habilidad que recargues con Blandir.','Habilidad de élite. Recarga tus habilidades de ataque. Ganas 2...7 de energía por cada habilidad recargada.'],
390=>['Tajo salvaje','Ataque con espada. Si este ataque impacta, interrumpe la acción del enemigo objetivo. Si la acción era un conjuro, haces 1...40 de daño adicional.','Ataque con espada. Interrumpe una acción. Efecto de la interrupción: +1...40 de daño si la acción era un conjuro.'],
391=>['Disparo del cazador','Ataque con arco. Si el Disparo del cazador impacta, el objetivo sufrirá una hemorragia durante 3...25 segundos.','Ataque con arco. Causa hemorragia (3...25 segundos).'],
392=>['Inmovilizar','Ataque con arco. Si Inmovilizar impacta, tu objetivo quedará lisiado durante 3...15 segundos.','Ataque con arco. Causa lisiadura (3...15 segundos).'],
393=>['Disparo lesionador','Ataque con arco de élite. Si el Disparo lesionador impacta, tu objetivo quedará lisiado durante 4...14 segundos. Este ataque no puede bloquearse.','Ataque con arco de élite. No se puede bloquear. Causa lisiadura (4...14 segundos).'],
394=>['Disparo poderoso','Ataque con arco. Si el Disparo poderoso impacta, el enemigo objetivo recibe +25...50 de daño.','Ataque con arco. El enemigo objetivo recibe 25...50 de daño.'],
395=>['Descarga de flechas','Ataque con arco de élite. Se eliminan todas tus preparaciones. Disparas flechas al enemigo objetivo y a un máximo de 5 enemigos adyacentes a él. Estas flechas hacen +5...20 de daño si impactan.','Ataque con arco de élite. Hace +5...20 de daño. Golpea a 5 enemigos adyacentes a tu objetivo. Se eliminan todas tus preparaciones.'],
396=>['Disparo doble','Ataque con arco. Disparas dos flechas simultáneamente al enemigo objetivo. Estas flechas hacen un 25% menos de daño.','Ataque con arco. Disparas dos flechas simultáneamente al enemigo objetivo. Estas flechas hacen un 25% menos de daño.'],
397=>['Disparo rápido','Ataque con arco de élite. Lanzas una flecha que vuela el doble de rápido.','Ataque con arco de élite. Lanzas una flecha que vuela el doble de rápido.'],
398=>['Ataque penetrante','Ataque con arco. Si el Ataque penetrante golpea al enemigo, le harás +5...25 de daño. Tiene un 10% de penetración de armadura.','Ataque con arco. Hace +5...25 de daño. 10% de penetración de armadura.'],
399=>['Disparo de distracción','Ataque con arco. Si el Disparo de distracción impacta, interrumpe la acción del enemigo pero hace sólo 1...16 de daño. Si la acción interrumpida era una habilidad, ésta estará desactivada durante 20 segundos adicionales.','Ataque con arco. Interrumpe una acción. Efecto: la habilidad interrumpida está desactivada durante +20 segundos. Sólo hace 1...16 de daño.'],
400=>['Disparo preciso','Ataque con arco. Si el Disparo preciso impacta, harás +3...10 de daño. El Disparo preciso no puede bloquearse. Esta acción se interrumpe con facilidad.','Ataque con arco. Hace +3...10 de daño. No se puede bloquear. Se te puede interrumpir con facilidad.'],
402=>['Disparo definido','Ataque con arco. Harás +5...20 de daño si golpeas al enemigo. Si este ataque falla, todas tus habilidades de ataque se recargarán.','Ataque con arco. Hace +5...20 de daño. Se recargan todas tus habilidades de ataque si falla.'],
403=>['Disparo veloz','Ataque con arco. Disparas una flecha que se mueve 3 veces más rápido de lo normal y no se puede bloquear.','Ataque con arco. Lanzas una flecha que vuela el triple de rápido. No se puede bloquear.'],
404=>['Flecha envenenada','Ataque con arco de élite. Si la Flecha envenenada impacta, tu objetivo estará envenenado durante 5...20 segundos.','Ataque con arco de élite. Causa envenenamiento (5...20 segundos).'],
405=>['Disparo de promesa','Ataque con arco de élite. Si el Disparo de promesa impacta, todas tus habilidades se recargan excepto Disparo de promesa. Si falla, todas tus habilidades se desactivan durante 10...4 segundos. (50% de probabilidades de fallar con Pericia 7 o menos.)','Ataque con arco de élite. Recarga todas las habilidades excepto Disparo de promesa si impacta. Desactiva todas las habilidades si falla (10...4 segundos). 50% de posibilidad de fallo sin Precisión 8 o superior.'],
406=>['Disparo debilitador','Ataque con arco. Si el Disparo debilitador impacta, tu objetivo pierde 1...10 de energía.','Ataque con arco. Pérdida de 1...10 de energía.'],
407=>['Disparo a quemarropa','Ataque con arco. Disparas una flecha que tiene la mitad de alcance, pero que hace +10...40 de daño.','Ataque con arco con mitad de alcance. Hace +10...40 de daño.'],
408=>['Conmoción','Ataque con arco. Si la Conmoción impacta mientras el enemigo objetivo está lanzado un conjuro, éste se interrumpe y tu objetivo quedará aturdido durante 5...20 segundos. Este ataque hace sólo 1...16 de daño.','Ataque con arco. Interrumpe un conjuro. Efecto de la interrupción: causa aturdimiento (5...20 segundos). Solo hace 1...16 de daño.'],
409=>['Disparo de castigo','Ataque con arco de élite. Si Disparo de castigo impacta, haces +10...20 de daño y tu objetivo es interrumpido.','Ataque con arco de élite. Hace +10...20 de daño. Interrumpe una acción.'],
411=>['Encantar animal','Habilidad. Encantar al animal objetivo. Una vez encantado, tu compañero animal viajará contigo siempre que tengas equipado Encantar animal. No es posible encantar animales que estén más de 4 niveles por encima del personaje.','Habilidad. Encantar al animal objetivo. Una vez encantado, tu compañero animal viajará contigo siempre que tengas equipado Encantar animal. No es posible encantar animales que estén más de 4 niveles por encima del personaje.'],
412=>['Llamada de protección','Grito. Durante 120 segundos, tu compañero animal tendrá una reducción del daño base de 5...20.','Grito. (120 segundos). Tu mascota tiene una reducción del daño de 5...20.'],
415=>['Llamada de celeridad','Grito. Durante 30 segundos, tu mascota ataca un 33% más rápido y se mueve un 33% más deprisa.','Grito. (30 segundos.) Tu mascota se mueve y ataca un 33% más rápido.'],
422=>['Revivir animal','Habilidad. Resucita a todos los compañeros animales aliados cercanos, que vuelven a la vida con el 10...94 % de salud.','Habilidad. Resucita a todas las mascotas aliadas en la zona (10...94 % de salud).'],
423=>['Vínculo simbiótico','Grito. Durante 120...300 segundos, tu animal compañero gana 1...3 de regeneración de salud y la mitad de todo el daño que reciba tu animal lo recibes tú en su lugar.','Grito. (120...300 segundos). Tu mascota tiene +1...3 de regeneración de salud. La mitad de todo el daño que reciba tu mascota lo recibes tú en su lugar.'],
424=>['Arrojar tierra','Habilidad. El enemigo al que toques y todos los adyacentes se quedarán ciegos durante 3...15 segundos.','Habilidad de toque. Causa ceguera (3...15 segundos). También afecta a los enemigos adyacentes al enemigo objetivo.'],
425=>['Esquiva','Actitud. Durante 5...11 segundos, te mueves un 33% más rápido y tienes un 27...75% de posibilidad de bloquear los proyectiles que te lancen. La esquiva finaliza si atacas.','Actitud. (5...11 segundos). Te mueves un 33% más rápido y tienes un 27...75% de probabilidades de bloquear ataques con proyectiles. Acaba si atacas.'],
426=>['Disparo violento','Ataque con arco. Si el Disparo violento impacta, interrumpes la acción del enemigo objetivo. Si la acción era un conjuro, haces +13...28 de daño.','Ataque con arco. Interrumpe una acción. Efecto de la interrupción: +13...28 de daño si la acción era un conjuro.'],
427=>['Sello de antídoto','Sello. Te curas de veneno, enfermedad, ceguera y una condición adicional.','Sello. Cura veneno, enfermedad, ceguera y una condición adicional.'],
428=>['Flechas incendiarias','Ataque con arco de élite. Disparas flechas al enemigo objetivo y a un máximo de 2 enemigos cercanos a él, que arderán durante 1...3 segundos.','Ataque con arco de élite. Alcanza a 2 enemigos cercanos a tu objetivo y causa quemadura (1...3 segundos).'],
429=>['Flechas de Melandru','Preparación["Preparaciones"] de élite. Durante 18 segundos, tus flechas causan una hemorragia durante 3...25 segundos y hacen +8...28 de daño si impactan en un objetivo que esté bajo un encantamiento.','Preparación["Preparaciones"] de élite. (18 segundos). Tus flechas causan hemorragia (3...25 segundos) y hacen +8...28 de daño a enemigos encantados.'],
430=>['Apuesta del tirador','Preparación["Preparaciones"] de élite. Durante 18 segundos, ganas 5...10 de energía siempre que tus flechas impacten, pero pierdes 10 de energía siempre que fallen.','Preparación["Preparaciones"] de élite. (18 segundos). Ganas 5...10 de energía cada vez que tus flechas alcancen a un enemigo. Pierdes 10 de energía si fallas.'],
431=>['Flechas inflamables','Preparación["Preparaciones"]. Durante 24 segundos, tus flechas explotan al contacto, haciendo 3...18 de daño de fuego al enemigo objetivo y los adyacentes.','Preparación["Preparaciones"]. (24 segundos). Tus flechas hacen 3...18 de daño de fuego al enemigo objetivo y los adyacentes.'],
432=>['Medir el viento','Preparación["Preparaciones"]. Durante 24 segundos, tus flechas se mueven el doble de rápido de lo normal y hacen 3...10 de daño adicional.','Preparación["Preparaciones"]. (24 segundos). +3...10 de daño. Tus flechas se mueven el doble de rápido.'],
433=>['Flechas en llamas','Preparación["Preparaciones"]. Durante 24 segundos, tus flechas hacen daño de fuego además de hacer 3...24 de daño de fuego adicional.','Preparación["Preparaciones"]. (24 segundos). +3...24 de daño de fuego. Tus flechas hacen daño de fuego.'],
434=>['Gas asfixiante','Preparación["Preparaciones"]. Durante 1...12 segundos, tus flechas hacen 1...8 de daño adicional y dispersan un gas asfixiante al impactar en los enemigos adyacentes. Este gas interrumpe a los enemigos que intenten lanzar conjuros.','Preparación["Preparaciones"]. (1...12 segundos). +1...8 de daño. Propagas gas asfixiante a los enemigos adyacentes al objetivo. El gas interrumpe conjuros.'],
435=>['Aplicar veneno','Preparación["Preparaciones"]. Durante los 24 segundos que dura esta habilidad, los enemigos a los que alcancen tus ataques físicos quedan envenenados durante 3...15 segundos.','Preparación["Preparaciones"]. (24 segundos). Tus ataques físicos causan envenenamiento (3...15 segundos).'],
436=>['Confortar animal','Habilidad. Curas 40...120 de salud a tu mascota animal. Si está muerta, la resucitarás con 10...58% de salud. Si tienes equipado Confortar animal, tu mascota viajará contigo.','Habilidad. Tu mascota gana 40...120 de salud. Resucita a tu mascota (10...58% de salud). Si tienes equipado Confortar animal, tu mascota viajará contigo.'],
437=>['Ataque bestial','Ataque con mascota. El siguiente ataque de tu mascota será el Ataque bestial, que causa +5...20 de daño. Si consigue golpear a un enemigo lanzando un conjuro, será derribado.','Ataque con mascota. Hace +5...20 de daño. Causa derribo si el enemigo objetivo está lanzando un conjuro.'],
438=>['Ataque mutilador','Ataque con mascota. Con el Ataque mutilador, tu compañero animal hará +5...20 de daño. Si el golpe impacta, ese enemigo quedará lisiado durante 3...15 segundos.','Ataque con mascota. Inflige 5...20 de daño. Lisia (3...15 segundos) al impactar.'],
439=>['Embestida animal','Ataque con mascota. El siguiente ataque de tu mascota será la Embestida animal, que causa +5...35 de daño. Si golpea a un enemigo atacando, sufrirá una hemorragia durante 5...25 segundos.','Ataque con mascota. Hace 5...35 de daño. Causa hemorragia si el enemigo objetivo está atacando (5...25 segundos).'],
440=>['Golpe carroñero','Ataque con mascota. Con el Golpe carroñero tu compañero animal hará +10...25 de daño. Si el ataque alcanza a un enemigo que esté sufriendo una condición, ganas 3...15 de energía.','Ataque con mascota. Hace +10...25 de daño. Ganas 3...15 de energía si el enemigo objetivo tiene alguna condición.'],
441=>['Salto de Melandru','Ataque con mascota. Tu mascota hará un Salto de Melandru que causa +5...20 de daño a todos los enemigos cercanos.','Ataque con mascota. Causa +5...20 de daño a los enemigos cercanos.'],
442=>['Ataque feroz','Ataque con mascota de élite. Con el Ataque feroz tu compañero animal hará +13...28 de daño. Si el ataque impacta, ganarás adrenalina y 3...10 de energía.','Ataque con mascota de élite. Hace +13...28 de daño. Ganas adrenalina y 3...10 de energía.'],
443=>['Salto de depredador','Ataque con mascota. Con el Salto de depredador tu compañero animal hará +5...35 de daño y ganará 5...50 de salud cuando golpee al enemigo.','Ataque con mascota. Hace +5...35 de daño. Tu mascota gana 5...50 de salud si este ataque impacta.'],
444=>['Ataque brutal','Ataque con mascota. Con el Ataque brutal tu compañero animal hará +5...35 de daño. Si el ataque alcanza a un enemigo cuya salud esté por debajo del 50%, recibirá +5...35 de daño extra.','Ataque con mascota. Hace +5...35 de daño. +5...35 de daño extra si el enemigo objetivo está por debajo del 50% de salud.'],
445=>['Embestida','Ataque con mascota. Con la Embestida tu compañero animal hará +1...12 de daño. Si el ataque alcanza a un enemigo que esté usando una habilidad, ésta se interrumpirá y está desactivada durante 20 segundos.','Ataque con mascota. Hace +1...12 de daño. Interrumpe una habilidad. Efecto: la habilidad interrumpida está desactivada durante +20 segundos.'],
446=>['Ungüento de Troll','Habilidad. Durante 13 segundos, ganas +3...10 de regeneración de salud.','Habilidad. (13 segundos). Tienes +3...10 de regeneración de salud.'],
447=>['Grito de Otyugh','Grito. Durante 10...25 segundos, tu compañero animal gana +24 de armadura y no se le puede bloquear.','Grito. (10...25 segundos). Tu mascota tiene +24 de armadura y no la pueden bloquear.'],
448=>['Escape','Actitud de élite. Durante 1...8 segundos, te mueves un 33% más rápido y tienes un 75% de posibilidades de bloquear ataques.','Actitud de élite. (1...8 segundos). Te mueves un 33% más rápido y tienes un 75% de posibilidades de bloquear.'],
449=>['Actitud de preparación','Actitud de élite. Durante 20...35 segundos, tus preparaciones se recargarán un 50% más rápido y durarán un 30...300% más.','Actitud de élite. (20...35 segundos). Tus preparaciones se recargan un 50% más rápido y duran un 30...300% más.'],
450=>['Torbellino defensivo','Actitud. Durante 8...20 segundos, tienes un 75% de posibilidades de bloquear ataques. Si consigues bloquear un proyectil, los enemigos adyacentes recibirán 5...11 de daño.','Actitud. (8...20 segundos). Tienes un 75% de posibilidades de bloquear. Haces 5...11 de daño a los enemigos adyacentes cuando bloquees un ataque con proyectil.'],
451=>['Resistencia de Melandru','Actitud de élite. Durante 8...20 segundos, ganas una regeneración de salud de +4 y de +1 de energía por cada condición y maleficio que sufras.','Actitud de élite. (8...20 segundos.) Tienes una regeneración de salud de +4 y de +1 de energía por cada condición y maleficio que te hayan echado.'],
452=>['Defensas de arácnido','Actitud. Durante 5...11 segundos, ganas un 75% de posibilidades de bloquear ataques y 34...60 de armadura contra daño elemental.','Actitud. (5...11 segundos). Tienes 75% de posibilidades de bloquear y +34...60 de armadura contra daño de los elementos.'],
453=>['Reflejos felinos','Actitud. Durante 5...11 segundos, tienes un 75% de posibilidades de bloquear ataques cuerpo a cuerpo y proyectiles, y atacarás un 33% más deprisa.','Actitud. (5...11 segundos). Atacas un 33% más rápido y tienes un 75% de posibilidades de bloquear.'],
454=>['Furia del tigre','Actitud. Todas tus habilidades que no sean de ataque estarán desactivadas durante 5 segundos. Durante 5...11 segundos, atacas un 25% más rápido.','Actitud. (5...11 segundos). Atacas un 25% más deprisa. Tus otras habilidades que no son de ataque quedan desactivadas (5 segundos).'],
455=>['Cazador de tormentas','Actitud. Durante 8...20 segundos, te moverás un 25% más rápido y obtendrás 1...5 de energía cada vez que recibas daños elementales.','Actitud. (8...20 segundos). Te mueves un 25% más rápido y ganas 1...5 de energía cada vez que recibas daños de los elementos.'],
456=>['Rapidez de la serpiente','Actitud. Durante 15...30 segundos, los tiempos de recarga de tus habilidades se reducen en un 33%. La Rapidez de la serpiente termina si tu salud está por debajo del 50%.','Actitud. (15...30 segundos). Tus habilidades se recargan un 33% más deprisa. Acaba si tu salud cae por debajo del 50%.'],
457=>['Trampa de polvo','Trampa. Cuando se active esta trampa, por cada segundo que pase (5 en total), todos los enemigos cercanos se quedarán ciegos durante 3...8 segundos y recibirán 10...25 de daño. Cuando actives esta habilidad, se te podrá interrumpir con facilidad. La Trampa de polvo dura 90 segundos.','Trampa. (90 segundos). Afecta a los enemigos cercanos. Hace 10...25 de daño por segundo (5 segundos). Causa ceguera (3...8 segundos) por segundo (5 segundos). Se puede interrumpir con facilidad.'],
458=>['Trampa de espinas','Trampa. Cuando se activa esta trampa, todos los enemigos del área reciben 7...23 de daño perforante, quedarán lisiados y sufrirán una hemorragia durante 3...25 segundos. La Trampa de espinas dura 90 segundos. Cuando actives esta habilidad, se te podrá interrumpir con facilidad.','Trampa. (90 segundos). Afecta a los enemigos cercanos. Hace 7...23 de daño perforante. Causa lisiadura y hemorragia (3...25 segundos). Se puede interrumpir con facilidad.'],
459=>['Trampa de fuego','Trampa. Cuando se active esta trampa, por cada segundo que pase (3 en total) todos los enemigos del área reciben 5...20 de daño de fuego y arden durante 1...3 segundos. La Trampa de fuego se desactiva a los 90 segundos. Cuando la estés colocando, se te podrá interrumpir con facilidad.','Trampa. (90 segundos). Afecta a los enemigos cercanos. Hace 5...20 de daño de fuego por segundo (3 segundos). Causa quemadura (1...3 segundos). Se puede interrumpir con facilidad.'],
460=>['Manantial de curación','Trampa. Durante 10 segundos, los aliados adyacentes se curan 15...60 de salud cada 2 segundos. Se te podrá interrumpir con facilidad mientras estés activando esta habilidad.','Trampa. (10 segundos). Afecta a los aliados adyacentes. Cura 15...60 de salud cada 2 segundos. Se puede interrumpir con facilidad.'],
461=>['Trampa de pinchos','Trampa de élite. Cuando se activa esta trampa, cada segundo (durante 2 en total) todos los enemigos cercanos reciben 10...40 de daño perforante, quedan lisiados durante 3...25 segundos y son derribados. La Trampa de pinchos dura 90 segundos. Se te podrá interrumpir con facilidad mientras la estés colocando.','Trampa de élite. (90 segundos). Afecta a los enemigos cercanos. Cada segundo (durante 2 en total), esta trampa hace 10...40 de daño perforante, causa derribo y causa lisiadura (3...25 segundos). Se puede interrumpir con facilidad.'],
462=>['Invierno','Ritual de la naturaleza. Creas un espíritu de nivel 1...10. Las criaturas que estén en su zona recibirán daño frío en vez de daño elemental. Morirá a los 30...240 segundos.','Ritual de la naturaleza. Crea un espíritu de nivel 1...10 (30...240 segundos de vida). Convierte a daño frío el daño de los elementos que reciban las criaturas de la zona. No afecta a los espíritus.'],
463=>['Aventamiento','Ritual de la naturaleza. Creas un espíritu de nivel 1...10. Las criaturas no espíritus que estén en su zona recibirán 4 puntos de daño adicional cada vez que reciban daño físico. Morirá a los 30...240 segundos.','Ritual de la naturaleza. Creas un espíritu de nivel 1...10 (30...240 segundos de vida). Aumenta el daño físico en +4 de las criaturas de la zona. No afecta a los espíritus.'],
464=>['Filo de extinción','Ritual de la naturaleza. Creas un espíritu de nivel 1...10. Si alguna criatura no espíritu muere dentro de su zona, el Filo de extinción hará 14...50 de daño a todas las criaturas del mismo tipo que estén por debajo del 90% de salud y dentro de su zona. El espíritu morirá a los 30...240 segundos.','Ritual de la naturaleza. Crea un espíritu de nivel 1...10 (30...240 segundos de vida). Hace 14...50 de daño a las criaturas de la zona siempre que alguna del mismo tipo muera. No afecta a los espíritus. No afecta a las criaturas por encima del 90% de salud.'],
465=>['Gran conflagración','Ritual de la naturaleza de élite. Creas un espíritu de nivel 1...10. Las criaturas no espíritus que estén en su zona recibirán daño de fuego en vez de daño físico. Morirá a los 30...240 segundos.','Ritual de la naturaleza de élite. Crea un espíritu de nivel 1...10 (30...240 segundos de vida). Convierte a daño de fuego el daño físico que reciban las criaturas de la zona. No afecta a los espíritus.'],
466=>['Conflagración','Ritual de la naturaleza. Creas un espíritu de nivel 1...10. Las criaturas no espíritus que estén en su zona recibirán daño de fuego cuando sean alcanzados por flechas. Morirá a los 30...240 segundos.','Ritual de la naturaleza. Crea un espíritu de nivel 1...10 (30...240 segundos de vida). Todas las flechas que disparen las criaturas de la zona hacen daño de fuego. No afecta a los espíritus.'],
467=>['Temporada de fertilidad','Ritual de la naturaleza. Creas un espíritu de nivel 1...10. Las criaturas no espíritus que estén en su zona tendrán +50...150 de salud máxima y +8 de armadura. Morirá a los 15...90 segundos.','Ritual de la naturaleza. Crea un espíritu de nivel 1...10 (15...90 segundos de vida). Las criaturas dentro de la zona tendrán +50...150 de salud máxima y +8 de armadura. No afecta a los espíritus.'],
468=>['Simbiosis','Ritual de la naturaleza. Creas un espíritu de nivel 1...10. Por cada encantamiento que tenga una criatura no espíritu dentro la zona, ganará +27...150 de salud máxima. Morirá a los 30...240 segundos.','Ritual de la naturaleza. Crea un espíritu de nivel 1...10 (30...240 segundos de vida). Las criaturas dentro de la zona tendrán +27...150 de salud máxima por cada encantamiento que tengan. No afecta a los espíritus.'],
469=>['Ecos primarios','Ritual de la naturaleza. Creas un espíritu de nivel 1...10. A las criaturas no espíritus que estén en su zona les costará 10 de energía usar sellos. Morirá a los 30...240 segundos.','Ritual de la naturaleza. Creas un espíritu de nivel 1...10 (30...240 segundos de vida). Los sellos cuestan 10 de energía a las criaturas de la zona. No afecta a los espíritus.'],
470=>['Temporada de depredadores','Ritual de la naturaleza. Creas un espíritu de nivel 1...10. Las criaturas no espíritus que estén en su zona se benefician un 20% menos de las curaciones. Si tus ataques impactan, ganarás 5 de salud. Morirá a los 30...240 segundos.','Ritual de la naturaleza. Crea un espíritu de nivel 1...10 (30...240 segundos de vida). Las criaturas dentro de la zona se benefician un 20% menos de las curaciones. Las criaturas ganan 5 de salud cada vez que ataquen. No afecta a los espíritus.'],
471=>['Suelo congelado','Ritual de la naturaleza. Creas un espíritu de nivel 1...10. Las criaturas no espíritus que estén en su zona no podrán activar habilidades de resurrección. Morirá a los 30...180 segundos.','Ritual de la naturaleza. Crea un espíritu de nivel 1...10 (30...180 segundos de vida). Las criaturas dentro de la zona no pueden activar habilidades de resurrección. No afecta a los espíritus.'],
472=>['Vientos favorables','Ritual de la naturaleza. Creas un espíritu de nivel 1...10. Las criaturas no espíritus que estén en su zona dispararán las flechas el doble de deprisa y harán +6 de daño. Morirá a los 30...240 segundos.','Ritual de la naturaleza. Creas un espíritu de nivel 1...10 (30...240 segundos de vida). Las flechas se mueven el doble de rápido y hacen +6 de daño a las criaturas de la zona. No afecta a los espíritus.'],
474=>['Viento vigorizante','Ritual de la naturaleza. Creas un espíritu de nivel 1...6. A las criaturas no espíritus que estén en su zona les costará 15 de energía menos usar las habilidades (coste mínimo 10) y éstas se recargarán un 25% más lento. Morirá a los 1...60 segundos.','Ritual de la naturaleza. Creas un espíritu de nivel 1...6 (1...60 segundos de vida). Las habilidades cuestan 15 menos de energía (coste mínimo 10) y se recargan un 25% más lento para las criaturas de la zona. No afecta a los espíritus.'],
475=>['Céfiro acelerador','Ritual de la naturaleza. Creas un espíritu de nivel 1...10. Las criaturas no espíritus que estén en su zona recargarán sus habilidades el doble de rápido y les costará 30% más energía usarlas. Morirá a los 15...90 segundos.','Ritual de la naturaleza. Creas un espíritu de nivel 1...10 (15...90 segundos de vida). Las habilidades cuestan un 30% más de energía y se recargan el doble de rápido para las criaturas de la zona. No afecta a los espíritus.'],
476=>['Renovación de la naturaleza','Ritual de la naturaleza. Creas un espíritu de nivel 1...10. Durante 30...240 segundos, los encantamientos y maleficios lanzados por criaturas no espíritus tardan el doble en invocarse y además costará el doble de energía mantener encantamientos. Morirá a los 30...240 segundos.','Ritual de la naturaleza. Creas un espíritu de nivel 1...10 (30...240 segundos de vida.) Para las criaturas de la zona, los encantamientos y maleficios tardan el doble en lanzarse y cuesta el doble de energía mantener encantamientos. No afecta a los espíritus.'],
477=>['Terreno fangoso','Ritual de la naturaleza. Creas un espíritu de nivel 1...10. Las criaturas no espíritus que estén en su zona se moverán un 10% más despacio y los aumentos de velocidad no funcionarán. Morirá a los 30...180 segundos.','Ritual de la naturaleza. Crea un espíritu de nivel 1...10 (30...180 segundos de vida). Las criaturas dentro de la zona se mueven un 10% más lento; también impide los aumentos de velocidad. No afecta a los espíritus.'],
570=>['Marca de inseguridad','Conjuro con maleficio de élite. Durante 5...25 segundos, el enemigo objetivo sufre -1...5 de degeneración de salud, y los encantamientos y posturas de ese enemigo acaban un 20...60 % antes. Todas tus habilidades que no sean de Asesino se desactivan durante 5 segundos.','Conjuro con maleficio de élite. (5...25 segundos) Provoca -1...5 de degeneración de salud. Los encantamientos y actitudes desaparecen un 20...60 % más rápido en el enemigo objetivo. Desactiva las habilidades que no sean de asesino (5 segundos).'],
571=>['Daga desbaratadora','Conjuro. Lanzas una Daga desbaratadora al enemigo objetivo que le hará 10...35 de daño de tierra. Si estaba intentando usar una habilidad, le interrumpirás. Este conjuro tiene la mitad de alcance de lo normal.','Conjuro con mitad de alcance. Proyectil: hace 10...35 de daño de tierra. Interrumpe una habilidad.'],
572=>['Paradoja mortal','Actitud. Todas tus habilidades de ataque quedan desactivadas durante 10 segundos. Además, durante 5...15 segundos tus habilidades de Asesino se activarán y recargarán un 33% más deprisa.','Actitud. (5...15 segundos). Tus habilidades de Asesino se activan y recargan un 33% más deprisa. Desactiva tus habilidades de ataque (10 segundos).'],
763=>['Mirada ictérica','Conjuro con encantamiento. Eliminas un encantamiento del enemigo objetivo. Si se elimina un encantamiento, durante los próximos 1...20 segundos, tu próximo conjuro con encantamiento se lanza 0...1 segundos más deprisa y cuesta 1...10 menos de energía.','Conjuro con encantamiento. Elimina un encantamiento del enemigo objetivo. Efecto de eliminación: tu próximo encantamiento se lanza 0...1 segundos más deprisa y cuesta 1...10 menos de energía. (1...20 segundos).'],
764=>['Gemido de condena','Conjuro con maleficio de élite. Durante 2...6 segundos, todos los atributos del enemigo objetivo se borran a 0.','Conjuro con maleficio de élite. (2...6 segundos). Los atributos del enemigo objetivo se borran a 0.'],
766=>['Mirada de desprecio','Conjuro. Si el enemigo objetivo tiene más del 50% de salud, perderá todos sus encantamientos.','Conjuro. Quita todos los encantamientos del enemigo objetivo. No tiene efecto a menos que este enemigo tenga más del 50% de salud.'],
769=>['Defensa de la víbora','Conjuro. Todos los enemigos cercanos quedan envenados durante 5...20 segundos. Das un paso sombrío a un lugar cercano, lejos de tu objetivo.','Conjuro. Causa envenenamiento (5...20 segundos) a todos los enemigos cercanos y das un paso sombrío a un lugar cercano, lejos de tu objetivo.'],
770=>['Retorno','Conjuro. Todos los enemigos adyacentes quedan lisiados durante 3...8 segundos. Das un paso sombrío a la ubicación del aliado objetivo.','Conjuro. Causa lisiadura (3...8 segundos) a todos los enemigos adyacentes a ti. Das un paso sombrío hasta el aliado objetivo. No te puedes apuntar a ti mismo.'],
771=>['Aura de desplazamiento','Conjuro con encantamiento de élite. Al invocar el Aura de desplazamiento, das un paso sombrío hasta el enemigo objetivo. Cuando dejes de mantener el aura, volverás a tu ubicación original.','Conjuro con encantamiento de élite. Das un paso sombrío hasta el enemigo objetivo. Efecto final: vuelves a tu ubicación original.'],
772=>['Generoso sea Tsungrai','Conjuro con objeto. Llevas las cenizas de Tsungrai durante 15...60 segundos y mientras ganarás +50...140 de salud máxima. Si las sueltas, recuperarás 100...280 de salud.','Conjuro con objeto. (15...60 segundos). Tienes +50...140 de salud máxima. Efecto al soltarse: ganas 100...280 de salud.'],
773=>['Bendito sea Vorizun','Conjuro con objeto. Llevas las cenizas de Vorizun durante 15...60 segundos. Mientras, ganarás +15 de armadura y +30 de energía máxima.','Conjuro con objeto. (15...60 segundos). Ganas +15 de armadura y +30 de energía máxima.'],
775=>['Brote mortal','Ataque doble. Debe ir precedido de un "ataque complementario". Si impacta, el Brote mortal hará +20...45 al enemigo objetivo y 20...45 a los enemigos adyacentes.','Ataque doble. Hace +20...45 de daño. También afecta a los enemigos adyacentes al enemigo objetivo. Debe ir precedido de un ataque complementario.'],
776=>['Colmillos afilados','Ataque doble. Debe ir precedido de un "ataque complementario". Si impacta, los Comillos afilados harán +10...20 de daño al enemigo, que también sufrirá una hemorragia y una herida grave durante 5...20 segundos.','Ataque doble. Hace +10...20 de daño. Causa hemorragia y herida grave (5...20 segundos). Debe ir precedido de un ataque complementario.'],
777=>['Cuernos del buey','Ataque doble. Debe ir precedido de un "ataque complementario". Si impactan, los cuernos harán +1...11 de daño. Si el enemigo golpeado no tiene aliados adyacentes, será derribado.','Ataque doble. Hace +1...11 de daño. Causa derribo si el enemigo objetivo no tiene aliados adyacentes. Debe ir precedido de un ataque complementario.'],
778=>['Araña colgante','Ataque complementario. Debe lanzarse sobre un enemigo derribado. Si impacta, hará +15...35 de daño y el enemigo quedará envenenado durante 5...20 segundos.','Ataque complementario. Hace +15...35 de daño. Causa envenenamiento (5...20 segundos). No tiene efecto si el objetivo no está derribado.'],
779=>['Loto negra','Ataque inicial. Si impacta, este ataque hace +10...31 de daño. Si el enemigo objetivo está sufriendo un maleficio, ganas 5...13 de energía.','Ataque inicial. Hace +10...31 de daño. Ganas 5...13 de energía si el enemigo objetivo está maldito.'],
780=>['Colmillos de zorro','Ataque complementario. Debe ir precedido de un ataque inicial. Los colmillos no pueden bloquearse y hacen +10...35 si impactan.','Ataque complementario. Hace +10...35 de daño. No se puede bloquear. Debe ir precedido de un ataque inicial.'],
781=>['Golpe de Moebius','Ataque complementario de élite. Debe ir acompañado de un ataque doble. Si impacta, hará +10...35 de daño y si golpeas a un enemigo cuya salud está por debajo del 50%, todas tus otras habilidades de ataque se recargarán.','Ataque complementario de élite. Hace +10...35 de daño. Recarga tus demás habilidades de ataque si la salud del enemigo objetivo está por debajo del 50%. Debe ir precedido de un ataque doble.'],
782=>['Ataque dentado','Ataque inicial. Si impacta, el enemigo objetivo sufrirá una hemorragia durante 5...20 segundos.','Ataque inicial. Causa hemorragia (5...20 segundos).'],
783=>['Ataque imprevisto','Ataque inicial. Si este ataque impacta, harás +19...31 de daño. Si el enemigo objetivo estaba por encima del 90% de su salud, le harás 15...75 de daño adicional.','Ataque inicial. Hace +19...31 de daño. +15...75 de daño extra si el enemigo objetivo está por encima del 90% de salud.'],
784=>['Aspid','Conjuro. Debe ir precedido de un ataque inicial. El enemigo objetivo es derribado y queda envenenado durante 5...20 segundos.','Conjuro. Causa derribo. Causa envenenamiento (5...20 segundos). Debe ir precedido de un ataque inicial.'],
785=>['Marca de muerte','Conjuro con maleficio. Durante 4...10 segundos, el enemigo objetivo se beneficia un 50% menos de las curaciones.','Conjuro con maleficio. (4...10 segundos). El enemigo objetivo se beneficia un 50% menos de las curaciones.'],
786=>['Palma de hierro','Habilidad. Haces 5...50 de daño al enemigo que toques y si éste estaba padeciendo una condición o un maleficio, le derribarás. La Palma de hierro cuenta como ataque inicial.','Habilidad de toque. Hace 5...50 de daño. Causa derribo si el enemigo objetivo tiene un maleficio o una condición. Esta habilidad cuenta como un ataque inicial.'],
787=>['Arma elástica','Conjuro con arma. Durante 3...12 segundos, el objetivo (un aliado o tú mismo) llevará un Arma elástica. Cuando esté padeciendo una condición o maleficio, ganará +1...6 de regeneración de salud y +24 de armadura.','Conjuro con arma. (3...12 segundos). +1...6 de regeneración de salud y +24 de armadura. No tiene efecto si el aliado objetivo no tiene una condición o un maleficio.'],
788=>['Ciego sea Mingson','Conjuro con objeto. Llevas las cenizas de Mingson durante 15...60 segundos. Al soltarlas, todos los enemigos cercanos quedan cegados durante 3...8 segundos.','Conjuro con objeto. (15...60 segundos). Efecto al soltarse: causa ceguera (3...8 segundos) a todos los enemigos cercanos.'],
789=>['Codicioso sea Kuurong','Conjuro con objeto de élite. Llevas las cenizas de Kuurong durante 15...60 segundos. Al soltarlas, todos los enemigos de la zona reciben 15...75 de daño y son derribados.','Conjuro con objeto de élite. (15...60 segundos). Efecto al soltarse: hace 15...75 de daño y derriba a todos los enemigos de la zona.'],
790=>['Rencoroso sea Khanhei','Conjuro con objeto de élite. Llevas las cenizas de Khanhei durante 5...11 segundos. Mientras, siempre que un enemigo te golpee, le robarás 10...45 de salud.','Conjuro con objeto de élite. (5...11 segundos). Robas 10...45 de salud de cada enemigo que te golpee con un ataque.'],
791=>['Carne de mi carne','Conjuro. Pierdes la mitad de la salud para resucitar al miembro del grupo objetivo con la que tengas y 5...20% de energía.','Conjuro. Resucita al miembro del grupo objetivo (con la mitad de tu salud actual y 5...20% de energía). Pierdes la mitad de salud.'],
792=>['Arma de astillas','Conjuro con arma. Durante 20 segundos, el aliado objetivo tiene un Arma de astillas. Los siguientes (1...5) ataques del aliado objetivo harán 5...50 de daño a un máximo de 4 enemigos adyacentes.','Conjuro con arma. (20 segundos). Sus ataques hacen 5...50 de daño hasta a 3 enemigos adyacentes. Acaba después de 1...5 ataques.'],
793=>['Arma de guardia','Conjuro con arma. Durante 3...8 segundos, el aliado objetivo tiene un Arma de guardia, que le dará un 50% de probabilidades de bloquear ataques y +2...4 de regeneración de salud.','Conjuro con arma. (3...8 segundos.) +2...4 de regeneración de salud. 50% de probabilidades de bloquear.'],
794=>['Arma de lamentos','Conjuro con arma. Durante 3...14 segundos, el objetivo (un aliado o tú mismo) tiene un Arma de lamentos. Siempre que ésta golpee a un enemigo atacando, le interrumpirá.','Conjuro con arma. (3...14 segundos). Los ataques interrumpen a los enemigos que ataquen.'],
795=>['Arma de pesadilla','Conjuro con arma. Durante 12 segundos, el aliado objetivo llevará un Arma de pesadilla, gracias a la que el daño de sus siguientes ataques (3) se reduce en 10...50 y roban hasta 10...50 de salud.','Conjuro con arma. (12 segundos). Los ataques del objetivo (un aliado o tú mismo) roban 10...50 de salud pero hacen 10...50 menos de daño. Acaba después de 3 ataques.'],
799=>['Mirada de seducción','Conjuro de élite. Das un paso sombrío hasta el enemigo objetivo, quien quedará aturdido durante 3...9 segundos.','Conjuro de élite. Das un paso sombrío hasta el enemigo. Causa aturdimiento (3...9 segundos).'],
800=>['Toxina persistente','Conjuro con maleficio. Durante 5 segundos, el enemigo objetivo sufre una degeneración de -1...5 de salud. Si el enemigo está en movimiento cuando la Toxina persistente acabe, ésta se renovará durante otros 5 segundos.','Conjuro con maleficio. (5 segundos). Causa -1...5 de degeneración de salud. Renovación: si el enemigo objetivo se está moviendo cuando este maleficio acabe.'],
801=>['Mortaja de silencio','Conjuro con maleficio de élite. Se desactivan todos tus conjuros durante 15 segundos. Durante 1...6 segundos, el enemigo al que toques no podrá lanzar conjuros.','Conjuro con maleficio de élite de toque. (1...6 segundos). El enemigo objetivo no puede lanzar conjuros. Tus conjuros están desactivados durante 15 segundos.'],
802=>['Defensas expuestas','Conjuro con maleficio. Durante 1...11 segundos, el enemigo objetivo no puede bloquear tus ataques.','Conjuro con maleficio. (1...11 segundos). El enemigo objetivo no puede bloquear tus ataques.'],
803=>['Sanguijuela poderosa','Conjuro con maleficio de élite. Si el enemigo objetivo está lanzando un conjuro o cántico, se interrumpirá y durante 10 segundos le robarás hasta 5...15 de energía cada vez que lance un conjuro.','Conjuro con maleficio de élite. Interrumpes un conjuro o cántico. Efecto de interrupción: robas 5...15 de energía cada vez que el enemigo objetivo lance un conjuro (10 segundos).'],
804=>['Languidez arcana','Conjuro con maleficio de élite. Durante 1...10 segundos, todos los conjuros lanzados por el enemigo objetivo causan 10 de sobrelanzamiento.','Conjuro con maleficio de élite. (1...10 segundos.) Los conjuros del enemigo objetivo causan 10 de sobrelanzamiento.'],
805=>['Animar horror vampírico','Conjuro. Explotas al cadáver más cercano para crear un Horror vampírico de nivel 1...17. Siempre que éste haga daño, tú ganarás la misma cantidad de salud.','Conjuro. Crea un horror vampírico de nivel 1...17. Ganas la misma cantidad de salud que el daño que haga. Explotas un cadáver.'],
806=>['Fervor del profano','Conjuro con encantamiento de élite. Durante 5 segundos y 3 segundos más por cada rango de cosecha de almas, tus conjuros de Nigromante cuestan -1...6 de energía, pero sufres una hemorragia durante 10 segundos cada vez que lances uno.','Conjuro con encantamiento de élite. (5 segundos más 3 segundos adicionales por cada rango de cosecha de almas.) Tus conjuros de Nigromante cuestan 1...6 menos de energía. Sufres hemorragia (10 segundos) cada vez que lanzas un conjuro de Nigromante.'],
808=>['Marca del segador','Conjuro con maleficio de élite. Durante 30 segundos, el enemigo objetivo sufre una degeneración de salud de -1...5. Si muere mientras tenga la Marca del segador, ganarás 5...15 de energía.','Conjuro con maleficio de élite. (30 segundos). Causa -1...5 de degeneración de salud. Ganas 5...15 de energía si el enemigo objetivo muere mientras tenga este maleficio.'],
809=>['Guijarro','Conjuro con maleficio de élite. El enemigo objetivo recibe 25...100 de daño frío, se mueve un 66 % más lento y queda maldecido con Guijarro durante 3 segundos. Cuando este termine, ese enemigo y todos los enemigos cercanos recibirán 25...100 de daño frío adicional.','Conjuro con maleficio de élite. (3 segundos.) Efecto inicial: hace 25...100 de daño frío y el objetivo se mueve un 66 % más lento. Efecto final: hace 25...100 de daño frío al objetivo y los enemigos adyacentes.'],
810=>['Defensa del protector','Habilidad. Durante 5...11 segundos, los aliados adyacentes tienen un 75% de probabilidades de bloquear ataques. La Defensa del protector acaba cuando te muevas.','Habilidad. (5...11 segundos). Los aliados adyacentes tienen un 75% de probabilidades de bloquear. Acaba si te mueves.'],
811=>['Corramos juntos','Actitud. Durante 5...15 segundos, tú y tu mascota corréis un 25% más rápido.','Actitud. (5...15 segundos). Tú y tu mascota os movéis un 25% más rápido.'],
812=>['Desafiante sea Xinrae','Conjuro con objeto de élite. Llevas las cenizas de Xinrae durante 15...60 segundos. Mientras, no puedes perder más del 20% de tu salud máxima de un solo golpe. Cuando sueltes las cenizas, robarás 5...50 de salud de todos los enemigos cercanos.','Conjuro con objeto de élite. (15...60 segundos). No puedes perder más del 20% de tu salud máxima de un solo golpe. Efecto al soltarse: robas 5...50 de salud de los enemigos cercanos.'],
813=>['Aura de Lyssa','Conjuro con encantamiento de élite. Durante 10 segundos, tienes +0...5 de regeneración de energía. Este encantamiento se vuelve a activar cada vez que lances un conjuro contra un enemigo.','Conjuro con encantamiento de élite. (10 segundos). Tienes +0...5 de regeneración de energía. Renovación: cada vez que lances un conjuro contra un enemigo.'],
814=>['Refugio sombrío','Conjuro con encantamiento. Durante 6 segundos, ganarás una regeneración de salud de 5...10. Cuando el Refugio sombrío acabe, ganarás 40...100 de salud si estás atacando.','Conjuro con encantamiento. (6 segundos). Tienes +5...10 de regeneración de salud. Efecto final: te curas 40...100 de salud si estás atacando.'],
815=>['Alambre de escorpión','Conjuro con maleficio. Durante 8...20 segundos, la próxima vez que estés separado del enemigo objetivo en más de 75 metros, darás un paso sombrío a donde esté y le derribarás. Este conjuro tiene la mitad del alcance normal.','Conjuro con maleficio con mitad de alcance. (8...20 segundos). Das un paso sombrío hasta el enemigo objetivo y le derribas la próxima vez que se aleje más de 75 metros.'],
816=>['Actitud copiada','Conjuro con maleficio. Durante 10...35 segundos, cuando el enemigo objetivo esté usando una actitud, la utilizarás tú también.','Conjuro con maleficio. (10...35 segundos). Copias cualquier actitud usada por el enemigo objetivo.'],
817=>['Discordia','Conjuro de élite. Si el enemigo objetivo sufre una condición y está bajo los efectos de un maleficio o encantamiento, recibirá 30...110 de daño.','Conjuro de élite. Hace 30...110 de daño. No tiene efecto a menos que el enemigo objetivo tenga una condición y también un maleficio o un encantamiento.'],
818=>['Pozo de cansancio','Conjuro de pozo. Explotas el cadáver más cercano o sacrificas un 66 % de salud para crear un Pozo de cansancio durante 10...55 segundos. Los enemigos dentro de él sufren -1 de degeneración de energía.','Conjuro de pozo. (10...55 segundos). Los enemigos en este pozo sufren -1 de degeneración de energía. Explotas un cadáver reciente o sacrificas un 66 % de salud.'],
819=>['Espíritu vampírico','Conjuro con encantamiento de élite. Robas 15...60 de salud del enemigo objetivo. Durante 10 segundos, tienes +5...10 de regeneración de salud.','Conjuro con encantamiento de élite. Robas 15...60 de salud del enemigo objetivo. Tienes +5...10 de regeneración de salud (10 segundos).'],
820=>['Depravación','Conjuro con maleficio de élite. Durante 5...20 segundos, siempre que el enemigo objetivo lance un conjuro, éste y un enemigo cercano perderán 1...5 de energía.','Conjuro con maleficio de élite. (5...20 segundos). Hace perder 1...5 de energía cada vez que el enemigo objetivo lance un conjuro. Un enemigo cercano a tu objetivo también pierde energía.'],
821=>['Venas heladas','Conjuro con maleficio de élite. El enemigo objetivo recibe 10...90 de daño frío. Además, durante 10...35 segundos, todos los enemigos cercanos recibirán 20...110 de daño frío si muere.','Conjuro con maleficio de élite. (10...35 segundos). Hace 20...110 de daño frío a los enemigos cercanos si el enemigo objetivo muere. Efecto inicial: 10...90 de daño frío.'],
822=>['Rodillas debilitadas','Conjuro con maleficio de élite. Durante 1...16 segundos, el enemigo objetivo sufre -1...4 de degeneración de salud y recibe 5...20 de daño mientras se mueva.','Conjuro con maleficio de élite. (1...16 segundos). El enemigo objetivo sufre -1...4 de degeneración de salud y recibe 5...20 de daño mientras se mueva.'],
823=>['Velocidad del fuego','Conjuro con encantamiento. Durante 7 segundos, ardes y te mueves un 30...45% más rápido. Cuando termina Velocidad del fuego, todos los enemigos adyacentes arden durante 3...9 segundos.','Conjuro con encantamiento. (7 segundos.) Te mueves un 30...45% más rápido. Ardes (7 segundos). Efecto final: causa quemadura (3...9 segundos) a los enemigos adyacentes.'],
824=>['Flechas de lava','Conjuro. Las flechas de lava pueden alcanzar a 3 enemigos cercanos al objetivo y causan 20...65 de daño de fuego si impactan.','Conjuro. Proyectil: hace 20...65 de daño de fuego. Efecto extra: lanza proyectiles a otros 2 enemigos cerca de tu objetivo.'],
825=>['Manto de ascuas','Conjuro. Creas un Manto de ascuas en la ubicación del enemigo objetivo. Durante 5 segundos, todos los enemigos adyacentes al objetivo reciben 5...29 de daño de fuego cada segundo. Cualquier enemigo derribado en el Manto de ascuas arde durante 3...7 segundos.','Conjuro. Hace 5...29 de daño de fuego por segundo (5 segundos) en la ubicación del enemigo objetivo. Golpea a los enemigos adyacentes a tu objetivo. Causa quemadura (3...7 segundos) a los enemigos derribados.'],
826=>['Forma sombría','Conjuro con encantamiento de élite. Durante 5...21 segundos, no puedes ser objetivo de conjuros enemigos y ganas 5 de reducción de daño por cada encantamiento de Asesino que tengas. No puedes hacer más de 5...25 de daño con cada habilidad o ataque.','Conjuro con encantamiento de élite. (5...21 segundos). No puedes ser objetivo de conjuros enemigos. Ganas 5 de reducción de daño por cada encantamiento de Asesino que tengas. No puedes hacer más de 5...25 de daño con cada habilidad o ataque.'],
827=>['Sifón de fuerza','Conjuro con maleficio de élite. Durante 5...20 segundos, el enemigo objetivo hace 5...50 de daño menos con sus ataques, y todos tus ataques contra él tienen un 50% más de probabilidades de ser críticos.','Conjuro con maleficio de élite. (5...20 segundos). El enemigo objetivo hace -5...50 de daño de ataque. Tienes +50% de probabilidades de dar un golpe crítico a este enemigo.'],
828=>['Miasma vil','Conjuro con maleficio. El enemigo objetivo recibe 10...65 de daño frío. Si está padeciendo una condición, recibirá el Miasma vil y sufrirá una degeneración de salud de -1...5 durante 10 segundos.','Conjuro con maleficio. Causa -1...5 de degeneración de salud (10 segundos). Efecto inicial: 10...65 de daño frío. Sólo funciona el maleficio si el enemigo objetivo tiene una condición.'],
830=>['Rayo del juicio','Conjuro de élite. Invocas un Rayo del juicio en la ubicación del enemigo objetivo. Durante 5 segundos, los enemigos adyacentes a esa ubicación recibirán 10...50 de daño sagrado y arderán durante 1...3 segundos por segundo.','Conjuro de élite. Hace 10...50 de daño sagrado y causa quemadura (1...3 segundos) por cada segundo (5 segundos). Alcanza a los enemigos adyacentes a la ubicación inicial del enemigo objetivo.'],
831=>['Furia primitiva','Actitud de élite. Durante 1...9 segundos, atacas un 33 % más rápido y te mueves un 33 % más rápido, pero recibes 150...125 % de daño.','Actitud de élite. (1...9 segundos). Atacas un 33 % más rápido y te mueves un 33 % más rápido, pero recibes 150...125 % de daño. Recibes 150...125 % de daño.'],
832=>['Animar gólem de carne','Conjuro de élite. Explotas al cadáver más cercano para animar un Gólem de carne de nivel 3...25, que dejará 1...4 cadáveres aprovechables. Solo podrás tener un Gólem de carne a la vez.','Conjuro de élite. Crea un Gólem de carne de nivel 3...25 que deja 1...4 cadáveres recientes al morir. Explotas un cadáver reciente. No puedes tener más de un Gólem de carne simultáneamente.'],
834=>['Prisa temeraria','Conjuro con maleficio. Durante 6...12 segundos, el enemigo objetivo y los adyacentes recibirán el maleficio Prisa temeraria. Mientras éste dure, atacarán un 25% más deprisa pero tendrán un 50% de posibilidades de fallar en sus ataques.','Conjuro con maleficio. También afecta a los enemigos adyacentes a tu objetivo (6...12 segundos). Tienen un 50% de probabilidades de fallar, pero atacan un 25% más deprisa.'],
835=>['Vínculo de sangre','Conjuro con maleficio. Durante 3...12 segundos, el enemigo objetivo y todos los adyacentes recibirán el maleficio Vínculo de sangre. Cada vez que un aliado alcance a alguno de ellos con un ataque, el aliado ganará 5...20 de salud. Si alguno de esos enemigos muere mientras tenía el Vínculo de sangre, todos los aliados adyacentes a él se curan 20...100 de salud.','Conjuro con maleficio. También afecta a los enemigos adyacentes al objetivo (3...12 segundos). Los aliados que golpeen a esos enemigos ganan 5...20 de salud. Si alguno de esos enemigos muere mientras tenía el maleficio, todos los aliados adyacentes a él se curan 20...100.'],
836=>['Cabalga en el rayo','Conjuro de élite. Cabalgas hacia el objetivo sobre un relámpago. Todos los enemigos cercanos quedan cegados durante 1...5 segundos. Si tu objetivo es un enemigo, recibe 10...70 de daño de relámpago. Este conjuro tiene un 25% de penetración de armadura.','Conjuro de élite. Causa 10...70 de daño de relámpago. 25% de penetración de armadura. Causa ceguera a los enemigos adyacentes (1...5 segundos). Llegas a tu objetivo inmediatamente. Se puede lanzar sobre aliados.'],
837=>['Bendición de energía','Conjuro con encantamiento de élite. Durante 36...60 segundos, Bendición de energía aumenta tu salud máxima y la del aliado objetivo en 1...3 por cada punto de vuestra energía máxima respectiva. Cuando se aplica este encantamiento por primera vez, tú y tu objetivo ganáis 1...12 de energía. Ganas 1 de energía adicional por cada 2 puntos de almacenamiento de energía que tengas.','Conjuro con encantamiento de élite. (36...60 segundos). Tu salud máxima y la del aliado objetivo aumentan 1...3 por cada punto de energía máxima. Efecto inicial: Ambos ganáis 1...12 de energía. Tú ganas +1 de energía por cada 2 puntos de almacenamiento de energía.'],
838=>['Pesar de Dwayna','Conjuro con encantamiento. Durante 30 segundos, el objetivo (un aliado o tú mismo) y todos los cercanos quedan encantados con el Pesar de Dwayna. Si alguno muere mientras, el grupo se cura 5...50 de salud.','Conjuro con encantamiento. También encanta a los aliados cercanos a tu objetivo (30 segundos). El grupo se cura 5...50 de salud si alguno de esos aliados muere.'],
839=>['"¡Retirada!"','Grito. Si hay algún aliado muerto al alcance del oído, tu grupo se moverá un 33% más deprisa durante 5...11 segundos.','Grito. (5...11 segundos). Los miembros del grupo al alcance del oído se mueven un 33% más rápido. No tiene efecto a menos que haya aliados muertos al alcance del oído.'],
840=>['Corazón envenenado','Conjuro. Tú y todos los enemigos cercanos quedan envenados durante 5...15 segundos.','Conjuro. Causa envenenamiento (5...15 segundos) a los enemigos cercanos. Tú también te envenenas.'],
841=>['Suelo fétido','Conjuro. El enemigo objetivo recibe 15...65 de daño frío. Si está derribado, quedará envenenado durante 5...20 segundos.','Conjuro. Hace 15...65 de daño frío. Causa envenenamiento (5...20 segundos) si el enemigo objetivo está derribado.'],
842=>['Arco de relámpagos','Conjuro. El enemigo objetivo recibe 5...40 de daño de relámpago. Si estás sobrelanzando, dos enemigos próximos a tu objetivo reciben 15...85 de daño de relámpago. El daño de Arco de relámpagos tiene un 25% de penetración de armadura.','Conjuro. Causa 5...40 de daño de relámpago. Hace 15...85 de daño de relámpago a dos enemigos cercanos si estás sobrelanzando. 25% de penetración de armadura.'],
843=>['Soplo','Conjuro con encantamiento de élite. Durante 5...11 segundos, tú y el aliado objetivo os movéis un 33% más rápido. Cuando lanzas este conjuro, todos los enemigos adyacentes a ti y tu objetivo reciben 15...70 de daño frío. Los enemigos alcanzados por Soplo mientras estén atacando o moviéndose serán derribados.','Conjuro con encantamiento de élite. (5...11 segundos). Tú y el aliado objetivo os movéis un 33% más rápido. Efecto inicial: Los enemigos adyacentes a ti y tu aliado objetivo reciben 15...70 de daño frío. Los enemigos que estén atacando o moviéndose serán derribados.'],
844=>['Movimiento de tierra','Conjuro. Creas un Movimiento de tierra en la ubicación del enemigo objetivo. Durante los próximos 5 segundos, los enemigos cercanos a esa ubicación recibirán 10...40 de daño de tierra por segundo. Todos los enemigos que se estén moviendo más rápido de lo normal cuando les alcance el Movimiento de tierra caerán al suelo.','Conjuro. Hace 10...40 de daño de tierra por segundo (5 segundos). Alcanza a los enemigos cercanos a la ubicación inicial del objetivo. Causa derribo a los enemigos que se muevan más rápido de lo normal.'],
845=>['Llama líquida','Conjuro. El enemigo objetivo recibe 7...112 de daño de fuego. Si éste estaba atacando o lanzando un conjuro, los enemigos cercanos también reciben 7...112 de daño de fuego.','Conjuro. Hace 7...112 de daño de fuego. Hace 7...112 de daño de fuego a los enemigos cercanos a tu objetivo si está atacando o lanzando un conjuro.'],
846=>['Vapor','Conjuro. El enemigo objetivo recibe 20...60 de daño frío. Si el enemigo objetivo está ardiendo, el Vapor lo cegará durante 5...10 segundos, además de infligirle 20...60 de daño de fuego adicional.','Conjuro. Hace 20...60 de daño frío. Causa ceguera (5...10 segundos) e inflige 20...60 de daño de fuego si el enemigo objetivo está ardiendo.'],
847=>['Sello vinculante','Sello de élite. Curas al objetivo (un aliado o tú mismo) 20...80 de salud. Tu siguiente conjuro de curación o protección que lances sobre el mismo objetivo cura 20...100 de salud extra.','Sello de élite. Curas 20...80 de salud. Tu siguiente conjuro de curación o protección que lances sobre un aliado cura +20...100 de salud extra.'],
848=>['Maleficio inverso','Conjuro con encantamiento. Quita un maleficio del objetivo (un aliado o tú mismo). Si quitas un maleficio de esta forma, durante 5...10 segundos, el próximo ataque que éste reciba se reduce en 5...50.','Conjuro con encantamiento. (5...10 segundos). Elimina un maleficio del objetivo (un aliado o tú mismo). El siguiente daño que reciba este objetivo se reduce en 5...50. No tiene efecto si el objetivo no tiene un maleficio.'],
849=>['Tajo desgarrador','Ataque con hacha. Haces +5...20 de daño si este golpe impacta. Si alcanza a un enemigo derribado, sufrirá una hemorragia durante 5...20 segundos.','Ataque con hacha. Hace +5...20 de daño. Causa hemorragia (5...20 segundos) si el enemigo objetivo está derribado.'],
850=>['Golpe feroz','Ataque con martillo. Si el Golpe feroz impacta, harás +5...20 de daño. Si el enemigo objetivo está sufriendo debilitamiento, también padecerá herida grave durante 1...8 segundos.','Ataque con martillo. Hace +5...20 de daño. Causa herida grave (1...8 segundos) si el enemigo objetivo está debilitado.'],
851=>['Tajada del sol y la luna','Ataque con espada. Atacas al enemigo objetivo por partida doble. No se puede bloquear.','Ataque con espada. Atacas dos veces al enemigo objetivo. No se puede bloquear.'],
852=>['Disparo astillado','Ataque con arco. Si el Disparo astillado impacta, harás +3...15 de daño. En caso de que se bloquee este golpe, todos los enemigos de la zona de tu objetivo recibirán 5...65 de daño.','Ataque con arco. Causa +3...15 de daño. Hace 5...65 de daño a los enemigos de la zona si se bloquea.'],
853=>['Disparo de Melandru','Ataque con arco de élite. Si el Disparo de Melandru impacta, tu objetivo sufrirá una hemorragia durante 5...25 segundos. Si impacta en un enemigo que se está moviendo o ha sido derribado, le harás +10...25 de daño y quedará lisiado durante 5...15 segundos.','Ataque con arco de élite. Causa hemorragia (5...25 segundos). Hace +10...25 de daño y causa lisiadura (5...15 segundos) si el enemigo objetivo estaba moviéndose o había sido derribado.'],
854=>['Cepo','Trampa. Cuando se activa esta trampa, todos los enemigos cercanos quedarán lisiados durante 3...15 segundos. La trampa dura 90 segundos. Cuando actives esta habilidad, se te podrá interrumpir con facilidad.','Trampa. (90 segundos.) Afecta a los enemigos cercanos. Causa lisiadura (3...15 segundos). Se puede interrumpir con facilidad.'],
858=>['Dagas danzantes','Conjuro. Lanzas tres Dagas danzantes al enemigo, que hacen 5...35 de daño de tierra al impactar. Tienen la mitad de alcance de lo normal. Esta habilidad cuenta como un ataque inicial.','Conjuro con mitad de alcance. Tres proyectiles: cada uno hace 5...35 de daño de tierra. Cuenta como un ataque inicial.'],
859=>['Conjurar pesadilla','Conjuro con maleficio. Durante 2...16 segundos, el enemigo objetivo sufre una degeneración de salud de -8.','Conjuro con maleficio. (2...16 segundos). Causa -8 de degeneración de salud.'],
860=>['Sello de interrupción','Sello. Si el enemigo objetivo está lanzando un conjuro, le interrumpes y le haces 10...51 de daño. Si el enemigo tiene un maleficio, el Sello de interrupción podrá interrumpir habilidades que no sean conjuros.','Sello. Interrumpe un conjuro. Puede interrumpir cualquier habilidad si el enemigo objetivo tiene algún maleficio. Efecto de interrupción: hace 10...51 de daño.'],
862=>['Mirada rapaz','Conjuro de élite. Hace 20...40 de daño y roba 20...40 de salud del enemigo objetivo y todos los cercanos.','Conjuro de élite. Hace 20...40 de daño y roba 20...40 de salud del enemigo objetivo y los cercanos.'],
863=>['Orden de la apostasía','Conjuro con encantamiento de élite. Durante 5 segundos, siempre que un aliado golpee a algún enemigo con daño físico, éste perderá un encantamiento. Si es un encantamiento de Monje, perderás 10...3% de salud máxima.','Conjuro con encantamiento de élite. Afecta a todos los compañeros de equipo (5 segundos). Éstos pierden un encantamiento cuando hagan daño físico. Coste de la eliminación: por cada encantamiento de Monje, pierdes un 10...3% de salud máxima.'],
864=>['Mirada opresora','Conjuro. El enemigo objetivo y los adyacentes reciben 10...30 de daño de sombra. Los enemigos que ya estén padeciendo alguna condición quedan envenenados y debilitados durante 3...12 segundos.','Conjuro. Hace 10...30 de daño al enemigo objetivo y los adyacentes. Causa envenenamiento y debilitamiento (3...12 segundos) a los enemigos que estén padeciendo alguna condición.'],
865=>['Martillo de relámpago','Conjuro. El enemigo objetivo recibe 10...100 de daño de relámpago y tiene la armadura rota durante 5...20 segundos. Martillo de relámpago tiene un 25% de penetración de armadura.','Conjuro. Causa 10...100 de daño de relámpago. Causa armadura rota (5...20 segundos). 25% de penetración de armadura.'],
866=>['Cuchilla de vapor','Conjuro. El enemigo objetivo recibe 15...135 de daño frío. Cuchilla de vapor hace la mitad de daño si el enemigo tiene algún encantamiento sobre él.','Conjuro. Hace 15...135 de daño frío. Mitad del daño si el objetivo enemigo está encantado.'],
867=>['Luz sanadora','Conjuro de élite. Curas 40...120 de salud al objetivo (un aliado o tú mismo). Si tiene un encantamiento, ganas 1...3 de energía.','Conjuro de élite. Cura 40...120 de salud Ganas 1...3 de energía si el objetivo (un aliado o tú mismo) tiene un encantamiento.'],
869=>['"¡Cobarde!"','Grito de élite. Si el enemigo objetivo se está moviendo, es derribado.','Grito de élite. Causa derribo si el enemigo objetivo está en movimiento.'],
870=>['Pestilencia','Ritual de la naturaleza. Creas un espíritu de nivel 1...10. Si alguna criatura no espíritu muere en su zona, todas las condiciones que tenía se contagian a las criaturas de la zona que ya tenían alguna condición. El espíritu morirá a los 30...180 segundos.','Ritual de la naturaleza. Crea un espíritu de nivel 1...10 (30...180 segundos de vida). Cuando alguna criatura de la zona muera, las condiciones que tenía se contagian a las criaturas de la zona que ya tenían alguna condición. No afecta a los espíritus.'],
871=>['Nanasombría','Ritual con espíritus. Creas un espíritu de nivel 1...10. Los ataques de estos espíritus hacen un 5...20 de daño y causan ceguera durante 1...6 segundos. El espíritu morirá a los 30 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...10 (30 segundos de vida). Sus ataques hacen 5...20 de daño y causan ceguera (5...20 segundos).'],
876=>['Sello de sombras','Sello. Haces 5...35 de daño al enemigo objetivo. Si éste estaba ciego, le harás 15...60 de daño de sombra adicional.','Sello. Hace +5...35 de daño. +15...60 de daño extra si el enemigo objetivo sufre ceguera.'],
877=>['Balanza de Lyssa','Conjuro. El enemigo objetivo pierde un encantamiento. Si tienes más encantamientos que el enemigo objetivo, esta habilidad no tendrá efecto.','Conjuro. Elimina un encantamiento del enemigo objetivo. No tiene efecto si tienes más encantamientos que este enemigo.'],
878=>['Visiones de arrepentimiento','Conjuro con maleficio de élite. Durante 10 segundos, el enemigo objetivo y los enemigos adyacentes reciben 15...45 de daño cada vez que utilicen una habilidad y 5...50 de daño adicional si no están bajo los efectos de ningún otro maleficio de Hipnotizador.','Conjuro con maleficio de élite. También afecta a los enemigos cercanos al objetivo (10 segundos). Estos enemigos reciben 15...45 de daño cada vez que utilicen una habilidad y 5...50 de daño adicional si no están bajo los efectos de ningún otro maleficio de Hipnotizador.'],
879=>['Ilusión de dolor','Conjuro con maleficio. Durante 8 segundos, el enemigo objetivo sufre -3...10 de degeneración de salud y recibe 3...10 de daño por segundo. Cuando la Ilusión de dolor termine, el enemigo se cura 36...120 de salud.','Conjuro con maleficio. (8 segundos). Causa -3...10 de degeneración de salud y el enemigo objetivo recibe 3...10 de daño por segundo. Efecto final: el enemigo se cura 36...120 de salud.'],
880=>['Velocidad robada','Conjuro con maleficio de élite. Durante 1...10 segundos, el enemigo objetivo y los adyacentes necesitarán 100% más de tiempo para lanzar conjuros. Los conjuros dirigidos a estos enemigos lanzados por ti o tus aliados tardan 50% menos en lanzarse.','Conjuro con maleficio de élite. También afecta a los enemigos adyacentes (1...10 segundos). Dobla el tiempo de lanzamiento. Los conjuros que tú o tus aliados lancéis sobre estos enemigos tienen un -50% de tiempo de lanzamiento.'],
881=>['Sello de éter','Sello. Si tienes menos de 5...10 de energía, ganarás 10...20.','Sello. Ganas 10...20 de energía. No funciona si no tienes menos de 5...10 de energía.'],
882=>['Sello del desencantamiento','Sello. Pierdes toda la energía. El enemigo objetivo pierde un encantamiento.','Sello. Elimina un encantamiento. Pierdes toda la energía.'],
883=>['Minoría ruidosa','Conjuro con maleficio. Durante 5...20 segundos, el enemigo objetivo y todos los enemigos cercanos no podrán usar gritos o cánticos.','Conjuro con maleficio. También afecta a los enemigos cercanos al objetivo (5...20 segundos). Éstos no pueden usar gritos ni cánticos.'],
884=>['Llamas abrasadoras','Conjuro de élite. Atacas al enemigo objetivo y a los cercanos con unas Llamas abrasadoras. Harás 10...100 de daño de fuego cuando alcances a enemigos que ya estaban ardiendo. Los que no lo estaban arderán durante 1...7 segundos.','Conjuro de élite. Alcanza a los enemigos cerca de tu objetivo. Hace 10...100 de daño de fuego a los enemigos que ya estaban ardiendo. Causa quemadura (1...7 segundos) a los enemigos que no estaban ardiendo.'],
885=>['Guardián de acero','Conjuro con encantamiento. Durante 2...6 segundos, todos los miembros del equipo al alcance del oído tendrán un 75% de posibilidades de bloquear ataques. Si se bloquea un ataque, todos los aliados al alcance del oído se curarán 10...40 de salud y el Guardián de acero terminará.','Conjuro con encantamiento. (2...6 segundos). Los miembros del equipo al alcance del oído tienen un 75% de posibilidades de bloquear ataques. Efecto al bloquear: Los aliados al alcance del oído se curarán 10...40 de salud y el Guardián de acero terminará.'],
886=>['Brisa apacible','Conjuro con encantamiento. Durante 8...18 segundos, el objetivo (un aliado o tú mismo) tiene +10 de regeneración de salud. Este encantamiento terminará si ataca o usa alguna habilidad.','Conjuro con encantamiento. (8...18 segundos). +10 de regeneración de salud. Acaba si el objetivo (un aliado o tú mismo) ataca o usa una habilidad.'],
887=>['Sello del rejuvenecimiento','Sello. Curas al objetivo (un aliado o tú mismo) 15...75 de salud. Si estaba atacando o lanzando un conjuro, se curará 15...75 de salud extra.','Sello. Cura 15...75 de salud. 15...75 de salud extra si el objetivo (un aliado o tú mismo) está lanzando un conjuro o atacando.'],
888=>['Hacha giratoria','Ataque con hacha de élite. Si el Hacha giratoria impacta, harás +5...20 de daño y cualquier actitud que estuviera usando el enemigo terminará. No se puede bloquear.','Ataque con hacha de élite. Hace +5...20 de daño y elimina una actitud. No se puede bloquear.'],
889=>['Golpe eficaz','Ataque con martillo de élite. Si el Golpe feroz impacta, haces +10...30 de daño y anulas cualquier actitud que esté usando el enemigo objetivo. El enemigo objetivo estará debilitado durante 5...20 segundos. Este ataque no puede bloquearse.','Ataque con martillo de élite. Hace +10...30 de daño. Elimina la actitud del enemigo objetivo. Causa debilitamiento (5...20 segundos). No se puede bloquear.'],
891=>['"¡No pasarán!"','Grito. Todos los enemigos adyacentes en movimiento son derribados. Esta habilidad se recarga 1...8 segundos más deprisa por cada enemigo derribado (máximo 25 segundos).','Grito. Derriba a todos los enemigos cercanos en movimiento. Se recarga 1...8 segundos más deprisa por cada enemigo afectado (máximo 25 segundos).'],
892=>['Espada temblorosa','Ataque con espada de élite. Si la Espada temblorosa impacta, haces +10...40 de daño. Si este ataque golpea a un enemigo en movimiento, quedará aturdido durante 10 segundos.','Ataque con espada de élite. Hace +10...40 de daño. Causa aturdimiento (10 segundos) si el enemigo objetivo está moviéndose.'],
893=>['Flechas dirigidas','Preparación["Preparaciones"]. Durante 3...14 segundos, tus flechas no se pueden bloquear. Esta habilidad terminará si fallas al atacar.','Preparación["Preparaciones"]. (3...14 segundos). Tus flechas no se pueden bloquear. Acaba si fallas.'],
898=>['Sobrecarga','Conjuro con maleficio. Durante 5 segundos, el enemigo objetivo sufre -1...3 de degeneración de salud. Si el enemigo objetivo está usando una habilidad, Sobrecarga hace 15...75 de daño al enemigo y un 75 % de ese daño a todos los enemigos adyacentes.','Conjuro con maleficio. (5 segundos). Causa -1...3 de degeneración de salud. Si el enemigo objetivo está usando una habilidad, ese enemigo sufre 15...75 de daño y todos los enemigos adyacentes a él reciben un 75 % de ese daño.'],
899=>['Imágenes de remordimiento','Conjuro con maleficio. Durante 5...10 segundos, el enemigo objetivo sufre una degeneración de salud de -1...3. Si estaba atacando, recibirá 10...52 de daño.','Conjuro con maleficio. (5...10 segundos). Causa -1...3 de degeneración de salud. Efecto inicial: 10...52 de daño si este enemigo está atacando.'],
900=>['Carga compartida','Conjuro con maleficio de élite. Durante 5...20 segundos, el enemigo objetivo y todos los que estén en la zona atacarán, lanzarán conjuros y se moverán un 50 % más despacio.','Conjuro con maleficio de élite. También se aplica el maleficio a los enemigos en la zona de tu objetivo (5...20 segundos). Estos enemigos atacan, lanzan conjuros y se mueven un 50 % más despacio.'],
901=>['Vínculo de almas','Conjuro con maleficio de élite. Durante 30 segundos, cada vez que el enemigo objetivo sea curado, el que le cure recibe 20...80 de daño. Este maleficio acaba si el objetivo tiene un maleficio de plegarias de ataque.','Conjuro con maleficio de élite. (30 segundos). Cada vez que el enemigo objetivo sea curado, el que le cure recibe 20...80 de daño. Acaba si el objetivo tiene un maleficio de plegarias de ataque.'],
902=>['Sangre del agresor','Conjuro. Robas hasta 5...45 de salud del enemigo objetivo. Si éste estaba atacando, queda debilitado durante 3...12 segundos.','Conjuro. Roba 5...45 de salud. Causa debilitamiento (3...12 segundos) si el enemigo objetivo estaba atacando.'],
903=>['Prisma helado','Conjuro. El enemigo objetivo recibe 15...75 de daño frío. Si ese enemigo tiene un maleficio de magia de agua, Prisma helado hace +15...75 de daño frío a los demás enemigos cercanos.','Conjuro. Hace 15...75 de daño frío. Hace +15...75 de daño frío a los demás enemigos cercanos si el objetivo tiene un maleficio de magia de agua.'],
904=>['Hacha furiosa','Ataque con hacha. Si el Hacha furiosa impacta, harás +5...35 de daño. Si se bloquea el ataque, ganarás 3 de adrenalina.','Ataque con hacha. Hace +5...35 de daño. Te da 3 golpes de adrenalina si se bloquea.'],
905=>['Golpe auspiciante','Ataque con martillo. Si el Golpe auspiciante impacta, haces +5...20 de daño y ganas 3...8 de energía. Si el enemigo objetivo está sufriendo debilitamiento, este ataque no se puede bloquear.','Ataque con martillo. Hace +5...20 de daño y ganas adrenalina y 3...8 de energía. No se puede bloquear si el enemigo objetivo está debilitado.'],
906=>['"¡De rodillas!"','Grito. Pierdes toda la adrenalina. Si algún enemigo adyacente está derribado, recargarás todas tus actitudes.','Grito. Recarga todas tus actitudes si un enemigo adyacente está derribado. Pierdes toda la adrenalina.'],
907=>['Golpe del dragón','Ataque con espada de élite. Si el Golpe del dragón impacta, harás +10...40 de daño y ganarás 1...5 de adrenalina.','Ataque con espada de élite. Hace +10...40 de daño. Ganas 1...5 golpes de adrenalina.'],
908=>['Disparo del merodeador','Ataque con arco. Si el Disparo del merodeador impacta, harás +25...55 de daño y todas tus habilidades que no sean de ataque estarán desactivadas durante 5 segundos.','Ataque con arco. Hace +25...55 de daño. Tus demás habilidades que no sean de ataque se desactivan (5 segundos) si este ataque impacta.'],
909=>['Disparo certero','Ataque con arco. This shot moves three times faster, cannot be blocked, and strikes for +10...40 damage but all of your other attack skills are disabled for 8...4 seconds.','Ataque con arco. Deals +10...40 damage. Unblockable. This shot moves three times faster.Your other attack skills are disabled (8...4 seconds).'],
910=>['Grieta del abismo','Conjuro. Abres un abismo en la ubicación del enemigo objetivo. Después de 3 segundoss, todos los enemigos adyacentes reciben 25...125 de daño de relámpago y tienen la armadura rota durante 1...20 segundos.','Conjuro. Después de 3 segundos, afecta a los enemigos adyacentes a la ubicación inicial del enemigo. Hace 25...125 de daño de relámpago y causa armadura rota (1...20 segundos).'],
911=>['Unión','Ritual con espíritus. Creas un espíritu de nivel 1...12. Siempre que un aliado no espíritu reciba daño o pierda vida dentro de su zona, el daño se reducirá en 15 y el espíritu recibirá 15 de daño. El espíritu morirá a los 30...60 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...12 (30...60 segundos de vida). Siempre que un aliado no espíritu reciba daño o pierda vida dentro de su zona, el daño se reducirá en 15 y el espíritu recibirá 15 de daño.'],
913=>['Calmado sea Tanasen','Conjuro con objeto de élite. Llevas las cenizas de Tanasen durante 5...20 segundos. Mientras, tendrás +10...25 de armadura y no te podrán interrumpir.','Conjuro con objeto de élite. (5...20 segundos). Tienes +10...25 de armadura. No se te puede interrumpir.'],
914=>['Alma consumida','Conjuro de élite. Robas 5...70 de salud del enemigo objetivo. Todas las criaturas hostiles invocadas que se encuentren cerca del enemigo reciben 25...125 de daño.','Conjuro de élite. Roba 5...70 de salud. Causa 25...125 de daño a las criaturas hostiles invocadas que se encuentran cerca del enemigo objetivo.'],
915=>['Luz espiritual','Conjuro. Curas 60...180 de salud al objetivo (un aliado o tú mismo). Si hay espíritus al alcance del oído, no sacrificarás salud.','Conjuro. Cura 60...180 de salud. No sacrificas tu salud si hay espíritus al alcance del oído.'],
916=>['Lamento','Conjuro con maleficio. Durante 5...20 segundos, el enemigo objetivo y todos los enemigos cercanos sufrirán -0...3 de degeneración de salud. Cuando este maleficio se active, los enemigos afectados reciben 10...50 de daño si estás al alcance del oído de un espíritu o cadáver.','Conjuro con maleficio. También afecta a los enemigos cercanos al objetivo (5...20 segundos). Causa -0...3 de degeneración de salud. Efecto inicial: hace 10...50 de daño a estos enemigos si estás al alcance del oído de algún espíritu o cadáver.'],
917=>['Alma rota','Conjuro. Destruyes al espíritu aliado objetivo. Todos los enemigos cercanos reciben 50...140 de daño de relámpago y quedan cegados durante 3...12 segundos.','Conjuro. Destruye al espíritu aliado objetivo. Hace 50...140 de daño de relámpago y causa ceguera (3...12 segundos) a los enemigos cercanos.'],
918=>['Espíritu carnal','Conjuro. Destruyes al espíritu aliado que toques y todos los aliados cercanos se curan 30...240 de salud.','Conjuro de toque. Destruye al espíritu aliado tocado. Cura 30...240 de salud a los aliados cercanos.'],
919=>['Quemadura espiritual','Conjuro. Haces 5...50 de daño de relámpago al enemigo objetivo. Si hay espíritus al alcance del oído, este ataque causará quemadura durante 1...5 segundos.','Conjuro. Causa 5...50 de daño relámpago. Causa quemadura (1...5 segundos) si estás al alcance del oído de algún espíritu.'],
920=>['Destrucción','Ritual con espíritus. Creas un espíritu de nivel 1...14 que muere al cabo de 30 segundos. Cuando éste muera, todos los enemigos de la zona reciben 5...25 de daño por cada segundo que haya vivido (máximo 150 de daño).','Ritual con espíritus. Creas un espíritu de nivel 1...14 que muere al cabo de 30 segundos. Cuando éste muera, todos los enemigos de la zona reciben 5...25 de daño por cada segundo que haya vivido (máximo 150 de daño).'],
921=>['Disonancia','Ritual con espíritus. Creas un espíritu de nivel 1...12 que hará 5...20 de daño e interrumpe a cualquiera que alcance. Morirá a los 10...25 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...12 (10...25 segundos de vida). Sus ataques hacen 5...20 de daño e interrumpen.'],
923=>['Desencantamiento','Ritual con espíritus. Crea un espíritu de nivel 1...12. Hace 5...20 de daño y quita un encantamiento a cualquiera que alcance. Muere a los 10...35 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...12 (10...35 segundos de vida). Sus ataques hacen 5...20 de daño y eliminan un encantamiento.'],
925=>['Recuerdo','Conjuro con encantamiento. Nada ocurrirá mientras mantengas el Recuerdo. Cuando acabe, darás un paso sombrío hasta el aliado objetivo y todas tus habilidades quedarán desactivadas durante 3 segundos.','Conjuro con encantamiento. Efecto final: das un paso sombrío hasta el aliado objetivo. No te puedes apuntar a ti mismo y desactiva todas tus habilidades durante 3 segundos cuando acabe.'],
926=>['Dagas afiladas','Conjuro con encantamiento. Durante 5...30 segundos, los ataques con daga que realices causarán una hemorragia al enemigo que durará 5...15 segundos.','Conjuro con encantamiento. (5...30 segundos.) Los ataques con daga causan hemorragia (5...15 segundos).'],
927=>['Temor vergonzoso','Conjuro con maleficio. Durante 10 segundos, el enemigo objetivo se mueve un 10% más rápido de lo normal, pero por cada segundo que esté en movimiento recibirá 5...20 de daño.','Conjuro con maleficio. (10 segundos). El enemigo objetivo recibe 5...20 de daño por segundo mientras esté moviéndose, pero se mueve un 10% más deprisa.'],
928=>['Mortaja sombría','Conjuro con maleficio de élite. Durante 3...9 segundos, al enemigo objetivo no le podrán echar encantamientos.','Conjuro con maleficio de élite. (3...9 segundos). Al enemigo objetivo no le podrán echar encantamientos.'],
929=>['Sombra fugaz','Actitud. Durante 10...40 segundos, te mueves un 15% más rápido de lo normal. Cuando la Sombra fugaz acabe, darás un paso sombrío hasta tu ubicación original.','Actitud. (10...40 segundos). Te mueves un 15% más rápido. Efecto final: vuelves a tu ubicación original.'],
930=>['Encantamiento próspero','Conjuro con encantamiento. Durante 20 segundos, el siguiente conjuro que lances estará desactivado 10...5 segundos más de lo normal, pero ganarás un 110...200% del coste de energía de ese conjuro.','Conjuro con encantamiento. (20 segundos). Tu siguiente conjuro te da el 110...200% de su coste de energía.Este conjuro tarda 10...5 segundos más en recargarse.'],
931=>['Regreso poderoso','Conjuro. Si el enemigo objetivo está lanzando un conjuro o cántico, éste se interrumpirá y el enemigo objetivo ganará 10...5 de energía.','Conjuro. Interrumpe un conjuro o cántico. Efecto de interrupción: el enemigo objetivo gana 10...5 de energía.'],
932=>['Complicación','Conjuro. Si el enemigo objetivo está utilizando una habilidad, la interrumpirás y se desactivará durante 5...12 segundos más para el enemigo objetivo y los enemigos cercanos a él.','Conjuro. Interrumpe una habilidad. Efecto de interrupción: desactiva la habilidad interrumpida (+5...12 segundos) para el enemigo objetivo y los enemigos cercanos.'],
933=>['Tormenta fragmentadora','Conjuro de élite. El enemigo objetivo pierde todos los encantamientos. Por cada uno que pierda así, la Tormenta fragmentadora estará desactivada durante 7 segundos.','Conjuro de élite. Elimina todos los encantamientos. Coste de la eliminación: la Tormenta fragmentadora está desactivada durante +7 segundos por cada encantamiento eliminado.'],
934=>['Sello antinatural','Sello. El enemigo objetivo recibe 15...75 de daño. Si el enemigo se encuentra bajo los efectos de un maleficio o un encantamiento, los enemigos adyacentes al objetivo reciben 5...50 de daño.','Sello. Hace 15...75 de daño. Hace 5...50 de daño a otros enemigos adyacentes si el objetivo tiene un maleficio o un encantamiento.'],
935=>['Subida de bilis','Conjuro con maleficio. Durante 20 segundos, este maleficio no hace nada. Cuando la Subida de bilis termine, el enemigo objetivo y todos los que estén en la zona reciben 1...6 de daño por cada segundo que haya estado activado el maleficio.','Conjuro con maleficio. (20 segundos). Efecto final: hace 1...6 de daño por cada segundo que haya estado activada la Subida de bilis. También afecta a los demás enemigos de la zona.'],
936=>['Envenenaencantamientos','Conjuro. El enemigo objetivo pierde un encantamiento. Por cada uno que le quede, estará envenenado durante 3...10 segundos.','Conjuro. Elimina un encantamiento del enemigo objetivo. Causa envenenamiento (3...10 segundos por cada encantamiento que le quede a ese enemigo).'],
937=>['Onda expansiva','Conjuro de élite. Todos los enemigos de la zona reciben 15...60 de daño de tierra y padecen debilitamiento durante 1...10 segundos. Los enemigos cercanos también reciben +15...60 de daño de tierra y tienen la armadura rota durante 1...10 segundos. Los enemigos adyacentes sufren los efectos anteriores, reciben +15...60 de daño de tierra y quedan cegados durante 1...10 segundos.','Conjuro de élite. Todos los enemigos de la zona reciben 15...60 de daño de tierra y padecen debilitamiento (1...10 segundos). Los enemigos cercanos también reciben +15...60 de daño de tierra y tienen la armadura rota (1...10 segundos). Los adyacentes también reciben +15...60 de daño de tierra y quedan cegados (1...10 segundos).'],
938=>['Protección de estabilidad','Conjuro de protección. Creas una Protección de estabilidad en el lugar donde estés. Durante 10...25 segundos, los aliados no espíritus no podrán ser derribados.','Conjuro de protección. (10...25 segundos). No se puede derribar a los aliados dentro de esta protección. No afecta a los aliados espíritus.'],
939=>['Grilletes de hielo','Conjuro con maleficio de élite. Durante 1...10 segundos, la velocidad de movimiento del enemigo objetivo se reduce un 66%. Mientras esté bajo los efectos de un encantamiento, el movimiento de ese enemigo se reduce un 90%.','Conjuro con maleficio de élite. (1...10 segundos). El enemigo objetivo se mueve un 66% más despacio. Este enemigo se mueve un 90% más despacio si está encantado.'],
941=>['Luz bendita','Conjuro de élite. Curas 10...120 de salud al objetivo (un aliado o tú mismo) y le quitas una condición y un maleficio.','Conjuro de élite. Cura 10...120 de salud. Quita una condición y un maleficio.'],
942=>['Sacamaleficios','Conjuro de élite. Quitas todos los maleficios del objetivo (un aliado o tú mismo) y de los adyacentes. Por cada uno que quites, este conjuro tardará 2 segundos más en recargarse. (50 % de probabilidad de fallo con un nivel de favor divino de 4 o menos.)','Conjuro de élite. Elimina todos los maleficios. También afecta a los aliados adyacentes. Coste de la eliminación: +2 segundos de recarga por cada maleficio eliminado. 50 % de probabilidades de fallar con favor divino inferior a 5.'],
943=>['Extinción','Conjuro. Quitas una condición de cada miembro del grupo. Si alguno estaba sufriendo una quemadura, se curará 10...100 de salud.','Conjuro. Afecta a todos los miembros del equipo. Elimina una condición. Los miembros curados de quemadura se curan 10...100 de salud.'],
944=>['Sello de fuerza','Sello. Tus siguientes ataques (1...16) hacen +5 de daño.','Sello. Tus ataques hacen +5 de daño. Acaba después de 1...16 ataques.'],
946=>['Poder de tramperos','Preparación["Preparaciones"] de élite. Durante 12...36 segundos, será más difícil que te interrumpan si estás colocando una trampa y tu atributo supervivencia en la naturaleza aumenta 0...4.','Preparación["Preparaciones"] de élite. (12...36 segundos). Será más difícil que te interrumpan si estás colocando una trampa. Ganas +0...4 de supervivencia en la naturaleza.'],
947=>['Zarzas','Ritual de la naturaleza. Creas un espíritu de nivel 1...10. Cuando alguna criatura no espíritu de la zona sea derribada, recibirá 5 de daño y sufrirá una hemorragia durante 5...20 segundos. El espíritu morirá a los 30...240 segundos.','Ritual de la naturaleza. Creas un espíritu de nivel 1...10 (30...240 segundos de vida). Las criaturas derribadas reciben 5 de daño y sufren hemorragia (5...20 segundos). No afecta a los espíritus.'],
948=>['Ataque de la desesperación','Ataque inicial. Si tienes menos de 50...80% de salud, harás +15...60 de daño.','Ataque inicial. Hace +15...60 de daño si tienes menos del 50...80% de salud.'],
949=>['Camino del zorro','Conjuro con encantamiento. Durante 10...35 segundos, tus siguientes ataques (1...6) no se pueden bloquear.','Conjuro con encantamiento. (10...35 segundos). Tus ataques no se pueden bloquear. Acaba después de 1...6 ataques.'],
950=>['Carga sombría','Conjuro con maleficio. Durante 3...15 segundos, el enemigo objetivo se mueve un 25% más lento y tiene 20...30 menos de armadura contra tus ataques siempre que no tenga otros maleficios.','Conjuro con maleficio. (3...15 segundos). El enemigo objetivo se mueve un 25% más lento y tiene 20...30 menos de armadura contra tus ataques.La reducción de armadura sólo afecta al enemigo si no tiene otros maleficios.'],
951=>['Chorro de velocidad','Conjuro con maleficio. Durante 5...15 segundos, el enemigo objetivo se mueve un 33 % más lento y tú un 33 % más deprisa. Este conjuro se recarga un 50 % más rápido si se lanza contra un enemigo en movimiento.','Conjuro con maleficio. (5...15 segundos) El enemigo objetivo se mueve un 33% más lento y tú un 33 % más deprisa. Se recarga un 50 % más rápido si se lanza contra un enemigo en movimiento.'],
952=>['Carga mortal','Conjuro. Das un paso sombrío hasta el enemigo objetivo. Si éste tiene más salud que tú, te curarás 65...200 de salud.','Conjuro. Das un paso sombrío hasta el enemigo objetivo. Te curas 65...200 de salud si este enemigo tiene más que tú.'],
953=>['Flujo de poder','Conjuro con maleficio de élite. Si el enemigo objetivo está lanzando un conjuro o cántico, se interrumpirá y durante 4...10 segundos, el enemigo sufrirá -2 de degeneración de energía.','Conjuro con maleficio de élite. Interrumpe un conjuro o cántico. Efecto de interrupción: -2 de degeneración de energía (4...10 segundos).'],
954=>['Maleficios exhortados','Conjuro de élite. Eliminas un máximo de 2 maleficios del objetivo (un aliado o tú mismo).','Conjuro de élite. Elimina 2 maleficios del objetivo (un aliado o tú mismo).'],
955=>['Rasgar encantamiento','Conjuro. Eliminas 1 encantamientos del enemigo objetivo. Si se elimina un encantamiento, ese enemigo sufrirá una hemorragia durante 5...25 segundos.','Conjuro. Elimina 1 encantamientos. Efecto de la eliminación: causa una hemorragia (5...25 segundos).'],
957=>['Escudo de conjuros','Conjuro con encantamiento. Durante 5...20 segundos, mientras estés invocando conjuros, los enemigos no te los podrán lanzar a ti. Cuando el Escudo de conjuros acabe, todas tus habilidades estarán desactivadas durante 8...4 segundos.','Conjuro con encantamiento. (5...20 segundos). Mientras lances conjuros, no te los podrán lanzar a ti. Efecto final: tus habilidades se desactivan (8...4 segundos).'],
958=>['Susurro de curación','Conjuro. El aliado objetivo se cura 40...100 de salud. Este conjuro tiene la mitad de alcance de lo normal.','Conjuro con mitad de alcance. Cura 40...100 de salud. No te puedes apuntar a ti mismo.'],
959=>['Luz etérea','Conjuro. El objetivo (un aliado o tú mismo) se cura 25...100 de salud. Este conjuro se puede interrumpir con facilidad.','Conjuro. Cura 25...100 de salud. Se puede interrumpir con facilidad.'],
960=>['Liberación de encantamientos','Conjuro. Pierdes todos los encantamientos. Cada miembro del grupo se cura 5...35 de salud por encantamiento de Monje perdido.','Conjuro. Elimina todos tus encantamientos. Cura 5...35 de salud a todos los miembros del grupo por cada encantamiento de Monje eliminado.'],
961=>['Desgarre','Ritual de la naturaleza de élite. Creas un espíritu de nivel 1...10. Las criaturas dentro de la zona con hemorragia sufrirán -2 de degeneración de salud. Este espíritu muere a los 30...240 segundos. Cuando lo haga, todas las criaturas no espíritus por debajo del 90% de salud sufrirán una hemorragia durante 5...25 segundos.','Ritual de la naturaleza de élite. Crea un espíritu de nivel 1...10 (30...240 segundos de vida). Las criaturas dentro de la zona con hemorragia tienen -2 de degeneración de salud: Efecto final: causa hemorragia (5...25 segundos) a las criaturas de la zona que tengan menos del 90% de salud. No afecta a los espíritus.'],
962=>['Transfusión espiritual','Conjuro. El espíritu más cercano pierde 5...50 de salud y el objetivo (un aliado o tú mismo) se cura 5 por cada punto perdido.','Conjuro. El espíritu más cercano pierde 5...50 de salud. Cura 5 de salud al aliado objetivo por cada punto de salud perdido.'],
963=>['Restauración','Ritual con espíritus. Creas un espíritu de nivel 1...14. Cuando muera, todos los miembros del grupo en la zona resucitan con 5...50% de salud y nada de energía. Muere a los 30 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...14 (30 segundos de vida). Efecto final: los miembros del grupo muertos en la zona resucitan con el 5...50% de salud y 0 de energía.'],
964=>['Arma vengativa','Conjuro con arma. Durante 8 segundos, la siguiente vez que al objetivo aliado reciba daño o pierda vida por el ataque de un enemigo, el aliado le robará 15...60 de salud al enemigo.','Conjuro con arma. (8 segundos.) Roba 15...60 de salud del siguiente enemigo que haga daño o robe vida al aliado objetivo.'],
973=>['Pólvora lacrimosa','Conjuro. Debe ir precedido de un ataque complementario. El enemigo objetivo y todos los adyacentes quedarán cegados durante 3...15 segundos.','Conjuro. Causa ceguera (3...15 segundos) al enemigo objetivo y los adyacentes. Debe ir precedido de un ataque complementario.'],
974=>['Toque de la mantis','Habilidad. El enemigo objetivo quedará lisiado durante 5...20 segundos. Esta habilidad cuenta como si fuese un ataque complementario.','Habilidad. Causa incapacitación (5...20 segundos). Esta habilidad cuenta como un ataque complementario.'],
975=>['Ataque agotador','Ataque doble. Debe seguir a un ataque inicial. Interrumpe la acción del enemigo objetivo. Si estaba lanzando un conjuro, el enemigo objetivo sufre 10 de sobrelanzamiento.','Ataque doble. Interrumpe una acción. Causa 10 de sobrelanzamiento si la acción interrumpida era el lanzamiento de un conjuro. Debe seguir a un ataque inicial.'],
976=>['Golpe repetitivo','Ataque complementario. Debe ir precedido de un "ataque complementario". Si impacta, este ataque hará +10...30 de daño, y si falla, tardará 15 segundos más en recargarse.','Ataque complementario. Hace +10...30 de daño. Esta habilidad tarda +15 segundos más en recargarse si falla. Debe ir precedida de un ataque complementario.'],
977=>['Camino del loto','Conjuro con encantamiento. Durante 20 segundos, la próxima vez que golpees con una habilidad de ataque doble, ganarás 5...20 de energía.','Conjuro con encantamiento. (20 segundos). Ganas 5...20 de energía la próxima vez que hagas un ataque doble.'],
978=>['Marca de inestabilidad','Conjuro con maleficio. Durante 20 segundos, la próxima vez que golpees al enemigo objetivo con una habilidad de ataque doble, éste será derribado.','Conjuro con maleficio. (20 segundos). Causa derribo al enemigo objetivo la próxima vez que le hagas un ataque doble.'],
979=>['Recelo','Conjuro con maleficio. Durante 6 segundos, el siguiente conjuro que el enemigo objetivo lance sobre uno de tus aliados falla y haces 10...80 de daño a este enemigo y un 75 % de ese daño a todos los enemigos adyacentes.','Conjuro con maleficio. (6 segundos). El siguiente conjuro que el enemigo objetivo lance sobre uno de tus aliados falla y haces 10...80 de daño a este enemigo y un 75 % de ese daño a todos los enemigos cercanos.'],
980=>['Festín espiritual','Conjuro. Destruyes a todos los espíritus aliados cercanos. Por cada uno destruido así, todos los miembros del grupo se curan 50...100 de salud.','Conjuro. Cura 50...100 de salud a todos los miembros del equipo por cada espíritu aliado cercano. Todos los espíritus aliados cercanos se destruyen.'],
981=>['Recuperación','Ritual con espíritus. Creas un espíritu de nivel 1...14. Los aliados no espíritu dentro de la zona ganan +1...3 de regeneración de salud. Morirá a los 15...45 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...14 (15...45 segundos de vida). Los aliados no espíritu dentro de la zona tienen +1...3 de regeneración de salud.'],
982=>['Cobijo','Ritual con espíritus. Creas un espíritu de nivel 1...12. Los aliados no espíritus dentro de la zona no pueden perder más del 10% del máximo de salud de un solo ataque. Cuando este espíritu prevenga daño, perderá 75...45 de salud. Morirá a los 30...60 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...12 (30...60 segundos de vida). Los aliados no espíritus dentro de la zona no pueden perder más del 10% del máximo de salud de un solo ataque. Coste por defensa: el espíritu pierde 75...45 de salud.'],
983=>['Arma de sombra','Conjuro con arma. Durante 1...7 segundos, el aliado objetivo tiene un Arma de sombra. Cada vez que un ataque impacta sobre el aliado, el atacante queda cegado durante 5 segundos. Las próximas 1...3 veces que el aliado acierte un ataque, su objetivo quedará cegado durante 5 segundos.','Conjuro con arma. (1...7 segundos). Causa ceguera (5 segundos) sobre cualquiera que ataque al aliado objetivo. Los próximos 1...3 ataques del aliado objetivo causan ceguera (5 segundos) si aciertan.'],
985=>['Cebo','Conjuro. Target foe and all foes adjacent to your target are Crippled and Bleeding for 5...15 seconds. Caltrops has half the normal range.','Conjuro con mitad de alcance. Inflicts Crippled and Bleeding conditions (5...15 seconds) on target and adjacent foes.'],
986=>['Golpe de las nueve colas','Ataque doble. Debe ir precedido de un ataque complementario. Esta habilidad no puede bloquearse y hace +15...40 de daño si impacta.','Ataque doble. Hace +15...40 de daño. No se puede bloquear. Debe ir precedido de un ataque complementario.'],
987=>['Camino de la mano abierta','Conjuro con encantamiento de élite. Durante 5...15 segundos, los ataques complementarios y dobles no consumen energía y se recargan un 25...50 % más rápido.','Conjuro con encantamiento de élite. (5...15 segundos). Los ataques complementarios y dobles no consumen energía y se recargan un 25...50 % más rápido.'],
988=>['Golpe en las sienes','Ataque complementario de élite. Debe ir precedido de un ataque inicial. Si impacta, el enemigo objetivo quedará aturdido y cegado durante 1...10 segundos y, si estaba lanzando un conjuro, le interrumpirás.','Ataque complementario de élite. Interrumpe un conjuro. Causa aturdimiento y ceguera (1...10 segundos). Debe ir precedido de un ataque inicial.'],
989=>['Golpe del fénix dorado','Ataque complementario. Si no estás bajo el efecto de un encantamiento, esta habilidad fallará. Si alcanza al enemigo, el Golpe del fénix dorado causa +10...30 de daño y todos los enemigos cercanos sufrirán 10...30 de daño.','Ataque complementario. Hace +10...30 de daño al objetivo y 10...30 a los enemigos cercanos. Falla si no estás encantado.'],
990=>['Cancelar encantamientos','Habilidad. El enemigo objetivo pierde un encantamiento. Todas tus demás habilidades que no sean de ataque quedarán desactivadas durante 8...4 segundos. Por cada habilidad desactivada de esta manera, el enemigo objetivo tocado pierde 1 encantamiento extra.','Habilidad de toque. Eliminas un encantamiento por cada habilidad no de ataque que tengas. Todas tus habilidades que no sean de ataque están desactivadas (8...4 segundos).'],
991=>['Negación de maleficios','Conjuro. Quitas un maleficio del objetivo (un aliado o tú mismo) y un maleficio adicional por cada habilidad de favor divino que tengas recargándose.','Conjuro. Quita un maleficio del objetivo (un aliado o tú mismo) y un maleficio adicional por cada habilidad de favor divino que tengas recargándose.'],
992=>['Tajada triple','Ataque con hacha de élite. Atacas al enemigo objetivo y a los adyacentes. Cada ataque hace +10...40 de daño.','Ataque con hacha de élite. Hace +10...40 de daño. También alcanza a los enemigos adyacentes.'],
993=>['Golpe enrabietado','Ataque con martillo de élite. Si el Golpe enrabietado impacta, ganas 1...4 de adrenalina. Si alcanzas a un enemigo en movimiento, haces +10...40 de daño y le derribas.','Ataque con martillo de élite. Ganas 1...4 de adrenalina si impacta. Hace +10...40 de daño y causa derribo si el objetivo estaba en movimiento.'],
994=>['Golpe renovador','Ataque con martillo. Si impacta, el Golpe renovador hace +10...40 de daño. Si golpeas a un enemigo derribado, ganas 3 de energía y esta habilidad se recargará instantáneamente.','Ataque con martillo. Hace +10...40 de daño. Ganas 3 de energía y esta habilidad se recargará instantáneamente si el enemigo estaba derribado.'],
995=>['Actitud felina','Actitud. Durante 4...10 segundos, atacas un 33% más deprisa. La Actitud felina termina si alguno de tus ataques fallan.','Actitud. (4...10 segundos). Atacas un 33% más deprisa. Acaba si fallas.'],
996=>['Golpe firme','Ataque con espada. Si consigues dar este golpe, harás +5...20 de daño, además de 5...20 extra si estás manteniendo alguna actitud.','Ataque con espada. Hace +5...20 de daño. 5...20 de daño extra si mantienes una actitud.'],
997=>['Hambruna','Ritual de la naturaleza de élite. Creas un espíritu de nivel 1...10. Cuando cualquier criatura no espíritu dentro de la zona se quede sin energía, recibirá 20...70 de daño. Morirá a los 30...180 segundos.','Ritual de la naturaleza de élite. Crea un espíritu de nivel 1...10 (30...180 segundos de vida). Hace 20...70 de daño a las criaturas de la zona que se queden sin energía. No afecta a los espíritus.'],
1018=>['Ojo crítico','Habilidad. Durante 10...35 segundos, tienes un 3...15% de probabilidades extra de hacer un golpe crítico al atacar. Ganarás 1 de energía cuando lo logres.','Habilidad. (10...35 segundos). Tienes +3...15% de probabilidades de hacer un golpe crítico. Ganas 1 de energía cada vez que lo hagas.'],
1019=>['Golpe crítico','Ataque doble. Debe ir precedido de un "ataque complementario". Si impacta, este ataque será crítico, hará +10...30 de daño y ganarás 1...3 de energía.','Ataque doble. Hace +10...30 de daño. Golpe crítico automático. Ganas 1...3 de energía. Debe ir precedido de un ataque complementario.'],
1020=>['Filos de acero','Ataque doble. Debe ir precedido de un "ataque complementario". Si impacta, este ataque hará +5...16 de daño (máximo 60 extra) por cada ataque con daga que se esté recargando.','Ataque doble. Hace +5...16 de daño (máximo 60) por cada ataque con daga que se esté recargando. Debe ir precedido de un ataque complementario.'],
1021=>['Golpe selvático','Ataque complementario. Debe ir precedido de un ataque inicial. Si alcanza al enemigo, este ataque hace +10...25 de daño. Si el enemigo objetivo está lisiado, dicho enemigo y los que estén cerca sufrirán 1...31 de daño.','Ataque complementario. Causa +10...25 de daño. Causa 1...31 de daño al enemigo objetivo, y los que estén cerca si el objetivo está lisiado. Debe ir precedido de un ataque inicial.'],
1022=>['Golpe salvaje','Ataque complementario. Debe ir precedido de un ataque inicial. Si alcanza al enemigo, este ataque causa +10...35 de daño y anula cualquier actitud que esté usando el enemigo objetivo. Este ataque no puede bloquearse.','Ataque complementario. Causa +10...35 de daño. Elimina la actitud del enemigo objetivo. No se puede bloquear. Debe ir precedido de un ataque inicial.'],
1023=>['Picadura de mantis','Ataque inicial. Si alcanzas al enemigo objetivo, le harás +5...15 de daño. Si estaba en movimiento, quedará lisiado durante 3...15 segundos.','Ataque inicial. Hace +5...15 de daño. Causa lisiadura (3...15 segundos) si el enemigo objetivo está moviéndose.'],
1024=>['Estocada de la mantis negra','Ataque inicial. Si impacta, harás al enemigo objetivo +8...20 de daño. Si tiene un maleficio, quedará lisiado durante 3...15 segundos.','Ataque inicial. Hace +8...20 de daño. Causa lisiadura (3...15 segundos) si el enemigo objetivo tiene un maleficio.'],
1025=>['Tajo de distracción','Ataque inicial. Si impacta, este ataque interrumpe la acción del enemigo objetivo. Si la acción era un conjuro, éste quedará desactivado durante 3...10 segundos.','Ataque inicial. Interrumpe una acción. Si la acción interrumpida era un conjuro, se desactivará (3...10 segundos).'],
1026=>['Loto dorada','Ataque inicial. Si impacta el ataque, harás de +5...20 daño. Si estás bajo los efectos de un encantamiento, ganarás 5...8 de energía.','Ataque inicial. Hace +5...20 de daño. Ganas 5...8 de energía si tienes un encantamiento.'],
1027=>['Defensas críticas','Conjuro con encantamiento. Durante 4...10 segundos, tienes un 75% de probabilidades de bloquear ataques. Las Defensas críticas se recargan cada vez que hagas un golpe crítico.','Conjuro con encantamiento. (4...10 segundos). Tienes 75% de probabilidades de bloquear. Renovación: cada vez que hagas un golpe crítico.'],
1028=>['Camino de perfección','Conjuro con encantamiento. Durante 60 segundos, siempre que consigas hacer un golpe crítico recuperarás 10...40 de salud.','Conjuro con encantamiento. (60 segundos.) Los golpes críticos te hacen recuperar 10...40 de salud.'],
1029=>['Apostasía oscura','Conjuro con encantamiento de élite. Durante 3...17 segundos, cada vez que consigas dar un golpe crítico, quitarás un encantamiento del objetivo. Si lo quitas de este modo, perderás 10...3 de energía o la Apostasía oscura finalizará.','Conjuro con encantamiento de élite. (3...17 segundos). Tus golpes críticos eliminan un encantamiento. Coste de la eliminación: pierdes 10...3 de energía o la Apostasía oscura acaba.'],
1030=>['Furia de langosta','Conjuro con encantamiento de élite. Durante 10...35 segundos tienes un 50% más de probabilidades de dar un golpe doble mientras uses dagas.','Conjuro con encantamiento de élite. (10...35 segundos). Tienes +50% de probabilidades de dar un golpe doble. No tiene efecto si no llevas unas dagas.'],
1031=>['Mortaja de agonía','Conjuro con encantamiento. Durante 30...60 segundos, si estás por debajo del 50% de salud, tendrás +3...8 de regeneración de salud y un 75% de probabilidades de bloquear ataques.','Conjuro con encantamiento. (30...60 segundos.) Tienes +3...8 de regeneración de salud y un 75% de probabilidades de bloquear. Sólo surte efecto si tu Salud está por debajo del 50%.'],
1032=>['Corazón de sombra','Conjuro. Recuperas 30...150 de salud. Das un paso sombrío a un lugar cercano, lejos de tu objetivo.','Conjuro. Recuperas 30...150 de salud y das un paso sombrío a un lugar cercano, lejos de tu objetivo.'],
1033=>['Empalar','Habilidad. Debe ir precedido de ataque doble. El enemigo objetivo recibe 25...100 de daño de tierra y sufre una herida grave durante 5...20 segundos.','Habilidad. Hace 25...100 de daño de tierra. Causa herida grave (5...20 segundos). Debe ir precedido de un ataque doble.'],
1034=>['Herida supurante','Conjuro con maleficio de élite. For 1...7 seconds, target foe moves 33% slower. That foe takes 5...25 damage each second while suffering from a condition.','Conjuro con maleficio de élite. (1...7 segundos). El enemigo objetivo se mueve un 33% más despacio. Éste recibirá 5...25 de daño por segundo mientras sufra una condición.'],
1035=>['Promesa del Asesino','Conjuro con maleficio de élite. Durante 5...15 segundos, si el enemigo objetivo muere, ganarás 5...20 de energía y todas tus habilidades quedarán recargadas.','Conjuro con maleficio de élite. (5...15 segundos). Ganas 5...20 de energía y se recargan todas tus habilidades si el enemigo objetivo muere.'],
1036=>['Sello de malicia','Sello. Por cada condición que padezca el enemigo objetivo, tú perderás una condición.','Sello. Pierdes una condición por cada una que tenga el enemigo objetivo.'],
1037=>['Huida oscura','Actitud. Durante 5...15 segundos, te mueves un 25% más deprisa y recibes la mitad de daño. La Huida oscura finaliza si atacas con éxito.','Actitud. (5...15 segundos). Te mueves un 25% más deprisa y recibes la mitad de daño. Acaba si atacas con éxito.'],
1038=>['Daga lisiadora','Conjuro. Envías una Daga lisiadora al enemigo objetivo, que le hará 15...60 de daño de tierra y le dejará lisiado durante 3...15 segundos si estaba en movimiento. Este conjuro tiene la mitad de alcance de lo normal.','Conjuro con mitad de alcance. Proyectil: hace +15...60 de daño de tierra. Causa lisiadura (3...15 segundos) si el enemigo objetivo está moviéndose.'],
1040=>['Paseo espiritual','Conjuro. Das un paso sombrío hasta el espíritu objetivo.','Conjuro. Das un paso sombrío hasta el espíritu objetivo.'],
1041=>['Furia inadvertida','Actitud. Todos los enemigos cercanos quedan cegados durante 3...10 segundos. Durante 10...30 segundos, los enemigos cegados no te podrán bloquear.','Actitud. Causa ceguera a los enemigos cercanos (3...10 segundos). Los enemigos cegados no podrán bloquear tus ataques (10...30 segundos).'],
1042=>['Cuchillas fugaces','Actitud de élite. Durante 5...30 segundos, tienes un 75% de posibilidades de bloquear los ataques que te hagan mientras ataques. Si bloqueas un ataque de este modo, el atacante recibirá 5...20 de daño.','Actitud de élite. (5...30 segundos). 75% de probabilidades de bloquear mientras ataques. Efecto del bloqueo: 5...20 de daño a tu atacante.'],
1043=>['Brío','Actitud. Durante 3 segundos, corres un 50% más rápido.','Actitud. (3 segundos). Te mueves un 50% más rápido.'],
1044=>['Cárcel oscura','Conjuro con maleficio. Das un paso sombrío hasta el enemigo objetivo. Durante 1...6 segundos, el enemigo objetivo se moverá un 33% más lento.','Conjuro con maleficio. Das un paso sombrío hasta el enemigo objetivo. Éste se mueve un 33% más lento (1...6 segundos).'],
1045=>['Bofetada','Habilidad de élite. El enemigo objetivo tocado recibe 10...65 de daño y queda lisiado durante 1...5 segundos. Esta habilidad cuenta como ataque complementario.','Habilidad de élite de toque. Hace 10...65 de daño y causa lisiadura (1...5 segundoss). Esta habilidad cuenta como un ataque complementario.'],
1048=>['Encantamiento descubierto','Conjuro. Quitas un encantamiento del enemigo objetivo y ganas 3...15 de energía. Durante 20 segundos, el Encantamiento revelado será sustituido por el encantamiento que se haya quitado al enemigo.','Conjuro. Elimina un encantamiento del enemigo objetivo. Efecto de la eliminación: ganas 3...15 de energía; este conjuro se sustituye por el encantamiento (20 segundos).'],
1049=>['Maleficio revelado','Conjuro. Se elimina un maleficio del objetivo (un aliado o tú mismo) y ganas 4...10 de energía. Durante 20 segundos, el Maleficio revelado será sustituido por el maleficio que hayas quitado.','Conjuro. Elimina un maleficio del aliado objetivo. Efecto de la eliminación: ganas 4...10 de energía; este conjuro se sustituye por el maleficio (20 segundos).'],
1052=>['Dolor acumulado','Conjuro. Haces 15...75 de daño al enemigo. Si estaba padeciendo 2 o más maleficios, sufrirá una herida grave durante 5...20 segundos.','Conjuro. Hace 15...75 de daño. Causa una herida grave (5...20 segundos) si el enemigo objetivo tiene 2 o más maleficios.'],
1053=>['Distracción psíquica','Conjuro de élite. El resto de tus habilidades se desactivarán durante 8 segundos. Si el enemigo objetivo está utilizando una habilidad, ésta se interrumpirá y estará desactivada durante 5...12 segundos más.','Conjuro de élite. Interrumpe una habilidad. Efecto de interrupción: desactiva la habilidad interrumpida (+5...12 segundos). El resto de tus habilidades estarán desactivadas (8 segundos).'],
1054=>['Rostro ancestral','Conjuro con encantamiento. Durante 4...10 segundos, siempre que el objetivo (un aliado o tú mismo) sea golpeado en un ataque cuerpo a cuerpo, todos los enemigos adyacentes pierden su adrenalina y 3 de energía.','Conjuro con encantamiento. (4...10 segundos). Todos los enemigos adyacentes pierden su adrenalina y 3 de energía cada vez que el objetivo (un aliado o tú mismo) sea golpeado por un ataque cuerpo a cuerpo.'],
1055=>['Inseguridad constante','Conjuro con maleficio de élite. Durante 5 segundos, el enemigo objetivo sufre -1...6 de degeneración de salud. Si ese enemigo tiene otro maleficio cuando la Inseguridad constante se hubiese acabado, ésta se vuelve a reactivar.','Conjuro con maleficio de élite. (5 segundos). Causa -1...6 de degeneración de salud. Renovación: si el enemigo objetivo recibe otro maleficio antes de que la Inseguridad constante se haya acabado.'],
1056=>['Carga de Kitah','Conjuro con maleficio. Durante 6...12 segundos, el enemigo objetivo se moverá un 50% más lento. Cuando la Carga de Kitah finalice, ganarás 10...18 de energía.','Conjuro con maleficio. (6...12 segundos). El enemigo objetivo se mueve un 50% más lento. Efecto final: ganas 10...18 de energía.'],
1057=>['Inestabilidad psíquica','Conjuro de élite. Interrumpe la acción del enemigo objetivo. Si se trata de un habilidad, derribas al enemigo y a todos los enemigos cercanos durante 2...4 segundos. (50% de posibilidades de fallar con lanzamiento de conjuros rápido 4 o inferior.)','Conjuro de élite. Interrumpe una acción. Efecto de interrupción: Si la acción es una habilidad, causa el derribo del enemigo objetivo y todos los enemigos adyacentes durante 2...4 segundos. 50% de posibilidades de fallar a menos que tengas lanzamiento de conjuros rápido 5 o superior.'],
1059=>['Sello de devoramaleficios','Sello. El aliado tocado y hasta 2...5 aliados adyacentes pierden un maleficio. Ganas 1...4 de energía por cada maleficio eliminado de esta manera.','Sello de toque. Elimina un maleficio al enemigo objetivo y a 2...5 aliados adyacentes. Efecto de la eliminación: ganas 1...4 de energía por cada maleficio eliminado.'],
1061=>['Retroalimentación','Conjuro. El enemigo objetivo pierde un encantamiento. Si se elimina de esta manera, pierde además 4...10 de energía.','Conjuro. Elimina un encantamiento. Efecto de la eliminación: el enemigo objetivo pierde 4...10 de energía.'],
1062=>['Latrocinio arcano','Conjuro. Durante 5...35 segundos, un conjuro aleatorio del enemigo objetivo se desactiva y el Latrocinio arcano es sustituido por ese conjuro.','Conjuro. (5...35 segundos). Desactiva un conjuro al azar. Esta habilidad se convierte en ese conjuro.'],
1066=>['Aguafiestas','Conjuro con maleficio de élite. Durante 3...15 segundos, siempre que el enemigo objetivo ataque o lance un conjuro sobre una criatura con menos salud, perderá 25...100 de salud.','Conjuro con maleficio de élite. (3...15 segundos). El enemigo objetivo pierde 25...100 de salud cada vez que ataque o lance conjuros sobre una criatura con menos salud.'],
1067=>['Golpe envenenado','Conjuro. El enemigo objetivo recibe 12...48 de daño de sombra. Si la salud de ese enemigo está por encima del 50%, le robarás 12...48 de salud.','Conjuro. Hace 12...48 de daño. Roba 12...48 de salud si el enemigo objetivo está por encima del 50% de salud.'],
1068=>['Escalofrío punzante','Conjuro. Haces al enemigo objetivo 15...60 de daño frío. Si éste tenía más salud que tú, el Escalofrío punzante se recargará inmediatamente.','Conjuro. Hace 15...60 de daño frío. Se recarga al instante si el enemigo objetivo tiene más salud que tú.'],
1069=>['Sabor del dolor','Conjuro. Si el enemigo objetivo está por debajo del 50% de salud, ganas 30...150 de salud.','Conjuro. Te curas 30...150 de salud. No funciona a menos que el enemigo objetivo esté por debajo del 50% de salud.'],
1070=>['Profanar encantamientos','Conjuro. El enemigo objetivo y todos los enemigos cercanos reciben 6...60 de daño de sombra y 4...20 de daño de sombra por cada encantamiento que tengan.','Conjuro. Hace 6...60 de daño al enemigo objetivo y los cercanos. Hace 4...20 de daño extra por encantamiento que tengan.'],
1071=>['Escalofríos temerosos','Conjuro con maleficio. Durante 10...40 segundos, siempre que el enemigo objetivo reciba daño frío al usar una habilidad, ese enemigo será interrumpido y tú perderás 8...3 de energía o finalizarán los Escalofríos temerosos.','Conjuro con maleficio. (10...40 segundos). Interrumpe las habilidades del enemigo objetivo si recibe daño frío. Coste de la interrupción: pierdes 8...3 de energía o este maleficio acaba.'],
1075=>['Enjambre vampírico','Conjuro. Un Enjambre vampírico roba 15...60 de salud de hasta tres enemigos en la zona.','Conjuro. Roba 15...60 de salud. Alcanza a 2 enemigos más en la zona.'],
1076=>['Chupador de sangre','Conjuro. Si tienes más del 90% de salud, sufrirás una hemorragia durante 6 segundos. Robas 20...65 de salud del enemigo objetivo.','Conjuro. Roba 20...65 de salud. Sufres una hemorragia (6 segundos) si tu salud estaba por encima del 90%'],
1077=>['Mordedura de vampiro','Habilidad. Toca a un enemigo para robarle hasta 29...74 de salud.','Habilidad de toque. Roba 29...74 de salud.'],
1078=>['Mordedura rastrera','Habilidad. El enemigo objetivo tocado recibe 20...58 de daño.','Habilidad de toque. Hace 20...58 de daño.'],
1079=>['Toque debilitante','Habilidad. El enemigo tocado pierde 5...65 de salud y queda debilitado durante 5...20 segundos.','Habilidad de toque. Causa 5...65 de pérdida de salud. Causa debilitamiento (5...20 segundos).'],
1081=>['Viento de Teinai','Conjuro. El enemigo objetivo y los adyacentes reciben 10...40 de daño frío. Los enemigos con quemadura alcanzados por el viento de Teinai reciben 40...80 de daño adicional y los interrumpe.','Conjuro. Hace 10...40 de daño frío. Los enemigos con quemadura reciben +40...80 de daño y son interrumpidos. También golpea a los adyacentes.'],
1082=>['Flecha eléctrica','Conjuro. Mandas un Flecha eléctrica que vuela presta hacia el enemigo objetivo y le causa 5...50 de daño de relámpago. Si la Flecha eléctrica alcanza a un enemigo con la armadura rota, ganas 5 de energía y 1 de energía por cada dos rangos de almacenamiento de energía. Flecha eléctrica tiene un 25% de penetración de armadura.','Conjuro. Proyectil rápido: causa 5...50 de daño de relámpago. Obtienes 5 de energía y 1 de energía por cada dos rangos de almacenamiento de energía si alcanzas a un enemigo con la armadura rota. 25% de penetración de armadura.'],
1083=>['Suelo inestable','Conjuro de élite. Creas un Suelo inestable donde se encuentre el enemigo objetivo. Durante 5 segundos, los enemigos cercanos reciben 10...40 de daño de tierra por segundo. Los enemigos alcanzados por Suelo inestable que estén atacando serán derribados.','Conjuro de élite. Hace 10...40 de daño de tierra por segundo (5 segundos) y causa derribo a los enemigos que estén atacando. Alcanza a los enemigos cercanos a la ubicación inicial del objetivo.'],
1084=>['Armadura tajada','Conjuro con encantamiento. Durante 5...11 segundos, tienes 25...50% de probabilidades de bloquear ataques y, cuando seas el objetivo de ataques o conjuros hostiles, un enemigo cercano recibirá 5...35 de daño de tierra.','Conjuro con encantamiento. (5...11 segundos). Tienes un 25...50% de probabilidad de bloquear. Hace 5...35 de daño de tierra a un enemigo cercano cuando seas el objetivo de ataques o conjuros hostiles.'],
1085=>['Explosión de ceniza','Conjuro con maleficio. El enemigo objetivo y los adyacentes reciben 35...65 de daño de tierra. Los enemigos con quemadura alcanzados por la Explosión de ceniza quedan malditos durante 5 segundos y tienen un 20...75% de posibilidades de fallar en sus ataques.','Conjuro con maleficio. Hace 35...65 de daño de tierra. Los enemigos que arden quedan malditos durante 5 y fallan un 20...75% de los ataques. También golpea a los adyacentes.'],
1086=>['Pisotón de dragón','Conjuro. Invocas un Pisotón de dragón en la ubicación del enemigo objetivo. Todos los enemigos cercanos a esa ubicación son derribados y reciben 26...100 de daño de tierra.','Conjuro. Causa 26...100 de daño de tierra. Causa derribo. También afecta a los enemigos cercanos a este enemigo.'],
1088=>['Viento secundario','Conjuro de élite. Ganas 1 de energía y 5 de salud por cada punto de energía restringido por el sobrelanzamiento. Pierdes todos los encantamientos.','Conjuro de élite. Ganas 1 de energía y 5 de salud por cada punto de sobrelanzamiento. Pierdes todos los encantamientos.'],
1090=>['Brasas humeantes','Conjuro con maleficio. El enemigo objetivo recibe 10...70 de daño de fuego. Si estás sobrelanzando, ese enemigo queda maldito por las Brasas humeantes durante 3 segundos y recibe 5...25 de daño de fuego adicional cada segundo.','Conjuro con maleficio. Hace 10...70 de daño de fuego al objetivo. Si estás sobrelanzando, ese enemigo queda maldito durante 3 segundos y recibe 5...25 de daño de fuego cada segundo.'],
1091=>['Dragón doble','Conjuro con encantamiento de élite. Invocas el poder del dragón. Durante 8 segundos, tú y el aliado objetivo quedáis encantados con Dragón doble. Los enemigos adyacentes reciben 10...40 de daño de fuego cada segundo. Además, cuando tú o tu aliado uséis habilidades que apunten a un enemigo, ese enemigo arderá durante 1...4 segundos.','Conjuro con encantamiento de élite. (8 segundos). Os encanta a ti y al aliado objetivo. Los enemigos adyacentes reciben 10...40 de daño de fuego cada segundo. Las habilidades que apuntan a un enemigo también causan quemadura (1...4 segundos).'],
1093=>['Calor de Teinai','Conjuro de protección. Coloca una protección de Calor de Teinai en tu ubicación durante 10...15 segundos. Los enemigos del interior de la protección sufren 2...5 de degeneración de salud. Los enemigos debilitados atacan un 33% más despacio. Esta habilidad estará desactivada durante 20 segundos.','Conjuro de protección. (10...15 segundos.) Causa -2...5 de degeneración de salud. Los enemigos debilitados en la protección atacan un 33% más despacio. Desactivada durante 20 segundos.'],
1094=>['Aliento de fuego','Conjuro. Creas un Aliento de fuego en la ubicación actual del enemigo objetivo. Durante 5 segundos, los enemigos adyacentes a la zona reciben 10...40 de daño de fuego por segundo.','Conjuro. Causa 10...40 de daño de fuego por segundo (5 segundos). Alcanza a los enemigos adyacentes a la ubicación inicial del objetivo.'],
1095=>['Supernova','Conjuro de élite. El enemigo objetivo alcanzado y todos los enemigos de la zona reciben 7...112 de daño de fuego y arden durante 1...4 segundos. Por cada enemigo que alcances, recibes 2 de energía.','Conjuro de élite de toque. Hace 7...112 de daño de fuego. Causa quemadura (1...4 segundos). Ganas 2 de energía por cada enemigo alcanzado. También alcanza a los enemigos dentro del área.'],
1096=>['Glifo de esencia','Glifo. Durante 15 segundos, tu siguiente conjuro se lanzará de forma instantánea pero perderás toda la energía.','Glifo. (15 segundos). Tu siguiente conjuro se lanza instantáneamente. Pierdes toda la energía.'],
1097=>['Prisión de Teinai','Conjuro con maleficio. Durante 1...8 segundos, las piernas del enemigo objetivo quedan aprisionadas en hielo, haciendo que el enemigo se mueva un 66% más despacio. Si el enemigo tiene la armadura rota, el hielo penetra y causa 5...9 de degeneración de salud.','Conjuro con maleficio. (1...8 segundos.) El enemigo objetivo se mueve un 66% más despacio. Los enemigos con la armadura rota tienen 5...9 de degeneración de salud.'],
1098=>['Espejo de hielo','Conjuro con maleficio de élite. Destrozas un Espejo de hielo. Todos los enemigos cerca de ti y del aliado objetivo reciben 15...70 de daño frío y se mueven un 66% más despacio durante 2...6 segundos. Si alcanzas a un enemigo que tiene un maleficio de magia de agua, el Espejo de hielo se recarga un 50% más rápido.','Conjuro con maleficio de élite. Hace 15...70 de daño frío y los enemigos se mueven un 66% más despacio (2...6 segundos). Afecta a los enemigos cerca de ti y del aliado objetivo. Se recarga un 50% más deprisa si alcanza a un enemigo que tiene un maleficio de magia de agua.'],
1099=>['Cristales de Teinai','Conjuro. El enemigo objetivo recibe 20...40 de daño. Si el enemigo objetivo tiene una maldición de magia de agua, este conjuro le causa a él y a los enemigos cercanos 20...40 puntos de daño adicionales y los enemigos cercanos también tienen la armadura rota durante 5...15 segundos.','Conjuro. Hace 20...40 de daño al objetivo. Hace +20...40 más de daño y rompe la armadura (5...15 segundos) a los enemigos cercanos si ese enemigo tenía un maleficio de magia de agua.'],
1113=>['Cólera del Kirin','Conjuro. Durante 5 segundos, los enemigos adyacentes recibirán 8...32 de daño sagrado por segundo.','Conjuro. Hace 8...32 de daño sagrado por segundo (5 segundos). Alcanza a los enemigos adyacentes a tu ubicación inicial.'],
1114=>['Vínculo espiritual','Conjuro con encantamiento. Durante 8 segundos, siempre que el objetivo (un aliado o tú mismo) reciba más de 50 de daño de los próximos 10 ataques o conjuros, se curará 30...90 de salud.','Conjuro con encantamiento. (8 segundos.) Cura 30...90 de salud siempre que el objetivo (un aliado o tú mismo) reciba más de 50 de daño. Acaba cuando este aliado reciba daño de 10 ataques o conjuros.'],
1115=>['Aire de encantamiento','Conjuro con encantamiento de élite. Durante 4...10 segundos, costará 10 menos energía lanzar encantamientos sobre el aliado objetivo (mínimo 1 de energía).','Conjuro con encantamiento de élite. (4...10 segundos). Los encantamientos sobre el aliado objetivo cuestan 10 menos de energía (mínimo 1 de energía). No te puedes apuntar a ti mismo.'],
1117=>['Deleite celestial','Conjuro. Tanto tú como los miembros del grupo al alcance del oído os curáis 15...60 de salud.','Conjuro. Tú y los miembros del grupo al alcance del oído os curáis 15...60 de salud.'],
1118=>['Explosión curativa','Conjuro de élite. Curas 20...120 de salud al aliado objetivo. Todos los miembros del grupo que estén al alcance del oído del objetivo ganan salud igual a la bonificación de favor divino de este hechizo. Tus plegarias de ataque quedan deshabilitadas durante 20 segundos.','Conjuro de élite. Cura 20...120. Los miembros del grupo que estén al alcance del oído del objetivo ganan salud igual a la bonificación de favor divino. <c x="SkillDull">Deshabilita tus plegarias de ataque (20 segundos).'],
1119=>['Area curativa de Karei','Conjuro. Tanto tú como todas las criaturas adyacentes os curáis 30...180 de salud.','Conjuro. Te curas 30...180 de salud. También cura a las criaturas adyacentes.'],
1120=>['Mirada de Jamei','Conjuro. Curas 35...180 de salud al aliado objetivo.','Conjuro. Cura 35...180 de salud. No te puedes apuntar a ti mismo.'],
1121=>['Don de salud','Conjuro. Todas tus demás habilidades de plegarias curativas quedan desactivadas durante 10...5 segundos. El aliado objetivo se cura 15...150 de salud.','Conjuro. Cura 15...150 de salud. Desactiva tus otras habilidades de plegarias curativas (10...5 segundos). No te puedes apuntar a ti mismo.'],
1123=>['Vaina de vida','Conjuro con encantamiento de élite. Eliminas 0...2 condiciones del objetivo aliado. Durante 8 segundos, la próxima vez que hagan daño o roben salud al aliado, éste ganará esa cantidad de salud en lugar de perderla (máximo 20...100).','Conjuro con encantamiento de élite. (8 segundos.) Convierte el siguiente daño o robo de salud recibido (máximo 20...100) en curación. Efecto inicial: Elimina 0...2 condiciones.'],
1126=>['Eliminación empática','Conjuro de élite. Tú y el aliado objetivo os quitáis una condición y un maleficio, y os curáis 50 de salud.','Conjuro de élite. Elimina una condición y un maleficio del aliado objetivo y de ti mismo, y cura 50 de salud. No te puedes apuntar a ti mismo.'],
1128=>['Canto de resurrección','Conjuro. Resucitas a un aliado con la misma salud que tengas y 5...35% de energía. Este conjuro tiene la mitad de alcance que los normales.','Conjuro con mitad de alcance. Resucita al miembro del equipo objetivo con tu salud actual y 5...35% de energía.'],
1129=>['Palabra de censura','Conjuro de élite. Haces 30...130 de daño sagrado al enemigo objetivo. Si tiene menos del 50 % de salud, la Palabra de censura tardará 20 segundos más en recargarse.','Conjuro de élite. Hace 30...130 de daño sagrado. +20 de tiempo de recarga si el enemigo objetivo está por debajo del 50 % de salud.'],
1130=>['Lanza de luz','Conjuro. Una lanza de luz vuela al enemigo objetivo, que hará 26...56 de daño sagrado si le alcanza y +15...60 de daño extra si estaba atacando.','Conjuro. Proyectil: hace 26...56 de daño sagrado. 15...60 de daño extra si el enemigo objetivo está atacando.'],
1131=>['Alma de piedra','Habilidad. El enemigo al que toques recibe 10...55 de daño sagrado. Si está derribado, recibirá 10...55 de daño sagrado extra.','Habilidad de toque. Hace 10...55 de daño sagrado. 10...55 de daño sagrado extra si el enemigo objetivo está derribado.'],
1133=>['Golpe embriagado','Ataque cuerpo a cuerpo. Si este ataque impacta, harás +10...40 de daño y tu objetivo sufrirá una de las siguientes condiciones: herida grave (durante 20 segundos), debilidad (20 segundos), hemorragia (25 segundos) o lisiadura (15 segundos). Después del Golpe embriagado, serás derribado.','Ataque cuerpo a cuerpo. Hace +10...40 de daño. Causa una de estas condiciones al azar: herida grave (20 segundos), debilitamiento (20 segundos), hemorragia (25 segundos) o lisiadura (15 segundos). Eres derribado.'],
1134=>['Barrido de Leviatán','Ataque cuerpo a cuerpo. Si este ataque impacta, harás +5...20 de daño. Si se bloquea este ataque, tu objetivo es derribado y sufre 10...34 de daño.','Ataque cuerpo a cuerpo. Hace +5...20 de daño. Causa derribo y hace 10...34 de daño si se bloquea.'],
1135=>['Golpe de Jaizhenju','Ataque con espada. Si el Golpe de Jaizhenju impacta, harás +1...30 de daño. Si no estás utilizando ninguna actitud, no se podrá bloquear.','Ataque con espada. Hace +1...30 de daño. No se puede bloquear a menos que mantengas una actitud.'],
1136=>['Tajo penetrante','Ataque con hacha. Si impacta, harás +10...25 de daño. Este ataque de hacha tiene un 20% de posibilidades de penetrar la armadura.','Ataque con hacha. Hace +10...25 de daño. 20% de penetración de armadura.'],
1137=>['Golpe del yeti','Ataque con martillo. Pierdes toda la adrenalina. Ataca a todos los enemigos adyacentes. Si este ataque alcanza a un enemigo que esté sufriendo una condición, le derribarás. (50% de posibilidades de fallar con dominio del martillo 4 o inferior).','Ataque con martillo. Ataca a todos los enemigos adyacentes. Derriba a los enemigos padeciendo alguna condición. Pierdes toda la adrenalina. 50% de posibilidades de fallar a no ser que tengas dominio del martillo 5 o superior.'],
1141=>['"¡Vais a morir!"','Grito. Si el enemigo objetivo está por debajo del 90 % de salud, ganas 1...3 golpes de adrenalina.','Grito. Ganas 1...3 golpes de adrenalina. No tiene efecto a menos que el enemigo objetivo esté por debajo del 90 % de salud.'],
1142=>['Bloqueo favorable','Actitud de élite. Durante 8 segundos, bloqueas el siguiente ataque contra ti. Ganas 1...4 golpes de adrenalina cuando esta actitud acabe.','Actitud de élite. (8 segundos). Bloquea un ataque. Efecto final: ganas 1...4 golpes de adrenalina.'],
1144=>['Tajo de Aladeacero','Ataque con espada. Este ataque hace +1...40 de daño si impacta.','Ataque con espada. Hace +1...40 de daño.'],
1146=>['Empujón','Habilidad de élite. El enemigo tocado por el objetivo recibe 15...75 de daño, su postura acaba y cae derribado.','Habilidad de élite de toque. El enemigo tocado por el objetivo recibe 15...75 de daño, su postura acaba y cae derribado.'],
1191=>['Ataque incisivo','Ataque con arco. Si el Ataque incisivo impacta, harás +5...25 de daño. Tiene un 10% de penetración de armadura.','Ataque con arco. Hace +5...25 de daño. 10% de penetración de armadura.'],
1192=>['Disparo de Zojun','Ataque con arco. Disparas una flecha que tiene la mitad de alcance, pero que hace +10...40 de daño.','Ataque con arco con mitad de alcance. Hace +10...40 de daño.'],
1194=>['Vínculo depredador','Grito. Durante 5...20 segundos, tu mascota ataca un 25% más rápido y te hace recuperar 1...31 de salud con cada ataque realizado.','Grito. (5...20 segundos.) Tu mascota ataca un 25% más rápido y recuperas 1...31 de energía con cada ataque realizado.'],
1195=>['Curación simbiótica','Habilidad de élite. Durante 15 segundos, tu mascota roba 1...20 de salud cada vez que logre hacer un ataque. Tú y tu mascota os curáis 20...104 de salud. Si tu mascota está muerta, la resucitarás con el 50% de salud. Si tienes equipada esta habilidad, tu mascota viajará contigo.','Habilidad de élite. (15 segundos). Los ataques de tu mascota roban 1...20 de salud. Efecto inicial: tú y tu mascota os curáis 20...104 de salud; resucitas a tu mascota (50% de salud) si está muerta. Si tienes equipada esta habilidad, tu mascota viajará contigo.'],
1196=>['Premura de Zojun','Actitud. Durante 5...11 segundos, te mueves un 33% más rápido y tienes un 27...75% de posibilidades de bloquear los proyectiles que te lancen. La Premura de Zojun finaliza si atacas.','Actitud. (5...11 segundos). Te mueves un 33% más rápido y tienes un 27...75% de probabilidades de bloquear proyectiles. Acaba si atacas.'],
1197=>['Disparo molesto','Ataque con arco. El Disparo molesto hace sólo 10...30 de daño pero es el doble de rápido de lo normal. Si alcanzas a un enemigo por debajo del 50% de salud, se recargará al instante. El resto de tus habilidades de ataque estarán desactivadas durante 2 segundos.','Ataque con arco. Flecha rápida. Hace 10...30 de daño. Se recarga al instante si el enemigo objetivo está por debajo del 50% de salud. Tus otras habilidades de ataque estarán desactivadas (2 segundos).'],
1198=>['Flecha de punta ancha','Ataque con arco de élite. Lanzas una flecha de punta ancha que se mueve más despacio de lo normal. Si consigues alcanzar al enemigo, quedará aturdido durante 5...20 segundos y si además estaba lanzando un conjuro, le interrumpirás.','Ataque con arco de élite. Flecha lenta. Interrumpe un conjuro. Causa aturdimiento (5...20 segundos).'],
1199=>['Flechas de cristal','Preparación["Preparaciones"] de élite. Durante 10...35 segundos, tus flechas hacen +6...20 de daño y causan hemorragia durante 10...20 segundos si las bloquean.','Preparación["Preparaciones"] de élite. (10...35 segundos). Tus flechas hacen +6...20 de daño. Causan hemorragia si se bloquean (10...20 segundos).'],
1200=>['Sello del arquero','Sello de élite. Durante 1...24 segundos, las condiciones que causes mientras lleves un arco duran un 150% más.','Sello de élite. (1...24 segundos). Las condiciones que causes mientras lleves un arco duran un 150% más.'],
1201=>['Salto salvaje','Ataque con mascota. El siguiente ataque de tu mascota será el Salto salvaje, que causa +5...20 de daño. Si consigue golpear a un enemigo preparando un conjuro, es derribado.','Ataque con mascota. Hace +5...20 de daño. Causa derribo si el enemigo objetivo está lanzando un conjuro.'],
1202=>['Embestida enrabietada','Ataque con mascota de élite. Tu mascota lanzará un ataque Embestida enrabietada que causa una herida grave al enemigo objetivo durante 5...20 segundoss y provoca +10...50 de daño.','Ataque con mascota de élite. Causa una herida grave (5...20 segundos) y provoca +10...50 de daño.'],
1203=>['Vapuleo bestial','Ataque con mascota. El siguiente ataque de tu mascota será el Vapuleo bestial, que causa +5...20 de daño. Si consigue golpear a un enemigo derribado, quedará éste aturdido durante 4...10 segundos.','Ataque con mascota. Hace +5...20 de daño. Causa aturdimiento (4...10 segundos) si el enemigo objetivo está derribado.'],
1205=>['Mordedura venenosa','Ataque con mascota. Tu mascota hará una mordedura que envenenará al enemigo objetivo durante 5...20 segundos.','Ataque con mascota. Causa envenenamiento (5...20 segundos).'],
1206=>['Brinco','Ataque con mascota. Tu mascota pegará un salto que causa +5...20 de daño. Si consigue golpear a un enemigo moviéndose, éste será derribado.','Ataque con mascota. Hace +5...20 daño. Causa derribo si el enemigo objetivo está en movimiento.'],
1209=>['Furia bestial','Actitud. Todas tus habilidades que no sean de ataque estarán desactivadas durante 5 segundos. Durante 5...11 segundos, atacas un 25% más rápido.','Actitud. (5...11 segundos). Atacas un 25% más deprisa. Tus otras habilidades que no son de ataque quedan desactivadas (5 segundos).'],
1211=>['Nido de víboras','Trampa. Creas un Nido de víboras. Al activarse, los enemigos cercanos recibirán 5...35 de daño perforante y quedarán envenenados durante 5...20 segundos. El Nido de víboras se morirá a los 90 segundos. Se te podrá interrumpir con facilidad mientras lo coloques.','Trampa. ((90 segundos). Afecta a los enemigos cercanos. Hace 5...35 de daño perforante. Causa envenenamiento (5...20 segundos). Se puede interrumpir con facilidad.'],
1212=>['Equinoccio','Ritual de la naturaleza de élite. Creas un espíritu de nivel 1...10. Los conjuros lanzados en su zona de alcance que causen sobrelanzamiento causan 10 de sobrelanzamiento adicionales. El espíritu morirá a los 30...240 segundos.','Ritual de la naturaleza de élite. Crea un espíritu de nivel 1...10 (30...240 segundos de vida). Los conjuros que causen sobrelanzamiento lanzados en la zona de alcance causan 10 de sobrelanzamiento adicionales.'],
1213=>['Tranquilidad','Ritual de la naturaleza. Creas un espíritu de nivel 1...10. Los encantamientos lanzados por criaturas no espíritus dentro de su radio se acaban un 20...50% más rápido. Morirá a los 15...120 segundos.','Ritual de la naturaleza. Crea un espíritu de nivel 1...10 (15...120 segundos de vida). Los encantamientos que tengan las criaturas de la zona acaban un 20...50% antes. No afecta a los espíritus.'],
1215=>['Clamor de almas','Conjuro de élite. El enemigo objetivo y los cercanos reciben 10...65 de daño de relámpago. Si estás al alcance del oído de un espíritu o estás llevando un objeto de mano, ganas 10 de energía.','Conjuro de élite. Hace 10...65 de daño de relámpago al enemigo objetivo y los cercanos. Ganas 10 de energía si estás al alcance del oído de un espíritu o estás llevando un objeto de mano.'],
1217=>['Señor de los rituales','Habilidad de élite. Durante 5...35 segundos, tus atributos de Ritualista aumentan en 2...4 puntos con tu siguiente habilidad. Si ésta es un ritual de encadenamiento, se recarga un 10...60% más deprisa y el Señor de los rituales se recarga instantáneamente.','Habilidad de élite. (5...35 segundos). Tienes +2...4 puntos en todos los atributos de Ritualista con tu siguiente habilidad. Si ésta es un ritual de encadenamiento, se recarga un 10...60% más deprisa y el Señor de los rituales se recarga instantáneamente.'],
1218=>['Malvado sea Daoshen','Conjuro con objeto. Llevas las cenizas de Daoshen durante 15...60 segundos. Mientras las lleves, todas las habilidades de Ritualista tienen 10% de penetración de armadura. Cuando las sueltes, todos los enemigos cercanos reciben 15...85 de daño de relámpago.','Conjuro con objeto. (15...60 segundos). Tus habilidades de Ritualista tienen un 10% de penetración de armadura. Efecto al soltarse: hace 15...85 de daño de relámpago a todos los enemigos cercanos.'],
1219=>['Protector sea Kaolai','Conjuro con objeto. Llevas las cenizas de Kaolai durante 15...60 segundos. Mientras, ganarás 20 de armadura y, cuando las sueltes, todos los miembros del grupo se curarán 20...95 de salud.','Conjuro con objeto. (15...60 segundos). Tienes +20 de armadura. Efecto al soltarse: todos los miembros del grupo se curan 20...95 de salud.'],
1220=>['En sintonía sea Songkai','Conjuro con objeto de élite. Llevas las cenizas de Songkai durante 45 segundos. Mientras, tus conjuros y rituales de encadenamiento de espíritus consumirán 5...50% menos de energía base.','Conjuro con objeto de élite. (45 segundos). Tus conjuros y rituales con espíritus cuestan un -5...50% del coste base de energía.'],
1221=>['Resistente sea Xiko','Conjuro con objeto. Llevas las cenizas de Xiko durante 5...20 segundos. Por cada maleficio o condición que estés padeciendo mientras tanto, ganarás +3 de regeneración de salud. Cuando sueltes las cenizas, perderás 1...4 condiciones.','Conjuro con objeto. (5...20 segundos). Tienes +3 de regeneración de salud por cada maleficio o condición que tengas. Efecto al soltarse: pierdes 1...4 condición["condiciones"].'],
1222=>['Vivaz sea Naomei','Conjuro con objeto. Llevas las cenizas de Naomei durante 45 segundos. Al soltarlas, todos los miembros del equipo dentro de la zona resucitarán con 15...75% de salud y cero de energía.','Conjuro con objeto. (45 segundos). Efecto al soltarse: resucita a los miembros del equipo dentro de la zona (15...75% de salud y cero de energía).'],
1223=>['Angustiosa sea Lingwah','Conjuro con objeto. Llevas las cenizas de Lingwah durante 10...60 segundos. Mientras las lleves, tus maleficios de Ritualista cuestan 1...5 menos de energía y duran un 50% más. Cuando sueltes las cenizas, se recargarán todos tus maleficios de Ritualista.','Conjuro con objeto. (10...60 segundos). Tus maleficios de Ritualista cuestan 1...5 menos de energía y duran un 50% más. Efecto al soltarse: todos tus maleficios de Ritualista se recargan.'],
1224=>['Espíritu arrastrado','Conjuro. Teletransportas al espíritu aliado objetivo hasta tu ubicación.','Conjuro. Teletransportas al espíritu aliado objetivo hasta tu ubicación.'],
1225=>['Golpe canalizado','Conjuro. Haces 5...95 de daño de relámpago al enemigo objetivo y 5...35 adicional si estás llevando algún objeto.','Conjuro. Hace 5...95 de daño de relámpago. 5...35 de daño de relámpago extra si llevas un objeto.'],
1226=>['Golpe del espíritu unido','Conjuro. Haces 20...65 de daño de relámpago al enemigo objetivo y todos los espíritus que controles al alcance del oído ganan 20...65 de salud.','Conjuro. Causa 20...65 de daño relámpago. Los espíritus que controles al alcance del oído ganan 20...65 de salud.'],
1227=>['Golpe de esencia','Conjuro. Haces 15...60 de daño de relámpago al enemigo objetivo. Si hay espíritus al alcance del oído, ganas 1...9 de energía.','Conjuro. Hace 15...60 de daño de relámpago. Ganas 1...9 de energía si hay espíritus al alcance del oído.'],
1228=>['Chorro espiritual','Conjuro. El espíritu que tengas más cerca pierde toda la energía. Tú ganas 30...60% de dicha energía.','Conjuro. El espíritu que tengas más cerca pierde toda la energía. Tú ganas 30...60% de dicha energía.'],
1229=>['Crecimiento explosivo','Conjuro con encantamiento. Durante 15...60 segundos, cuando crees una criatura, hasta un máximo de 5 enemigos cercanos recibirán 20...65 de daño de relámpago.','Conjuro con encantamiento. (15...60 segundos). Hace 20...65 de daño de relámpago a 5 enemigos cercanos cada vez que invoques alguna criatura.'],
1230=>['Bendición creadora','Conjuro con encantamiento. Durante 15...60 segundos, cuando crees una criatura ganarás 5...50 de salud y 1...6 de energía.','Conjuro con encantamiento. (15...60 segundos). Ganas 5...50 de salud y 1...6 de energía cada vez que invoques una criatura.'],
1231=>['Canalización espiritual','Conjuro con encantamiento de élite. Durante 12 segundos, tienes +1...6 de regeneración de energía. Cuando lances este conjuro, ganas 3...12 de energía si estás al alcance del oído de un espíritu.','Conjuro con encantamiento de élite. (12 segundos). Tienes +1...6 regeneración de energía. Efecto inicial: ganas 3...12 de energía si estás al alcance del oído de algún espíritu.'],
1232=>['Armadura de insensibilidad','Habilidad. Durante 10...35 segundos, tus espíritus al alcance del oído reciben 50% menos de daño y son inmunes a ataques críticos.','Habilidad. (10...35 segundos.) Tus espíritus al alcance del oído reciben 50% menos de daño y son inmunes a ataques críticos.'],
1233=>['Recuerdos calmantes','Conjuro. El objetivo (un aliado o tú mismo) se cura 10...100 de salud. Además, si estás llevando algún objeto, ganarás 3 de energía.','Conjuro. Cura 10...100 de salud. Ganas 3 de energía si estás llevando un objeto.'],
1234=>['Unir cuerpo y alma','Conjuro. Curas 20...115 de salud al aliado objetivo. El aliado pierde una condición por cada espíritu al alcance del oído.','Conjuro. Cura 20...115 de salud. Quita una condición por cada espíritu al alcance del oído.'],
1235=>['Arma deslustrada','Conjuro con maleficio. Durante 5...20 segundos, el enemigo objetivo y los adyacentes no podrán hacer un golpe crítico y hacen 3...20 menos de daño.','Conjuro con maleficio. También afecta a los enemigos adyacentes al objetivo (5...20 segundos). Elimina la posibilidad de hacer un golpe crítico. Reduce el daño en 3...20.'],
1236=>['Cadenas encadenadas','Conjuro con maleficio. Durante 3 segundos, el enemigo objetivo y los cercanos se mueven un 90% más despacio y reciben 1...30 de daño por segundo mientras se muevan.','Conjuro con maleficio. También afecta a los enemigos cercanos al objetivo (3 segundos). Estos enemigos se mueven un 90% más lento y reciben 1...30 de daño por segundo mientras se muevan.'],
1237=>['Vínculo doloroso','Conjuro con maleficio. Durante 10...20 segundos, el enemigo objetivo y los cercanos quedan maldecidos con el Vínculo doloroso y reciben 8...20 de daño siempre que un espíritu les golpee.','Conjuro con maleficio. También afecta a los enemigos cercanos a tu objetivo (10...20 segundos). Los espíritus hacen 8...20 más de daño a esos enemigos.'],
1238=>['Sello de creación','Sello. Ganas 4 de energía por cada criatura invocada que controles al alcance del oído (máximo 3...12 de energía).','Sello. Ganas 4 de energía (máximo 3...12 de energía) por cada criatura invocada que controles al alcance del oído.'],
1239=>['Sello de espíritus','Sello de élite. Creas 3 espíritus de nivel 1...12, cuyos ataques causan 5...20 de daño y mueren al cabo de 60 segundos.','Sello de élite. Crea 3 espíritus de nivel 1...12 (60 segundos de vida), cuyos ataques causan 5...20 de daño.'],
1240=>['Almas unidas','Habilidad de élite. Durante 5...45 segundos, tus rituales de encadenamiento de espíritus cuestan 15 menos de energía (mínimo 5) y se recargan instantáneamente. Almas unidas acaba después de 1...3 ritual[es] de encadenamiento.','Habilidad de élite. (5...45 segundos). Tus rituales de encadenamiento de espíritus cuestan 15 menos de energía (mínimo 5) y se recargan instantáneamente. Acaba después de 1...3 ritual[es] de encadenamiento.'],
1244=>['Velocidad fantasmal','Conjuro con encantamiento. Durante 5...30 segundos, los conjuros que lances al alcance del oído de un espíritu se recargan un 25% más rápido.','Conjuro con encantamiento. (5...30 segundos). Los conjuros que lances se recargan un 25% más deprisa. No tiene efecto si no estás al alcance del oído de algún espíritu.'],
1245=>['Mirada del más allá','Conjuro. El enemigo objetivo recibe 20...65 de daño de relámpago. Si estás al alcance del oído de algún espíritu, el enemigo queda cegado durante 2...6 segundos.','Conjuro. Causa 20...65 de daño relámpago. Causa ceguera durante 2...6 segundos si estás al alcance del oído de algún espíritu.'],
1246=>['Rabia ancestral','Habilidad. Durante 1 segundos, no ocurre nada. Cuando esta habilidad acabe, todos los enemigos adyacentes al enemigo objetivo reciben 5...110 de daño de relámpago.','Habilidad. (1 segundos). Efecto final: hace 5...110 de daño de relámpago a todos los enemigos adyacentes al objetivo (un aliado o tú mismo).'],
1247=>['Dolor','Ritual con espíritus. Creas un espíritu de nivel 1...12, cuyos ataques causan 5...30 de daño. Morirá a los 30...150 segundos.','Ritual con espíritus. Creas un espíritu de nivel 1...12 (30...150 segundos de vida). Sus ataques hacen 5...30 de daño.'],
1249=>['Desplazamiento','Ritual con espíritus. Creas un espíritu de nivel 1...14. Todos los aliados no espíritus al alcance del oído tienen un 75% de probabilidades de bloquear ataques. Cada vez que se bloquee uno así, este espíritu recibirá 60 de daño. Morirá a los 30...60 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...14 (30...60 segundos de vida). Los aliados no espíritu de la zona tienen un 75% de probabilidades de bloquear. Efecto del bloqueo: este espíritu recibe 60 de daño.'],
1250=>['Conservación','Ritual con espíritus de élite. Creas un espíritu de nivel 1...14 que, cada 4 segundos, curará a un aliado no espíritu de la zona 10...115 de salud. Morirá a los 90 segundos.','Ritual con espíritus de élite. Crea un espíritu de nivel 1...14 (90 segundos de vida). Cada 4 segundos, este espíritu cura 10...115 de salud a un aliado no espíritu de la zona.'],
1251=>['Vida','Ritual con espíritus. Creas un espíritu de nivel 1...14. Cuando éste muera, todos los aliados no espíritus de la zona se curarán 1...7 de salud por cada segundo que haya estado vivo. Morirá a los 20 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...14 (20 segundos de vida). Afecta a los aliados no espíritu dentro de la zona. Efecto final: cura 1...7 de salud por cada segundo que haya estado vivo.'],
1252=>['Atadura terrenal','Ritual con espíritus. Creas un espíritu de nivel 1...14. Todos los enemigos no espíritu derribados dentro de su zona no se podrán levantar en al menos 3 segundos. Cuando esto ocurra, el espíritu perderá 50...25 de salud. Morirá a los 15...45 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...14 (15...45 segundos de vida). Cada vez que los enemigos no espíritu de la zona sean derribados, estarán en el suelo al menos 3 segundos. Coste del derribo: el espíritu pierde 50...25 de salud.'],
1253=>['Canción sangrienta','Ritual con espíritus. Creas un espíritu de nivel 1...12 que muere a los 30...150 segundos. Los ataques de este espíritu roban hasta 5...25 de salud.','Ritual con espíritus. Crea un espíritu de nivel 1...12 (30...150 segundos de vida). Sus ataques roban 5...25 de salud.'],
1255=>['Trotamundeo','Ritual con espíritus de élite. Creas un espíritu de nivel 1...12. Cuando ataque a un enemigo parado, éste será derribado y el espíritu perderá 70...50 de salud. Morirá a los 30...60 segundos.','Ritual con espíritus de élite. Crea un espíritu de nivel 1...12 (30...60 segundos de vida). Sus ataques contra los enemigos parados causan derribo.Coste del derribo: el espíritu pierde 70...50 de salud.'],
1257=>['Arma de luz espiritual','Conjuro con arma de élite. Durante 10 segundos, el objetivo (un aliado o tú mismo) gana 5...25 de salud por segundo y 5...25 extra por segundo si está al alcance del oído de un espíritu.','Conjuro con arma de élite. (10 segundos). El aliado objetivo gana 5...25 de salud cada segundo. 5...25 de curación adicional por segundo si hay un espíritu al alcance del oído.'],
1258=>['Arma brutal','Conjuro con arma. Le das al objetivo (un aliado o tú mismo) un Arma brutal durante 10...40 segundos, con la que hará +5...15 de daño al golpear siempre que no tenga ningún encantamiento.','Conjuro con arma. (10...40 segundos). Los ataques hacen +5...15 de daño. No tiene efecto si el aliado objetivo está encantado.'],
1259=>['Arma dirigida','Conjuro con arma. Durante 4...10 segundos, los ataques de objetivo (un aliado o tú mismo) no pueden bloquearse.','Conjuro con arma. (4...10 segundos). Los ataques no se pueden bloquear.'],
1260=>['Docilidad','Conjuro con maleficio. Durante 5...30 segundos, el enemigo objetivo y todos los que estén en la zona atacarán un 50% más despacio.','Conjuro con maleficio. También afecta a los enemigos en la zona del objetivo (5...30 segundos). Atacan un 17% más despacio.'],
1261=>['Armadura frígida','Conjuro con encantamiento. Durante 10...25 segundos, ganas +10...40 de armadura contra daño físico y no puedes arder.','Conjuro con encantamiento. (10...25 segundos). Tienes +10...40 de armadura contra daño físico e inmunidad contra quemaduras.'],
1262=>['Anillo curativo','Conjuro. Curas 30...180 de salud a las criaturas adyacentes. No afecta a uno mismo.','Conjuro. Cura a los aliados y enemigos adyacentes 30...180 de salud. No afecta a uno mismo.'],
1263=>['Vuelta a la vida','Conjuro. Resucitas al compañero del grupo que toques con el 50% de salud y 5...20% de energía. Ese compañero y todos los aliados al alcance del oído se curan 55...130 de salud.','Conjuro de toque. Resucita al miembro del equipo (50% de salud y 5...20% de energía). Cura 55...130.de salud a los aliados al alcance del oído.'],
1264=>['Maldición','Conjuro. Haces 10...60 de daño de relámpago (máximo 135) al enemigo objetivo por cada ritual de encadenamiento de espíritus recargándose que tengas.','Conjuro. Hace +10...60 de daño relámpago (daño máximo: 135) por cada ritual con espíritus recargándose.'],
1265=>['Ventaja del atacante','Conjuro. Curas al objetivo (un aliado o tú mismo) 15...60 de salud. Si está bajo los efectos de un conjuro de arma, la Ventaja del atacante le curará 15...75 de salud extra.','Conjuro. Cura 15...60 de salud. Cura 15...75 de salud extra si este aliado está bajo un conjuro con arma.'],
1266=>['Calmante','Ritual con espíritus. Creas un espíritu de nivel 1...12. Los enemigos de la zona tardan el doble en crear adrenalina. Morirá a los 15...45 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...12 (15...45 segundos de vida). Los enemigos de la zona tardan el doble en acumular adrenalina.'],
1267=>['Arma vital','Conjuro con arma. Durante 5...30 segundos, el objetivo (un aliado o tú mismo) tiene un Arma vital y +40...175 de salud máxima.','Conjuro con arma. (5...30 segundos). +40...175 de salud máxima.'],
1268=>['Arma de velocidad','Conjuro con arma de élite. Durante 5...25 segundos, el objetivo (un aliado o tú mismo) tiene un Arma de velocidad, gracias a la cual los conjuros y los rituales de encadenamiento de espíritus se recargan un 33% más deprisa.','Conjuro con arma de élite. (5...25 segundos). Los conjuros y rituales con espíritus se recargan un 33% más rápido.'],
1269=>['Sello de rabia','Sello. Haces 5...50 de daño sagrado al enemigo objetivo, además de +5...10 de daño sagrado extra por cada habilidad de adrenalina que tenga.','Sello. Hace 5...50 de daño sagrado. 5...10 de daño sagrado extra por cada habilidad de adrenalina del enemigo objetivo.'],
1333=>['Prolongar condiciones','Conjuro de élite. Propagas todas las condiciones que tenga tu objetivo a los enemigos adyacentes. La duración de las condiciones se incrementará en un 5...100% (máximo 30 segundos).','Conjuro de élite. Propagas todas las condiciones que tenga tu objetivo a los enemigos adyacentes. La duración de las condiciones se incrementará en un 5...100% (máximo 30 segundos).'],
1334=>['Hipocondría','Conjuro. Transfieres todas las condiciones de los enemigos de la zona al enemigo objetivo.','Conjuro. Transfieres todas las condiciones de los enemigos de la zona al enemigo objetivo.'],
1335=>['Muerte del derrochador','Conjuro con maleficio. Durante 5 segundos, el enemigo objetivo se ve afectado por el maleficio Muerte del derrochador. Por cada segundo que dura el maleficio, el enemigo objetivo y todos los enemigos adyacentes a él reciben 1...10 de daño y 1...10 de daño adicional por cada segundo que el conjuro esté activo. El maleficio termina de forma prematura si el enemigo objetivo usa una habilidad.','Conjuro con maleficio. (5 segundos). Por cada segundo que dura el maleficio, el enemigo objetivo y todos los enemigos adyacentes a él reciben 1...10 de daño. Los enemigos reciben un daño de +1...10 por cada segundo que el maleficio esté activo. Termina de forma prematura si el enemigo objetivo usa una habilidad.'],
1336=>['Dolor espiritual','Conjuro. El enemigo objetivo recibe 15...75 de daño. Todas las criaturas hostiles invocadas que se encuentran en la zona del enemigo reciben 25...125 de daño.','Conjuro. Causa 15...75 de daño. Hace 25...125 de daño a las criaturas hostiles invocadas que se encuentran en la zona del enemigo objetivo.'],
1337=>['Quitailusiones','Conjuro. Eliminas un maleficio de Hipnotizador al enemigo objetivo. Si lo haces, perderá 1...5 de energía y tú ganarás 4 por cada punto que pierda.','Conjuro. Elimina un maleficio de Hipnotizador del enemigo objetivo. Hace perder 1...5 de energía. Ganas 4 de energía por cada punto perdido. No tiene efecto si no se elimina un maleficio.'],
1338=>['Persistencia de los recuerdos','Conjuro con encantamiento. Durante 5...20 segundos, siempre que te interrumpan al lanzar un conjuro, éste se recargará al instante.','Conjuro con encantamiento. (5...20 segundos). Tus conjuros interrumpidos se recargan al instante.'],
1339=>['Símbolos de inspiración','Habilidad de élite. Durante 6...40 segundos, esta habilidad se transforma en la habilidad de élite del enemigo objetivo. Las habilidades de élite que lances usarán tu atributo lanzamiento rápido en lugar de su atributo correspondiente.','Habilidad de élite. (6...40 segundos). Esta habilidad se transforma en la habilidad de élite del enemigo objetivo. Las habilidades de élite usarán tu atributo lanzamiento rápido en lugar de su atributo correspondiente.'],
1340=>['Celeridad simbólica','Conjuro con encantamiento. Durante 36...60 segundos, todos tus sellos utilizan tu atributo de lanzamiento rápido de conjuros, en lugar de los atributos normales.','Conjuro con encantamiento. (36...60 segundos). Tus sellos utilizan tu atributo de lanzamiento rápido de conjuros.'],
1341=>['Frustración','Conjuro con maleficio. Durante 5...20 segundos, el enemigo objetivo lanza los conjuros un 50% más despacio y recibe 5...50 de daño cada vez que se le interrumpa. Si se interrumpe una habilidad, la Frustración hace el doble de daño.','Conjuro con maleficio. (5...20 segundos). Hace que los conjuros tarden un 50% más en lanzarse. El enemigo objetivo recibe 5...50 de daño cada vez que se le interrumpa. Hace el doble de daño si se interrumpe una habilidad.'],
1342=>['Bromista','Conjuro de élite. Si el enemigo objetivo está utilizando una habilidad, ese enemigo y los de la zona serán interrumpidos y tú robarás 0...5 de energía de todos ellos.','Conjuro de élite. Interrumpe una habilidad. Efecto de interrupción: también interrumpe a otros enemigos de la zona y robas 0...5 de energía a todos ellos.'],
1343=>['Fantasma de éter','Conjuro con maleficio. Durante 10 segundos, el enemigo objetivo tiene una degeneración de energía de -1. Si este maleficio se elimina antes de tiempo, el enemigo pierde 1...5 de energía.','Conjuro con maleficio. (10 segundos). Causa -1 de degeneración de energía. Hace perder 1...5 de energía si este maleficio acaba antes.'],
1344=>['Red interruptora','Conjuro con maleficio. Interrumpes al enemigo objetivo. Durante 10 segundos, el enemigo tiene encima una Red interruptora. Cuando este maleficio termine, volverás a interrumpirlo de nuevo.','Conjuro con maleficio. (10 segundos). Efecto inicial: interrumpe una habilidad. Efecto final: interrumpe una habilidad.'],
1345=>['Enigma del encantador','Conjuro con maleficio de élite. Durante 10 segundos, el enemigo objetivo lanzará los encantamientos un 100...200 % más lento. Si el enemigo objetivo no está bajo los efectos de ningún encantamiento cuando este maleficio se active, el enemigo sufre 10...100 de daño y todos los enemigos adyacentes reciben un 75 % de ese daño.','Conjuro con maleficio de élite. Hace que los encantamientos tarden un 100...200 % más en lanzarse (10 segundos). Efecto inicial: causa 10...100 de daño al enemigo objetivo y un 75 % de ese daño a todos los enemigos adyacentes si el objetivo no tiene ningún encantamiento.'],
1346=>['Sello de las ilusiones','Sello de élite. Tus siguientes conjuros (1...3) usan el atributo "magia de ilusión" en vez de su atributo normal.','Sello de élite. Tus siguientes conjuros (1...3) usan el atributo "magia de ilusión" en vez de su atributo normal.'],
1347=>['Descargar encantamiento','Conjuro. Le quitas un encantamiento al enemigo objetivo. Si éste tenía un maleficio, esta habilidad se recargará un 20...50% más deprisa.','Conjuro. Elimina un encantamiento del enemigo objetivo. 20...50% menos de tiempo de recarga si el enemigo tiene un maleficio.'],
1348=>['Vórtice devoramaleficios','Conjuro de élite. Se elimina un maleficio de un objetivo aliado. Si se quita un maleficio de esta forma, los enemigos de la zona de ese aliado reciben 30...90 de daño y pierden un encantamiento.','Conjuro de élite. Elimina un maleficio de un objetivo aliado. Efecto de la eliminación: hace 30...90 de daño y elimina un encantamiento de los enemigos de la zona de ese aliado.'],
1349=>['Espejo del desencantamiento','Conjuro. Eliminas un encantamiento del enemigo objetivo y todos sus compañeros también pierden el mismo.','Conjuro. Elimina un encantamiento del enemigo objetivo. Los miembros del grupo del enemigo objetivo también pierden ese encantamiento.'],
1350=>['Robo simple','Conjuro de élite. Interrumpes la acción del enemigo objetivo. Si la acción era una habilidad, quedará desactivada durante 5...20 segundos, y el Robo simple es sustituido por esa habilidad.','Conjuro de élite. Interrumpe una acción. Efecto: si se interrumpe una habilidad, quedará desactivada y el Robo simple es sustituido por esa habilidad (5...20 segundos).'],
1351=>['Animar horror de mole','Conjuro. Explotas al cadáver más cercano para crear un horror de mole de nivel 1...17. Cuando muera, se sustituirá por un horror de sierra de nivel 0...15 que causará hemorragias al atacar.','Conjuro. Crea un horror de mole de nivel 1...17. Cuando muera, se sustituirá por un horror de sierra de nivel 0...15 que causa hemorragias al atacar. Explotas un cadáver.'],
1352=>['Orden de los muertos vivientes','Conjuro de élite. Durante 5 segundos, tus siervos hacen +3...16 de daño, pero pierdes 2% de tu salud máxima siempre que alguno de ellos logre golpear con un ataque.','Conjuro de élite. (5 segundos). Tus siervos hacen +3...16 de daño. Efecto por cada ataque de siervo: pierdes un 2% de tu salud máxima.'],
1353=>['Carne putrefacta','Conjuro. Destruyes a uno de tus siervos animados objetivo. Todos los enemigos cercanos a esa criatura quedan enfermos durante 5...15 segundos.','Conjuro. Destruye uno de tus siervos. Causa enfermedad (5...15 segundos) a los enemigos cercanos a este siervo.'],
1354=>['Festín mortal','Conjuro. Destruyes al muerto viviente aliado objetivo y todos tus otros muertos vivientes se curan 10...100 de salud.','Conjuro. Destruye uno de tus siervos. Cura a tus demás siervos 10...100 de salud.'],
1355=>['Huesos serrados','Conjuro con encantamiento de élite. En los próximos 60 segundos, cada vez que muera el siervo objetivo, se sustituirá por un horror de sierra de nivel 0...15 que hará hemorragias al atacar.','Conjuro con encantamiento de élite. (60 segundos). Cada vez que muera el siervo objetivo, se sustituirá por un horror de sierra de nivel 0...15 que causa hemorragia al atacar.'],
1356=>['Contagio','Conjuro con encantamiento de élite. Durante 60 segundos, cada vez que sufras una nueva condición, todos los enemigos de la zona la sufrirán también y sacrificarás el 10...5% del máximo de salud.','Conjuro con encantamiento de élite. (60 segundos). Cada vez que recibas una condición, todos los enemigos de la zona reciben la misma. Sacrificas el 10...5% de salud máxima cada vez que esto ocurra.'],
1358=>['Pulmones ulcerosos','Conjuro con maleficio. Durante 10...30 segundos, el enemigo objetivo y todos los cercanos sufrirán -4 de degeneración de salud cuando tengan una hemorragia, y cada vez que usen un grito o cántico sangrarán durante 5...20 segundos.','Conjuro con maleficio. También afecta a los enemigos cercanos a tu objetivo (10...30 segundos). Causa -4 de degeneración de salud a los que tengan una hemorragia. Causa hemorragia (5...20 segundos) cada vez que esos enemigos usen un grito o cántico.'],
1359=>['Dolor del desencantamiento','Conjuro de élite. El enemigo objetivo pierde 1...3 encantamientos. Si pierde alguno de este modo, ese enemigo y todos los adyacentes pierden 10...100 de salud.','Conjuro de élite. El enemigo objetivo pierde 1...3 encantamientos. Efecto: ese enemigo y todos los adyacentes pierden 10...100 de salud.'],
1360=>['Marca de furia','Conjuro con maleficio. Durante 5 segundos, los aliados que golpeen al enemigo objetivo ganan 0...2 golpes de adrenalina. Cuando este maleficio acabe, el enemigo tendrá la armadura rota durante 1...15 segundos.','Conjuro con maleficio. (5 segundos). Los aliados que golpeen al enemigo ganan 0...2 golpes de adrenalina. Efecto final: causa armadura rota (1...15 segundos).'],
1362=>['Corrompencantamientos','Conjuro con maleficio de élite. Quita un encantamiento del enemigo objetivo. Si se quita un encantamiento de esta forma, éste sufrirá una degeneración de -1...8 de salud durante 10 segundos.','Conjuro con maleficio de élite. Elimina un encantamiento del enemigo objetivo. Efecto de la eliminación: -1...8 de degeneración de salud (10 segundos).'],
1363=>['Sello del pesar','Sello. Haces 15...75 de daño al enemigo objetivo. Si está cerca de un cadáver o tiene una mascota muerta, esta habilidad se recargará al instante.','Sello. Causa 15...75 de daño. Recarga instantánea si el enemigo objetivo está cerca de un cadáver o tiene una mascota muerta.'],
1364=>['Sello de sufrimiento','Sello de élite. Sufres hemorragia durante 6 segundos. La próxima habilidad de Nigromante que lances sobre un enemigo causará hemorragia durante 2...16 segundos.','Sello de élite. Sufres hemorragia durante 6 segundos. Causa hemorragia (2...16 segundos) al objetivo de la próxima habilidad de Nigromante.'],
1365=>['Sello de las almas perdidas','Sello. Si el enemigo objetivo está por debajo del 50% de salud, ganas 10...100 de salud y 1...10 de energía.','Sello. Ganas 10...100 de salud y 1...10 de energía si el enemigo objetivo está por debajo del 50% de salud.'],
1366=>['Pozo de oscuridad','Conjuro de pozo. Explotas el cadáver más cercano o sacrificas un 66 % de salud para crear un Pozo de oscuridad durante 5...50 segundos. Los enemigos con algún maleficio dentro del pozo fallarán el 50 % de las veces.','Conjuro de pozo. (5...50 segundos). Los enemigos con maleficio dentro de este pozo tienen un 50 % de probabilidades de fallar. Explotas un cadáver reciente o sacrificas un 66 % de salud.'],
1367=>['Oleada cegadora','Conjuro de élite. El enemigo objetivo recibe 5...50 de daño de relámpago. Ese enemigo y todos los enemigos cercanos quedan cegados durante 3...8 segundos. Este conjuro tiene un 25% de penetración de armadura. Si este conjuro alcanza a un enemigo que esté atacando, también alcanza a los enemigos adyacentes y hace un 50% más de daño.','Conjuro de élite. Causa 5...50 de daño de relámpago. Causa ceguera al objetivo y a los enemigos cercanos (3...8 segundos). 25% de penetración de armadura. Si el objetivo estaba atacando, también alcanza a los enemigos adyacentes y hace un 50% más de daño.'],
1368=>['Vientos fríos','Conjuro con maleficio. El enemigo objetivo y todos los adyacentes reciben 30...60 de daño frío. Durante 10 segundos, el siguiente maleficio de agua dirigido a un enemigo con maleficio durará un 25...100% más.','Conjuro con maleficio. (10 segundos.) El siguiente maleficio de agua sobre el enemigo objetivo durará un 25...100% más. Efecto inicial: 30...60 de daño frío. También golpea a los adyacentes.'],
1369=>['Descarga eléctrica','Conjuro. Lanzas una Descarga eléctrica que hace 5...50 de daño de relámpago si acierta. Si impacta a un enemigo que esté moviéndose, le harás 5...50 de daño de relámpago extra. Este conjuro tiene un 25% de penetración de armadura.','Conjuro. Proyectil: hace 5...50 de daño de relámpago. Hace 5...50 más de daño de relámpago si el objetivo se está moviendo. 25% de penetración de armadura.'],
1370=>['Prisa del Djinn de tormenta','Conjuro con encantamiento. Te mueves un 25% más rápido durante 10...25 segundos. Por cada segundo en movimiento, pierdes 1 de energía.','Conjuro con encantamiento. (10...25 segundos). Te mueves un 25% más rápido. Pierdes 1 de energía cada segundo mientras te estés moviendo.'],
1371=>['Atacante de piedra','Conjuro con encantamiento. Durante 5...30 segundos, siempre que te golpeen con algún ataque elemental o físico, el daño recibido será de tierra.','Conjuro con encantamiento. (5...30 segundos). Convierte en daño de tierra el daño físico y de los elementos que recibas o hagas.'],
1372=>['Tormenta de arena','Conjuro de élite. Creas una Tormenta de arena en la ubicación del enemigo objetivo. Durante 10 segundos, los enemigos cercanos reciben 20...40 de daño de tierra por segundo y los que estén atacando 10...30 de daño de tierra adicional.','Conjuro de élite. Causa 20...40 de daño de tierra por segundo (10 segundos). Alcanza a los enemigos cercanos a la ubicación inicial del enemigo objetivo. Hace 10...30 de daño de tierra extra por segundo a los enemigos atacando.'],
1373=>['Vaina de piedra','Conjuro con encantamiento de élite. Durante 5...20 segundos, tú y el aliado objetivo tenéis +1...30 de armadura y sois inmunes a los golpes críticos. Cuando lanzas este conjuro, todos los enemigos cerca de ti y de tu objetivo reciben 15...70 de daño de tierra y sufren debilitamiento durante 5...20 segundos.','Conjuro con encantamiento de élite. (5...20 segundos). Os da a ti y al aliado objetivo +1...30 de armadura e inmunidad a los golpes críticos. Efecto inicial: Los enemigos cerca de ti y del aliado objetivo reciben 15...70 de daño de tierra y padecen debilitamiento (5...20 segundos).'],
1374=>['Halcón de ébano','Conjuro. Lanza un proyectil que provoca 10...85 de daño de tierra en el objetivo y causa debilitamiento durante 5...15 segundos si alcanza al enemigo.','Conjuro. Proyectil: causa 10...85 de daño de tierra y provoca debilitamiento (5...15 segundos).'],
1375=>['Aura de carne de piedra','Conjuro con encantamiento. Durante 5...15 segundos, el daño que recibas se reduce en 1...31 y eres inmune a ataques críticos.','Conjuro con encantamiento. (5...15 segundos). Reduce el daño que recibes en 1...31 y eres inmune a ataques críticos.'],
1376=>['Glifo de restauración','Glifo. Durante 15 segundos, tus siguientes 2 conjuros te curan 30...105 de salud y además te curas el 150...400% del coste de energía de cada conjuro.','Glifo. (15 segundos.) Tus siguientes 2 conjuros te curan 30...105 de salud y además te curas el 150...400% del coste de energía de cada conjuro.'],
1377=>['Prisma de éter','Habilidad de élite. Durante 3 segundos, todo el daño que recibes se reduce un 75%. Cuando el Prisma de éter acabe, ganarás 5...20 de energía.','Habilidad de élite. (3 segundos). Todo el daño que recibes se reduce un 75%. Efecto final: ganas 5...20 de energía.'],
1378=>['Maestro de magias','Conjuro con encantamiento de élite. Durante 1...61 segundos, todos tus atributos de los elementos pasan a 8...14 y tus conjuros de los elementos devuelven 1 de energía más el 30 % de su coste.','Conjuro con encantamiento de élite. (1...61 segundos). Tus atributos de los elementos pasan a 8...14 y tus conjuros de los elementos devuelven 1 de energía más el 30 % de su coste.'],
1379=>['Mirada brillante','Conjuro. El enemigo objetivo recibe 5...50 de daño de fuego. Si ese enemigo está ardiendo, ganas 5 de energía más 1 de energía por cada 2 rangos de almacenamiento de energía.','Conjuro. Hace 5...50 de daño de fuego. Ganas 5 de energía más 1 de energía por cada 2 rangos de almacenamiento de energía si el enemigo objetivo está ardiendo.'],
1380=>['Calor de la sabana','Conjuro de élite. Creas un Calor de la Sabana en la ubicación del enemigo objetivo. Durante 5 segundos, todos los enemigos cercanos reciben 5...20 de daño de fuego cada segundo que el conjuro esté activo.','Conjuro de élite. Causa 5...20 de daño de fuego por segundo desde el momento en que se lanza el conjuro (5 segundos). Alcanza a los enemigos cercanos a la ubicación inicial del objetivo.'],
1381=>['Prisa del Djinn de fuego','Conjuro con encantamiento. Los enemigos adyacentes reciben 15...120 de daño de fuego. Te mueves un 25% más rápido durante 8...14 segundos. Prisa del Djinn de fuego se recarga un 50% más rápido si el conjuro ha alcanzado a un enemigo.','Conjuro con encantamiento. (8...14 segundos). Te mueves un 25% más rápido. Efecto inicial: hace 15...120 de daño de fuego a los enemigos adyacentes a ti. Si haces daño a un enemigo con este conjuro, se recarga un 50% más rápido.'],
1382=>['Bocanada helada','Conjuro con maleficio. Si el enemigo objetivo está bajo los efectos de un maleficio de agua, recibe 20...80 de daño frío. De lo contrario, se mueve un 66% más despacio durante 1...5 segundos.','Conjuro con maleficio. Hace 20...80 de daño frío si el enemigo objetivo está bajo los efectos de un maleficio de agua. De lo contrario, el enemigo se mueve un 66% más despacio (1...5 segundos).'],
1390=>['Intervención del juez','Conjuro con encantamiento. Durante 10 segundos, la próxima vez que el objetivo (un aliado o tú mismo) reciba daño que podría ser letal, el daño se bloquea y haces 30...180 de daño sagrado a un enemigo cercano.','Conjuro con encantamiento. (10 segundos.) Impide el siguiente ataque crítico. Efecto: hace 30...180 de daño sagrado a un enemigo cercano al objetivo (un aliado o tú mismo).'],
1391=>['Espíritu de apoyo','Conjuro con encantamiento. Durante 5...23 segundos, cada vez que el objetivo (un aliado o tú mismo) reciba daño mientras esté derribado, se curará 5...50 de salud.','Conjuro con encantamiento. (5...23 segundos). Cura 5...50 de salud cada vez que el objetivo (un aliado o tú mismo) reciba daño mientras esté derribado.'],
1392=>['Curación atenta','Conjuro con encantamiento. Durante 10 segundos, el objetivo (un aliado o tú mismo) gana una regeneración de salud de +1...4. Si esta habilidad acaba antes de tiempo, ganará además 30...120 de salud.','Conjuro con encantamiento. (10 segundos). El objetivo (un aliado o tú mismo) tiene +1...4 de regeneración de salud y gana 30...120 de salud si este encantamiento acaba antes de tiempo.'],
1393=>['Bendición del sanador','Conjuro con encantamiento de élite. Durante 10...55 segundos, los conjuros de plegarias curativas se lanzarán un 50% más deprisa y curarán un 50% más.','Conjuro con encantamiento de élite. (10...55 segundos). Los conjuros de plegarias curativas se lanzan un 50% más deprisa y curan un 50% más.'],
1394=>['Pacto del sanador','Conjuro con encantamiento de élite. Mientras mantengas este encantamiento, tus conjuros de plegarias curativas curan un 20% menos pero costarán 1...4 menos de energía.','Conjuro con encantamiento de élite. Tus conjuros de plegarias curativas cuestan 1...4 menos de energía. Estos conjuros curan un 20% menos.'],
1395=>['Péndulo de Balthazar','Conjuro con encantamiento de élite. Durante 5...25 segundos, la próxima vez que un enemigo intente derribar al objetivo (un aliado o tú mismo), será el enemigo quien caiga.','Conjuro con encantamiento de élite. (5...25 segundos). Causa derribo al siguiente enemigo que intente derribar al objetivo (un aliado o tú mismo).'],
1396=>['Palabras confortantes','Conjuro. Curas al objetivo (un aliado o tú mismo) 20...65 de salud y 20...50 extra si está sufriendo alguna condición.','Conjuro. Cura 20...65 de salud. Cura 20...50 de salud extra si el objetivo (un aliado o tú mismo) tiene una condición.'],
1397=>['Luz de liberación','Conjuro de élite. Curas 5...70 de salud a todos los miembros del grupo.','Conjuro de élite. Cura 5...70 de salud a todo el grupo.'],
1398=>['Castigar encantamiento','Conjuro con maleficio. Durante 30 segundos, cada vez que echen un encantamiento sobre el enemigo objetivo, quien lo lance recibirá 15...75 de daño.','Conjuro con maleficio. (30 segundos). Hace 15...75 de daño a cualquiera que eche un encantamiento al enemigo objetivo.'],
1399=>['Escudo de absorción','Conjuro con encantamiento. Durante 3...7 segundos, el daño que reciba el objetivo (un aliado o tú mismo) se reduce en 5 cada vez que éste sea golpeado estando bajo los efectos de este encantamiento.','Conjuro con encantamiento. (3...7 segundos). Reduce 5 del daño que el objetivo (un aliado o tú mismo) reciba.'],
1400=>['Inversión del daño','Conjuro con encantamiento. Durante 8 segundos, la próxima vez que el objetivo (un aliado o tú mismo) sea atacado, en vez de recibir él el daño lo recibirá el enemigo (máximo 5...75).','Conjuro con encantamiento. (8 segundos). Impide el siguiente daño y le devuelve al atacante esa cantidad (máximo 5...75).'],
1401=>['Toque sanador','Conjuro. Quitas dos condiciones al aliado que toques y le curas 15...60 de salud por cada una que le quites.','Conjuro de toque. Elimina dos condiciones. Cura 15...60 de salud por condición.'],
1402=>['Hachazo crítico','Ataque con hacha. Si consigues dar este golpe, harás +5...20 de daño y si consigues un ataque crítico interrumpirás además al enemigo.','Ataque con hacha. Hace +5...20 de daño. Interrumpe una acción si consigues un golpe crítico.'],
1403=>['Hachazo agonizante','Ataque con hacha. Si este ataque impacta, harás +5...20 de daño. Si el enemigo objetivo tenía una herida grave, le interrumpirás.','Ataque con hacha. Hace +5...20 de daño. Interrumpe una acción si el enemigo objetivo tiene una herida grave.'],
1404=>['Flagelo','Actitud. Durante 1...15 segundos, atacas un 33% más rápido pero te mueves un 33% más despacio.','Actitud. (1...15 segundos). Atacas un 33% más deprisa. Te mueves un 33% más lento.'],
1405=>['Ataque en embestida','Actitud de élite. Durante 1...10 segundos, corres un 33% más deprisa. Tu siguiente ataque cuerpo a cuerpo hará +10...90 de daño y esta actitud terminará. También acabará si usas alguna habilidad.','Actitud de élite. (1...10 segundos). Te mueves un 33% más deprisa y haces +10...90 de daño con tu próximo golpe cuerpo a cuerpo. Acaba si golpeas o usas una habilidad.'],
1406=>['Cabezazo','Habilidad de élite. Haces 40...100 de daño al enemigo al que toques. Quedas aturdido durante 10 segundos.','Habilidad de élite de toque. Hace 40...100 de daño. Quedas aturdido (10 segundos).'],
1407=>['Comodidad del león','Habilidad. Todos tus sellos quedan desactivados durante 12 segundos. Te curas 50...110 de salud y ganas 0...3 de adrenalina.','Habilidad. Te curas 50...110 de salud y ganas 0...3 de adrenalina. Desactiva tus sellos (12 segundos).'],
1408=>['Furia del Ntouka','Habilidad de élite. Ganas 1...7 golpes de adrenalina. Durante 8 segundos, cada vez que uses una habilidad de adrenalina, se recargará durante 3 segundos.','Habilidad de élite. Ganas 1...7 de adrenalina. Durante 8 segundos, las habilidades de adrenalina tardan 3 segundos en recargarse cuando las uses.'],
1409=>['Golpe de mokele','Ataque con martillo. Si este ataque impacta, harás +5...20 de daño y ganarás 2 golpes de adrenalina.','Ataque con martillo. Hace +5...20 de daño y ganas 2 de adrenalina.'],
1410=>['Golpe autoritario','Ataque con martillo. Este ataque hace +1...20 de daño si impacta. Si se derriba al enemigo objetivo, queda aturdido durante 1...8 segundos.','Ataque con martillo. Hace +1...20 de daño. Si se derriban los enemigos objetivo, quedan aturdidos durante (1...8 segundos).'],
1411=>['Sello de vitalidad','Sello. Tienes +50...300 de salud máxima. Este sello se acaba si consigues dar un ataque.','Sello. Tienes +50...300 de salud máxima. Acaba si atacas con éxito.'],
1412=>['"¡Te han abandonado!"','Grito de élite. Si el enemigo objetivo no se encuentra cerca de un aliado, quedará lisiado y debilitado durante 8 segundos.','Grito de élite. Causa lisiadura y debilitamiento (8 segundos). No funciona si el enemigo objetivo está cercano a alguno de sus aliados.'],
1413=>['Explosión agresiva','Actitud. Durante 2...10 segundos, atacas un 33% más rápido. Cuando esta actitud termine, perderás toda la adrenalina.','Actitud. (2...10 segundos). Atacas un 33% más deprisa. Efecto final: pierdes toda la adrenalina.'],
1414=>['Carga enrabietada','Actitud. Corres un 25% más rápido durante 5...15 segundos. La Carga enrabietada termina cuando consigues dar a un enemigo, y ganas 0...3 golpes de adrenalina si golpeas con un ataque cuerpo a cuerpo.','Actitud. (5...15 segundos.) Te mueves un 25% más rápido. Ganas +0...3 de adrenalina en el próximo ataque cuerpo a cuerpo. <c x="SkillDull">Termina cuando vuelves a golpear.'],
1415=>['Tajo lisiador','Ataque con espada de élite. Si este ataque impacta, el enemigo objetivo quedará lisiado durante 5...15 segundos y sufrirá una hemorragia durante 10...25 segundos.','Ataque con espada de élite. Causa lisiadura (5...15 segundos) y hemorragia (10...25 segundos).'],
1416=>['Corte bárbaro','Ataque con espada. Si este ataque impacta, harás +5...30 de daño. Si no estás manteniendo ninguna actitud, también harás una hemorragia durante 5...15 segundos.','Ataque con espada. Hace +5...30 de daño. Causa hemorragia (5...15 segundos) si no mantienes ninguna actitud.'],
1465=>['Disparo preparado','Ataque con arco de élite. Si impacta el ataque, harás +10...25 daño. Si estás bajo los efectos de una preparación, ganarás 1...9 de energía.','Ataque con arco de élite. Hace +10...25 de daño. Ganas 1...9 de energía si tienes una preparación activa.'],
1466=>['Flecha ardiente','Ataque con arco de élite. Si este ataque impacta, hace +10...30 de daño y causa una quemadura durante 2...8 segundos.','Ataque con arco de élite. Hace +10...30 de daño. Causa quemadura (2...8 segundos).'],
1467=>['Disparo parabólico','Ataque con arco. Si esta flecha impacta, hará +10...35 de daño. No se podrá bloquear, pero va un 50% más despacio que las normales.','Ataque con arco. Hace +10...35 de daño. No se puede bloquear. Esta flecha se mueve un 50% más despacio.'],
1468=>['Golpe al unísono','Grito de élite. Tu mascota se mueve instantáneamente a tu objetivo y causa hemorragia durante 5...15 segundos con el siguiente ataque. La próxima vez que consigas hacer un ataque, el enemigo objetivo queda lisiado durante 5...15 segundos.','Grito de élite. Tu mascota se mueve instantáneamente al objetivo y causa hemorragia (5...15 segundos) con el siguiente ataque. La próxima vez que consigas hacer un ataque, causas lisiadura (5...15 segundos).'],
1469=>['Fuego cruzado','Ataque con arco. Si esta flecha alcanza al objetivo, le hará +5...20 de daño. Si está cerca de algún aliado tuyo, no la podrá bloquear.','Ataque con arco. Hace +5...20 de daño. No se puede bloquear si el enemigo objetivo está cerca de alguno de tus aliados.'],
1470=>['Flechas con espinas','Preparación["Preparaciones"]. Durante 24 segundos, tus flechas causan una hemorragia durante 3...15 segundos. Tienes -40 de armadura mientras actives esta habilidad.','Preparación["Preparaciones"]. (24 segundos). Tus flechas causan hemorragia (3...15 segundos). Tienes -40 de armadura mientras actives esta habilidad.'],
1471=>['Foco del carroñero','Habilidad de élite. Durante 10 segundos, si golpeas a un enemigo que esté sufriendo alguna condición, ganas 3...12 de energía.','Habilidad de élite. (10 segundos). Ganas 3...12 de energía si golpeas a un enemigo que tenga alguna condición.'],
1472=>['Toxicidad','Ritual de la naturaleza. Creas un espíritu de nivel 1...10. Las criaturas enfermas o envenenadas dentro de la zona sufren -2 de degeneración de salud. Morirá a los 30...180 segundos.','Ritual de la naturaleza. Crea un espíritu de nivel 1...10 (30...180 segundos de vida). Las criaturas envenenadas o enfermas dentro de la zona tienen -2 de degeneración de salud.'],
1473=>['Arenas movedizas','Ritual de la naturaleza de élite. Creas un espíritu de nivel 1...10. Todas las criaturas no espíritus de la zona perderán 1 de energía cuando ataquen o usen una habilidad. Morirá a los 30...180 segundos.','Ritual de la naturaleza de élite. Crea un espíritu de nivel 1...10 (30...180 segundos de vida). Las criaturas pierden 1 de energía cada vez que ataquen o usen una habilidad. No afecta a los espíritus.'],
1474=>['Abrazo de la tormenta','Actitud. Durante 10 segundos te mueves un 25% más deprisa. Esta actitud se renovará cada vez que recibas daños elementales.','Actitud. (10 segundos). Te mueves un 25% más deprisa. Renovación: cada vez que recibas daños de los elementos.'],
1475=>['Velocidad del trampero','Actitud. Durante 5...30 segundos, tus trampas se recargan un 25% más deprisa y se activan un 25% antes. Esta actitud acaba si haces un ataque.','Actitud. (5...30 segundos). Tus trampas se recargan un 25% más deprisa y se activan un 25% antes. Acaba si atacas con éxito.'],
1476=>['Suelo alambrado','Trampa. Cuando se active esta trampa, todos los enemigos cercanos reciben 5...20 de daño perforante y los que estén lisiados caerán al suelo. Esta trampa dura 90 segundos y se te podrá interrumpir con facilidad mientras la estés colocando.','Trampa. (90 segundos). Hace 5...20 de daño perforante a los enemigos cercanos. Causa derribo a los enemigos lisiados. Se puede interrumpir con facilidad.'],
1478=>['Oleada renovadora','Conjuro con maleficio. Durante 8 segundos, el enemigo objetivo recibe 2...12 de daño por segundo. Cuando este maleficio acabe, ganas 1...8 de energía.','Conjuro con maleficio. (8 segundos). Hace 2...12 de daño por segundo. Efecto final: Ganas 1...8 de energía.'],
1479=>['Ofrenda de espíritu','Conjuro de élite. Ganas 8...17 de energía. Si hay espíritus al alcance del oído, no sacrificas salud','Conjuro de élite. Ganas 8...17 de energía. No sacrificas salud si hay espíritus al alcance del oído.'],
1480=>['Don espiritual','Conjuro con encantamiento. Durante 60 segundos, cuando crees una criatura, todos los aliados cercanos ganarán 5...50 de salud y perderán 1 condición.','Conjuro con encantamiento. (60 segundos). Cuando crees una criatura, todos los aliados cercanos ganan 5...50 de salud y pierden una condición.'],
1481=>['Sello del pacto de muerte','Sello. Resucitas al miembro del grupo objetivo con tu salud actual y el 15...100% de energía máxima. La próxima vez que ese aliado muera en menos de 120 segundos, tú también morirás.','Sello. Resucita al miembro del grupo objetivo con tu salud actual y el 15...100% de energía máxima. Durante 120 segundos, si el aliado objetivo muere, tú también lo harás.'],
1482=>['Reclamo de esencia','Conjuro de élite. Todos tus espíritus mueren. Ganas 5...20 de energía y todos tus rituales de encadenamiento se recargan si algún espíritu muere de esta forma.','Conjuro de élite. Todos tus espíritus mueren. Si alguno muere de esta forma, ganas 5...20 de energía y todos tus rituales de encadenamiento se recargan.'],
1483=>['Golpe del destierro','Ataque cuerpo a cuerpo. Si impacta, este ataque hace 10...60 de daño sagrado. Causa el doble de daño a las criaturas invocadas.','Ataque cuerpo a cuerpo. Hace 10...60 de daño sagrado. Causa el doble de daño a las criaturas invocadas.'],
1484=>['Barrido místico','Ataque cuerpo a cuerpo. Si impacta, este ataque hace +3...12 de daño. Si estás encantado, este ataque hace +3...12 de daño adicional.','Ataque cuerpo a cuerpo. Hace +3...12 de daño. Hace +3...12 de daño adicional si estás encantado.'],
1485=>['Ataque del ermitaño','Ataque con guadaña. Si impacta, este ataque hace +1...10 de daño y quita un encantamiento de Derviche. Si se quita un encantamiento, haces +1...10 de daño adicional y golpeas a todos los enemigos adyacentes.','Ataque con guadaña. Hace +1...10 de daño y elimina un encantamiento de Derviche. Efecto de eliminación: hace +1...10 de daño adicional y golpea a todos los enemigos adyacentes.'],
1486=>['Segar impurezas','Ataque cuerpo a cuerpo. Este ataque hace +3...15 de daño si impacta. Cada enemigo que alcances pierde una condición. Para cada enemigo que pierde una condición, todos los enemigos adyacentes a él reciben 10...40 de daño.','Ataque cuerpo a cuerpo. Hace +3...15 de daño. Los enemigos que golpeas pierden una condición. Efecto de eliminación: todos los enemigos adyacentes a los que alcances reciben 10...40 de daño sagrado.'],
1487=>['Barrido de la doble luna','Ataque cuerpo a cuerpo. Pierdes un encantamiento de Derviche y ganas 10...50 de salud. Si se pierde un encantamiento de esta manera, tus ataques no se pueden bloquear, golpeas dos veces y ganas 10...70 de salud adicional.','Ataque cuerpo a cuerpo. Elimina uno de tus encantamientos de Derviche. Ganas 10...50 de salud. Efecto de eliminación: no te pueden bloquear, atacas dos veces y ganas 10...70 de salud adicional.'],
1488=>['Barrido victorioso','Ataque cuerpo a cuerpo. Este ataque hace +5...25 de daño si impacta. Si el enemigo objetivo está por debajo del 50% de salud, ganas 30...80 de salud.','Ataque cuerpo a cuerpo. Hace +5...25 de daño. Ganas 30...80 de salud por cada enemigo alcanzado que tenga menos salud que tú.'],
1489=>['Barrido irresistible','Ataque con guadaña. Haces +3...15 de daño y pierdes un encantamiento de Derviche. Si pierdes un encantamiento de esta manera, Barrido irresistible no se puede bloquear, elimina una actitud y hace +3...15 de daño adicional.','Ataque con guadaña. Hace +3...15 de daño. Elimina uno de tus encantamientos de Derviche. Efecto de eliminación: no te pueden bloquear, quita una actitud, hace +3...15 de daño adicional.'],
1490=>['Asalto piadoso','Ataque cuerpo a cuerpo. Si impacta, este ataque hace +10...20 de daño y quita un encantamiento de Derviche. Si se quitó un encantamiento de Derviche, esta habilidad se recarga un 75% más rápido y los enemigos adyacentes reciben 15...40 de daño.','Ataque cuerpo a cuerpo. Hace +10...20 de daño. Quita uno de tus encantamientos de Derviche. Efecto de eliminación: esta habilidad se recarga un 75% más rápido y los enemigos adyacentes reciben 15...40 de daño.'],
1491=>['Tornado místico','Conjuro. Hace 10...60 de daño de frío a todos los enemigos cercanos. Si estás encantado, este conjuro hace 10...60 de daño de frío adicional.','Conjuro. Hace 10...60 de daño de frío a todos los enemigos cercanos. Hace 10...60 de daño de frío adicional si estás encantado.'],
1493=>['Dedos de Grenth','Conjuro con encantamiento de destello. Todos los enemigos cercanos reciben 10...40 de daño de frío. Durante 30 segundos, tus ataques hacen daño de frío. Cuando termina este encantamiento, transfieres 1...2 condiciones a todos los enemigos cercanos.','Conjuro con encantamiento de destello. (30 segundos). Tus ataques hacen daño de frío. Efecto inicial: los enemigos cercanos reciben 10...40 de daño de frío. Efecto final: transfiere 1...2 condiciones a todos los enemigos cercanos.'],
1495=>['Aura de espinas','Conjuro con encantamiento de destello. Todos los enemigos cercanos sufren hemorragia durante 5...15 segundos. Durante 30 segundos, este encantamiento no tiene ningún efecto. Cuando termina este encantamiento, todos los enemigos adyacentes quedan lisiados durante 3...8 segundos.','Conjuro con encantamiento de destello. (30 segundos). Efecto inicial: causa hemorragia (5...15 segundos) a los enemigos cercanos. Efecto final: causa lisiadura (3...8 segundos) a los enemigos cercanos.'],
1496=>['Cólera de Balthazar','Conjuro con encantamiento de destello. Todos los enemigos cercanos arden durante 1...3 segundos. Durante los 20 segundos posteriores, este encantamiento no tendrá ningún efecto. Cuando este encantamiento termina, ganas 1...2 golpes de adrenalina si hay algún enemigo al alcance del oído.','Conjuro con encantamiento de destello. (20 segundos). Efecto inicial: causa quemadura (1...3 segundos) a los enemigos cercanos. Efecto final: ganas 1...2 golpes de adrenalina si hay enemigos al alcance del oído.'],
1497=>['Manto polvoriento','Conjuro con encantamiento de destello. Los enemigos cercanos reciben 10...40 de daño de tierra. Durante 30 segundos, tus ataques hacen daño de tierra. Cuando termina este encantamiento, todos los enemigos adyacentes quedan cegados durante 1...4 segundos.','Conjuro con encantamiento de destello. (30 segundos). Tus ataques hacen daño de tierra. Efecto inicial: hace 10...40 de daño de tierra a los enemigos cercanos. Efecto final: causa ceguera (1...4 segundos) a los enemigos cercanos.'],
1498=>['Fuerza desequilibrante','Conjuro con encantamiento de destello. Los enemigos cercanos reciben 10...40 de daño de tierra. Durante 30 segundos, tus ataques hacen daño de tierra. Cuando termina este encantamiento, todos los enemigos adyacentes tienen la armadura rota durante 1...10 segundos.','Conjuro con encantamiento de destello. (30 segundos). Tus ataques hacen daño de tierra. Efecto inicial: hace 10...40 de daño de tierra a los enemigos cercanos. Efecto final: causa armadura rota (1...10 segundos) a los enemigos cercanos.'],
1499=>['Renovación piadosa','Conjuro con encantamiento de destello de élite. Durante 8 segundos, no ocurre nada. Cuando termina este encantamiento, se recarga Renovación piadosa y ganas 0...5 de energía y 0...30 de salud.','Conjuro con encantamiento de destello de élite. (8 segundos). Efecto final: se recarga a sí mismo y ganas 0...5 de energía y 0...30 de salud.'],
1500=>['Manto milagroso','Conjuro con encantamiento de destello. Durante 20 segundos, tienes un 40 % de probabilidad de bloquear y un 4...10 % extra por cada encantamiento adicional (máximo un 80 %). Todos los enemigos cercanos reciben 10...40 de daño de tierra cada vez que te quitan un encantamiento de Derviche.','Conjuro con encantamiento de destello. (20 segundos). Tienes un 40 % de probabilidad de bloquear y un 4...10 % extra por cada encantamiento adicional. 10...40 de daño de tierra a los enemigos cercanos cada vez que te quitan un encantamiento de Derviche.'],
1502=>['Celo arcano','Conjuro con encantamiento de élite. Durante 10 segundos, cada vez que lances un conjuro, ganas 2 de energía por cada encantamiento que tengas encima (máximo 2...7 de energía).','Conjuro con encantamiento de élite. (10 segundos). Ganas 2 de energía (máximo 2...7) por cada encantamiento que tengas cuando lances un conjuro.'],
1503=>['Vigor místico','Conjuro con encantamiento. Durante 20 segundos, cada vez que ataques con éxito, ganas 3...15 de salud por cada encantamiento que tengas (máximo 25 de salud).','Conjuro con encantamiento. (20 segundos). Ganas 3...15 de salud (máximo 25) por cada encantamiento que tengas cuando ataques con éxito.'],
1504=>['Intervención atenta','Conjuro con encantamiento. Durante 60 segundos, la próxima vez que un ataque haga caer la salud del objetivo (un aliado o tú mismo) por debajo del 25%, se curará 50...200 de salud.','Conjuro con encantamiento. (60 segundos). Cura 50...200 de salud la próxima vez que el daño haga caer la salud del objetivo (un aliado o tú mismo) por debajo del 25%.'],
1505=>['Voto de piedad','Conjuro con encantamiento. Durante 20 segundos tienes +24 de armadura y +1...4 de regeneración de salud. Voto de piedad se renueva cada vez que finaliza un encantamiento sobre tu personaje.','Conjuro con encantamiento. (20 segundos). +24 de armadura y +1...4 de regeneración de salud. Renovación: cada vez que finaliza un encantamiento sobre tu personaje.'],
1506=>['Dádiva vital','Conjuro con encantamiento. Durante 20 segundos, tienes +40...100 de salud máxima. Cuando este encantamiento termine, te curarás 75...200 de salud.','Conjuro con encantamiento. (20 segundos). Tienes +40...100 de salud máxima. Efecto final: te curas 75...200 de salud.'],
1507=>['Corazón de la llama sagrada','Conjuro con encantamiento de destello. Todos los enemigos cercanos reciben 5...30 de daño sagrado. Durante los 30 segundos posteriores, tus ataques hacen daño sagrado. Cuando termina este encantamiento, todos los enemigos cercanos arden durante 2...5 segundos.','Conjuro con encantamiento de destello. (30 segundos). Tus ataques hacen daño sagrado. Efecto inicial: hace 5...30 de daño sagrado a los enemigos cercanos. Efecto final: causa quemadura (2...5 segundos) a los enemigos cercanos.'],
1508=>['Prolongar encantamientos','Habilidad. Durante 10 segundos, tu próximo encantamiento de Derviche durará un 10...150% más.','Habilidad. (10 segundos)Tu próximo encantamiento de Derviche durará un 10...150% más.'],
1509=>['Intervención de fe','Conjuro con encantamiento. Si tu salud cae por debajo del 50%, la Intervención de fe terminará. Al hacerlo, te curarás 30...150 de salud.','Conjuro con encantamiento. Ganas 30...150 de salud la próxima vez que te quedes por debajo del 50% de salud.'],
1510=>['Cristales de arena','Conjuro con encantamiento de destello. Durante 30 segundos, los próximos 1...5 ataques con guadaña hacen 10...60 de daño de tierra a todos los enemigos adyacentes al objetivo.','Conjuro con encantamiento de destello. (30 segundos). Los ataques con guadaña hacen 10...60 de daño de tierra a todos los enemigos adyacentes al objetivo. Termina después de 1...5 golpes.'],
1512=>['Premura de Lyssa','Conjuro con encantamiento de destello. Durante 3...15 segundos, tus encantamientos de Derviche se recargarán un 33% más rápido. Cuando activas este encantamiento, se interrumpe la acción de todos los enemigos adyacentes. Cuando se termina este encantamiento, se interrumpe la acción de todos los enemigos adyacentes. 50% de posibilidades de fallar a menos que tengas plegarias de viento 5 o superior.','Conjuro con encantamiento de destello. (3...15 segundos). Tus encantamientos de Derviche se recargan un 33% más rápido. Efecto inicial: interrumpe la acción de todos los enemigos adyacentes. Efecto final: interrumpe la acción de todos los enemigos adyacentes. (50% de posibilidades de fallar a menos que tengas plegarias de viento 5 o superior).'],
1513=>['Manos guiadoras','Conjuro con encantamiento. Durante 20 segundos, tus próximos 0...3 ataques no se pueden bloquear. Cuando se activa, esta habilidad quita la ceguera.','Conjuro con encantamiento. (20 segundos). Tus próximos 0...3 ataques no se pueden bloquear. Efecto inicial: quita la ceguera.'],
1514=>['Estabilidad pasajera','Conjuro con encantamiento de destello. Durante 4...10 segundos, no te pueden derribar y te mueves un 25% más deprisa. Este encantamiento termina prematuramente si evita un derribo.','Conjuro con encantamiento de destello. (4...10 segundos). No te pueden derribar y te mueves un 25% más deprisa. Termina si evita un derribo.'],
1515=>['Armadura de santidad','Conjuro con encantamiento. Todos los enemigos cercanos quedan debilitados durante 5...15 segundos. Durante 15 segundos, los enemigos que tengan una condición te harán 5...20 menos de daño.','Conjuro con encantamiento. Causa debilidad a los enemigos cercanos (5...15 segundos). Recibes 5...20 menos de daño de los enemigos que tengan una condición (15 segundos).'],
1516=>['Regeneración mística','Conjuro con encantamiento. Durante 5...20 segundos, ganas +1...4 de regeneración de salud por cada encantamiento que posea tu personaje (máximo 8).','Conjuro con encantamiento. (5...20 segundos). Ganas +1...4 de regeneración de salud por cada encantamiento que posea tu personaje (máximo 8).'],
1517=>['Voto de silencio','Conjuro con encantamiento de élite. Durante 5...10 segundos, no te podrán echar conjuros, pero tú tampoco podrás lanzarlos.','Conjuro con encantamiento de élite. (5...10 segundos). No puedes ser objetivo de conjuros. No puedes lanzar conjuros.'],
1518=>['Avatar de Balthazar','Transformación["Transformaciones"] de élite. Durante 10...90 segundos, ganas +20 de armadura contra daño físico, ganas adrenalina un 25% más rápido, tus ataques hacen daño sagrado y cada vez que pierdes un encantamiento de Derviche, los enemigos cercanos arden durante 1...3 segundos. La habilidad queda desactivada durante 45 segundos.','Transformación["Transformaciones"] de élite. (10...90 segundos). Ganas +20 de armadura contra daño físico, ganas adrenalina un 25% más rápido, tus ataques hacen daño sagrado, causas quemadura (1...3 segundos) a los enemigos cercanos cuando pierdes un encantamiento de Derviche. La habilidad queda desactivada durante 45 segundos.'],
1519=>['Avatar de Dwayna','Transformación["Transformaciones"] de élite. Durante 10...90 segundos, tus ataques hacen daño sagrado. Cada vez que utilizas una habilidad de ataque de Derviche, pierdes un maleficio. Cada vez que pierdes un encantamiento de Derviche, todos los aliados al alcance del oído se curan 5...50 de salud. La habilidad queda desactivada durante 45 segundos.','Transformación["Transformaciones"] de élite. (10...90 segundos.) Hace daño sagrado. Pierdes un maleficio cada vez que utilizas una habilidad de ataque de Derviche. Todos los aliados al alcance del oído se curan 5...50 de salud cada vez que pierdes un encantamiento de Derviche. La habilidad queda desactivada durante 45 segundos.'],
1520=>['Avatar de Grenth','Transformación["Transformaciones"] de élite. Durante 10...90 segundos, tus ataques con guadaña hacen daño oscuro y roban 0...12 de salud. Eres inmune a la enfermedad y causas enfermedad en todos los enemigos adyacentes durante 3 segundos cada vez que pierdes un encantamiento de Derviche. Esta habilidad está desactivada durante 45 segundos.','Transformación["Transformaciones"] de élite. (10...90 segundos). Tus ataques con guadaña hacen daño oscuro y roban 0...12 de salud. Eres inmune a la enfermedad. Causa enfermedad a todos los enemigos adyacentes (3 segundos) cuando pierdes un encantamiento de Derviche. Esta habilidad está desactivada durante 45 segundos.'],
1521=>['Avatar de Lyssa','Transformación["Transformaciones"] de élite. Durante 10...90 segundos, tus encantamientos de Derviche se recargan un 50% más rápido e infliges daño de caos con tus ataques. Cada vez que pierdes un encantamiento de Derviche, robas 1 de energía de todos los enemigos cercanos. Esta habilidad está desactivada durante 45 segundos.','Transformación["Transformaciones"] de élite. (10...90 segundos). Tus encantamientos de Derviche se recargan un 50% más deprisa e infliges daño de caos con tus ataques. Robas 1 de energía de los enemigos cercanos cuando pierdes un encantamiento de Derviche. Esta habilidad está desactivada durante 45 segundos.'],
1522=>['Avatar de Melandru','Transformación["Transformaciones"] de élite. Durante 10...90 segundos, tienes +150 de salud, +30 de armadura contra daño de los elementos y tus ataques infligen daño de tierra. Cada vez que pierdes un encantamiento de Derviche, todos los compañeros al alcance del oído pierden una condición. Esta habilidad está desactivada durante 45 segundos.','Transformación["Transformaciones"] de élite. (10...90 segundos). Tienes +150 de salud máxima, +30 de armadura contra daño de los elementos y tus ataques infligen daño de tierra. Curas una condición de todos tus compañeros al alcance del oído cada vez que pierdes un encantamiento de Derviche. Esta habilidad está desactivada durante 45 segundos.'],
1523=>['Meditación','Conjuro con encantamiento. Pierdes toda la adrenalina. Durante 20 segundos, ganas 1...4 de energía cada vez que termina uno de tus encantamientos.','Conjuro con encantamiento. (20 segundos). Pierdes toda la adrenalina. Ganas 1...4 de energía cada vez que termina uno de tus encantamientos.'],
1524=>['Celo del ermitaño','Conjuro con encantamiento. Ganas 1...3 de energía (máximo 8) por cada enemigo al alcance del oído. Durante los 10 segundos posteriores, este encantamiento no tendrá ningún efecto. Cuando este encantamiento termina, ganas 1...3 de energía (máximo 8) por cada enemigo al alcance del oído.','Conjuro con encantamiento. (10 segundos). Efecto inicial: ganas 1...3 de energía (máximo 8) por cada enemigo al alcance del oído. Efecto final: ganas 1...3 de energía (máximo 8) por cada enemigo al alcance del oído.'],
1525=>['Curación innata','Conjuro. Cura 50...170 de salud. Si no estás encantado, este conjuro se activa un 50% más rápido.','Conjuro. Cura 50...170 de salud. Esta habilidad se activa un 50% más rápido si no estás encantado.'],
1526=>['Imbuir salud','Conjuro. Curas al aliado objetivo un 5...50% de tu salud actual (300 de salud como máximo).','Conjuro. Cura el 5...50% de tu salud actual (máximo 300). No te puedes apuntar a ti mismo.'],
1527=>['Curación mística','Conjuro. Cura 5...65 de salud. También cura 5...65 de salud a todos tus compañeros encantados.','Conjuro. Te curas 5...65 de salud. Cura 5...65 de salud a todos tus compañeros encantados.'],
1528=>['Toque de Dwayna','Conjuro. Curas al aliado que toques 60 de salud por cada encantamiento que tengas encima (máximo 60...240).','Conjuro de toque. Cura 60 de salud (máximo 60...240) por cada encantamiento que tengas.'],
1529=>['Restauración piadosa','Conjuro. Ganas 80...150 de salud y pierdes 1 encantamiento de Derviche. Si se elimina un encantamiento de este modo, también pierdes 1...3 maleficios.','Conjuro. Ganas 80...150 de salud y pierdes 1 encantamiento de Derviche. Efecto de eliminación: pierdes 1...3 maleficios.'],
1530=>['Sello de luz piadosa','Sello. Quita un encantamiento de Derviche. Curas 30...150 de salud al aliado objetivo. Si se quitó un encantamiento de esta manera, este sello se recarga un 75% más rápido.','Sello. Cura 30...150 de salud. Quita uno de tus encantamientos de Derviche. Efecto de eliminación: se recarga un 75% más rápido.'],
1531=>['Aura intimidante','Conjuro con encantamiento. Durante 60 segundos, tienes +40...100 de salud máxima y recibes 1...10 menos de daño de los enemigos que tienen menos salud que tú.','Conjuro con encantamiento. (60 segundos). Tienes +40...100 de salud máxima y recibes -1...10 de daño de los enemigos que tienen menos salud que tú.'],
1532=>['Tormenta de arena mística','Conjuro. Creas una Tormenta de arena en tu ubicación, que dura 3 segundos. Cada segundo, los enemigos cercanos a esta ubicación reciben 10...40 de daño de tierra. Los enemigos que atacan reciben 10...20 de daño adicional. Si estás encantado cuando lanzas este conjuro, dura el doble de tiempo.','Conjuro. (3 segundos). Hace 10...40 de daño de tierra por segundo. Hace 10...20 de daño adicional a los enemigos que atacan. Alcanza a los enemigos cercanos a tu ubicación inicial. Dura el doble de tiempo si estás encantado.'],
1533=>['Vientos del desencantamiento','Conjuro. Elimina uno de tus encantamientos de Derviche. Si se quitó un encantamiento, todos los enemigos cercanos pierden un encantamiento y reciben 20...80 de daño de frío.','Conjuro. Elimina uno de tus encantamientos de Derviche. Efecto de eliminación: todos los enemigos cercanos pierden un encantamiento y sufren 20...80 de daño de frío.'],
1534=>['Toque desgarrador','Conjuro. Hace 15...65 de daño de frío al enemigo objetivo. Pierdes un encantamiento de Derviche. Si se quitó un encantamiento, el enemigo pierde un encantamiento y ganas 2 golpes de adrenalina.','Conjuro de toque. Hace 15...65 de daño de frío. Pierdes un encantamiento de Derviche. Efecto de eliminación: el enemigo objetivo pierde un encantamiento y tú ganas 2 golpes de adrenalina.'],
1535=>['Barrido lisiador','Ataque con guadaña. Si este ataque impacta en un enemigo, éste quedará lisiado durante 3...12 segundos. Esta habilidad hace +3...15 de daño adicional si el enemigo está en movimiento.','Ataque con guadaña. (3...12 segundos.) Causa lisiadura. Hace +3...15 de daño a los enemigos en movimiento.'],
1536=>['Golpe hiriente','Ataque con guadaña de élite. Si este ataque impacta, haces +5...20 de daño, el enemigo objetivo sufre hemorragia durante 5...20 segundos y pierdes un encantamiento de Derviche. Si se quitó un encantamiento, el enemigo objetivo también padecerá herida grave durante 5...20 segundos.','Ataque con guadaña de élite. Hace +5...20 de daño y causa hemorragia (5...20 segundos). Quita un encantamiento de Derviche. Efecto de eliminación: causa una herida grave (5...20 segundos).'],
1537=>['Golpe cansado','Ataque con guadaña. Quita un encantamiento de Derviche. Si se quitó un encantamiento, causas una herida grave durante 3...10 segundos. Sufres debilitamiento durante 10 segundos si no se quita un encantamiento.','Ataque con guadaña. Quita un encantamiento de Derviche. Efecto de eliminación: causa una herida grave (3...10 segundos). Sufres debilitamiento (10 segundos) si no se pierde un encantamiento.'],
1538=>['Asalto de Lyssa','Ataque con guadaña. Si impacta, este ataque interrumpe la acción. Si estás encantado, todas las habilidades que interrumpas se desactivarán durante 1...10 segundos más. Este ataque hace 50% de daño normal.','Ataque con guadaña. Interrumpe una acción. Si estás encantado, las habilidades que interrumpas se desactivarán durante 1...10 segundos más. Este ataque hace 50% de daño normal.'],
1539=>['Victoria espeluznante','Ataque con guadaña. Si alcanza al enemigo, este ataque hace +3...15 de daño. Para cada enemigo alcanzado que tenga menos salud que tu personaje, dicho enemigo y todos los adyacentes reciben 10...30 de daño de frío.','Ataque con guadaña. Hace +3...15 de daño. Hace 10...30 de daño de frío a cada enemigo alcanzado cuya salud sea menor que la de tu personaje y a los enemigos adyacentes a ellos.'],
1540=>['Convicción','Conjuro con encantamiento de destello. Durante 10 segundos, ganas +10 de armadura si tienes una condición y ganas 1...3 de regeneración de salud por cada condición que estés padeciendo. Cuando termina este encantamiento, te curas de 1...2 condiciones','Conjuro con encantamiento de destello. (10 segundos). Ganas +10 de armadura mientras sufras una condición. Ganas 1...3 de regeneración de salud por cada condición que tengas. Efecto final: elimina 1...2 condiciones.'],
1541=>['Prisa encantada','Conjuro con encantamiento de destello. Te mueves un 25% más rápido durante 7 segundos. Si este encantamiento termina antes de tiempo, pierdes 1 condiciones.','Conjuro con encantamiento de destello. (7 segundos). Te mueves un 25% más rápido. Pierdes 1 condiciones si el encantamiento termina antes de tiempo.'],
1542=>['Concentración piadosa','Actitud. Durante 5...20 segundos no podrás ser interrumpido, pero cada vez que intenten interrumpirte, perderás 1 encantamiento de Derviche o la Concentración piadosa finalizará.','Actitud. (5...20 segundos). Evita que puedan interrumpirte. Coste por defensa: pierdes un encantamiento de Derviche o la Concentración piadosa finaliza.'],
1543=>['Prisa piadosa','Actitud. Pierdes un encantamiento de Derviche y te mueves un 25% más rápido durante 1...7 segundos. Si se quitó un encantamiento, corres un 50% más rápido.','Actitud. (1...7 segundos). Pierdes un encantamiento de Derviche y te mueves un 25% más rápido. Efecto de eliminación: corres un 50% más rápido.'],
1544=>['Torbellino de asalto','Conjuro con encantamiento de destello. Durante 1...6 segundos, te mueves un 33% más rápido de lo normal. La próxima vez que golpees a un enemigo, todos los demás enemigos cercanos recibirán 10...60 de daño frío y este encantamiento terminará.','Conjuro con encantamiento de destello. (1...6 segundos). Te mueves un 33% más rápido. Harás 10...60 de daño frío al resto de enemigos cercanos la próxima vez que golpees a un enemigo y este encantamiento terminará.'],
1545=>['Prueba de fe','Conjuro. Hace 15...75 de daño frío y recibe un encantamiento por enemigo. Si un enemigo no estaba encantado, queda aturdido durante 2...6 segundos.','Conjuro de toque. Hace 15...75 de daño frío y elimina un encantamiento. El enemigo queda aturdido durante 2...6 segundos si no estaba encantado.'],
1546=>['Lanza resplandeciente','Ataque con lanza. Si este ataque impacta, harás +5...25 de daño al enemigo y arderá durante 1...3 segundos.','Ataque con lanza. Hace 5...25 de daño. Causa quemadura (1...3 segundos).'],
1547=>['Lanzamiento poderoso','Ataque con lanza. Tu lanza vuela tres veces más rápido. Si impacta, hará +10...40 de daño.','Ataque con lanza. Hace +10...40 de daño. Esta lanza vuela tres veces más rápido.'],
1548=>['Lanza cruel','Ataque con lanza de élite. Si este ataque impacta, harás +10...50 de daño. Si impacta a un enemigo parado, le harás una herida grave que durará 5...20 segundos.','Ataque con lanza de élite. Hace +10...50 de daño. Causa herida grave (5...20 segundos) si el enemigo objetivo está parado.'],
1549=>['Lanzamiento del cazador','Ataque con lanza. Si este ataque impacta, harás +5...20 de daño y 5...40 extra si el enemigo estaba en movimiento.','Ataque con lanza. Hace +5...20 de daño. +5...40 de daño extra si el enemigo objetivo se está moviendo.'],
1550=>['Lanzamiento imparable','Ataque con lanza. Si impacta, este ataque hace +10...40 de daño. No puede bloquearse.','Ataque con lanza. Hace +10...40 de daño. No se puede bloquear.'],
1551=>['Lanza de relámpago','Ataque con lanza. Golpea a todos los enemigos que haya entre tu objetivo y tú. Si impacta, inflige +10...20 de daño de relámpago. Este ataque tiene un 25 % de penetración de armadura.','Ataque con lanza. Inflige +10...20 de daño de relámpago. 25 % de penetración de armadura. Golpea a todos los enemigos que haya entre tu objetivo y tú.'],
1552=>['Lanza cansada','Ataque con lanza. Si este ataque impacta, harás +10...40 de daño pero quedarás debilitado durante 5 segundos.','Ataque con lanza. Hace +10...40 de daño. Quedas debilitado (5 segundos).'],
1553=>['Himno de furia','Cántico de élite. Durante 10 segundos, todos los miembros del grupo al alcance del oído ganan 2...5 de adrenalina la próxima vez que usen una habilidad de ataque.','Cántico de élite. (10 segundos). Los miembros del grupo al alcance del oído ganan 2...5 de adrenalina con su siguiente habilidad de ataque.'],
1554=>['Himno lisiador','Cántico de élite. Durante 10 segundos, la siguiente habilidad de ataque que usen los aliados al alcance del oído causará lisiadura durante 5...15 segundos.','Cántico de élite. (10 segundos). Los aliados al alcance del oído causan lisiadura (5...15 segundos) con su siguiente habilidad de ataque.'],
1555=>['Himno defensivo','Cántico de élite. Durante 4...10 segundos, todos los miembros del grupo al alcance del oído tienen un 50% de posibilidades de bloquear ataques. Este cántico acaba si el miembro del grupo consigue golpear con una habilidad de ataque.','Cántico de élite. (4...10 segundos). Los miembros del grupo al alcance del oído tienen un 50% de probabilidades de bloquear. Acaba al usar con éxito una habilidad de ataque.'],
1556=>['Bienandanza','Grito. Durante 5...20 segundos, todos los aliados al alcance del oído se mueven un 25% más deprisa si están bajo los efectos de un encantamiento.','Grito. (5...20 segundos). Los aliados al alcance del oído se mueven un 25% más rápido si tienen un encantamiento.'],
1557=>['Himno de fuego','Cántico. Durante 10 segundos, la siguiente habilidad de ataque que usen los compañeros al alcance del oído causa también una quemadura durante 1...5 segundos.','Cántico. (10 segundos). Los miembros del grupo al alcance del oído causan quemadura (1...5 segundos) con su siguiente habilidad de ataque.'],
1558=>['"¡A la yugular!"','Grito. Durante 10 segundos, la próxima vez que algún aliado al alcance del oído ataque, habrá un 30...100% de posibilidades que sea un golpe crítico.','Grito. (10 segundos). Los aliados al alcance del oído tienen +30...100% de probabilidades de hacer un golpe crítico con su siguiente ataque.'],
1559=>['Himno de envidia','Cántico. Durante 10 segundos, la siguiente habilidad de ataque que usen los aliados al alcance del oído hará +10...25 de daño a los enemigos con más del 50% de salud.','Cántico. (10 segundos). Los aliados al alcance del oído hacen +10...25 de daño con su siguiente habilidad de ataque. El extra de daño sólo afecta a los enemigos con más del 50% de salud.'],
1560=>['Canción de poder','Cántico. Durante 5...20 segundos, todos los aliados al alcance del oído ganan 4 de regeneración de energía hasta que usen alguna habilidad.','Cántico. (5...20 segundos). Los aliados al alcance del oído ganan +4 de regeneración de energía. Acaba al usar una habilidad.'],
1561=>['Himno de celo','Cántico. Durante 10 segundos, la próxima vez que algún aliado al alcance del oído use una habilidad de ataque, recuperará 1...8 de energía.','Cántico. (10 segundos). Los aliados al alcance del oído ganan 1...8 de energía con su siguiente habilidad de ataque.'],
1562=>['Aria de celo','Cántico. Durante 10 segundos, la próxima vez que algún aliado al alcance del oído use un conjuro, recuperará 1...6 de energía.','Cántico. (10 segundos). Los aliados al alcance del oído ganan 1...6 de energía con su siguiente conjuro.'],
1563=>['Lírica de celo','Cántico. Durante 10 segundos, la próxima vez que algún aliado al alcance del oído use un sello, recuperará 1...8 de energía.','Cántico. (10 segundos). Los aliados al alcance del oído ganan 1...8 de energía con su siguiente sello.'],
1564=>['Balada de restauración','Cántico. Durante 10 segundos, la próxima vez que hagan daño a algún compañero al alcance del oído, se curará 15...75 de salud.','Cántico. (10 segundos). Los miembros del grupo al alcance del oído ganan 15...75 de salud la próxima vez que reciban daño.'],
1565=>['Coro de restauración','Cántico. Durante 10 segundos, la próxima vez que algún aliado al alcance del oído use un grito o cántico, se curará 30...90 de salud.','Cántico. (10 segundos). Los aliados al alcance del oído se curan 30...90 de salud con su siguiente grito o cántico.'],
1566=>['Aria de restauración','Cántico. Durante 10 segundos, la próxima vez que algún compañero al alcance del oído use un conjuro, se curará 30...90 de salud.','Cántico. (10 segundos). Los miembros del grupo al alcance del oído ganan 30...90 de salud con su siguiente conjuro.'],
1567=>['Canción de concentración','Cántico. Durante 10 segundos, la siguiente habilidad que use cada aliado al alcance del oído no se podrá interrumpir.','Cántico. (10 segundos). A los aliados al alcance del oído no se les puede interrumpir su próxima habilidad.'],
1568=>['Himno de guía','Cántico de élite. Durante 10 segundos, la siguiente habilidad de ataque que use cada miembro del grupo al alcance del oído no se podrá bloquear.','Cántico de élite. (10 segundos). A los miembros del grupo al alcance del oído no se les puede interrumpir su próxima habilidad de ataque.'],
1569=>['Coro vitalizante','Cántico. Durante 10 segundos, el siguiente cántico o grito que use cada aliado al alcance del oído consume 3...7 menos de energía.','Cántico. (10 segundos). A los aliados al alcance del oído les cuesta 3...7 menos de energía su siguiente grito o cántico.'],
1570=>['Canción de purificación','Cántico de élite. Durante 20 segundos, los aliados al alcance del oído se curarán 1 condición al usar sus siguientes habilidades (1...6).','Cántico de élite. (20 segundos). Los aliados al alcance del oído pierden una condición con sus siguientes habilidades (1...6).'],
1571=>['Aria rompemaleficios','Cántico. Durante 10 segundos, la próxima vez que algún aliado al alcance del oído lance un conjuro, perderá 1 maleficio.','Cántico. (10 segundos). Los aliados al alcance del oído pierden un maleficio con su siguiente conjuro.'],
1572=>['"¡Firme!"','Grito. Durante 5...15 segundos, la siguiente vez que se intente derribar al aliado objetivo no surtirá efecto y, en lugar de ello, todos los enemigos cercanos recibirán 15...75 de daño.','Grito. (5...15 segundos.) Evita el siguiente derribo y causa 15...75 de daño a todos los enemigos cercanos al aliado objetivo. No te puedes apuntar a ti mismo como objetivo.'],
1573=>['Pavor','Habilidad. Si esta habilidad alcanza a un enemigo derribado, este quedará aturdido durante 5...15 segundos.','Habilidad. Causa aturdimiento. (5...15 segundos). No tiene efecto si el objetivo no está derribado.'],
1574=>['Armonía duradera','Eco. Durante 10...35 segundos, el efecto de los cánticos y gritos durarán un 50% más en el aliado objetivo no espíritu.','Eco. (10...35 segundos). Los cánticos y gritos duran un 50% más en el aliado objetivo. No se puede apuntar a un espíritu.'],
1575=>['Cierre llameante','Eco. Durante 10...35 segundos, cada vez que un grito o cántico termine en el aliado objetivo no espíritu, todos los enemigos adyacentes a él arderán durante 1...7 segundos.','Eco. (10...35 segundos). Causa quemadura (1...7 segundos) a los enemigos adyacentes cada vez que los efectos de un cántico o grito acaban en el objetivo (un aliado o tú mismo). No se puede apuntar a un espíritu.'],
1576=>['Estribillo quemador','Eco. Durante 20 segundos, si el aliado objetivo no espíritu golpea a un enemigo con más salud que él, éste arderá durante 1...3 segundos. Este eco se reactivará cada vez que los efectos de un grito o cántico terminen en el aliado.','Eco. (20 segundos). Causa quemadura (1...3 segundos) si el objetivo (un aliado o tú mismo) alcanza a un enemigo con más salud. Renovación: cada que vez que los efectos de un cántico o grito acaben en ese aliado. No se puede apuntar a un espíritu.'],
1577=>['Cierre de restauración','Eco. Durante 10...35 segundos, cada vez que un grito o cántico alcance a un aliado no espíritu objetivo, éste recuperará 15...75 de salud.','Eco. (10...35 segundos.) El aliado objetivo gana 15...75 de salud cada vez que los efectos de un cántico o grito le alcancen. No puedes apuntar a espíritus.'],
1578=>['Estribillo sanador','Eco. Durante 15 segundos, el aliado objetivo no espíritu tiene +2...3 de regeneración de salud. Este eco se reactivará cada vez que los efectos de un grito o cántico terminen en el aliado','Eco. (15 segundos). El objetivo (un aliado o tú mismo) tiene +2...3 de regeneración de salud. Renovación: cada vez que los efectos de un cántico o grito acaben en él.No se puede apuntar a un espíritu.'],
1579=>['Cierre purificador','Eco. Durante 10...35 segundos, el aliado objetivo no espíritu pierde 1 condición siempre que los efectos de un cántico o grito acaben en él.','Eco. (10...35 segundos). El objetivo (un aliado o tú mismo) pierde una condición cada vez que los efectos de un cántico o grito acaben en él.No se puede apuntar a un espíritu.'],
1580=>['Estribillo afilado','Eco. Durante 20 segundos, el aliado objetivo no espíritu tendrá un 5...20% de posibilidades de bloquear los ataques que reciba. Este eco se reactivará cada vez que los efectos de un cántico o grito alcancen al aliado.','Eco. (20 segundos.) El aliado objetivo tiene un 5...20% de posibilidades de bloquear ataques. Renovación: Cada vez que los efectos de un cántico o grito alcancen al aliado. No puedes apuntar a los espíritus.'],
1581=>['Sello brillante','Sello. Si el enemigo objetivo está ardiendo, ganas 5...15 de energía.','Sello. Ganas 5...15 de energía si el enemigo objetivo está ardiendo.'],
1583=>['Celo del líder','Habilidad. Ganas 2...4 de energía por cada aliado cercano (máximo 8...12 de energía).','Habilidad. Ganas 2...4 de energía (máximo 8...12) por cada aliado cercano.'],
1584=>['Comodidad del líder','Habilidad. Ganas 30...75 de salud y además +10...20 extra por cada aliado al alcance del oído (máximo 140 de salud).','Habilidad. Ganas 30...75 de salud y 10...20 extra (máximo 140) por cada aliado al alcance del oído.'],
1585=>['Sello de sinergia','Sello. Curas al aliado objetivo 40...100 de salud. Si no estás bajo los efectos de un encantamiento, tú te curarás también 40...100 de salud.','Sello. Cura al aliado objetivo 40...100 de salud. Tú también te curas 40...100 si no tienes ningún encantamiento. No te puedes apuntar a ti mismo.'],
1586=>['Protección angelical','Habilidad. Durante 10 segundos, siempre que el aliado objetivo reciba más de 250...80 de daño por segundo, se curará en salud el número de puntos de daño que sobrepasen a esta cantidad.','Habilidad. (10 segundos). Cada segundo que el aliado objetivo reciba daño por encima de 250...80, ese aliado se cura esa cantidad. No te puedes apuntar a ti mismo.'],
1587=>['Vínculo angelical','Habilidad de élite. Durante 10 segundos, la próxima vez que un objetivo (un aliado o tú mismo) al alcance del oído reciba daño que podría ser letal, el daño es bloqueado y ese objetivo recupera 20...200 de salud. El Vínculo angelical acaba en los demás aliados.','Habilidad de élite. (10 segundos). La próxima vez que un objetivo (un aliado o tú mismo) al alcance del oído reciba daño que podría ser letal, el daño es bloqueado y ese objetivo recupera 20...200 de salud. Acaba en los demás aliados.'],
1588=>['Sello de cauterio','Sello de élite. Todos los miembros del grupo pierden todas las condiciones. Tú ardes 1 segundo por cada condición que elimines de esta forma.','Sello de élite. Los miembros del grupo pierden todas las condiciones. Empiezas a arder (un segundo por cada condición eliminada).'],
1589=>['"¡Mantente en guardia!"','Grito. Durante 5...20 segundos, todos los miembros del grupo al alcance del oído ganan +24 de armadura si no se están moviendo.','Grito. (5...20 segundos). Los miembros del grupo al alcance del oído ganan +24 de armadura si no se están moviendo.'],
1590=>['"¡Lidera la marcha!"','Grito. El aliado objetivo se mueve un 25% más deprisa durante 1...5 segundos por cada aliado al alcance del oído (máximo 30 segundos).','Grito. El aliado objetivo se mueve un 25% más deprisa durante 1...5 segundos (máximo 30 segundos) por cada aliado al alcance del oído.'],
1591=>['"¡Rápido!"','Grito. Durante 5...20 segundos, el aliado objetivo se mueve un 33% más deprisa. Esta habilidad termina si ataca con éxito.','Grito. (5...20 segundos). El aliado objetivo se mueven un 33% más deprisa. Acaba si el aliado hace un ataque. No te puedes apuntar a ti mismo.'],
1592=>['"¡Volveremos!"','Grito. Todos los miembros del grupo al alcance del oído resucitarán con 25...50% de salud y 5...20% de energía.','Grito. Todos los miembros del grupo al alcance del oído resucitarán (25...50% de salud y 5...20% de energía).'],
1593=>['"¡No te rindas!"','Grito. Todos los aliados de la zona y por debajo del 75% de salud ganan 1...10 de energía.','Grito. Los aliados al alcance del oído ganan 1...10 de energía. Sólo afecta a los aliados por debajo del 75% de salud.'],
1594=>['"¡Ayuda!"','Grito. El aliado no espíritu objetivo gana 15...90 de salud. Durante 1...10 segundos, los conjuros que te lancen los otros aliados se invocarán un 50 % más deprisa.','Grito. (1...10 segundos). El aliado no espíritu objetivo gana 15...90 de salud y los conjuros que te lancen los otros aliados se invocarán un 50 % más deprisa.'],
1595=>['"¡Atrás!"','Grito. Durante 4...10 segundos, los aliados al alcance del oído ganan 5...15 de salud por segundo al moverse y van un 33% más deprisa. Este grito termina en un aliado si éste logra hacer un ataque.','Grito. (4...10 segundos). Los aliados al alcance del oído ganan 5...15 de salud por segundo mientras se muevan y se mueven un 33% más deprisa. Los efectos acaban en un aliado cuando ataque con éxito.'],
1596=>['"¡Que vienen!"','Grito de élite. Durante 4...10 segundos, todos los aliados al alcance del oído se mueven un 33% más rápido y ganan 5...15 de salud mientras se muevan.','Grito de élite. (4...10 segundos.) Los aliados al alcance del oído se mueven un 33% más rápido y ganarán 5...15 de salud al moverse.'],
1597=>['"¡Están ardiendo!"','Grito. Durante 10 segundos, los compañeros de equipo al alcance del oído reciben 5...35% menos de daño de los enemigos ardiendo.','Grito. (10 segundos). Los miembros del grupo al alcance del oído reciben 5...35% menos de daño de los enemigos ardiendo.'],
1598=>['"¡Arriba!"','Grito. Durante 15 segundos, todos los compañeros al alcance del oído y por debajo del 75% de salud ganarán +1...5 de regeneración de salud.','Grito. (15 segundos). Los miembros del grupo al alcance del oído ganan +1...5 de regeneración de salud. Sólo afecta a los miembros del grupo por debajo del 75% de salud.'],
1599=>['¡Es sólo un rasguño!','Grito de élite. El aliado objetivo pierde todas las condiciones. Si pierde alguna de esta forma, se moverá un 25% más deprisa durante 1...10 segundos.','Grito de élite. Elimina todas las condiciones del aliado objetivo. Ese aliado se mueve un 25% más deprisa (1...10 segundos) si se elimina una condición. No te puedes apuntar a ti mismo.'],
1600=>['Lanza espinada','Ataque con lanza. Si este ataque impacta, tu objetivo sufrirá una hemorragia durante 5...20 segundos.','Ataque con lanza. Causa hemorragia (5...20 segundos).'],
1601=>['Ataque malintencionado','Ataque con lanza. Si este ataque impacta, harás +5...20 de daño al enemigo. Si es un golpe crítico, le harás una herida grave que durará 5...15 segundos.','Ataque con lanza. Hace +5...20 de daño. Causa herida grave (5...15 segundos) con un golpe crítico.'],
1602=>['Golpe abrumador','Ataque con lanza de élite. Si alcanzas al enemigo, le harás +10...50 de daño. Si estaba sufriendo una condición, quedará aturdido durante 4...10 segundos.','Ataque con lanza de élite. Hace +10...50 de daño. Causa aturdimiento (4...10 segundos) si el enemigo objetivo tiene alguna condición.'],
1603=>['Lanza despiadada','Ataque con lanza. Si alcanzas a un enemigo con menos del 50% de salud, sufrirá una herida grave durante 5...20 segundos.','Ataque con lanza. Causa herida grave (5...20 segundos). No tiene efecto a menos que el objetivo tenga menos del 50% de salud.'],
1604=>['Lanzamiento desbaratador','Ataque con lanza. Si alcanzas a un enemigo que esté sufriendo una condición, le interrumpirás.','Ataque con lanza. Interrumpe las acciones. No tiene efecto a menos que el enemigo objetivo tenga un condición.'],
1605=>['Lanzamiento salvaje','Ataque con lanza. Si acierta, este ataque hace +5...20 de daño y anula cualquier actitud que esté usando tu objetivo. Este ataque no puede bloquearse. Todas tus habilidades que no sean ataques con lanza se desactivarán durante 3 segundos.','Ataque con lanza. Hace +5...20 de daño. No se puede bloquear. Elimina la actitud del objetivo.Desactiva todas tus habilidades que no sean ataques con lanza durante 3 segundos.'],
1633=>['Golpe malicioso','Ataque cuerpo a cuerpo. Si este ataque alcanza a un enemigo que esté sufriendo alguna condición, le harás +10...30 de daño y será un golpe crítico.','Ataque cuerpo a cuerpo. Si el enemigo objetivo tiene una condición, este ataque hace +10...30 de daño y es golpe crítico.'],
1634=>['Asalto destructivo','Ataque doble de élite. Debe ir precedido de un ataque complementario. Si impacta, harás 5...50 de daño al enemigo objetivo y perderá un encantamiento. No se puede bloquear este ataque.','Ataque doble de élite. Hace 5...50 de daño. Elimina un encantamiento. No se puede bloquear. Debe ir precedido de un ataque complementario.'],
1635=>['Golpe del cráneo dorado','Ataque complementario de élite. Si estás bajo los efectos de un encantamiento y este ataque impacta, el enemigo objetivo quedará aturdido durante 1...12 segundos.','Ataque complementario de élite. Causa aturdimiento. (1...12 segundos). No tiene efecto a menos que tengas algún encantamiento.'],
1636=>['Golpe de la araña negra','Ataque complementario. Debe golpear a un enemigo afectado por un maleficio. Si impacta, hará +5...20 de daño y el enemigo quedará envenenado durante 5...20 segundos.','Ataque complementario. Hace +5...20 de daño. Causa envenenamiento (5...20 segundos). Debe golpear a un enemigo con maleficio.'],
1637=>['Golpe del zorro dorado','Ataque inicial. Si este ataque impacta, harás +10...30 de daño al enemigo objetivo. Si estás bajo los efectos de un encantamiento, no se te podrá bloquear.','Ataque inicial. Hace +10...30 de daño. No se puede bloquear si tienes un encantamiento.'],
1638=>['Prisa mortal','Conjuro con encantamiento. Durante 10...35 segundos, los conjuros de alcance medio se lanzarán y se recargarán un 5...50% y un 5...60% más deprisa respectivamente.','Conjuro con encantamiento. (10...35 segundos). Tus conjuros de alcance medio se lanzan y se recargan un 5...50% y un 5...60% más deprisa respectivamente.'],
1639=>['Remedio del Asesino','Conjuro con encantamiento. Durante 30 segundos, tus siguientes habilidades de ataque (1...10) eliminarán una condición.','Conjuro con encantamiento. (30 segundos). Tus siguientes habilidades de ataque (1...10) eliminan una condición cada una.'],
1640=>['Promesa del zorro','Conjuro con encantamiento de élite. Durante 5...20 segundos, tus ataques con dagas no se pueden bloquear. Este encantamiento terminará si fallas al atacar.','Conjuro con encantamiento de élite. (5...20 segundos). Tus ataques con dagas no se pueden bloquear. Acaba la próxima vez que falles.'],
1641=>['Neutralidad fingida','Conjuro con encantamiento. Durante 4...10 segundos, tienes +7 de regeneración de salud y +80 de armadura. Este encantamiento acaba si atacas con éxito o usas una habilidad.','Conjuro con encantamiento. (4...10 segundos). Tienes +7 de regeneración de salud y +80 de armadura. Acaba si atacas con éxito o usas una habilidad.'],
1642=>['Cebos escondidos','Conjuro con maleficio de élite. Tus habilidades que no sean de asesino se desactivan durante 3 segundos. Durante 1...10 segundos, el enemigo objetivo se moverá un 50 % más lento. Cuando este maleficio acabe, el enemigo quedará lisiado durante 1...15 segundos.','Conjuro con maleficio de élite. (1...10 segundos). Causa una reducción del 50% en el movimiento. Efecto final: causa lisiadura (1...15 segundos). Tus habilidades que no sean de Asesino se desactivan (10 segundos).'],
1643=>['Asaltaencantamientos','Habilidad de élite. Debe ir precedido de un ataque doble. El enemigo objetivo pierde todos los encantamientos.','Habilidad de élite. Elimina todos los encantamientos. Debe ir precedido de un ataque doble.'],
1644=>['Colapso del derrochador','Habilidad de élite. Das un paso sombrío hasta el enemigo objetivo. Si éste no estaba usando ninguna habilidad, le derribas. Todas tus habilidades de ataque que no sean para daga estarán desactivadas durante 10 segundos.','Habilidad de élite. Das un paso sombrío hasta el enemigo objetivo. Causa derribo si éste no estaba usando ninguna habilidad. Desactiva todas tus habilidades de ataque que no sean para daga (10 segundos).'],
1645=>['Saquear encantamiento','Habilidad. Si el enemigo objetivo tocado está derribado, perderá un encantamiento.','Habilidad de toque. Elimina un encantamiento. No tiene efecto si el enemigo objetivo no está derribado.'],
1646=>['Augurio de muerte','Conjuro con maleficio. Durante 5...35 segundos, la próxima vez que un ataque debería dejar al enemigo objetivo con menos del 50% de salud, le harás una herida grave durante 5...20 segundos y darás un paso sombrío hasta él. Este conjuro tiene la mitad de alcance de lo normal.','Conjuro con maleficio con mitad de alcance. (5...35 segundos). Causa herida grave (5...20 segundos) y das un paso sombrío hasta el enemigo objetivo la próxima vez que un ataque le deje con menos del 50% de salud.'],
1647=>['Sello del shock tóxico','Sello. Si el enemigo objetivo está envenenado, le haces 10...100 de daño.','Sello. Hace 10...100 de daño. No tiene efecto si el enemigo objetivo no está envenenado.'],
1648=>['Sello de la penumbra','Sello. El enemigo objetivo pierde un encantamiento por cada maleficio que esté sufriendo.','Sello. Elimina un encantamiento por cada maleficio que tenga el enemigo objetivo.'],
1649=>['Camino del Asesino','Actitud de élite. Durante los próximos 20 segundos mientras lleves dagas, atacas un 5...20% más deprisa y tienes +5...35% de probabilidades de dar un golpe crítico.','Actitud de élite. (20 segundos). Mientras lleves dagas, atacas un 5...20% más deprisa y tienes +5...35% de probabilidades de dar un golpe crítico.'],
1650=>['Paseo sombrío','Actitud. Das un paso sombrío hasta el enemigo objetivo. Durante 15 segundos, no ocurre nada. Tus habilidades de ataque quedan deshabilitadas durante 1 segundo. Tus actitudes y encantamientos quedan deshabilitados durante 10 segundos. Cuando termina esta actitud, regresas a tu ubicación original.','Actitud. (15 segundos). Das un paso sombrío hasta el enemigo objetivo. Efecto final: regresas a tu ubicación original. Deshabilita tus habilidades de ataque durante 1 segundo. Deshabilita tus encantamientos y actitudes durante 10 segundos.'],
1651=>['Retirada mortal','Conjuro. Das un paso sombrío hasta el aliado objetivo. Si tienes menos salud que él, ganas 40...130 de salud.','Conjuro. Ganas 40...130 de salud si tienes menos que el aliado objetivo. Efecto inicial: das un paso sombrío hasta ese aliado. No te puedes apuntar a ti mismo.'],
1652=>['Cárcel sombría','Conjuro con maleficio de élite. Das un paso sombrío hasta el enemigo objetivo. Durante 1...7 segundos, el enemigo objetivo se moverá un 66% más lento.','Conjuro con maleficio de élite. Das un paso sombrío hasta el enemigo objetivo. Éste se mueve un 66% más lento (1...7 segundos).'],
1653=>['Intercambio','Conjuro. Tú y la criatura invocada objetivo intercambiáis vuestra posición dando un paso sombrío.','Conjuro. Tú y la criatura invocada objetivo intercambiáis vuestra posición dando un paso sombrío.'],
1654=>['Mezcla sombría','Conjuro con encantamiento de élite. Das un paso sombrío hasta el aliado objetivo. Cuando acabe este encantamiento, volverás a tu ubicación original.','Conjuro con encantamiento de élite. Das un paso sombrío hasta el aliado objetivo. Efecto final: vuelves a tu ubicación original. No te puedes apuntar a ti mismo.'],
1655=>['Precio del orgullo','Conjuro con maleficio. Durante 5 segundos, la próxima vez que el enemigo objetivo use una habilidad de élite, perderá 3...15 de energía.','Conjuro con maleficio. (5 segundos). Hace perder 3...15 de energía la próxima vez que el enemigo objetivo use una habilidad de élite.'],
1656=>['Aire de desencantamiento','Conjuro con maleficio de élite. Eliminas un encantamiento del enemigo objetivo y todos los cercanos. Durante 5...20 segundos, los encantamientos que tengan acaban un 150...300% antes.','Conjuro con maleficio de élite. También afecta a los enemigos cercanos al objetivo (5...20 segundos). Elimina un encantamiento del objetivo y los enemigos cercanos. Los encantamientos que tengan acaban un 150...300% antes.'],
1657=>['Sello de torpeza','Sello. Si el enemigo objetivo está atacando, interrumpirás su acción y la de los enemigos adyacentes a él, y recibirán 15...60 de daño. Todos los enemigos que estén utilizando habilidades de ataque son derribados.','Sello. Interrumpe un ataque del enemigo objetivo y los enemigos adyacentes a él. Efecto de interrupción: hace 15...60 de daño; derriba a los enemigos usando habilidades de ataque.'],
1658=>['Postura simbólica','Actitud. Durante 5...20 segundos, el siguiente sello que actives se recargará un 20...80% más rápido.','Actitud. (5...20 segundos). Tu siguiente sello se recarga un 20...80% más rápido.'],
1659=>['Frío tóxico','Conjuro de élite. El enemigo objetivo recibe 15...75 de daño frío. Si está bajo los efectos de un maleficio o de un encantamiento, estará envenenado durante 10...25 segundos.','Conjuro de élite. Hace 15...75 de daño frío. Causa envenenamiento (10...25 segundos) si el enemigo objetivo tiene un maleficio o un encantamiento.'],
1660=>['Pozo de silencio','Conjuro de pozo. Explotas el cadáver más cercano o sacrificas un 66 % de salud para crear un Pozo de silencio durante 10...30 segundos. Los enemigos en este pozo no pueden usar gritos ni cánticos, y sufren -1...4 de degeneración de salud.','Conjuro de pozo. (10...30 segundos). Los enemigos en este pozo no pueden usar gritos ni cánticos, y sufren -1...4 de degeneración de salud. Explotas un cadáver reciente o sacrificas un 66 % de salud.'],
1661=>['Piedra brillante','Conjuro. Lanza un proyectil que causa 5...50 de daño de tierra si alcanza el objetivo. Si este conjuro alcanza a un enemigo debilitado, ganas 5 de energía más 1 de energía por cada 2 rangos de almacenamiento de energía.','Conjuro. Proyectil: causa 5...50 de daño de tierra. Ganas 5 de energía más 1 de energía por cada 2 rangos de almacenamiento de energía si el enemigo objetivo está debilitado.'],
1662=>['Maldición mental','Conjuro de élite. El enemigo objetivo recibe 15...60 de daño de fuego. Si tienes más energía que el enemigo objetivo, ganas 1...8 de energía.','Conjuro de élite. Hace 15...60 de daño de fuego. Si tienes más energía que el enemigo objetivo, ganas 1...8 de energía.'],
1663=>['Llama elemental','Conjuro con encantamiento. Durante 10...35 segundos, siempre que apliques un maleficio elemental a un enemigo, arderá durante 1...5 segundos.','Conjuro con encantamiento. (10...35 segundos.) Causa quemadura (1...5 segundos) cuando se lanza un maleficio elemental al objetivo.'],
1664=>['Relámpago invocado','Conjuro de élite. El enemigo objetivo y otros dos enemigos que se encuentren cerca recibirán 10...90 de daño de relámpago. Este conjuro tiene un 25% de penetración de armadura.','Conjuro de élite. Causa 10...90 de daño de relámpago. Golpea a dos enemigos cerca del objetivo. 25% de penetración de armadura.'],
1683=>['Guardián meditabundo','Conjuro con encantamiento. Durante 5...11 segundos, el objetivo (un aliado o tú mismo) tiene un 50% de posibilidades de bloquear ataques de enemigos encantados.','Conjuro con encantamiento. (5...11 segundos). 50% de probabilidades de bloquear a enemigos encantados.'],
1684=>['Perspicacia del escriba','Conjuro con encantamiento de élite. Durante 10...35 segundos, ganarás 3 de energía cada vez que uses un sello.','Conjuro con encantamiento de élite. (10...35 segundos). Ganas 3 de energía cada vez que uses un sello.'],
1685=>['Rapidez sagrada','Conjuro con encantamiento. Durante 1...60 segundos, lanzas un 50% más deprisa tus conjuros de plegarias curativas. Este encantamiento acabará si lanzas algún otro encantamiento.','Conjuro con encantamiento. (1...60 segundos). Tus conjuros de plegarias curativas se lanzan un 50% más deprisa. Acaba si usas un encantamiento.'],
1686=>['Atisbo de luz','Conjuro de élite. Curas 10...115 de salud al objetivo (un aliado o tú mismo).','Conjuro de élite. Cura 10...115 de salud.'],
1687=>['Bendición de celo','Conjuro de élite. Curas al objetivo (un aliado o tú mismo) 30...180 de salud. Si estaba por debajo del 50% de salud, ganarás 7 de energía.','Conjuro de élite. Cura 30...180 de salud. Ganas 7 de energía si el objetivo (un aliado o tú mismo) estaba por debajo del 50% de salud.'],
1688=>['Celo del defensor','Conjuro con maleficio de élite. Durante 10...30 segundos, siempre que el enemigo objetivo ataque, ganarás 2 de energía.','Conjuro con maleficio de élite. (10...30 segundos). Ganas 2 de energía siempre que el enemigo objetivo consiga hacer un ataque.'],
1689=>['Sello de ira mística','Sello. Haces 25 de daño sagrado al enemigo objetivo por cada encantamiento que tengas encima (máximo 30...120 de daño sagrado).','Sello. Hace 25 de daño sagrado por cada encantamiento que tengas (máximo 30...120 de daño sagrado).'],
1690=>['Sello de eliminación','Sello de élite. Si el objetivo (un aliado o tú mismo) está bajo los efectos de un encantamiento, perderá un maleficio y una condición.','Sello de élite. Elimina un maleficio y una condición. No tiene efecto a menos que el objetivo (un aliado o tú mismo) tenga un encantamiento.'],
1691=>['Terminar condición','Conjuro. Quitas una condición al objetivo (un aliado o tú mismo). Si el objetivo está bajo los efectos de un encantamiento, se curará 15...75 de salud.','Conjuro. Elimina una condición. Cura 15...75 de salud si el objetivo (un aliado o tú mismo) tiene un encantamiento.'],
1692=>['Desviar maleficios','Conjuro de élite. Quitas hasta 1...3 maleficios del objetivo (un aliado o tú mismo). Por cada uno que quites, perderá una condición y ganará 15...75 de salud.','Conjuro de élite. Elimina 1...3 maleficios. Por cada uno eliminado, el objetivo (un aliado o tú mismo) pierde una condición y gana 15...75 de salud.'],
1693=>['Contraataque','Ataque cuerpo a cuerpo. Si impacta este ataque, harás +5...35 daño. Si el enemigo estaba atacando, ganarás 2...6 de energía.','Ataque cuerpo a cuerpo. Hace +5...35 de daño. Ganas 2...6 de energía si el enemigo objetivo está atacando.'],
1694=>['Golpe antihechizos','Ataque cuerpo a cuerpo de élite. Si este ataque impacta, harás +7...25 de daño. Si el objetivo está bajo los efectos de un encantamiento, no lo podrá bloquear.','Ataque cuerpo a cuerpo de élite. Hace +7...25 de daño. No se puede bloquear si el enemigo objetivo tiene un encantamiento.'],
1695=>['Golpe del soldado','Ataque cuerpo a cuerpo. Si este ataque impacta, harás +10...40 más de daño. Si estás bajo los efectos de un grito o cántico, no se podrá bloquear.','Ataque cuerpo a cuerpo. Hace +10...40 de daño. No se puede bloquear si estás bajo los efectos de un cántico o grito.'],
1696=>['Decapitación','Ataque con hacha de élite. You lose all adrenaline and all Energy. This attack is unblockable, you deal +5...80 damage, and cause a Deep Wound for 5...20 seconds. This attack is always critical and if foe is killed, nearby foes are Weakened for 8 seconds.','Ataque con hacha de élite. Deals +5...80 damage. Inflicts Deep Wound condition (5...20 seconds). Automatic critical hit. If foe is killed, nearby foes are Weakened (8 seconds). You lose all adrenaline and Energy.'],
1697=>['Golpe del cazamagos','Ataque con martillo de élite. Si este ataque impacta, derribas al enemigo objetivo. Si éste está bajo los efectos de un encantamiento, no te podrá bloquear.','Ataque con martillo de élite. Causa derribo. No se puede bloquear si el enemigo objetivo tiene un encantamiento.'],
1698=>['Actitud del soldado','Actitud de élite. Durante 5...15 segundos, tienes un 75% de posibilidades de bloquear. Atacas un 33% más deprisa si estás bajo los efectos de un grito o cántico.','Actitud de élite. (5...15 segundos). Tienes un 75% de probabilidades de bloquear. Atacas un 33% más deprisa si estás bajo los efectos de un grito o cántico.'],
1699=>['Defensa del soldado','Actitud. Durante 1...6 segundos, tienes un 75% de probabilidades de bloquear ataques si estás bajo los efectos de un grito o cántico. Ganas 1 golpe de adrenalina por cada ataque bloqueado.','Actitud. (1...6 segundos). Tienes un 75% de probabilidades de bloquear si estás bajo los efectos de un grito o cántico. Efecto al bloquear: ganas 1 de adrenalina.'],
1700=>['Defensa frenética','Actitud. Durante 8 segundos tienes un 75% de probabilidades de bloquear ataques, pero te harán el doble de daño.','Actitud. (8 segundos). Tienes un 75% de probabilidades de bloquear. Recibes el doble de daño.'],
1701=>['Actitud firme','Actitud de élite. Durante 10 segundos, la próxima vez que intenten derribarte, en lugar de ello ganas 1...4 golpes de adrenalina y 1...7 de energía.','Actitud de élite. (10 segundos). La próxima vez que deberías ser derribado, ganas 1...4 de adrenalina y 1...7 de energía.'],
1702=>['Golpe de los colmillos de acero','Ataque con espada. Si este ataque impacta, harás +1...31 de daño. Si golpeas a un objetivo derribado, ganarás 1...5 de adrenalina.','Ataque con espada. Hace +1...31 de daño. Ganas 1...5 de adrenalina si el enemigo objetivo está derribado.'],
1719=>['Disparo estridente','Ataque con arco. Si este ataque impacta, harás +10...25 de daño. Si tu objetivo está al alcance del oído, sufrirá una hemorragia durante 5...20 segundos.','Ataque con arco. Hace +10...25 de daño. Causa hemorragia (5...20 segundos) si el enemigo objetivo está al alcance del oído.'],
1720=>['Flecha afilada','Ataque con arco. Si este ataque impacta, harás +5...20 de daño. Si es además un golpe crítico, harás +5...25 de daño adicional.','Ataque con arco. Hace +5...20 de daño. +5...25 de daño extra si das un golpe crítico.'],
1721=>['Violencia al unísono','Habilidad de élite. Durante 3...15 segundos, tú y tu mascota atacáis un 33% más rápido y os movéis un 25% más rápido también.','Habilidad de élite. (3...15 segundos). Tú y tu mascota atacáis un 33% más deprisa y os movéis un 25% más rápido. No tiene efecto a menos que la mascota esté viva.'],
1722=>['Flecha ahorquillada','Ataque con arco. Disparas dos flechas simultáneamente al enemigo objetivo. Si estás bajo los efectos de un maleficio o un encantamiento, sólo dispararás una flecha.','Ataque con arco. Disparas dos flechas simultáneamente. Sólo disparas una flecha si estás bajo los efectos de un maleficio o un encantamiento.'],
1723=>['Precisión interruptora','Preparación["Preparaciones"]. Durante 36 segundos, siempre que consigas hacer un golpe crítico con tus flechas interrumpirás al enemigo.','Preparación["Preparaciones"]. (36 segundos). Interrumpe una acción siempre que tus flechas hagan un golpe crítico.'],
1724=>['Destreza del experto','Actitud de élite. Durante 1...20 segundos, atacas un 33% más deprisa y tu atributo puntería sube 2.','Actitud de élite. (1...20 segundos). Atacas un 33% más deprisa y ganas +2 en tu atributo puntería.'],
1725=>['Vientos ruidosos','Ritual de la naturaleza. Creas un espíritu de nivel 1...10, que hará que los cánticos y gritos cuesten 1...5 más de energía. Morirá a los 30...180 segundos.','Ritual de la naturaleza. Creas un espíritu de nivel 1...10 (30...180 segundos de vida). A las criaturas de la zona les cuesta 1...5 de energía usar cánticos y gritos.'],
1726=>['Disparo antimagos','Ataque con arco de élite. Si impacta, este ataque interrumpe la acción del enemigo objetivo. Si la acción era un conjuro, quedará desactivado durante 10 segundos más. No se puede bloquear este ataque.','Ataque con arco de élite. Interrumpe una acción. Efecto: la habilidad interrumpida queda desactivada durante +10 segundos. No se puede bloquear.'],
1727=>['Zancada natural','Actitud. Durante 1...8 segundos, corres un 33% más deprisa y tienes un 50% de posibilidades de bloquear ataques. La Zancada natural acaba si te echan un maleficio o un encantamiento.','Actitud. (1...8 segundos). Te mueves un 33% más deprisa y tienes un 33% de probabilidades de bloquear. Acaba si recibes un maleficio o un encantamiento.'],
1728=>['Violencia del heket','Actitud. Durante 5...11 segundos, atacas un 33% más deprisa. Esta actitud termina si usas una habilidad de ataque.','Actitud. (5...11 segundos). Atacas un 33% más deprisa. Acaba si usas una habilidad.'],
1729=>['Trampa de humo','Trampa de élite. Cuando se active esta trampa de humo, todos los enemigos situados en la zona quedarán cegados y atontados durante 5...10 segundos. La trampa de humo dura 90 segundos. Se te podrá interrumpir con facilidad mientras la coloques.','Trampa de élite. (90 segundos). Causa ceguera y aturdimiento (5...10 segundos) a los enemigos de la zona. Se puede interrumpir con facilidad.'],
1730=>['Calor indignante','Ritual de la naturaleza de élite. Creas un espíritu de nivel 1...10. Las criaturas no espíritus que estén en su zona ganarán adrenalina el doble de rápido. Morirá a los 30...120 segundos.','Ritual de la naturaleza de élite. Crea un espíritu de nivel 1...10 (30...120 segundos de vida). Las criaturas de la zona ganan el doble de adrenalina.'],
1731=>['Elocuente sea Sogolon','Conjuro con objeto. Durante 60 segundos, todos los gritos y cánticos que uses durarán un 20...50% más.','Conjuro con objeto. (60 segundos). Los gritos y cánticos que uses duran un 20...50% más.'],
1732=>['Destructora sea Glaive','Conjuro con objeto de élite. Llevas las cenizas de Glaive durante 30...60 segundos. Mientras las lleves, todas las habilidades de Ritualista tienen 20% de penetración de armadura. Cuando las sueltes, todos los enemigos de la zona reciben 15...85 de daño de relámpago.','Conjuro con objeto de élite. (30...60 segundos). Tus habilidades de Ritualista tienen un 20% de penetración de armadura. Efecto al soltarse: hace 15...85 de daño de relámpago a los enemigos de la zona.'],
1733=>['Golpe del atacante','Conjuro. El enemigo objetivo recibe 10...60 de daño de relámpago. Si estás bajo los efectos de un conjuro para armas, le harás 10...50 de daño de relámpago extra.','Conjuro. Hace 10...60 de daño de relámpago. 10...50 de daño de relámpago extra si tienes un conjuro con arma.'],
1734=>['Mirada de furia','Ritual con espíritus. Destruyes el espíritu objetivo y creas un espíritu de furia de nivel 1...14, cuyos ataques causan 5...20 de daño. Morirá a los 30...60 segundos.','Ritual con espíritus. Destruye un espíritu. Creas un espíritu de nivel 1...14 (30...60 segundos de vida). Sus ataques hacen 5...20 de daño.'],
1736=>['Fuerza espiritual','Conjuro con encantamiento de élite. Durante 15...60 segundos, tus ataques hacen 5...35 más de daño mientras estés bajo los efectos de un conjuro para arma.','Conjuro con encantamiento de élite. (15...60 segundos). Tus ataques hacen +5...35 de daño si tienes un conjuro con arma.'],
1737=>['Celo del atacante','Conjuro con encantamiento de élite. Durante 10...40 segundos, cuando lances un conjuro con arma a algún aliado, ganarás 1...5 de energía.','Conjuro con encantamiento de élite. (10...40 segundos). Ganas 1...5 de energía cuando lances un conjuro con arma.'],
1738=>['Visión del más allá','Conjuro con encantamiento. Durante 8...20 segundos, no se te podrá cegar.','Conjuro con encantamiento. (8...20 segundos). Eres inmune a la ceguera.'],
1739=>['Recuerdos renovadores','Conjuro con encantamiento. Durante 5...20 segundos, mientras lleves un objeto, los conjuros para armas y objetos que lances te costarán un 5...35% menos de energía.','Conjuro con encantamiento. (5...20 segundos). Tus conjuros con armas y objetos consumen un 5...35% menos de energía. No tiene efecto si no estás llevando algún objeto.'],
1740=>['Remedio del atacante','Conjuro con encantamiento. Durante 10...30 segundos, cuando lances un conjuro para arma a algún aliado, este perderá 2 condiciones.','Conjuro con encantamiento. (10...30 segundos). Cada vez que lances un conjuro de arma, el aliado objetivo pierde 2 condiciones.'],
1741=>['Luz de espejo fantasmal','Conjuro. Curas a un aliado 15...90 de salud. Si estás al alcance del oído de un espíritu, tú te curarás también 15...90 de salud.','Conjuro. Cura 15...90 de salud. Ganas 15...90 de salud si hay algún espíritu al alcance del oído. No te puedes apuntar a ti mismo.'],
1742=>['Sello de poder fantasmal','Sello de élite. Durante 5...20 segundos, todos los espíritus al alcance del oído que controles atacan un 33% más rápido y hacen +5...10 de daño.','Sello de élite. (5...20 segundos). Todos los espíritus al alcance del oído que controles atacan un 33% más rápido y hacen +5...10 de daño.'],
1743=>['Sello de encadenamiento','Sello. Pierdes 200...50 de salud y asumes el control del espíritu objetivo controlado por el enemigo. (50% de posibilidades de fallar con engendramiento 4 o inferior.)','Sello. Pierdes 200...50 de salud. Asumes el control del espíritu objetivo controlado por el enemigo. <c x="SkillDull">50% de posibilidades de fallar a menos que tengas engendramiento 5 o superior.'],
1744=>['Carga del cuidador','Conjuro de élite. El enemigo objetivo recibe 20...85 de daño de relámpago. Si estás llevando algún objeto, ganas 7 de energía y 5...50 de salud.','Conjuro de élite. Hace 20...85 de daño de relámpago. Ganas 7 de energía y 5...50 de salud si llevas algún objeto.'],
1745=>['Angustia','Ritual con espíritus. Creas un espíritu de nivel 1...11, cuyos ataques causan 5...20 de daño y hacen el doble de daño a los enemigos que tengan algún maleficio. Morirá a los 15...45 segundos.','Ritual con espíritus. Creas un espíritu de nivel 1...11 (15...45 segundos de vida). Sus ataques hacen 5...20 de daño. Doble de daño a los enemigos con maleficio.'],
1747=>['Fortalecimiento','Ritual con espíritus. Creas un espíritu de nivel 1...14. Todos los aliados dentro de su radio que lleven un objeto ganan 15...45 de salud y 10 de energía máxima. Este espíritu morirá a los 15...60 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...14 (15...60 segundos de vida). Los aliados dentro de su radio que lleven un objeto ganan 15...45 de salud máxima y 10 de energía máxima.'],
1748=>['Mejoría','Ritual con espíritus. Creas un espíritu de nivel 1...14. Las condiciones que estén sufriendo los aliados de la zona terminarán un 20...50% más deprisa. Morirá a los 30...60 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...14 (30...60 segundos de vida). Las condiciones que tengan los aliados de la zona duran un 20...50% menos.'],
1749=>['Arma de furia','Conjuro con arma de élite. Durante 5...20 segundos, el objetivo (un aliado o tú mismo) gana 100% más de adrenalina y 1 de energía siempre que ataque con éxito.','Conjuro con arma de élite. (5...20 segundos). Ganas un 100% más de adrenalina y +1 de energía cada vez que el objetivo (un aliado o tú mismo) consiga hacer un ataque.'],
1750=>['Arma de Xinrae','Conjuro con arma de élite. Durante 8 segundos, la siguiente vez que el objetivo (un aliado o tú mismo) reciba daño de un enemigo, éste se reduce al 5% de la salud máxima del objetivo, que roba además 20...80 de salud del enemigo.','Conjuro con arma de élite. (8 segundos). La siguiente vez que el objetivo (un aliado o tú mismo) reciba daño de un enemigo, éste se reduce al 5% de la salud máxima del objetivo, que roba además 20...80 de salud del enemigo.'],
1751=>['Arma del militar','Conjuro con arma. Durante 3...13 segundos, si el objetivo (un aliado o tú mismo)ataca a un enemigo que no está atacando, le interrumpirá.','Conjuro con arma. (3...13 segundos). Los ataques interrumpen una acción. No interrumpe a los enemigos atacando.'],
1752=>['Arma de remedio','Conjuro con arma de élite. Durante 8 segundos, la siguiente vez que el objetivo aliado reciba daño o pierda vida debido al ataque de un enemigo, el aliado le robará 20...80 de salud al enemigo y perderá 2 condiciones.','Conjuro con arma de élite. (8 segundos). La próxima vez que el objetivo aliado reciba daño o pierda vida debido al ataque de un enemigo, el aliado le robará 20...80 de salud al enemigo y perderá 2 condiciones.'],
1753=>['Barrido desgarrador','Ataque con guadaña. Haces +5...20 de daño y pierdes un encantamiento de Derviche. Si se perdió un encantamiento, quitas uno de cada enemigo que golpees.','Ataque con guadaña. Hace +5...20 de daño. Pierdes un encantamiento de Derviche. Efecto de eliminación: los enemigos que golpeas pierden un encantamiento.'],
1754=>['Acometida','Conjuro con encantamiento de destello de élite. Durante 3...15 segundos, atacas, te mueves y acumulas adrenalina un 25% más rápido.','Conjuro con encantamiento de destello de élite. (3...15 segundos). Atacas, te mueves y acumulas adrenalina un 25% más rápido.'],
1755=>['Corrupción mística','Conjuro con encantamiento de destello. Todos los enemigos adyacentes sufren enfermedad durante 1...10 segundos. Durante 20 segundos, no ocurre nada. La duración de la enfermedad se dobla si estás encantado cuando activas esta habilidad. Cuando termina este encantamiento, todos los miembros del grupo que estén al alcance del oído se curan de la enfermedad.','Conjuro con encantamiento de destello. (20 segundos). Efecto inicial: todos los enemigos cercanos sufren enfermedad (1...10 segundos). Si ya estás encantado, la duración se dobla. Efecto final: los miembros del grupo al alcance del oído pierden la enfermedad.'],
1756=>['Garra de Grenth','Conjuro con encantamiento de destello de élite. For 20 seconds, your attack skills also Cripple that foe for 1...11 seconds and you transfer 1...3 conditions from yourself to that foe.','Conjuro con encantamiento de destello de élite. (20 seconds.) Inflict Cripple (1...11 seconds) with your attack skills and transfer 1...3 conditions.'],
1757=>['Velo de espinas','Conjuro con encantamiento de destello. Cuando lanzas este encantamiento, todos los enemigos cercanos reciben 5...50 de daño perforante. Durante 5...25 segundos, recibes 5...35% menos daño de conjuros.','Conjuro con encantamiento de destello. (5...25 segundos). El daño que recibas de los conjuros se reduce un 5...35%. Efecto inicial: todos los enemigos cercanos reciben 5...50 de daño perforante.'],
1758=>['Garra del hostigador','Conjuro con encantamiento de destello. Durante 5...20 segundos, los ataques contra los enemigos en movimiento también los dejarán lisiados durante 2...9 segundos. Cuando lanzas este encantamiento, pierdes la lisiadura y otra condición más. Este encantamiento termina después de causar lisiadura 1...3 veces.','Conjuro con encantamiento de destello. (5...20 segundos). Los ataques a los enemigos en movimiento los dejan lisiados. Efecto inicial: pierdes la lisiadura y otra condición más. Termina después de causar lisiadura 1...3 veces.'],
1759=>['Voto de fuerza','Conjuro con encantamiento de élite. Durante 15 segundos, cuando ataques a un enemigo con tu guadaña, haces un 10...25 de daño cortante a todos los enemigos adyacentes.','Conjuro con encantamiento de élite. (15 segundos). Los ataques con guadaña hacen 10...25 de daño cortante a todos los enemigos adyacentes.'],
1760=>['Aura de polvo de ébano','Conjuro con encantamiento de destello de élite. Cuando lanzas este encantamiento, todos los enemigos cercanos quedan cegados durante 1...7 segundos. Durante 30 segundos, si llevas un arma de tierra, tus ataques cuerpo a cuerpo hacen +3...30 de daño de tierra. Cuando termina este encantamiento, tu ceguera se cura.','Conjuro con encantamiento de destello de élite. (30 segundos). Haces +3...30 de daño de tierra con tus ataques cuerpo a cuerpo. Efecto inicial: los enemigos cercanos se quedan ciego durante 1...7 segundos. Efecto final: quita la ceguera. No surte efecto si no llevas un arma de tierra.'],
1761=>['Voto de celo','Conjuro con encantamiento de élite. Durante 20 segundos, tienes una regeneración de energía de -2 y ganas 1...6 de energía cada vez que golpees con un ataque.','Conjuro con encantamiento de élite. (20 segundos). Ganas 1...6 de energía cada vez que ataques con éxito. Tienes -2 de regeneración de energía.'],
1762=>['Corazón de furia','Actitud. Durante 2...10 segundos, atacas un 25% más rápido.','Actitud. (2...10 segundos). Atacas un 25% más rápido.'],
1763=>['Renovación de celo','Conjuro con encantamiento de destello. Todos los enemigos cercanos reciben 5...30 de daño sagrado. Durante 5...25 segundos, tienes -1 de regeneración de energía y ganas 1 de energía cada vez que golpeas a un enemigo. Si este maleficio acaba prematuramente, ganas 1...5 de energía.','Conjuro con encantamiento de destello. (5...25 segundos). Efecto inicial: hace 5...30 de daño sagrado a los enemigos cercanos. Tienes -1 de regeneración de energía y ganas 1 de energía cada vez que golpeas a un enemigo. Gana 1...5 de energía si este encantamiento termina prematuramente.'],
1764=>['Perspicacia del atacante','Conjuro con encantamiento de destello. Durante 3...10 segundos, tienes un 50% de posibilidades de bloquear mientras se ataca. Cuando termina este encantamiento, todos los enemigos adyacentes quedan debilitados durante 3...15 segundos.','Conjuro con encantamiento de destello. (3...10 segundos). Tienes 50% de probabilidades de bloquear mientras atacas. Efecto final: causa debilidad durante 3...15 segundos a los enemigos adyacentes.'],
1765=>['Aura desgarradora','Conjuro con encantamiento de destello. Cuando lanzas este encantamiento, todos los enemigos cercanos reciben 10...40 de daño de frío. Durante 30 segundos, tus habilidades de ataque quitan encantamientos a los enemigos derribados. Cuando termina este encantamiento, todos los enemigos cercanos tienen la armadura rota durante 1...10 segundos.','Conjuro con encantamiento de destello. (30 segundos). Tus habilidades de ataque quitan encantamientos a los enemigos derribados. Efecto inicial: hace 10...40 de daño de frío a todos los enemigos cercanos. Efecto final: los enemigos cercanos tienen la armadura rota durante 1...10 segundos.'],
1766=>['Gracia del pie con plumas','Conjuro con encantamiento. Durante 5...20 segundos, te mueves un 25% más rápido y las condiciones desaparecen un 50% antes.','Conjuro con encantamiento. (5...20 segundos). Te mueves un 25% más rápido y las condiciones desaparecen un 50% antes.'],
1767=>['Barrido del segador','Ataque con guadaña de élite. Si este ataque impacta, causarás lisiadura a tu objetivo durante 3...15 segundos. Pierdes un encantamiento de Derviche. Si se quitó un encantamiento, este ataque derriba durante 2...3 segundos.','Ataque con guadaña de élite. (3...15 segundos.) Causa lisiadura. Pierdes un encantamiento de Derviche. Efecto de eliminación: causa derribo durante 2...3 segundos.'],
1768=>['Rapidez del hostigador','Conjuro con encantamiento de destello. Durante 2...8 segundos, te mueves un 25% más rápido y haces +3...12 de daño contra los enemigos en movimiento.','Conjuro con encantamiento de destello. (2...8 segundos). Te mueves un 25% más rápido y haces +3...12 de daño a los enemigos en movimiento.'],
1769=>['Enfado dirigido','Habilidad de élite. Durante 45 segundos, ganas un 0...150% más de adrenalina.','Habilidad de élite. (45 segundos). Ganas un 0...150% más de adrenalina.'],
1770=>['Temperamento natural','Habilidad. Durante 4...15 segundos, ganas un 33% más de adrenalina mientras no estés bajo los efectos de ningún encantamiento.','Habilidad. (4...15 segundos). Ganas un 33% más de adrenalina. No tiene efecto si no tienes un encantamiento.'],
1771=>['Canción de la restauración','Cántico de élite. Durante 10 segundos, la próxima vez que algún miembro del grupo al alcance del oído use una habilidad, se curará 45...110 de salud.','Cántico de élite. (10 segundos). Los miembros del grupo al alcance del oído ganan 45...110 de salud con su siguiente habilidad.'],
1772=>['Lírica de purificación','Cántico. Durante 5...20 segundos, la próxima vez que algún aliado al alcance del oído use un sello, se curará 1 condición.','Cántico. (5...20 segundos). Los aliados al alcance del oído pierden una condición con su siguiente sello.'],
1773=>['Furia del soldado','Eco de élite. Durante 10...35 segundos, si estás bajo los efectos de un cántico o grito, atacas un 33% más deprisa y ganas 33% más de adrenalina, pero tienes -20 de armadura.','Eco de élite. (10...35 segundos). Atacas un 33% más deprisa y ganas 33% de adrenalina si estás bajo los efectos de un grito o cántico. Tienes -20 de armadura.'],
1774=>['Estribillo agresivo','Eco. Durante 5...25 segundos, atacas un 25% más rápido pero tienes -20 de armadura. Este eco se reactivará cada vez que los efectos de un cántico o grito te alcancen.','Eco. (5...25 segundos). Atacas un 25% más rápido. Renovación: cada vez que los efectos de un cántico o grito acaben. Tienes -20 de armadura.'],
1775=>['Final vigorizante','Eco. Durante 10...35 segundos, cada vez que los efectos de un grito o cántico terminen en el aliado objetivo no espíritu, éste ganará 1...2 de energía.','Eco. (10...35 segundos). El objetivo (un aliado o tú mismo) gana 1...2 de energía cada vez que los efectos de un cántico o grito acaben en él.No se puede apuntar a un espíritu.'],
1776=>['Sello de agresión','Sello. Si estás bajo los efectos de un grito o cántico, ganarás 2 de adrenalina.','Sello. Ganas 2 de adrenalina si estás bajo los efectos de un cántico o grito.'],
1777=>['Sello del remedio','Sello. Pierdes 1 condición.','Sello. Pierdes una condición.'],
1778=>['Sello del retorno','Sello. Resucitas al aliado objetivo con 5...20% de salud y 1...4% de energía por cada miembro del grupo al alcance del oído.','Sello. Resucita al aliado objetivo (5...20% de salud y 1...4% de energía por cada miembro del grupo al alcance del oído).'],
1779=>['"¡Esta es la nuestra!"','Grito. Ganas 2 de adrenalina por cada miembro del grupo al alcance del oído (máximo 1...8 de adrenalina).','Grito. Ganas 2 de adrenalina (máximo 1...8) por cada miembro del grupo al alcance del oído.'],
1780=>['"¡No nos toquéis!"','Grito. Durante 20 segundos, las siguientes habilidads de toque 1...5 contra ti fallarán.','Grito. (20 segundos.) Las siguientes habilidads de toque 1...5 contra ti fallarán.'],
1781=>['"¡A por su punto débil!"','Grito. Durante 5...20 segundos, la próxima vez que el aliado objetivo ataque, causará +5...50 de daño y hará una herida grave que durará 5...20 segundos.','Grito. (5...20 segundos.) El aliado objetivo causará causa +5...50 de daño y hará una herida grave (5...20 segundos) con el siguiente ataque.'],
1782=>['"¡El poder es vuestro!"','Grito de élite. Durante 2...4 segundos, todos los aliados al alcance del oído ganan +1...2 de regeneración de energía.','Grito de élite. (2...4 segundos). Todos los aliados al alcance del oído ganan +1...2 de regeneración de energía.'],
1783=>['Lanza del homicida','Ataque con lanza. Si este ataque impacta, harás +5...25 de daño al enemigo. Si éste tiene más salud que tú, le harás una herida grave que durará 5...20 segundos.','Ataque con lanza. Hace +5...25 de daño. Causa herida grave (5...20 segundos) si el enemigo objetivo tiene más salud que tú.'],
1784=>['Jabalina ligera','Ataque con lanza. Si este ataque impacta, harás +5...20 de daño. Si estás bajo los efectos de un encantamiento, la jabalina irá el doble de rápido y no se podrá bloquear.','Ataque con lanza. Hace +5...20 de daño. Esta lanza vuela el doble de rápido y no se puede bloquear si tienes un encantamiento.'],
1814=>['Mirada del Iluminador','Habilidad. Haces 100 de daño sagrado al demonio de Abaddon objetivo y le interrumpes. Esta habilidad golpeará a un enemigo adicional por cada rango de Iluminador que hayas conseguido. Esta habilidad estará desactivada durante 15 segundos después de usarse.','Habilidad. Haces 100 de daño sagrado al demonio de Abaddon objetivo y le interrumpes. Alcanza a un enemigo adicional en la zona por cada rango de Iluminador que hayas conseguido. Esta habilidad queda desactivada (15 segundos).'],
1815=>['Sello del Iluminador','Sello. Si estás dentro de la zona de un demonio de Abaddon, ganarás 3...5 de adrenalina y 16...24 de energía.','Sello. Ganas 3...5 de adrenalina y 16...24 de energía si estás dentro de la zona de un demonio de Abaddon.'],
1816=>['Sello de renacimiento de los Lanceros','Sello. Resucitas al miembro del grupo objetivo en tu posición con toda la salud y 10% de energía por cada rango de Lancero que hayas conseguido. Este sello sólo se puede usar una vez por misión a menos que lo recargue un aumento de moral.','Sello. Resucitas al miembro del grupo objetivo en tu posición (toda la salud y 10% de energía por cada rango de Lancero que hayas conseguido). Este sello sólo volverá a estar activado cuando consigas un aumento de moral.'],
1948=>['Santuario sombrío','Conjuro con encantamiento. Quedas cegado durante 5 segundos. Además, durante 10 segundos, ganas 7...10 de regeneración de salud y +40 de armadura.','Conjuro con encantamiento. (10 segundos). Ganas +7...10 de regeneración de salud y +40 de armadura. Sufres ceguera (5 segundos).'],
1949=>['Pesadilla de éter','Conjuro con maleficio. El enemigo objetivo pierde 5...8 de energía. Por cada punto de energía que pierda así, ese enemigo y todos los que estén en la zona sufrirán una degeneración de salud de -1 durante 10 segundos.','Conjuro con maleficio. Hace perder 5...8 de energía. El enemigo objetivo y los de la zona tienen -1 de degeneración de salud por cada punto de energía perdido (10 segundos).'],
1950=>['Sello de corrupción','Sello. Haces 20...30 de daño al enemigo objetivo y todos los cercanos. Por cada enemigo que tenga una condición o maleficio, ganas 2 de energía (máximo 12...20 de energía).','Sello. Hace 20...30 de daño al enemigo objetivo y los cercanos. Ganas 2 de energía (máximo 12...20) por cada uno de esos enemigos que tenga una condición o maleficio.'],
1951=>['Señor elemental','Conjuro con encantamiento. Durante 40...60 segundos, tus atributos de los elementos aumentan en 1 punto. Cada vez que lances un conjuro, ganas 1 de energía por cada 10 rangos de almacenamiento de energía y además te curas el 100...300% del coste de energía del conjuro.','Conjuro con encantamiento. (40...60 segundos). Tus atributos de los elementos aumentan en 1. Cada vez que lances un conjuro, ganas 1 de energía por cada 10 rangos de almacenamiento de energía y además te curas el 100...300% del coste de energía del conjuro.'],
1952=>['Espíritu caritativo','Conjuro con encantamiento. Durante 15...20 segundos, los conjuros cuyo objetivo sea otro aliado te costarán 3 menos de energía.','Conjuro con encantamiento. (15...20 segundos.) Los conjuros que tengan como objetivo otro aliado te costarán 3 menos de energía.'],
1953=>['Disparo triple','Ataque con arco. Disparas 3 flechas simultáneamente al enemigo objetivo. Estas flechas hacen un 40...25% menos de daño.','Ataque con arco. Disparas 3 flechas simultáneamente al enemigo objetivo. Estas flechas hacen un 40...25% menos de daño.'],
1954=>['"¡Poneos a salvo!"','Grito. Durante 4...6 segundos, todos compañeros de equipo ganan +100 de armadura.','Grito. (4...6 segundos). Los demás miembros del grupo ganan +100 de armadura.'],
1955=>['Aura del poder divino','Conjuro con encantamiento. Durante (45 segundos), haces 20...25 de daño sagrado a todos los enemigos adyacentes cuando pierdes un encantamiento de Derviche.','Conjuro con encantamiento. (45 segundos). Cuando pierdes un encantamiento de Derviche, los enemigos adyacentes reciben 20...25 de daño sagrado.'],
1957=>['Lanza de furia','Ataque con lanza. Este ataque hace +30...40 de daño. Si impacta a un enemigo padeciendo alguna condición, ganarás 3...6 de adrenalina.','Ataque con lanza. Hace +30...40 de daño. Ganas 3...6 golpes de adrenalina si golpeas a algún enemigo con condición.'],
1986=>['Asalto vampírico','Ataque doble. Debe ir precedido de un ataque complementario. Si este ataque impacta, robas 10...40 de salud.','Ataque doble. Roba 10...40 de salud si este ataque impacta. Debe ir precedido de un ataque complementario.'],
1987=>['Ataque de loto','Ataque complementario. Debe ir precedido de un ataque inicial. Si impacta, este ataque hace +10...25 de daño y ganas 5...20 de energía.','Ataque complementario. Hace +10...25 de daño; ganas 5...20 de energía. Debe ir precedido de un ataque inicial.'],
1988=>['Ataque del colmillo dorado','Ataque complementario. Debe ir precedido de un ataque inicial. Si estás bajo los efectos de un encantamiento y este ataque impacta, el enemigo objetivo sufrirá una herida grave durante 5...20 segundos.','Ataque complementario. Causa herida grave (5...20 segundos) si tienes algún encantamiento. Debe ir precedido de un ataque inicial.'],
1990=>['Ataque de loto caída','Ataque complementario. Debe alcanzar a un enemigo derribado. Si impacta, hará +15...35 de daño y ganarás 1...12 de energía.','Ataque complementario. Hace +15...35 de daño. Ganas 1...12 de energía. No tiene efecto si el enemigo objetivo no está derribado.'],
1991=>['Sello del sádico','Sello. Ganas 10...45 de salud por cada condición que sufra el enemigo objetivo.','Sello. Ganas 10...45 de salud por cada condición que sufra el enemigo objetivo.'],
1992=>['Sello de distracción','Sello. Si el enemigo objetivo está lanzando un conjuro, éste se interrumpirá y estará desactivado durante 1...5 segundos por cada sello que lleves.','Sello. Interrumpe un conjuro. Efecto de interrupción: el conjuro del enemigo objetivo queda desactivado durante 1...5 segundos por cada sello que lleves.'],
1993=>['Sello del recuerdo','Sello. Durante 6 segundos, tienes -4 de regeneración de energía. Cuando este efecto acabe, ganas 13...20 de energía.','Sello. (6 segundos). Tienes -4 de regeneración de energía. Efecto final: ganas 13...20 de energía.'],
1994=>['Cerrojo de poder','Conjuro. Si el enemigo objetivo está lanzando un conjuro o cántico, éste se interrumpirá y estará desactivado durante 5...13 segundos más.','Conjuro. Interrumpe un conjuro o cántico. Efecto de interrupción: el conjuro o cántico interrumpido está desactivado durante +5...13 segundos.'],
1995=>['Quien no derrocha, no necesita','Conjuro. Si el enemigo objetivo no está lanzando un conjuro ni atacando, ganarás 8...13 de energía.','Conjuro. Ganas 8...13 de energía si el enemigo objetivo no está lanzando un conjuro ni atacando.'],
1996=>['Suma de todos los temores','Conjuro con maleficio. Durante 4...12 segundos, el enemigo objetivo se mueve, ataca y lanza conjuros un 33% más lento.','Conjuro con maleficio. (4...12 segundos). El enemigo objetivo se mueve, ataca y lanza conjuros un 33% más lento.'],
1997=>['Aura desdeñosa','Conjuro con encantamiento. Durante 5...20 segundos, los ataques cuerpo a cuerpo del aliado objetivo causan debilitamiento durante 5...20 segundos.','Conjuro con encantamiento. (5...20 segundos). Los ataques cuerpo a cuerpo del aliado objetivo causan debilitamiento (5...20 segundos).'],
1998=>['Cacofonía','Conjuro con maleficio. Durante 15 segundos, cada vez que el enemigo objetivo use un grito o un cántico, recibirá 30...105 de daño.','Conjuro con maleficio. (15 segundos). Hace 30...105 de daño cada vez que el enemigo objetivo use un grito o un cántico.'],
1999=>['Abrazo de invierno','Conjuro con maleficio. Durante 2...6 segundos, el enemigo objetivo se mueve un 66% más despacio y sufre 5...15 de daño mientras se mueva.','Conjuro con maleficio. (2...6 segundos). El enemigo objetivo se mueve un 66% más despacio y sufre 5...15 de daño al moverse.'],
2000=>['Grilletes de tierra','Conjuro con maleficio. Durante 3 segundos, el enemigo objetivo y los cercanos se mueven un 90% más despacio. Cuando Grilletes de tierra termina, aplica debilitamiento durante 5...20 segundos.','Conjuro con maleficio. (3 segundos.) El enemigo objetivo y los cercanos se mueven un 90% más despacio. Causa debilitamiento durante 5...20 segundos al acabar.'],
2001=>['Protección de debilidad','Conjuro de protección. Creas una Protección de debilidad en tu ubicación actual. Durante 5...20 segundos, los enemigos del área sufren debilitamiento durante 5...segundos cuando reciban daño de los elementos.','Conjuro de protección. (5...20 segundos). Causa debilitamiento (5...20 segundos) a los enemigos que reciban daño de los elementos dentro de la protección.'],
2002=>['Glifo de rapidez','Glifo. Durante 15 segundos, tus próximos conjuros (1...5) se recargan un 25% más rápido y sus proyectiles se mueven un 200% más deprisa.','Glifo. (15 segundos). Tus siguientes 1...5 conjuro["conjuros"] se recargan un 25% más rápido y sus proyectiles se mueven un 200% más deprisa.'],
2003=>['Curar maleficio','Conjuro. Eliminas un maleficio del objetivo (un aliado o tú mismo). Al hacerlo, ese aliado se cura 30...100 de salud.','Conjuro. Elimina un maleficio. Efecto de la eliminación: cura 30...100 de salud.'],
2004=>['Condición atacante','Conjuro. Eliminas una condición del objetivo (un aliado o tú mismo). Al hacerlo, los enemigos de la zona reciben 10...60 de daño sagrado.','Conjuro. Elimina una condición. Efecto de la eliminación: hace 10...60 de daño sagrado a los enemigos de la zona del objetivo (un aliado o tú mismo).'],
2005=>['Bendición del atacante','Conjuro con encantamiento. Durante 30 segundos, tus plegarias de ataque tienen un extra doble de favor divino.','Conjuro con encantamiento. (30 segundos). Tus plegarias de ataque tienen el doble del extra de curación del favor divino.'],
2006=>['Sello de castigo','Sello. Haces 26...56 de daño sagrado al enemigo objetivo. Si estaba atacando, ganas 4...14 de energía.','Sello. Hace 26...56 de daño sagrado. Ganas 4...14 de energía si el enemigo objetivo está atacando.'],
2007=>['Velo purificador','Conjuro con encantamiento. Mientras mantengas este encantamiento, las condiciones acaban un 5...50% antes en el aliado objetivo. Cuando este encantamiento acabe, ese objetivo se quita una condición.','Conjuro con encantamiento. Las condiciones del objetivo (un aliado o tú mismo) acaban un 5...50% antes. Efecto final: elimina una condición.'],
2008=>['Golpe pulverizador','Ataque con martillo. Si alcanzas a un enemigo derribado, sufrirá debilitamiento y una herida grave durante 5...20 segundos.','Ataque con martillo. Causa debilitamiento y herida grave (5...20 segundos) si el enemigo objetivo está derribado.'],
2009=>['Hachazo vivaz','Ataque con hacha. Si impacta, este ataque es siempre un golpe crítico.','Ataque con hacha. Siempre golpe crítico.'],
2010=>['Cortarodillas','Ataque con espada. Si este ataque impacta a un enemigo lisiado, ganas 2...7 de energía y 1...3 golpes de adrenalina.','Ataque con espada. Ganas 2...7 de energía y 1...3 de adrenalina si el enemigo objetivo está lisiado.'],
2011=>['Pulso','Habilidad. Tú y el enemigo al que toques sois derribados. Pierdes la actitud que tengas en este momento.','Habilidad de toque. Causa derribo. También eres derribado. La actitud que tengas acaba.'],
2012=>['Guadaña radiante','Ataque con guadaña. Este ataque hace +1 de daño por cada punto de energía que tengas (máximo 5...30 de daño). Ganas 1...7 de energía si el ataque impacta.','Ataque con guadaña. Hace +1 de daño (máximo 5...30) por cada punto de energía que tengas. Ganas 1...7 de energía.'],
2013=>['Aura de Grenth','Conjuro con encantamiento de destello. Durante 20 segundos, haces 5...25 menos de daño y robas 5...25 de salud cada vez que atacas con guadaña. Cuando lanzas este encantamiento, robas 5...25 de salud a todos los enemigos adyacentes.','Conjuro con encantamiento de destello. (20 segundos). Haces 5...25 menos de daño y robas 5...25 de salud cuando atacas con guadaña. Efecto inicial: robas 5...25 de salud a todos los enemigos adyacentes.'],
2014=>['Sello de retención piadosa','Sello. Quita un encantamiento de Derviche. El enemigo objetivo se queda lisiado durante 5...15 segundos. Si se quitó un encantamiento, todos los enemigos de la zona del objetivo también quedan lisiados y este sello se recarga un 75 % más rápido.','Sello. Causa lisiadura (5...15 segundos). Elimina uno de tus encantamientos de Derviche. Efecto de eliminación: también causa lisiadura a los enemigos de la zona de tu objetivo y se recarga un 75 % más rápido.'],
2015=>['Guadaña de granjero','Ataque con guadaña. Si impacta, este ataque hará +5...20 de daño. Si alcanzas a más de un enemigo, se recargará de forma instantánea.','Ataque con guadaña. Hace +5...20 de daño. Se recarga al instante si alcanzas a más de un enemigo.'],
2016=>['Vigoroso sea Lee Sa','Conjuro con objeto. Llevas las cenizas de Lee Sa durante 5...15 segundos. Mientras, ganarás +2 de regeneración de energía. Cuando las sueltes, ganarás +1...10 de energía.','Conjuro con objeto. (5...15 segundos). Tienes +2 de regeneración de energía. Efecto al soltarse: ganas +1...10 de energía.'],
2017=>['Himno de debilidad','Cántico. Durante 8 segundos, la siguiente habilidad de ataque que usen los aliados al alcance del oído causa también debilitamiento durante 1...16 segundos.','Cántico. (8 segundos). Los aliados al alcance del oído causan debilitamiento (1...16 segundos) con su próxima habilidad de ataque.'],
2018=>['Himno de interrupción','Cántico. Durante 1...10 segundos, la siguiente habilidad de ataque que usen los aliados al alcance del oído interrumpe también.','Cántico. (1...10 segundos). Los aliados al alcance del oído interrumpen una acción con su siguiente habilidad de ataque.'],
2051=>['Invocar espíritus','Conjuro. Todos los espíritus que controles dan un paso sombrío hasta tu ubicación y ganan 60...100 de salud.','Conjuro. Los espíritus que controles dan un paso sombrío hasta tu ubicación y ganan 60...100 de salud.'],
2052=>['Colmillo sombrío','Conjuro con maleficio. Das un paso sombrío hasta el enemigo objetivo. Durante 10 segundos, este maleficio no hace nada. Cuando acabe, volverás a tu ubicación original y el enemigo sufrirá una herida grave durante 5...20 segundos.','Conjuro con maleficio. Das un paso sombrío hasta el enemigo objetivo. Efecto final tras 10 segundos: causa herida grave (5...20 segundos); vuelves a tu ubicación original.'],
2053=>['Riesgo calculado','Conjuro con maleficio. Durante 3...24 segundos, los ataques del enemigo objetivo hacen +10 de daño, pero hay un 50% de posibilidades de que dicho enemigo reciba el daño realizado con cada ataque. (Máximo 15...100 de daño.)','Conjuro con maleficio. (3...24 segundos). Los ataques del enemigo objetivo hacen +10 de daño. Cada ataque tiene 50% de posibilidades de que el enemigo reciba el daño realizado con cada ataque (máximo 15...100).'],
2054=>['Armadura encogida','Conjuro con maleficio. Durante 10 segundos, el enemigo objetivo sufre -1...4 de degeneración de salud. Cuando este maleficio termine, tendrá la armadura rota durante 5...20 segundos.','Conjuro con maleficio. (10 segundos). Causa -1...4 de degeneración de salud. Efecto final: causa armadura rota (5...20 segundos).'],
2055=>['Aneurisma','Conjuro. El enemigo objetivo recupera toda la energía. Por cada punto de energía que recupere, el enemigo recibe 1...3 de daño y los enemigos adyacentes a él pierden 1 de energía. (Máximo 1...30 de energía perdida).','Conjuro. El enemigo objetivo recupera toda la energía. Por cada punto de energía que recupere, el objetivo recibe 1...3 de daño y todos los enemigos adyacentes pierden 1 de energía (máximo 1...30).'],
2056=>['Ojo errante','Conjuro con maleficio. Durante 4 segundos, la próxima vez que el enemigo objetivo ataque, le interrumpirás y todos los enemigos cercanos recibirán 30...110 de daño.','Conjuro con maleficio. (4 segundos). Interrumpe el siguiente ataque del enemigo objetivo. Efecto: 30...110 de daño a los enemigos cercanos.'],
2057=>['Festín corrupto','Conjuro. Todas las condiciones se transfieren del aliado objetivo a ti mismo. Por cada condición adquirida de esta manera, ganas 0...45 de salud y 2...4 de energía. Esta habilidad se recarga dos veces más rápido si quitas la enfermedad de tu objetivo.','Conjuro. Recibes todas las condiciones que tenga el aliado objetivo. Ganas 0...45 de salud y 2...4 de energía por cada condición que recibes. La mitad de la recarga si quitas la enfermedad. Tú mismo no puedes ser el objetivo.'],
2058=>['Bilis putrefacta','Conjuro con maleficio. Durante 5...25 segundos, el enemigo objetivo sufre -1...3 de degeneración de salud. Si muere mientras estaba bajo los efectos de este maleficio, los enemigos cercanos recibirán 25...85 de daño.','Conjuro con maleficio. (5...25 segundos). Causa -1...3 de degeneración de salud. Hace 25...85 de daño a todos los enemigos cercanos si el objetivo muere.'],
2059=>['Descarga de caparazón','Conjuro. El enemigo objetivo recibe 10...30 de daño de relámpago y tiene la armadura rota durante 5...20 segundos. Este conjuro tiene un 25% de penetración de armadura. Si estás sobrelanzando, este conjuro golpea a los enemigos adyacentes.','Conjuro. Causa 10...30 de daño de relámpago. Causa armadura rota (5...20 segundos). 25% de penetración de armadura. Si estás sobrelanzando, golpea a los adyacentes.'],
2060=>['Glifo de inmolación','Glifo. Durante 15 segundos, tus siguientes conjuros lanzados contra un enemigo (1...4) también causan quemadura durante 1...4 segundos.','Glifo. (15 segundos). Tus siguientes 1...4 conjuro["conjuros"] lanzados contra enemigos también causan quemadura (1...4 segundos).'],
2061=>['Espíritu paciente','Conjuro con encantamiento. Durante 2 segundos, el aliado objetivo queda encantado con Espíritu paciente. A menos que el encantamiento termine antes de tiempo, el aliado recibe 30...120 de salud como efecto final.','Conjuro con encantamiento. (2 segundos). Efecto final: cura 30...120 de salud. Ningún efecto si termina antes de tiempo.'],
2062=>['Cinta curadora','Conjuro. Curas al aliado objetivo 20...110 de salud. Hasta 2 aliados adicionales cercanos al objetivo se curan 10...100 de salud.','Conjuro. Cura 20...110 de salud. Cura 10...100 de salud a dos aliados cercanos al aliado objetivo. No te puedes apuntar a ti mismo.'],
2063=>['Aura de estabilidad','Conjuro con encantamiento. Durante 3...8 segundos, no podrán derribar al aliado objetivo.','Conjuro con encantamiento. (3...8 segundos). No pueden derribar al aliado objetivo. No te puedes apuntar a ti mismo.'],
2064=>['Mente pura','Conjuro con encantamiento. Durante 1...15 segundos, el aliado objetivo pierde un maleficio cada 5 segundos.','Conjuro con encantamiento. (1...15 segundos). Elimina un maleficio cada 5 segundos. No te puedes apuntar a ti mismo.'],
2065=>['Alma pura','Conjuro con encantamiento. Durante 1...15 segundos, el aliado objetivo pierde una condición cada 3 segundos.','Conjuro con encantamiento. (1...15 segundos). Elimina una condición cada 3 segundos. No te puedes apuntar a ti mismo.'],
2066=>['Desarme','Ataque con espada. Interrumpes la acción del enemigo. Si éste estaba atacando, todas sus habilidades de ataque estarán desactivadas durante 0...3 segundos.','Ataque con espada. Interrumpe al enemigo objetivo. Efecto de la interrupción: desactiva la habilidad del enemigo (0...3 segundos) si era de ataque.'],
2067=>['"¡Quería hacerlo!"','Grito. Si te derriban, ganas 1...6 golpes de adrenalina.','Grito. Ganas 1...6 golpes de adrenalina si te derriban.'],
2068=>['Fuego rápido','Preparación["Preparaciones"]. Durante 5...25 segundos, atacas un 33% más rápido con el arco.','Preparación["Preparaciones"]. (5...25 segundos). Atacas un 33% más rápido con el arco.'],
2069=>['Disparo del cazador perezoso','Ataque con arco. Si este ataque impacta, el enemigo objetivo recibe +10...25 de daño. Si no estaba usando ninguna habilidad, este disparo hará +10...35 de daño extra.','Ataque con arco. Hace +10...25 de daño. +10...35 de daño extra si el enemigo objetivo no está usando ninguna habilidad.'],
2070=>['Rebanador de auras','Ataque cuerpo a cuerpo. Si este ataque impacta, causarás hemorragia durante 5...15 segundos. Si estás encantado, también causas armadura rota durante 1...10 segundos.','Ataque cuerpo a cuerpo. Causa hemorragia (5...15 segundos). También causa armadura rota (1...10 segundos) si estás encantado.'],
2071=>['Barrido celoso','Ataque con guadaña. Si impacta, este ataque hace +5...20 de daño. Ganas 3 de energía y 1 de adrenalina por cada enemigo que golpees.','Ataque con guadaña. Hace +5...20 de daño. Ganas 3 de energía y 1 de adrenalina por cada enemigo que golpees.'],
2072=>['Puro sea Li Ming','Conjuro con objeto. Llevas las cenizas de Li Ming durante 5...20 segundos. Mientras, las condiciones que sufras se quitarán un 10...50% antes. Cuando las sueltes, todos los aliados al alcance del oído perderán 1...4 condición["condiciones"].','Conjuro con objeto. (5...20 segundos). Las condiciones que tengas acaban un 10...50% más rápido. Efecto al soltarse: elimina 1...4 condiciones de los aliados al alcance del oído.'],
2073=>['Arma de agresión','Conjuro con arma. Durante 5...15 segundos, atacas un 25% más rápido.','Conjuro con arma. (5...15 segundos). Atacas un 25% más rápido.'],
2074=>['Aplastador de pectorales','Ataque con lanza. Si este ataque impacta a un enemigo con la armadura rota, sufrirá una herida grave durante 5...20 segundos.','Ataque con lanza. Causa herida grave (5...20 segundos) si el enemigo objetivo tiene la armadura rota.'],
2075=>['Estribillo apresurado','Eco. Durante 8...20 segundos, el objetivo (un aliado o tú mismo) se mueve un 25% más deprisa. Este eco se reactivará cada vez que los efectos de un grito o cántico terminen en él.','Eco. (8...20 segundos). El objetivo (un aliado o tú mismo) se mueve un 25% más deprisa. Renovación: cada vez que los efectos de un grito o cántico terminen en él.'],
2091=>['Santuario sombrío','Conjuro con encantamiento. Quedas cegado durante 5 segundos. Además, durante 10 segundos, ganas +7...10 de regeneración de salud y +40 de armadura.','Conjuro con encantamiento. (10 segundos). Ganas +7...10 de regeneración de salud y +40 de armadura. Sufres ceguera (5 segundos).'],
2092=>['Pesadilla de éter','Conjuro con maleficio. El enemigo objetivo pierde 5...8 de energía. Por cada punto de energía que pierda así, ese enemigo y todos los que estén en la zona sufrirán una degeneración de salud de -1 durante 10 segundos.','Conjuro con maleficio. Hace perder 5...8 de energía. El enemigo objetivo y los de la zona tienen -1 de degeneración de salud por cada punto de energía perdido (10 segundos).'],
2093=>['Sello de corrupción','Sello. Haces 20...30 de daño al enemigo objetivo y todos los cercanos. Por cada enemigo que tenga una condición o maleficio, ganas 2 de energía (máximo 12...20 de energía).','Sello. Hace 20...30 de daño al enemigo objetivo y los cercanos. Ganas 2 de energía (máximo 12...20) por cada uno de esos enemigos que tenga una condición o maleficio.'],
2094=>['Señor elemental','Conjuro con encantamiento. Durante 40...60 segundos, tus atributos de los elementos aumentan en 1 punto. Cada vez que lances un conjuro, ganas 1 de energía por cada 10 rangos de almacenamiento de energía y además te curas el 100...300% del coste de energía del conjuro.','Conjuro con encantamiento. (40...60 segundos). Tus atributos de los elementos aumentan en 1. Cada vez que lances un conjuro, ganas 1 de energía por cada 10 rangos de almacenamiento de energía y además te curas el 100...300% del coste de energía del conjuro.'],
2095=>['Espíritu caritativo','Conjuro con encantamiento. Durante 15...20 segundos, los conjuros cuyo objetivo sea otro aliado te costarán 3 menos de energía.','Conjuro con encantamiento. (15...20 segundos.) Los conjuros que tengan como objetivo otro aliado te costarán 3 menos de energía.'],
2096=>['Disparo triple','Ataque con arco. Disparas 3 flechas simultáneamente al enemigo objetivo. Estas flechas hacen un 40...25% menos de daño.','Ataque con arco. Disparas 3 flechas simultáneamente al enemigo objetivo. Estas flechas hacen un 40...25% menos de daño.'],
2097=>['"¡Poneos a salvo!"','Grito. Durante 4...6 segundos, los demás compañeros de equipo ganan +100 de armadura.','Grito. (4...6 segundos). Los demás miembros del grupo ganan +100 de armadura.'],
2098=>['Aura del poder divino','Conjuro con encantamiento. Durante (45 segundos), haces 20...25 de daño sagrado a todos los enemigos adyacentes cuando pierdes un encantamiento de Derviche.','Conjuro con encantamiento. (45 segundos). Cuando pierdes un encantamiento de Derviche, los enemigos adyacentes reciben 20...25 de daño sagrado.'],
2099=>['Lanza de furia','Ataque con lanza. Este ataque hace +30...40 de daño. Si impacta a un enemigo padeciendo alguna condición, ganarás 3...6 de adrenalina.','Ataque con lanza. Hace +30...40 de daño. Ganas 3...6 golpes de adrenalina si golpeas a algún enemigo con condición.'],
2100=>['Invocar espíritus','Conjuro. Todos los espíritus que controles dan un paso sombrío hasta tu ubicación y ganan 60...100 de salud.','Conjuro. Los espíritus que controles dan un paso sombrío hasta tu ubicación y ganan 60...100 de salud.'],
2101=>['Agilidad crítica','Conjuro con encantamiento. Durante 4 segundos y 1 segundo extra por cada nivel de golpes críticos que tengas, atacas un 33% más deprisa y tienes +15...25 de armadura. Esta habilidad se reactivará cada vez que hagas un golpe crítico.','Conjuro con encantamiento. (4 segundos y 1 segundo extra por cada nivel de golpes críticos que tengas). Atacas un 33% más deprisa y ganas +15...25 de armadura. Renovación: cada vez que hagas un golpe crítico.'],
2102=>['Grito de dolor','Conjuro. Interrumpes la habilidad del enemigo objetivo. Si éste ya padecía un maleficio de Hipnotizador, dicho enemigo y todos los enemigos de la zona recibirán 25...50 de daño y sufrirán 3...5 de degeneración de salud durante 10 segundos.','Conjuro. Interrumpe una habilidad. Si el enemigo objetivo ya padecía otro maleficio de Hipnotizador, recibe 25...50 de daño y los enemigos de la zona sufren -3...5 de degeneración de salud (10 segundos).'],
2103=>['Necrosis','Habilidad. Si el enemigo objetivo está sufriendo una condición o maleficio, le harás 60...90 de daño.','Habilidad. Hace 60...90 de daño si el enemigo objetivo tiene una condición o maleficio.'],
2104=>['Intensidad','Habilidad. Durante 10 segundos, la próxima vez que causes daño elemental con un conjuro a un objetivo, todos los demás enemigos de la zona recibirán un 60...70% de ese daño.','Habilidad. (10 segundos.) La próxima vez que causes daño elemental con un conjuro, los demás objetivos de la zona recibirán un 60...70% de ese daño.'],
2105=>['Semilla de vida','Conjuro con encantamiento. Durante 2...5 segundos, cada vez que el aliado objetivo recibe daño, todos los miembros del grupo recuperan 2 de salud por cada nivel de favor divino.','Conjuro con encantamiento. (2...5 segundos.) Los miembros del grupo recuperan 2 de salud por cada nivel de favor divino cada vez que el aliado reciba daño. No puedes apuntarte a ti mismo como objetivo.'],
2107=>['Ataque en torbellino','Ataque cuerpo a cuerpo. Atacas al enemigo objetivo y a los adyacentes. Cada ataque hace +13...20 de daño.','Ataque cuerpo a cuerpo. Hace +13...20 de daño al enemigo objetivo y los adyacentes.'],
2108=>['Nunca embistes solo','Habilidad. Durante 18...25 segundos, tú y tu mascota atacáis un 25% más deprisa y tenéis +1...3 de regeneración de salud.','Habilidad. (18...25 segundos). Tú y tu mascota atacáis un 25% más deprisa y tenéis +1...3 de regeneración de salud.'],
2109=>['Aura eterna','Conjuro con encantamiento. Tienes +100 de salud máxima. Cuando termine este encantamiento, todos los miembros del grupo que estén en el área resucitarán con 40...50% de salud y 20...30% de energía.','Conjuro con encantamiento. Tienes +100 de salud máxima. Efecto final: todos los miembros del grupo que estén en el área resucitarán con 40...50% de salud y 20...30% de energía.'],
2110=>['Vampirismo','Ritual con espíritus. Creas un espíritu de nivel 4...14 que morirá a los 75...150 segundos. Los ataques de este espíritu roban 10...20 de salud y tú te curas 10...20.','Ritual con espíritus. Crea un espíritu de nivel 4...14 (75...150 segundos de vida). Sus ataques roban 10...20 de salud y tú te curas 10...20.'],
2112=>['"¡No hay nada que temer!"','Grito. Durante 4 segundos más 1 segundo extra por cada 2 niveles de liderazgo que tengas, todos los miembros del grupo al alcance del oído reciben un 20...35% menos de daño. Cuando este grito acabe, los miembros del grupo afectados se curarán 35...60 de salud.','Grito. (4 segundos y 1 segundo extra por cada 2 niveles de liderazgo que tengas). Reduce un 20...35% el daño que reciban los miembros del grupo al alcance del oído. Efecto final: cura 35...60 de salud.'],
2116=>['Ataque escurridizo','Ataque cuerpo a cuerpo. Si este ataque impacta, el enemigo objetivo queda cegado durante 5...8 segundos. Este ataque cuenta como un ataque inicial.','Ataque cuerpo a cuerpo. Causa ceguera (5...8 segundos). Cuenta como un ataque inicial.'],
2135=>['Buey pisoteador','Ataque doble. Debe ir precedido de un ataque complementario. Si impacta, harás +5...20 de daño. Si alcanzas a un enemigo lisiado, le derribirás.','Ataque doble. Hace +5...20 de daño. Causa derribo si el enemigo objetivo está lisiado. Debe ir precedido de un ataque complementario.'],
2136=>['Polvo de humo defensivo','Actitud. Durante 8 segundos, la próxima vez que te golpeen, recibes la mitad del daño y todos los enemigos cercanos quedan cegados durante 2...6 segundos.','Actitud. (8 segundos.) La próxima vez que te alcance un ataque, recibes la mitad de daño y causas ceguera (2...6 segundos) en los enemigos cercanos.'],
2137=>['Imagenes confusas','Conjuro con maleficio. Durante 2...10 segundos, el enemigo objetivo tarda el doble en activar habilidades que no sean de ataque.','Conjuro con maleficio. (2...10 segundos.) El enemigo objetivo tarda el doble en activar habilidades que no sean de ataque.'],
2138=>['Vigor del hechicero','Conjuro con encantamiento. Durante 10 segundos, tienes +1...8 de regeneración de salud. Vigor del hechicero acaba si utilizas una habilidad que no sea un maleficio.','Conjuro con encantamiento. (10 segundos.) Tienes +1...8 de regeneración de salud. Termina si utilizas una habilidad que no sea un maleficio.'],
2139=>['Masoquismo','Conjuro con encantamiento. Durante 10...40 segundos, los atributos magia de muerte y cosecha de almas aumentan en +2, y se sacrifica un 5...3% del nivel de salud máximo al lanzar un conjuro.','Conjuro con encantamiento. (10...40 segundos.) Magia de muerte y cosecha de almas aumentan en +2. Sacrificas un 5...3% del nivel de salud máximo al lanzar un conjuro.'],
2140=>['Trampa perforante','Trampa. Cuando se activa la trampa perforante, todos los enemigos cercanos reciben 5...50 de daño perforante. Los que tengan la armadura rota, reciben 15...60 de daño adicional. La trampa perforante dura 90 segundos. Es muy fácil interrumpirte mientras activas esta habilidad.','Trampa. (90 segundos). Afecta a los enemigos cercanos. Hace 5...50 de daño perforante. 15...60 de daño extra a los enemigos con la armadura rota. Se puede interrumpir con facilidad.'],
2141=>['Camaradería','Habilidad. Si tienes menos salud que tu mascota, te curas 30...120 de salud. Si la mascota tiene menos que tú, se cura 30...120 de salud.','Habilidad. Te curas 30...120 de salud si tienes menos que tu mascota. Cura 30...120 de salud a la mascota si tiene menos que tú.'],
2142=>['Agresión salvaje','Habilidad. Durante 5...20 segundos, tu mascota ataca un 33% más deprisa y hace 3...10 más de daño.','Habilidad. (5...20 segundos). Tu mascota ataca un 33% más deprisa y hace +3...10 de daño.'],
2143=>['Disparo interruptor','Ataque con arco. Si este ataque impacta, interrumpes la acción del enemigo. Si era una habilidad, haces +10...40 de daño.','Ataque con arco. Interrumpe una acción. Efecto de la interrupción: +10...40 de daño si interrumpes una habilidad.'],
2144=>['Embestida de flechas','Ataque con arco. Se eliminan todas tus preparaciones. Disparas flechas al enemigo objetivo y a un máximo de 3 enemigos adyacentes a él, que harán +1...10 de daño si impactan.','Ataque con arco. Hace +1...10 de daño. Alcanza a un máximo de 3 enemigos adyacentes a tu objetivo. Se eliminan todas tus preparaciones.'],
2145=>['Foco de experto','Preparación["Preparaciones"]. Durante 24 segundos, tus habilidades de ataque con arco consumen 1...2 menos de energía y hacen 1...10 de daño extra.','Preparación["Preparaciones"]. (24 segundos.) Tus habilidades de ataque con arco cuestan 1...2 menos de energía y hacen +1...10 de daño.'],
2146=>['Furia piadosa','Actitud. Quita un encantamiento de Derviche. Durante 1...7 segundos, atacas un 25% más rápido. Si se quitó un encantamiento, esta actitud dura el doble de tiempo.','Actitud. (1...7 segundos)Atacas un 25% más rápido y pierdes uno de tus encantamientos de Derviche. Efecto de eliminación: esta actitud dura el doble de tiempo.'],
2147=>['Victoria lisiadora','Ataque con guadaña. Si este ataque impacta en un enemigo, éste quedará lisiado durante 3...8 segundos. Si tienes más salud que el enemigo objetivo, todos los enemigos adyacentes recibirán 10...30 de daño de tierra.','Ataque con guadaña. (3...8 segundos). Causa lisiadura en el enemigo objetivo. Si tienes más salud que el enemigo objetivo, todos los enemigos adyacentes recibirán 10...30 de daño de tierra.'],
2148=>['Arma incisiva','Conjuro con arma. Durante 4...10 segundos, los siguientes 3 ataques del objetivo (un aliado o tú mismo) tienen un 10% de penetración de armadura y causan armadura rota durante 5...20 segundos.','Conjuro con arma. (4...10 segundos). Los siguientes 3 ataques del objetivo (un aliado o tú mismo) causan armadura rota (5...20 segundos) y tienen un 10% de penetración de armadura.'],
2149=>['Arma de renovación','Conjuro con arma. Durante 5...20 segundos, la próxima vez que el objetivo (un aliado o tú mismo) golpee con una habilidad de ataque, recuperará 1...7 de energía.','Conjuro con arma. (5...20 segundos). El objetivo (un aliado o tú mismo) gana 1...7 de energía la próxima vez que golpee con una habilidad de ataque.'],
2150=>['Lanza mutiladora','Ataque con lanza. Si este ataque impacta a un enemigo con hemorragia, quedará lisiado durante 5...20 segundos.','Ataque con lanza. Causa lisiadura (5...20 segundos) si el enemigo sufre hemorragia.'],
2186=>['Sello de corrupcion mortal','Sello. El enemigo objetivo recibe 5...35 de daño por cada condición que tenga (daño máximo: 130).','Sello. Causa +5...35 de daño (máximo 130) por cada condición que tenga el enemigo objetivo.'],
2187=>['Camino del maestro','Conjuro con encantamiento. Durante 60 segundos, si llevas un arma que no sea una daga, tienes un 3...33% de probabilidades extra de dar un golpe crítico.','Conjuro con encantamiento. (60 segundos). Si llevas un arma que no sea una daga, tienes +3...33% de probabilidades de dar un golpe crítico.'],
2188=>['Profanar defensas','Conjuro con maleficio. Durante 5...20 segundos, la próxima vez que el enemigo objetivo bloquee un ataque, recibirá 30...120 de daño.','Conjuro con maleficio. (5...20 segundos). Hace 30...120 de daño la próxima vez que el enemigo objetivo bloquee un ataque.'],
2189=>['Mirada de Angorodon','Conjuro. Robas 10...50 de salud del enemigo objetivo. Si estás sufriendo alguna condición, ganas 3...12 de energía.','Conjuro. Roba 10...50 de salud. Ganas 3...12 de energía si tienes una condición.'],
2190=>['Aumento magnético','Conjuro con encantamiento. El enemigo objetivo recibe 15...75 de daño. Si estás sobrelanzando, Aumento magnético encanta a todos los aliados al alcance del oído durante 1...5 segundos para que bloqueen el siguiente ataque dirigido a ellos.','Conjuro con encantamiento. Causa 15...75 de daño. Si estás sobrelanzando, los aliados al alcance del oído quedan encantados durante 1...5 y bloquean el siguiente ataque dirigido a ellos.'],
2191=>['Suelo resbaladizo','Conjuro. Si el objetivo y los enemigos adyacentes están cegados o en movimiento, son derribados. Hay un 50% de probabilidad de fallo con magia de agua de nivel 5 o inferior.','Conjuro. Si el enemigo está cegado o moviéndose, es derribado. Afecta a los enemigos adyacentes a tu objetivo. 50% de probabilidad de fallo a menos que se tenga magia de agua por encima del nivel 4.'],
2192=>['Hielo brillante','Conjuro. El enemigo objetivo recibe 5...50 de daño frío. Si ese enemigo está bajo los efectos de un maleficio de magia de agua, ganas 5 de energía más 1 de energía por cada 2 rangos de almacenamiento de energía.','Conjuro. Hace 5...50 de daño frío. Ganas 5 de energía más 1 de energía por cada 2 rangos de almacenamiento de energía si el enemigo objetivo está bajo los efectos de un maleficio de magia de agua.'],
2193=>['Explosión de energía','Conjuro. Haces 1...2 de daño al enemigo objetivo por cada punto de energía que tengas (máximo 130 de daño).','Conjuro. Hace 1...2 de daño (máximo 130) por cada punto de energía que tengas.'],
2194=>['Ataque de distracción','Ataque cuerpo a cuerpo. Si el Ataque de distracción impacta, no hace ningún daño e interrumpe la acción del enemigo objetivo. Si éste tenía la armadura rota, la habilidad quedará desactivada durante 30 segundos.','Ataque cuerpo a cuerpo. Interrumpe una acción. Efecto de interrupción: Desactiva la habilidad interrumpida (30 segundos) si el enemigo objetivo tiene la armadura rota. No hace daño.'],
2195=>['Ataque simbólico','Ataque cuerpo a cuerpo. Si este ataque impacta, harás +12 de daño por cada sello que lleves equipado (máximo 70 de daño adicional).','Ataque cuerpo a cuerpo. Hace +12 de daño (máximo 70) por cada sello que tengas equipado.'],
2196=>['Velocidad de soldado','Actitud. Te mueves un 15% más rápido durante 3...18 segundos. Te mueves un 15% extra más deprisa si estás bajo los efectos de un grito o cántico.','Actitud. (3...18 segundos). Te mueves un 15% más deprisa, y un 15% extra más deprisa si estás bajo los efectos de un grito o cántico.'],
2197=>['Golpe corporal','Ataque cuerpo a cuerpo. Si este ataque impacta, haces +10...40 de daño al enemigo objetivo. Si tiene la armadura rota, sufrirá una herida grave durante 0...15 segundos.','Ataque cuerpo a cuerpo. Hace +10...40 de daño. Causa herida grave (0...15 segundos) si el enemigo objetivo tiene la armadura rota.'],
2198=>['Disparo corporal','Ataque con arco. Si este ataque impacta, harás +5...20 de daño. Si alcanza a un enemigo con la armadura rota, ganarás 5...10 de energía.','Ataque con arco. Hace +5...20 de daño. Ganas 5...10 de energía si el enemigo objetivo tiene la armadura rota.'],
2199=>['Sello de punta venenosa','Sello. Durante 60 segundos, tu siguiente ataque también causa envenenamiento durante 8...15 segundos.','Sello. (60 segundos). Causa envenenamiento (8...15 segundos) con tu siguiente ataque.'],
2200=>['Sello de velocidad mística','Sello. Durante 30 segundos, los próximos 1...3 encantamientos que apunten a ti mismo se lanzan instantáneamente. Los encantamientos de destello no consumen usos de esta habilidad.','Sello. (30 segundos). Los próximos 1...3 encantamientos que apunten a ti mismo se lanzan instantáneamente. Los encantamientos de destello no consumen usos de esta habilidad.'],
2201=>['Escudo de fuerza','Conjuro con encantamiento de destello. Durante 1...16 segundos, se bloquearán los próximos 1 ataques que recibas. Si se bloquea un ataque, todos los enemigos adyacentes que atacan quedan derribados y sufren debilitamiento durante 5...20 segundos.','Conjuro con encantamiento de destello. (1...16 segundos). Bloquea los próximos 1 ataques que recibas. Derriba a los enemigos adyacentes que atacan y les causa lisiadura (5...20 segundos).'],
2202=>['Agarre sanador','Conjuro. Curas 30...90 de salud al objetivo (un aliado o tú mismo). Si el objetivo está bajo los efectos de un conjuro para arma, perderá una condición.','Conjuro. Cura 30...90 de salud. Elimina una condición si el objetivo (un aliado o tú mismo) tiene un conjuro con arma.'],
2203=>['Aura de la sanguijuela espiritual','Habilidad. Durante 5...20 segundos, todos tus espíritus al alcance del oído hacen 5...20 menos de daño y roban 5...20 de salud cuando atacan.','Habilidad. (5...20 segundos.) Todos tus espíritus al alcance del oído hacen 5...20 menos de daño y roban 5...20 de salud cuando atacan.'],
2204=>['Rejuvenecimiento','Ritual con espíritus. Creas un espíritu de nivel 1...20 que cura 3...10 de salud por segundo a todos los miembros del equipo al alcance del oído. El espíritu perderá 3...10 de salud por cada uno que cure. Morirá a los 30...90 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...20 (30...90 segundos de vida). Cura 3...10 de salud a los miembros del grupo al alcance del oído. Coste por curación: el espíritu pierde 3...10 de salud.'],
2205=>['Agonía','Ritual con espíritus. Creas un espíritu de nivel 1...12 que hace perder 3...10 de salud por segundo a los enemigos al alcance del oído. El espíritu perderá 3...10 de salud por cada enemigo dañado. Morirá a los 30...90 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...12 (30...90 segundos de vida). Hace perder 3...10 de salud por segundo a los enemigos al alcance del oído. El espíritu pierde 3...10 de salud por cada enemigo que pierda salud.'],
2206=>['Arma fantasmal','Conjuro con arma. Durante 5...20 segundos, el siguiente ataque del aliado objetivo no puede bloquearse.','Conjuro con arma. (5...20 segundos). No se puede bloquear el siguiente ataque del aliado objetivo. No te puedes apuntar a ti mismo.'],
2207=>['Discurso inspirador','Habilidad. Pierdes toda la adrenalina y el aliado objetivo gana 1...8 de adrenalina.','Habilidad. El aliado objetivo gana 1...8 de adrenalina. No te puedes apuntar a ti mismo. Pierdes toda la adrenalina.'],
2208=>['Escudo ardiente','Habilidad. Durante 3...9 segundos, mientras estés llevando un escudo, la siguiente habilidad de ataque contra ti será bloqueada. Si era un ataque cuerpo a cuerpo, el atacante arderá durante 1...6 segundos.','Habilidad. (3...9 segundos). Bloquea la siguiente habilidad de ataque contra ti. Causa quemadura (1...6 segundos) si era un ataque cuerpo a cuerpo. No funciona si no llevas un escudo.'],
2209=>['Lanza sagrada','Ataque con lanza. Si este ataque impacta, harás +5...20 de daño. Si impacta a una criatura invocada, todos los enemigos cercanos recibirán 15...90 de daño sagrado y arderán durante 3 segundos.','Ataque con lanza. Hace +5...20 de daño. 15...90 de daño sagrado y causa quemadura (3 segundos) a los enemigos cercanos si alcanzas a una criatura invocada.'],
2210=>['Barrido de lanza','Ataque con lanza. Si este ataque impacta, harás +5...20 de daño y el enemigo objetivo quedará aturdido durante 4...10 segundos. Este ataque tiene alcance cuerpo a cuerpo.','Ataque cuerpo a cuerpo con lanza. Hace +5...20 de daño y causa aturdimiento (4...10 segundos). Este ataque tiene alcance cuerpo a cuerpo.'],
2211=>['Ácido alquímico de Alkar','Conjuro. Lanzas el ácido alquímico de Alkar al enemigo objetivo. Éste y los enemigos adyacentes reciben 40...50 de daño. Los Destructores reciben 45...70 de daño extra y tienen la armadura rota durante 14...20 segundos.','Conjuro. Proyectil: hace 40...50 de daño al enemigo objetivo y los adyacentes. Hace 45...70 de daño extra y causa armadura rota (14...20 segundos) a los Destructores.'],
2212=>['Luz de Deldrimor','Conjuro. Todos los enemigos de la zona reciben 55...80 de daño sagrado. Además, ves en tu brújula por un momento todos los objetos ocultos.','Conjuro. Hace 55...80 de daño sagrado a los enemigos de la zona. Desvela en la brújula los objetos ocultos de la zona.'],
2213=>['Mordedura de oreja','Habilidad. El objetivo al que toques recibe 50...70 de daño perforante y sufre hemorragia durante 15...25 segundos.','Habilidad de toque. Hace 50...70 de daño perforante y causa hemorragia (15...25 segundos).'],
2214=>['Golpe bajo','Habilidad. Golpeas al enemigo objetivo con 45...70 de daño. Si el enemigo está derribado, recibirá 30...50 de daño adicional y tendrá la armadura rota durante 14...20 segundos.','Habilidad de toque. Hace 45...70 de daño. Hace 30...50 más de daño y rompe la armadura (durante 14...20 segundos) si el enemigo objetivo está derribado.'],
2215=>['Cabezazo de camorrista','Habilidad. Das un cabezazo al enemigo objetivo tocado, que hace 45...70 de daño y causa derribo si impacta.','Habilidad de toque. Hace 45...70 de daño. Causa derribo.'],
2216=>['"¡No tropecéis!"','Grito. Durante 3...5 segundos, no podrán derribar a los miembros del grupo al alcance del oído.','Grito. (3...5 segundos). Impide derribos; afecta a los miembros del grupo al alcance del oído.'],
2217=>['"¡Por el martillo de Ural!"','Grito. Durante 30 segundos, todos los miembros del grupo muertos que estén al alcance del oído resucitan con toda la salud y toda la energía. Los miembros del grupo resucitados hacen 25...33% de daño adicional. Cuando este efecto termina, los miembros del grupo afectados mueren. Esta habilidad no causa penalización por resucitar.','Grito. (30 segundos). Resucita a todos los miembros del grupo muertos al alcance del oído con toda la salud y toda la energía. Los miembros del grupo afectados hacen 25...33% de daño adicional. Los miembros del grupo afectados mueren cuando termina el efecto, pero no reciben penalización por resucitar.'],
2218=>['Maestro borracho','Actitud. Durante 72...90 segundos, te mueves y atacas un 10...15% más deprisa. Si estás borracho mientras activas esta habilidad, te moverás y atacarás un 25...33% más deprisa.','Actitud. (72...90 segundos). Te mueves y atacas un 10...15% más rápido si no estás borracho. Te mueves y atacas un 25...33% más rápido si lo estás.'],
2219=>['Arma del Gran Enano','Conjuro con arma. Durante 20 segundos, el arma del aliado objetivo hace +15...20 de daño y tiene 28...40% de posibilidades de causar derribos.','Conjuro con arma. (20 segundos). +15...20 de daño con el arma y 28...40% de probabilidades de causar derribo al atacar. No te puedes apuntar a ti mismo.'],
2220=>['Armadura del Gran Enano','Conjuro con encantamiento. Durante 22...40 segundos, el objetivo (un aliado o tú mismo) tiene +24 de armadura, +60 de salud máxima y +24 de armadura extra contra Destructores.','Conjuro con encantamiento. (22...40 segundos). +24 de armadura y +60 de salud máxima. +24 de armadura extra contra Destructores.'],
2221=>['Aliento del Gran Enano','Conjuro. Todos los miembros del grupo se quitan la quemadura y se curan 50...60 de salud.','Conjuro. Elimina la quemadura y cura 50...60 de salud. Afecta a los miembros del grupo.'],
2222=>['Tormenta de nieve','Conjuro. Creas una tormenta de nieve en la ubicación del enemigo objetivo. Durante 5 segundos, los enemigos adyacentes recibirán 30...40 de daño frío por segundo.','Conjuro. Hace 30...40 de daño frío por segundo (5 segundos). Alcanza a los enemigos adyacentes a la ubicación inicial del enemigo objetivo.'],
2223=>['Mina de pólvora','Trampa. Cuando se active esta trampa, todos los enemigos cercanos reciben 20...30 de daño, quedarán ciegos y sufrirán una hemorragia durante 7...10 segundos. La Mina de pólvora dura 90 segundos. Cuando la estés colocando, se te podrá interrumpir con facilidad.','Trampa. (90 segundos). Afecta a los enemigos cercanos. Hace 20...30 de daño. Causa ceguera y hemorragia (7...10 segundos). Se puede interrumpir con facilidad.'],
2224=>['Invocar Mursaat','Conjuro. Invocas un Mursaat de nivel 14...20 que vive durante 40...60 segundos y tiene la Carga debilitante. Sólo puede haber una invocación de Asura a la vez.','Conjuro. Invocas un Mursaat de nivel 14...20 (40...60 segundos de vida) que tiene la Carga debilitante. Sólo puede usarse una invocación de Asura a la vez.'],
2225=>['Invocar Djinn de rubí','Conjuro. Invocas un djinn de rubí de nivel 14...20 que vive durante 40...60 segundos y tiene la Inmolación. Sólo puede haber una invocación de Asura a la vez.','Conjuro. Invocas un djinn de rubí de nivel 14...20 (40...60 segundos de vida) que tiene la Inmolación. Sólo puede usarse una invocación de Asura a la vez.'],
2226=>['Invocar diablillo de hielo','Conjuro. Invocas un diablillo de hielo de nivel 14...20 que vive durante 40...60 segundos y tiene las Púas de hielo. Sólo puede haber una invocación de Asura a la vez.','Conjuro. Invocas un diablillo de hielo de nivel 14...20 (40...60 segundos de vida) que tiene las Púas de hielo. Sólo puede usarse una invocación de Asura a la vez.'],
2227=>['Invocar chamán naga','Conjuro. Invocas un chamán naga de nivel 14...20 que vive durante 40...60 segundos y tiene la Pedrada. Sólo puede haber una invocación de Asura a la vez.','Conjuro. Invocas un chamán Naga de nivel 14...20 (40...60 segundos de vida) que tiene la Pedrada. Sólo puede usarse una invocación de Asura a la vez.'],
2228=>['Golpe diestro','Ataque a distancia. Si este ataque impacta, haces 18...30 de daño al enemigo objetivo. Si tiene la armadura rota, sufrirá una hemorragia durante 18...30 segundos.','Ataque a distancia. Hace 18...30 de daño. Causa hemorragia (18...30 segundos) si el enemigo objetivo tiene la armadura rota.'],
2229=>['Sello de infección','Sello. Si el enemigo objetivo está sufriendo una hemorragia, queda enfermo durante 13...20 segundos.','Sello. Causa enfermedad (13...20 segundos) si el enemigo sufre hemorragia.'],
2230=>['Sello de triptófano','Sello. Durante 14...20 segundos, el enemigo objetivo y los adyacentes se mueven y atacan un 23...40% más despacio.','Sello. (14...20 segundos). El enemigo objetivo y los adyacentes se mueven y atacan un 23...40% más despacio.'],
2231=>['Estandarte de valor de la Vanguardia de Ébano','Conjuro de protección. Colocas un estandarte de valor de la Vanguardia de Ébano en tu ubicación actual. Durante 14...20 segundos, los aliados no espíritus de la zona ganarán +24 de armadura y +24 extra contra los Charr.','Conjuro de protección. (14...20 segundos). Los aliados dentro de esta protección tienen +24 de armadura y +24 de armadura extra contra los Charr. No afecta a los espíritus.'],
2232=>['Estandarte de sabiduría de la Vanguardia de Ébano','Conjuro de protección. Colocas un estandarte de sabiduría de la Vanguardia de Ébano en tu ubicación actual. Durante 14...20 segundos, los aliados no espíritus de la zona tendrán un 44...60% de probabilidades de que sus conjuros tarden la mitad en recargarse.','Conjuro de protección. (14...20 segundos). Los conjuros de los aliados dentro de esta protección tienen un 44...60% de probabilidades de recargarse un 50% más rápido. No afecta a los espíritus.'],
2233=>['Estandarte de honor de la Vanguardia de Ébano','Conjuro de protección. Colocas un estandarte de honor de la Vanguardia de Ébano en tu ubicación actual. Durante 14...20 segundos, los aliados no espíritus de la zona harán +8...15 de daño y +7...10 extra contra los Charr.','Conjuro de protección. (14...20 segundos). Los aliados dentro de esta protección hacen +8...15 de daño y +7...10 de daño extra contra los Charr. No afecta a los espíritus.'],
2234=>['Tirador de refuerzo de la Vanguardia de Ébano','Conjuro. El enemigo objetivo recibe 54...90 de daño perforante y sufre hemorragia durante 5...25 segundos. Este ataque tiene un 10% de probabilidades de hacer 540...900 de daño perforante extra. Si este ataque alcanza a un Charr, tiene un 25% de probabilidades de hacer 540...900 de daño perforante extra.','Conjuro. Hace 54...90 de daño perforante y causa hemorragia (5...25 segundos). 10% de probabilidades de hacer +540...900 de daño perforante extra. 25% de probabilidades de hacer +540...900 de daño perforante extra si el enemigo objetivo es un Charr.'],
2235=>['Asesino de refuerzo de la Vanguardia de Ébano','Conjuro. Invocas un Asesino de la Vanguardia de Ébano de nivel 14...20 con Palma de hierro, Colmillos de zorro y Golpe de las nueve colas. Este Asesino da un paso sombrío hasta el enemigo objetivo. Si éste era un Charr, vivirá durante 24...30 segundos, de lo contrario vivirá durante 12...15 segundos.','Conjuro. Invoca un Asesino de nivel 14...20 con Palma de hierro, Colmillos de zorro y Golpe de las nueve colas. Da un paso sombrío hasta el enemigo objetivo. Si éste era un Charr, el Asesino vive durante 24...30 segundos, de lo contrario vive durante 12...15 segundos.'],
2236=>['Pozo de ruina','Conjuro de pozo. Explotas el cadáver más cercano o sacrificas un 66 % de salud para crear un Pozo de ruina en esa ubicación. Durante 5...30 segundos, cada vez que un enemigo en este pozo reciba daño físico, tendrá la armadura rota durante 5...20 segundos.','Conjuro de pozo. (5...30 segundos). Rompes la armadura (durante 5...20 segundos) de los enemigos dentro del pozo que reciban daño físico. Explotas un cadáver reciente o sacrificas un 66 % de salud.'],
2237=>['Atrofia','Conjuro con maleficio. Durante 3...7 segundos, el atributo primario del enemigo objetivo baja hasta 0.','Conjuro con maleficio. (3...7 segundos). Reduce a 0 el atributo primario del enemigo objetivo.'],
2238=>['Lanza de redención','Ataque con lanza. Este ataque hará +5...20 de daño si alcanza al objetivo. Si falla, perderás una condición.','Ataque con lanza. Hace +5...20 de daño. Si falla, pierdes una condición.'],
2353=>['"¡Acaba con él!"','Grito. Si el enemigo objetivo tiene menos del 50% de salud, le haces 44...80 de daño y sufre una herida grave y armadura rota durante 12...20 segundos.','Grito. Hace 44...80 de daño y causa armadura rota y herida grave (12...20 segundos). No tiene efecto a menos que el objetivo tenga menos del 50% de salud.'],
2354=>['"¡Esquiva esto!"','Grito. Durante 16...20 segundos, tu siguiente ataque no se puede bloquear y hace +14...20 de daño.','Grito. (16...20 segundos). Tu siguiente ataque no se puede bloquear y hace +14...20 de daño.'],
2355=>['¡Soy el más fuerte!','Grito. Tus siguientes ataques (5...8) hacen +14...20 de daño extra.','Grito. Tus siguientes 5...8 ataques hacen +14...20 de daño.'],
2356=>['"¡Soy imparable!"','Grito. Durante 16...20 segundos, tienes +24 de armadura y no te pueden derribar ni dejar lisiado.','Grito. (16...20 segundos). Tienes +24 de armadura y no te pueden derribar ni dejar lisiado.'],
2357=>['Un toque de astucia','Conjuro con maleficio. Haces 44...80 de daño al enemigo objetivo tocado. Si estaba derribado, no podrá atacar durante 5...8 segundos.','Conjuro con maleficio de toque. Hace 44...80 de daño. El enemigo objetivo no puede atacar (5...8 segundos) si estaba derribado.'],
2358=>['"¡Te mueves como un enano!"','Grito. Derriba al enemigo objetivo y le causa 44...80 de daño. Ese enemigo también queda lisiado durante 8...15 segundos.','Grito. Hace 44...80 de daño, causa derribo e inflige lisiadura (8...15 segundos).'],
2359=>['"¡Sois unos enclenques!"','Grito. El enemigo objetivo y los enemigos adyacentes quedan debilitados durante 8...12 segundos.','Grito. Causa debilitamiento (8...12 segundos). También afecta a los enemigos adyacentes.'],
2360=>['No sientas dolor','Habilidad. Durante 30 segundos, tienes +2...3 de regeneración de salud. Si activas esta habilidad mientras estás borracho, tendrás +200...300 de salud máxima.','Habilidad. (30 segundos). Tienes +2...3 de regeneración de salud. Tienes +200...300 de salud máxima si activas esta habilidad mientras estás borracho.'],
2361=>['Garrote de los mil osos','Ataque cuerpo a cuerpo. Si este ataque impacta, harás +6...9 de daño por cada enemigo adyacente (máximo 60 de daño). Si el enemigo objetivo no era humano, le derribarás.','Ataque cuerpo a cuerpo. Hace +6...9 de daño por cada enemigo adyacente (máximo 60 de daño). Causa derribo si el enemigo objetivo no es humano.'],
2374=>['Bendición de la Osa Mayor','Transformación["Transformaciones"] de élite. Pierdes todos tus efectos y adoptas el aspecto de la Osa. Durante 60 segundos, tienes 100 de armadura y 750...800 de salud. Todos tus atributos bajan a 0 y tus habilidades son reemplazadas por las de la Osa.','Transformación["Transformaciones"] de élite. Pierdes todos tus efectos y adoptas el aspecto de la Osa (60 segundos). Todos tus atributos bajan a 0 y tus habilidades son reemplazadas por las de la Osa. Tienes 100 de armadura y 750...800 de salud.'],
2379=>['Bendición del lobo','Transformación["Transformaciones"] de élite. Pierdes todos tus efectos y adoptas el aspecto del lobo. Durante 60 segundos, tienes 80 de armadura, 660...700 de salud y 2...4 de regeneración de salud. Todos tus atributos bajan a 0 y tus habilidades son reemplazadas por las del lobo.','Transformación["Transformaciones"] de élite. Pierdes todos tus efectos y adoptas el aspecto del lobo (60 segundos). Todos tus atributos bajan a 0 y tus habilidades son reemplazadas por las del lobo. Tienes 80 de armadura, 660...700 de salud y 2...4 de regeneración de salud.'],
2384=>['Bendición del cuervo','Transformación["Transformaciones"] de élite. Pierdes todos tus efectos y adoptas el aspecto del cuervo. Durante 60 segundos, tienes 80 de armadura, 660...700 de salud y un 20...30% de probabilidades de bloquear. Todos tus atributos bajan a 0 y tus habilidades son reemplazadas por las del cuervo.','Transformación["Transformaciones"] de élite. Pierdes todos tus efectos y adoptas el aspecto del cuervo (60 segundos). Todos tus atributos bajan a 0 y tus habilidades son reemplazadas por las del cuervo. Tienes 80 de armadura, 660...700 de salud y un 20...30% de probabilidades de bloquear.'],
2411=>['Efecto óptico','Conjuro con encantamiento. Durante 10...16 segundos, te mueves un 20...33% más deprisa y tus conjuros tardan un 20% menos en lanzarse.','Conjuro con encantamiento. (10...16 segundos). Te mueves un 20...33% más rápido y lanzas conjuros un 20% más deprisa.'],
2412=>['Criminal elegante','Conjuro. Durante 10...20 segundos, un conjuro aleatorio del enemigo objetivo se desactiva y el Criminal elegante será reemplazado por el conjuro desactivado. Además ganas 5...10 de energía.','Conjuro. (10...20 segundos). Desactiva un conjuro. Esta habilidad se convierte en ese conjuro. Ganas 5...10 de energía.'],
2413=>['Tecnocháchara','Conjuro. El enemigo objetivo y todos los adyacentes reciben 30...40 de daño. Si el objetivo no es un jefe, él y los enemigos adyacentes quedarán aturdidos durante 3...5 segundos.','Conjuro. Hace 30...40 de daño al enemigo objetivo y los adyacentes. Causa aturdimiento (3...5 segundos) a esos enemigos si el objetivo no es un jefe.'],
2414=>['Campo de radiación','Conjuro de protección. Durante 5 segundos, los enemigos en la zona tienen una degeneración de salud de -4...6. Cuando este portal acabe, los enemigos en la zona quedan enfermos durante 12...20 segundos.','Conjuro de protección. (5 segundos). Causa -4...6 de degeneración de salud a los enemigos de la zona. Efecto final: causa enfermedad (12...20 segundos) a los enemigos de la zona.'],
2415=>['Barrido Asura','Conjuro con maleficio. Durante 9...12 segundos, tus ataques al enemigo objetivo no pueden fallar. Si eliminas a un enemigo que tiene el maleficio Barrido asura, pierdes 5% de penalización por resucitar.','Conjuro con maleficio. (9...12 segundos). Tus ataques al enemigo objetivo no pueden fallar. Si eliminas al enemigo, pierdes 5% de penalización por resucitar.'],
2416=>['Aire de superioridad','Habilidad. Durante 20...30 segundos, ganas un extra Asura al azar cada vez que consigas experiencia de matar algún enemigo.','Habilidad. (20...30 segundos). Ganas un extra Asura al azar cada vez que consigas experiencia de matar algún enemigo.'],
2417=>['Bloqueo mental','Conjuro con encantamiento. Durante 5...11 segundos, tienes un 50% de probabilidades de bloquear ataques. Este encantamiento se vuelve a activar cada vez que un enemigo te golpee.','Conjuro con encantamiento. (5...11 segundos). Tienes 50% de probabilidades de bloquear. Renovación: cada vez que un enemigo te alcance.'],
2418=>['Inversión de dolor','Conjuro con maleficio. Durante 6...10 segundos, cada vez que el enemigo objetivo haga daño, recibirá un 100...140% del que haga (máximo 80).','Conjuro con maleficio. (6...10 segundos). Devuelve un 100...140% del daño que haga el enemigo objetivo (máximo 80) cada vez que ataque.'],
2420=>['Huida de ébano','Conjuro. Das un paso sombrío hasta el aliado objetivo. Los dos os curáis 70...110 de salud.','Conjuro. Te cura a ti y al aliado objetivo 70...110 de salud. Efecto inicial: das un paso sombrío hasta ese aliado. No te puedes apuntar a ti mismo.'],
2421=>['Trampa de debilidad','Trampa. Cuando se active esta trampa, todos los enemigos cercanos quedan debilitados durante 10...20 segundos y reciben 24...50 de daño de relámpago. Todos los Charr son derribados. Esta trampa dura 90 segundos y se te podrá interrumpir con facilidad mientras la estés colocando.','Trampa. (90 segundos). Afecta a los enemigos cercanos. Hace 24...50 de relámpago. Causa debilitamiento (10...20 segundos). Derriba a los Charr. Se puede interrumpir con facilidad.'],
2422=>['Vientos','Ritual de la Vanguardia de Ébano. Creas un espíritu de nivel 4...10. Todos los enemigos dentro de su zona tienen un 15% de probabilidades de fallar ataques a distancia. Morirá a los 54...90 segundos.','Ritual de la Vanguardia de Ébano. Crea un espíritu de nivel 4...10 (54...90 segundos de vida). Afecta a los enemigos de la zona. 15% de probabilidades de que los ataques a distancia fallen.'],
2423=>['Estabilidad de enano','Conjuro con encantamiento. Durante 24...30 segundos, tus actitudes duran un 55...100% más. Si activas esta habilidad mientras estás borracho, no te podrán derribar.','Conjuro con encantamiento. (24...30 segundos). Tus actitudes duran un 55...100% más. No te pueden derribar si activas esta habilidad mientras estás borracho.'],
2657=>['Llamada de celeridad (PvP)','Grito. Durante 30 segundos, tu mascota ataca un 25% más rápido y se mueve un 25% más deprisa.','Grito. (30 segundos.) Tu mascota se mueve y ataca un 25% más rápido.'],
2734=>['Sacudida mental (PvP)','Conjuro con maleficio. Durante 5...40 segundos, cuando este enemigo sea el objetivo de una de tus habilidades de Hipnotizador que no sea un maleficio, perderá 1 de energía. Si el enemigo objetivo pierde toda su energía, la Sacudida mental acaba y dicho enemigo recibe 15...100 de daño.','Conjuro con maleficio. (5...40 segundos). Causa 1 de pérdida de energía cada vez que el enemigo es el objetivo de tus habilidades que no sean maleficios de Hipnotizador. Si el enemigo objetivo pierde toda su energía, la Sacudida mental acaba y dicho enemigo recibe 15...100 de daño.'],
2803=>['Congelar mente (PvP)','Conjuro con maleficio de élite. El enemigo objetivo recibe 10...60 de daño frío. Si tienes más energía que el enemigo objetivo, ese enemigo recibe 10...60 de daño frío adicional y se mueve un 90% más despacio durante 1...5 segundos.','Conjuro con maleficio de élite. Hace 10...60 de daño frío. Si tienes más energía que el enemigo objetivo, hace 10...60 de daño frío y causa una reducción del 90% en el movimiento (1...5 segundos).'],
2804=>['Impacto mental (PvP)','Conjuro de élite. El enemigo objetivo recibe 10...50 de daño de relámpago. Si tienes más energía que el enemigo objetivo, éste recibe 10...50 más de daño de relámpago y es derribado. Este conjuro tiene un 25% de penetración de armadura.','Conjuro de élite. Causa 10...50 de daño de relámpago. Si tienes más energía que el enemigo objetivo, hace +10...50 de daño de relámpago y provoca derribo. 25% de penetración de armadura.'],
2805=>['Forma de niebla (PvP)','Conjuro con encantamiento de élite. Durante 10...45 segundos, recibes un 33% menos de daño de los enemigos que estén bajo el efecto de maleficios de magia de agua. Cada vez que lances un conjuro de los elementos, todos aliados no espíritus al alcance del oído se curarán un 50...250% del coste de energía del conjuro. Este conjuro no curará a los aliados que estén por encima del 80% de salud.','Conjuro con encantamiento de élite. (10...45 segundos). Recibes un 33% menos de daño de los enemigos que estén bajo el efecto de maleficios de magia de agua. Cura a los aliados no espíritus al alcance del oído un 50...250% del coste de energía de tus conjuros de los elementos. No cura a los aliados que estén por encima del 80% de salud.'],
2806=>['Protección contra daños (PvP)','Conjuro de protección de élite. Creas una Protección contra daños en esta ubicación. Durante 5...15 segundos, los aliados no espíritus de la zona tienen +1...3 de regeneración de salud, +12...24 de armadura y un +12...24 adicional de armadura contra daño de los elementos. Este conjuro queda desactivado durante 30 segundos.','Conjuro de protección de élite. (5...15 segundos). Los aliados dentro de esta protección tienen +1...3 de regeneración de salud, +12...24 de armadura y un +12...24 adicional de armadura contra daño de los elementos. No afecta a los espíritus. Este conjuro queda desactivado durante 30 segundos.'],
2807=>['Cabalga en el relámpago (PvP)','Conjuro de élite. Cabalgas hacia el objetivo sobre un relámpago. Todos los enemigos cercanos quedan cegados durante 1...5 segundos. Si tu objetivo es un enemigo, recibe 10...70 de daño de relámpago. Este conjuro tiene un 25% de penetración de armadura.','Conjuro de élite. Causa 10...70 de daño de relámpago. 25% de penetración de armadura. Causa ceguera a los enemigos adyacentes (1...5 segundos). Llegas a tu objetivo inmediatamente. Se puede lanzar sobre aliados.'],
2808=>['Golpe enrabietado (PvP)','Ataque con martillo de élite. Si el Golpe enrabietado impacta, ganas 1...3 de adrenalina. Si alcanzas a un enemigo en movimiento, le harás +10...40 de daño y caerá al suelo.','Ataque con martillo de élite. Obtienes 1...3 de adrenalina si impactas. Hace +10...40 de daño y causa derribo si el objetivo estaba en movimiento.'],
2809=>['Llama de obsidiana','Conjuro. Hace 22...92 de daño al enemigo objetivo. Este conjuro ignora la armadura.','Conjuro. Causa 22...92 de daño.'],
2857=>['Égida (PvP)','Conjuro con encantamiento. Durante 1...3 segundos, el aliado objetivo no puede recibir conjuros hostiles y los ataques contra este miembro del grupo fallarán.','Conjuro con encantamiento. (1...3 segundos). El aliado objetivo no puede recibir conjuros hostiles. Los ataques contra este miembro del grupo fallarán. Tú mismo no puedes ser el objetivo.'],
2858=>['"¡Cuidado!" (PvP)','Grito. Los miembros del grupo al alcance del oído ganan +5...25 de armadura durante 10 segundos. Este grito acaba después de 1...3 ataques recibidos.','Grito. (10 segundos). Los miembros del grupo al alcance del oído tienen +5...25 de armadura. Acaba después de 1...3 ataques recibidos.'],
2859=>['Debilidad (PvP)','Conjuro. El objetivo estará debilitado durante 10...30 segundos.','Conjuro. Causa debilitamiento (10...30 segundos).'],
2860=>['Renovación de éter (PvP)','Conjuro con encantamiento de élite. Durante 10 segundos, cada vez que lances un conjuro, ganas 1...3 de energía y 5...20 de salud por cada encantamiento que tengas.','Conjuro con encantamiento de élite. (10 segundos). Cada vez que lances un conjuro, ganas 1...3 de energía y 5...20 de salud por cada encantamiento que tengas.'],
2861=>['Ataque penetrante (PvP)','Ataque con arco. Si el Ataque penetrante golpea al enemigo, le harás +5...15 de daño. Tiene un 10% de penetración de armadura.','Ataque con arco. Hace +5...15 de daño. 10% de penetración de armadura.'],
2862=>['Forma sombría (PvP)','Conjuro con encantamiento de élite. Durante 5...15 segundos, todos los conjuros y ataques dirigidos contra ti fallan. Cuando la Forma sombría acabe, te quedarás con 5...50 de salud.','Conjuro con encantamiento de élite. (5...15 segundos). Todos los conjuros y ataques dirigidos contra ti fallan. Efecto final: te quedas con 5...50 de salud.'],
2863=>['Discordia (PvP)','Conjuro de élite. Si el enemigo objetivo sufre una condición y está bajo los efectos de un maleficio o encantamiento, recibirá 30...110 de daño.','Conjuro de élite. Hace 30...110 de daño. No tiene efecto a menos que el enemigo objetivo tenga una condición y también un maleficio o un encantamiento.'],
2864=>['Ataque incisivo (PvP)','Ataque con arco. Si el Ataque incisivo impacta, harás +5...15 de daño. Tiene un 10% de penetración de armadura.','Ataque con arco. Hace +5...15 de daño. 10% de penetración de armadura.'],
2866=>['Carne de mi carne (PvP)','Conjuro. Pierdes la mitad de la salud para resucitar al miembro del grupo objetivo con la que tengas y 5...20% de energía.','Conjuro. Resucita al miembro del grupo objetivo (con la mitad de tu salud actual y 5...20% de energía). Pierdes la mitad de salud.'],
2867=>['Rabia ancestral (PvP)','Habilidad. Durante 3 segundos, todos los enemigos adyacentes al objetivo (un aliado o tú mismo) reciben 4...50 de daño de relámpago por segundo.','Habilidad. (3 segundos). Hace 4...50 de daño de relámpago por segundo a todos los enemigos adyacentes al objetivo (un aliado o tú mismo).'],
2868=>['Arma de astillas (PvP)','Conjuro con arma. Durante 20 segundos, el aliado objetivo tiene un Arma de astillas. Los siguientes (1...5) ataques del aliado objetivo harán 5...40 de daño a un máximo de 4 enemigos adyacentes.','Conjuro con arma. (20 segundos). Sus ataques hacen 5...40 de daño hasta a 3 enemigos adyacentes. Acaba después de 1...5 ataques.'],
2869=>['Remedio del Asesino (PvP)','Conjuro con encantamiento. Durante 30 segundos, tus siguientes habilidades de ataque (1...10) eliminarán una condición.','Conjuro con encantamiento. (30 segundos). Tus siguientes habilidades de ataque (1...10) eliminan una condición cada una.'],
2871=>['Luz de liberación (PvP)','Conjuro de élite. Todos los miembros del grupo se curan 5...70 de salud. Todas tus habilidades de plegarias de ataque estarán desactivadas durante 20 segundos.','Conjuro de élite. Cura 5...70 de salud a todo el grupo. Desactiva tus plegarias de ataque (20 segundos).'],
2872=>['Sello del pacto de muerte (PvP)','Sello. Resucitas al miembro del grupo objetivo con tu salud actual y el 15...100% de energía máxima. La próxima vez que ese aliado muera en menos de 120 segundos, tú también morirás.','Sello. Resucita al miembro del grupo objetivo con tu salud actual y el 15...100% de energía máxima. Durante 120 segundos, si el aliado objetivo muere, tú también lo harás.'],
2875=>['Lanzamiento del cazador (PvP)','Ataque con lanza. Si este ataque impacta, harás +5...20 de daño y 5...40 extra si el enemigo estaba en movimiento.','Ataque con lanza. Hace +5...20 de daño. +5...40 de daño extra si el enemigo objetivo se está moviendo.'],
2876=>['Himno defensivo (PvP)','Cántico de élite. Durante 4...10 segundos, todos los miembros del grupo al alcance del oído tienen un 50% de posibilidades de bloquear ataques. Este cántico acaba si el miembro del grupo consigue golpear con una habilidad de ataque.','Cántico de élite. (4...10 segundos). Los miembros del grupo al alcance del oído tienen un 50% de probabilidades de bloquear. Acaba al usar con éxito una habilidad de ataque.'],
2877=>['Balada de restauración (PvP)','Cántico. Durante 10 segundos, la próxima vez que hagan daño a algún compañero al alcance del oído, se curará 15...75 de salud.','Cántico. (10 segundos). Los miembros del grupo al alcance del oído ganan 15...75 de salud la próxima vez que reciban daño.'],
2878=>['Canción de restauración (PvP)','Cántico de élite. Durante 10 segundos, la próxima vez que algún miembro del grupo al alcance del oído use una habilidad, se curará 45...110 de salud.','Cántico de élite. (10 segundos). Los miembros del grupo al alcance del oído ganan 45...110 de salud con su siguiente habilidad.'],
2879=>['"¡Que vienen!" (PvP)','Grito de élite. Durante 4...10 segundos, todos los aliados al alcance del oído se mueven un 33% más rápido y ganan 5...15 de salud mientras se muevan.','Grito de élite. (4...10 segundos.) Los aliados al alcance del oído se mueven un 33% más rápido y ganarán 5...15 de salud al moverse.'],
2880=>['"¡Arriba!" (PvP)','Grito. Durante 10 segundos, todos los compañeros al alcance del oído y por debajo del 75% de salud ganarán +1...5 de regeneración de salud.','Grito. (10 segundos). Los miembros del grupo al alcance del oído ganan +1...5 de regeneración de salud. Sólo afecta a los miembros del grupo por debajo del 75% de salud.'],
2883=>['"¡Por la justicia!" (PvP)','Grito. Durante 8 segundos, cada vez que consigas atacar, ganas 1 extra de adrenalina.','Grito. (8 segundos). Ganas 1 extra de adrenalina cada vez que consigas atacar.'],
2884=>['Regeneración mística (PvP)','Conjuro con encantamiento. Durante 5...20 segundos, ganas +1...4 de regeneración de salud por cada encantamiento que tengas encima (máximo 3).','Conjuro con encantamiento. (5...20 segundos). Ganas +1...4 de regeneración de salud por cada encantamiento que tengas encima (máximo 3).'],
2885=>['Sangre debilitante (PvP)','Conjuro. El enemigo objetivo y los cercanos a él quedarán debilitados durante 1...16 segundos.','Conjuro. Causa debilitamiento (1...16 segundos) al enemigo objetivo y los cercanos.'],
2887=>['Sello del juicio (PvP)','Sello de élite. Derribas al enemigo objetivo. Ese enemigo y todos los adyacentes reciben 5...50 de daño sagrado. Este sello tiene la mitad de alcance de lo normal.','Sello de élite con mitad de alcance. Derriba al objetivo. Hace 5...50 de daño sagrado al enemigo objetivo y los adyacentes.'],
2891=>['Aura de persistencia (PvP)','Conjuro con encantamiento de élite. Devuelve la vida al aliado objetivo con la salud y energía al máximo. Si dejas de mantener este encantamiento o alguien lo quita, ese aliado muere y deja un cadáver explotable. No se penalizará por resucitar si se muere teniendo el Aura de persistencia. (50 % de posibilidades de fallo con favor divino 4 o inferior).','Conjuro con encantamiento de élite. Resucita al miembro del equipo objetivo (con toda la salud y energía). Efecto final: el aliado muere y deja un cadáver explotable. No sufre penalización por morir. 50 % de probabilidades de fallar con favor divino inferior a 5.'],
2892=>['Vínculo espiritual (PvP)','Conjuro con encantamiento. Durante 8 segundos, siempre que el objetivo (un aliado o tú mismo) reciba más de 50 de daño de los próximos 10 ataques o conjuros, se curará 30...90 de salud.','Conjuro con encantamiento. (8 segundos.) Cura 30...90 de salud siempre que el objetivo (un aliado o tú mismo) haga más de 50 de daño. Acaba cuando este aliado reciba daño de 10 ataques o conjuros.'],
2893=>['Arma de guardia (PvP)','Conjuro con arma. Durante 3...8 segundos, el aliado objetivo tiene un Arma de guardia, que le dará un 50% de probabilidades de bloquear ataques y +2...4 de regeneración de salud. El Arma de guardia termina si el aliado ataca.','Conjuro con arma. (3...8 segundos.) +2...4 de regeneración de salud. 50% de probabilidades de bloquear. Termina si el aliado objetivo ataca.'],
2895=>['Bendición del atacante (PvP)','Conjuro con encantamiento. Durante 4 segundos, tus plegarias de ataque tienen un extra doble de favor divino.','Conjuro con encantamiento. (4 segundos). Tus plegarias de ataque tienen el doble del extra de curación del favor divino.'],
2925=>['Disparo del cazador perezoso (PvP)','Ataque con arco. Si este ataque impacta, el enemigo objetivo recibe +5...15 de daño. Si el enemigo no estaba usando ninguna habilidad, este disparo hará +5...20 de daño extra.','Ataque con arco. Hace +5...15 de daño. +5...20 de daño extra si el enemigo objetivo no está usando ninguna habilidad.'],
2959=>['Destreza del experto (PvP)','Actitud de élite. Durante 1...20 segundos, atacas un 15% más deprisa y tu atributo puntería sube 1.','Actitud de élite. (1...20 segundos). Atacas un 15% más deprisa y ganas +1 en tu atributo puntería.'],
2965=>['Sello de espíritus (PvP)','Sello de élite. Ganas 3...12 de energía si estás al alcance del oído de algún espíritu.','Sello de élite. Ganas 3...12 de energía. No tiene efecto si no estás al alcance del oído de algún espíritu.'],
2966=>['Sello de poder fantasmal (PvP)','Sello de élite. Los ataques de la criatura invocada aliada objetivo hacen 5...35 más de daño. Después de 10 segundos, esa criatura se destruirá.','Sello de élite. La criatura aliada objetivo hace +5...35 de daño. Esa criatura muere a los 10 segundos.'],
2969=>['Medir el viento (PvP)','Preparación["Preparaciones"]. Durante 24 segundos, tus flechas vuelan el doble de rápido.','Preparación["Preparaciones"]. (24 segundos.) Tus flechas vuelan el doble de rápido.'],
2998=>['Fragilidad (PvP)','Conjuro con maleficio. Durante 8...20 segundos, el enemigo objetivo y los que le rodeen recibirán 5...20 de daño cada vez que sufran o se recuperen de una nueva condición.','Conjuro con maleficio. También afecta a los enemigos cercanos al objetivo (8...20 segundos). Estos enemigos reciben 5...20 de daño cada vez que ganen o pierdan una condición.'],
2999=>['Fuerza del honor (PvP)','Conjuro con encantamiento. Mientras mantengas este encantamiento, el aliado objetivo hace 1...5 más de daño en ataques cuerpo a cuerpo.','Conjuro con encantamiento. El aliado objetivo hace 1...5 más de daño en ataques cuerpo a cuerpo.'],
3002=>['Fortaleza del Guerrero (PvP)','Actitud de élite. Durante 5...35 segundos, ganas 3 de energía cada vez que golpees cuerpo a cuerpo. La Fortaleza del Guerrero no puede aumentar tu energía por encima de 10...25.','Actitud de élite. (5...35 segundos.) Ganas 3 de energía cada vez que golpees cuerpo a cuerpo. No ganas energía si tienes más de 10...25 de energía.'],
3003=>['Armadura de insensibilidad (PvP)','Conjuro con encantamiento. Durante 10...35 segundos, tienes una reducción del daño base de 10 cuando invoques rituales de encadenamiento de espíritus.','Conjuro con encantamiento. (10...35 segundos.) Tienes una reducción del daño base de 10 cuando invoques rituales de encadenamiento con espíritus.'],
3005=>['Unión (PvP)','Ritual con espíritus. Creas un espíritu de nivel 1...8. Siempre que un aliado no espíritu reciba daño o pierda vida dentro de su zona, el daño se reducirá en 15 y el espíritu recibirá 15 de daño. El espíritu morirá a los 30...60 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...8 (30...60 segundos de vida). Siempre que un aliado no espíritu reciba daño o pierda vida dentro de su zona, el daño se reducirá en 15 y el espíritu recibirá 15 de daño.'],
3006=>['Nanasombría (PvP)','Ritual con espíritus. Creas un espíritu de nivel 1...6. Los ataques de estos espíritus hacen un 5...20 de daño y causan ceguera durante 1...6 segundos. El espíritu morirá a los 30 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...6 (30 segundos de vida). Sus ataques hacen 5...20 de daño y causan ceguera (5...20 segundos).'],
3007=>['Dolor (PvP)','Ritual con espíritus. Creas un espíritu de nivel 1...8. Los ataques del espíritu causan 5...30 de daño. El espíritu morirá a los 30...150 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...8 (30...150 segundos de vida). Sus ataques causan 5...30 de daño.'],
3008=>['Destrucción (PvP)','Ritual con espíritus. Creas un espíritu de nivel 1...10 que muere al cabo de 30 segundos. Cuando éste muera, todos los enemigos de la zona reciben 1...10 de daño por cada segundo que haya vivido (máximo 150 de daño).','Ritual con espíritus. Crea un espíritu de nivel 1...10 (30 segundos de vida). Al morir, hace 1...10 de daño por cada segundo que haya vivido a todos los enemigos de la zona (máximo 150 de daño).'],
3009=>['Calmante (PvP)','Ritual con espíritus. Creas un espíritu de nivel 1...8. Todos los enemigos de la zona tardan el doble en crear adrenalina. El espíritu morirá a los 15...45 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...8 (15...45 segundos de vida). Los enemigos de la zona tardan el doble en crear adrenalina.'],
3010=>['Desplazamiento (PvP)','Ritual con espíritus. Creas un espíritu de nivel 1...10. Todos los aliados no espíritus de la zona tienen el 75% de probabilidades de bloquear los ataques que reciban. Cada vez que se bloquee un ataque de este modo, el espíritu recibe 60 de daño. El espíritu morirá a los 30...60 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...10 (30...60 segundos de vida). Los aliados de la zona que no son espíritus tienen un 75% de probabilidades de bloquear ataques. Efecto del bloqueo: el espíritu recibe 60 de daño.'],
3011=>['Conservación (PvP)','Ritual con espíritus de élite. Creas un espíritu de nivel 1...10. Cada 4 segundos, el espíritu cura 10...115 de salud a un aliado no espíritu de la zona. El espíritu morirá a los 90 segundos.','Ritual con espíritus de élite. Crea un espíritu de nivel 1...10 (90 segundos de vida). Cada 4 segundos, el espíritu cura 10...115 de salud a un aliado no espíritu.'],
3012=>['Vida (PvP)','Ritual con espíritus. Creas un espíritu de nivel 1...10. Cuando éste muera, todos los aliados no espíritus de la zona se curarán 1...7 de salud por cada segundo que haya estado vivo. El espíritu morirá a los 20 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...10 (20 segundos de vida). Afecta a los aliados de la zona que no sean espíritus. Efecto final: cura 1...7 de salud por cada segundo que el espíritu haya estado vivo.'],
3013=>['Recuperación (PvP)','Ritual con espíritus. Creas un espíritu de nivel1...10. Los aliados de la zona que no sean espíritus ganan +1...3 de regeneración de salud. El espíritu morirá a los 15...45 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...10 (15...45 segundos de vida). Los aliados de la zona que no sean espíritus tienen 1...3 de regeneración de salud.'],
3014=>['Disonancia (PvP)','Ritual con espíritus. Creas un espíritu de nivel 1...8. Este espíritu hace 5...20 de daño e interrumpe a cualquiera que alcance con su ataque. El espíritu morirá a los 10...25 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...8 (10...25 segundos de vida). Sus ataques causan 5...20 de daño e interrumpen las acciones de los enemigos.'],
3015=>['Atadura terrenal (PvP)','Ritual con espíritus. Creas un espíritu de nivel 1...10. Los enemigos que no sean espíritus y se derriben dentro de su zona permanecerán en el suelo durante, por lo menos, 3 segundos. Cuando esto ocurra, el espíritu perderá 50...25 de salud. El espíritu morirá a los 15...45 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...10 (15...45 segundos de vida). Cada vez que se derribe un enemigo no espíritu dentro de su zona, permanecerá en el suelo durante, por lo menos, 3 segundos. Coste del derribo: el espíritu pierde 50...25 de salud.'],
3016=>['Refugio (PvP)','Ritual con espíritus. Creas un espíritu de nivel 1...8. Los aliados que no sean espíritus y se encuentren dentro de su zona no perderán más del 10% del máximo de salud con un solo ataque. Cuando este espíritu se defienda, perderá 75...45 de salud. El espíritu morirá a los 30...60 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...8 (30...60 segundos de vida). Los aliados que no sean espíritus y se encuentren dentro de su zona no perderán más del 10% del máximo de salud con un solo ataque. Coste por defensa: el espíritu pierde 75...45 de salud.'],
3017=>['Desencantamiento (PvP)','Ritual con espíritus. Creas un espíritu de nivel 1...8. Este espíritu hace 5...20 de daño y cualquier enemigo que reciba su ataque pierde un encantamiento. El espíritu morirá a los 15...40 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...8 (15...40 segundos de vida). Sus ataques causan 5...20 de daño y eliminan un encantamiento.'],
3018=>['Restauración (PvP)','Ritual con espíritus. Creas un espíritu de nivel 1...10. Cuando éste muera, todos los miembros del grupo que se encuentren en la zona resucitarán con 5...50% de salud y nada de energía. El espíritu morirá a los 30 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...10 (30 segundos de vida). Efecto final: resucita a los miembros del grupo que se encuentren en la zona con 5...50% de salud y nada de energía.'],
3019=>['Canción sangrienta (PvP)','Ritual con espíritus. Creas un espíritu de nivel 1...8 que muere al cabo de 30...150 segundos. Los ataques de este espíritu roban hasta 5...25 de salud.','Ritual con espíritus. Crea un espíritu de nivel 1...8 (30...150 segundos de vida). Sus ataques roban 5...25 de salud.'],
3020=>['Trotamundeo (PvP)','Ritual con espíritus de élite. Creas un espíritu de nivel 1...8. Cuando este espíritu ataca a un enemigo parado, éste será derribado y el espíritu perderá 70...50 de salud. El espíritu morirá a los 30...60 segundos.','Ritual con espíritus de élite. Crea un espíritu de nivel 1...8 (30...60 segundos de vida). Si ataca a un enemigo parado, éste será derribado. Coste del derribo: el espíritu pierde 70...50 de salud.'],
3021=>['Calor de la Sabana (PvP)','Conjuro de élite. Creas un Calor de la Sabana en la ubicación del enemigo objetivo. Durante 5 segundos, todos los enemigos cercanos reciben 5...20 de daño de fuego cada segundo que el conjuro esté activo.','Conjuro de élite. Causa 5...20 de daño de fuego por segundo desde el momento en que se lanza el conjuro (5 segundos). Alcanza a los enemigos cercanos a la ubicación inicial del objetivo.'],
3022=>['Mirada de furia (PvP)','Ritual con espíritus. Destruyes el espíritu aliado objetivo y creas un espíritu de furia de nivel 1...10. Los ataques del espíritu causan 5...20 de daño. El espíritu morirá a los 30...60 segundos.','Ritual con espíritus. Destruye a un espíritu aliado. Crea un espíritu de nivel 1...10 (30...60 segundos de vida). Sus ataques causan 5...20 de daño.'],
3023=>['Angustia (PvP)','Ritual con espíritus. Creas un espíritu de nivel 1...7. Los ataques del espíritu causan 5...20 de daño y el doble a los enemigos que tengan algún maleficio. El espíritu morirá a los 15...45 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...7 (15...45 segundos de vida). Sus ataques causan 5...20 de daño. Causan el doble de daño a los enemigos que tengan algún maleficio.'],
3024=>['Fortalecimiento (PvP)','Ritual con espíritus. Creas un espíritu de nivel 1...10. Todos los aliados de la zona que lleven un objeto ganan 15...45 de salud y 10 de energía máxima. El espíritu morirá a los 15...60 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...10 (15...60 segundos de vida). Los aliados de la zona que lleven un objeto ganan 15...45 de salud y 10 de energía máxima.'],
3025=>['Recuperación (PvP)','Ritual con espíritus. Creas un espíritu de nivel 1...10. Las condiciones que estén sufriendo los aliados de la zona de este espíritu terminarán 20...50% más deprisa. El espíritu morirá a los 30...60 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...10 (30...60 segundos de vida). Las condiciones que estén sufriendo los aliados de la zona terminarán 20...50% más deprisa.'],
3026=>['"¡A la yugular!" (PvP)','Grito. Durante 10 segundos, la próxima vez que algún aliado al alcance del oído ataque, habrá un 30...75% de posibilidades que sea un golpe crítico.','Grito. (10 segundos.) Los aliados al alcance del oído tienen +30...75% de probabilidades de hacer un golpe crítico con su siguiente ataque.'],
3027=>['"¡Preparado!" (PvP)','Grito. Durante 5...15 segundos, la siguiente vez que intenten derribar al aliado objetivo no lo hará y, en lugar de ello, un enemigo cercano recibirá 15...90 de daño.','Grito. (5...15 segundos.) Evita el siguiente derribo y causa 15...90 de daño a uno de los enemigos cercanos al aliado objetivo. No te puedes apuntar a ti mismo como objetivo.'],
3028=>['Cierre llameante (PvP)','Eco. Durante 10...35 segundos, cada vez que un grito o cántico alcance al aliado no espíritu objetivo, todos los enemigos adyacentes a él arderán durante 1...5 segundos.','Eco. (10...35 segundos.) Causa quemadura (1...5 segundos) a los enemigos adyacentes cada vez que los efectos de un cántico o grito alcanzan al aliado objetivo. No puedes apuntar a los espíritus.'],
3029=>['Estribillo afilado (PvP)','Eco. Durante 20 segundos, el aliado no espíritu objetivo tendrá +10...40 de armadura contra daño cortante. Este eco se reactivará cada vez que los efectos de un cántico o grito alcancen al aliado.','Eco. (20 segundos.) El aliado objetivo tiene +10...40 de armadura contra daño cortante. Renovación: Cada vez que los efectos de un cántico o grito alcancen al aliado. No puedes apuntar a los espíritus.'],
3030=>['Sello del retorno (PvP)','Sello. Resucitas al aliado objetivo con 5...20% de salud y 1...4% de energía por cada miembro del grupo al alcance del oído.','Sello. Resucita al aliado objetivo (5...20% de salud y 1...4% de energía por cada miembro del grupo al alcance del oído).'],
3031=>['"¡No nos toquéis!" (PvP)','Grito. Durante 20 segundos, las siguientes habilidads de toque 1...5 contra ti fallarán.','Grito. (20 segundos.) Las siguientes habilidads de toque 1...5 contra ti fallarán.'],
3032=>['"¡Mantente en guardia!" (PvP)','Grito. Durante 5...20 segundos, todos los miembros del grupo al alcance del oído ganan +24 de armadura si no se están moviendo. Este efecto alcanza a un aliado afectado por este grito si el aliado ataca.','Grito. (5...20 segundos.) Los miembros del grupo al alcance del oído ganan +24 de armadura si no se están moviendo. Alcanza a un aliado si éste ataca.'],
3033=>['"¡Volveremos!" (PvP)','Grito. Durante 10 segundos, siempre que algún miembro del grupo al alcance del oído use una habilidad de resurrección, los aliados muertos volverán a la vida con un 10...75% más de salud y un 5...50% más de energía.','Grito. (10 segundos.) Cada vez que algún miembro del grupo al alcance del oído use una habilidad de resurrección, los aliados muertos vuelven a la vida con un 10...75% más de salud y un 5...50% más de energía.'],
3034=>['"¡A por su punto débil!" (PvP)','Grito. Durante 5...20 segundos, la próxima vez que el aliado objetivo dé un golpe crítico, también hará una herida grave que durará 5...20 segundos.','Grito. (5...20 segundos.) El aliado objetivo causa herida grave (5...20 segundos) con el siguiente golpe crítico.'],
3035=>['"¡No te rindas!"  (PvP)','Grito. Todos los aliados al alcance del oído y por debajo del 75% de salud ganan 1...10 de energía.','Grito. Los aliados al alcance del oído ganan 1...10 de energía. Sólo afecta a los aliados por debajo del 75% de salud.'],
3036=>['"¡Ayuda!" (PvP)','Grito. El aliado no espíritu objetivo gana 5...50 de salud. Durante 1...10 segundos, los conjuros que te lancen los otros aliados se invocarán un 50 % más deprisa.','Grito. (1...10 segundos). El aliado no espíritu objetivo gana 5...50 de salud y los conjuros que te lancen los otros aliados se invocarán un 50 % más deprisa.'],
3037=>['"¡Atrás!" (PvP)','Grito. Durante 4...10 segundos, todos los aliados al alcance del oído ganan 5...15 de salud por segundo mientras se muevan y se mueven un 33% más deprisa. Este grito termina en un aliado si éste logra hacer un ataque.','Grito. (4...10 segundos.) Los aliados al alcance del oído se mueven un 33% más deprisa y ganan 5...15 de salud por segundo mientras se muevan. Alcanza a un aliado si éste logra hacer un ataque.'],
3038=>['Agonía (PvP)','Ritual con espíritus. Creas un espíritu de nivel 1...8. El espíritu hace perder 3...10 de salud por segundo a todos los enemigos al alcance del oído. El espíritu perderá 3...10 de salud por cada enemigo dañado. El espíritu morirá a los 30...90 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...8 (30...90 segundos de vida). Hace perder 3...10 de salud por segundo a todos los enemigos al alcance del oído. El espíritu pierde 3...10 de salud por cada enemigo que pierda salud.'],
3039=>['Rejuvenecimiento (PvP)','Ritual con espíritus. Creas un espíritu de nivel 1...16. El espíritu cura 3...10 de salud por cada segundo a todos los miembros del grupo al alcance del oído. El espíritu perderá 3...10 de salud por cada miembro del grupo que haya curado. El espíritu morirá a los 30...90 segundos.','Ritual con espíritus. Crea un espíritu de nivel 1...16 (30...90 segundos de vida). Cura 3...10 de salud por segundo a los miembros del grupo al alcance del oído. Coste de la curación: el espíritu pierde 3...10 de salud.'],
3040=>['Himno de interrupción (PvP)','Cántico. Durante 1...10 segundos, la siguiente habilidad de ataque que usen los aliados al alcance del oído interrumpe también.','Cántico. (1...10 segundos.) Los aliados al alcance del oído interrumpen una acción con su siguiente habilidad de ataque.'],
3045=>['Confortar animal (PvP)','Habilidad. Curas 40...120 de salud a tu mascota animal. Si está muerta, la resucitarás con 10...58% de salud. Si tienes equipado Confortar animal, tu mascota viajará contigo.','Habilidad. Tu mascota gana 40...120 de salud. Resucita a tu mascota (10...58% de salud). Si tienes equipado Confortar animal, tu mascota viajará contigo.'],
3047=>['Salto de Melandru (PvP)','Ataque con mascota. Tu mascota hará un Salto de Melandru que causa +5...20 de daño. Si el ataque alcanza a un enemigo que está encantado, dicho enemigo y los que estén cerca sufrirán +5...35 de daño adicional.','Ataque con mascota. Causa +5...20 de daño. Causa +5...35 de daño adicional al enemigo objetivo y los que estén cerca si el objetivo está encantado.'],
3048=>['Mortaja de agonía (PvP)','Conjuro con encantamiento. Durante 30...60 segundos, si estás por debajo del 50% de salud, tendrás un 75% de probabilidades de bloquear ataques.','Conjuro con encantamiento. (30...60 segundos.) Tienes un 75% de probabilidades de bloquear. Sólo surte efecto si tu Salud está por debajo del 50%.'],
3049=>['Furia inadvertida (PvP)','Actitud. Durante 15...60 segundos, los enemigos cegados no podrán bloquear tus ataques.','Actitud. (15...60 segundos.) Los enemigos cegados no podrán bloquear tus ataques.'],
3050=>['Vínculo depredador (PvP)','Grito. Durante 5...20 segundos, los ataques de tu mascota que alcancen al enemigo te harán recuperar 1...31 de salud.','Grito. (5...20 segundos.) Recuperarás 1...31 de salud cada vez que un ataque de tu mascota alcance al enemigo.'],
3051=>['Embestida enrabietada (PvP)','Ataque con mascota de élite. Tu mascota lanzará un ataque Embestida enrabietada que causa +3...23 de daño al enemigo por cada habilidad de dominio de bestias que tengas recargándose (máximo 60).','Ataque con mascota de élite. Hace +3...23 de daño (máximo 60) por cada habilidad de dominio de bestias que tengas recargándose.'],
3053=>['Sello de corrupción mortal (PvP)','Sello. Debe ir precedido de un ataque doble. El enemigo objetivo recibe 5...35 de daño por cada condición que tenga (daño máximo: 130).','Sello. Causa 5...35 de daño (máximo 130) por cada condición que tenga el enemigo objetivo. Debe ir precedido de un ataque doble.'],
3054=>['Masoquismo (PvP)','Conjuro con encantamiento. Durante 30 segundos, ganarás 1...3 de energía cada vez que sacrifiques salud.','Conjuro con encantamiento. (30 segundos.) Ganas 1...3 de energía al sacrificar salud.'],
3058=>['Festín impío (PvP)','Conjuro. Robas 10...65 de salud de hasta 1...4 enemigos de la zona.','Conjuro. Robas 10...65 de salud de 1...4 enemigos del área cercana.'],
3059=>['Sello de la agonía (PvP)','Sello. Sufres una hemorragia durante 25 segundos. Todos los enemigos cercanos reciben 10...70 de daño.','Sello. Hace 10...70 de daño a los enemigos cercanos. Sufres una hemorragia (25 segundos).'],
3060=>['Escape (PvP)','Actitud de élite. Durante 1...8 segundos, te mueves un 33% más rápido y tienes un 75% de posibilidades de bloquear ataques. El Escape acaba si realizas un ataque cuerpo a cuerpo.','Actitud de élite. (1...8 segundos.) Te mueves un 33% más rápido y tienes un 75% de posibilidades de bloquear. Acaba si realizas un ataque cuerpo a cuerpo.'],
3061=>['Brote mortal (PvP)','Ataque doble. Debe ir precedido de un ataque complementario. Si impacta, el Brote mortal causará +20...45 de daño al enemigo objetivo y 20...45 a todos los enemigos adyacentes.','Ataque doble. Causa +20...45 de daño. También afecta a los enemigos adyacentes al objetivo. Debe ir precedido de un ataque complementario.'],
3062=>['Cierre de restauración (PvP)','Eco. Durante 10...35 segundos, las próximas 5 veces que los efectos de un grito o cántico alcancen a un aliado objetivo no espíritu, recuperará 15...75 de salud.','Eco. (10...35 segundos.) El aliado objetivo recupera 15...75 de salud las próximas 5 veces que un grito o cántico lo alcance. No puedes apuntar a espíritus.'],
3063=>['Mantra de determinación (PvP)','Actitud. Durante 5 segundos no podrás ser interrumpido, pero cada vez que se te hubiera podido interrumpir, perderás 10...4 de energía o el Mantra de determinación finalizará.','Actitud. (5 segundos.) Evita que puedan interrumpirte. Coste de la prevención: pierdes 10...4 de energía o el Mantra de determinación finalizará.'],
3141=>['Reflejos felinos (PvP)','Actitud. Durante 5...11 segundos, tienes un 75% de posibilidades de bloquear ataques cuerpo a cuerpo y proyectiles, y atacarás un 33% más deprisa.','Actitud. (5...11 segundos.) Atacas un 33% más rápido y tienes un 75% de posibilidades de bloquear.'],
3143=>['Golpe renovador (PvP)','Ataque con martillo. Si impacta, el Golpe renovador hace +5...20 de daño. Si golpeas a un enemigo derribado, ganas 3 de energía y esta habilidad se recargará instantáneamente.','Ataque con martillo. Hace +5...20 de daño. Ganas 3 de energía y esta habilidad se recargará instantáneamente si el enemigo estaba derribado.'],
3144=>['Curación simbiótica (PvP)','Habilidad de élite. Si tú o tu mascota estáis por debajo del 75% de salud, ganaréis 25...145 de salud. Si tu mascota está muerta, la resucitarás con el 50% de salud.','Habilidad de élite. Tú y tu mascota recuperáis 25...145 de salud. Si tu mascota está muerta, la resucitarás con el 50% de salud. Sólo surte efecto si tu salud o la de tu mascota están por debajo del 75%.'],
3145=>['Flechas de cristal (PvP)','Preparación["Preparaciones"] de élite. Durante 10...35 segundos, tus flechas hacen +6...18 de daño y causan hemorragia durante 10...20 segundos si las bloquean.','Preparación["Preparaciones"] de élite. (10...35 segundos.) Tus flechas hacen +6...18 de daño. Causan hemorragia si se bloquean (10...20 segundos).'],
3147=>['Flecha afilada (PvP)','Ataque con arco. Este ataque hace +5...15 de daño si impacta. Si es además un golpe crítico, harás +5...30 de daño adicional.','Ataque con arco. Hace +5...15 de daño. Hace +5...30 de daño extra si das un golpe crítico.'],
3148=>['Himno de envidia (PvP)','Cántico. Durante 10 segundos, la siguiente habilidad de ataque que usen los aliados al alcance del oído hará +10...20 de daño a los enemigos con más del 50% de salud.','Cántico. (10 segundos.) Los aliados al alcance del oído hacen +10...20 de daño con su siguiente habilidad de ataque. El extra de daño sólo se aplica a los enemigos con más del 50% de salud.'],
3149=>['Estribillo sanador (PvP)','Eco. Durante 15 segundos, tienes +2...3 de regeneración de salud. Este eco se reactivará cada vez que los efectos de un cántico o grito te alcancen.','Eco. (15 segundos.) Ganas +2...3 de regeneración de salud. Renovación: Cada vez que los efectos de un cántico o grito te alcancen.'],
3151=>['Empatía (PvP)','Conjuro con maleficio. Durante 5...15 segundos, siempre que el enemigo objetivo ataque, éste recibirá 15...45 de daño.','Conjuro con maleficio. (5...15 segundos). El enemigo objetivo recibe 15...45 de daño cada vez que ataca.'],
3152=>['Angustia agobiante (PvP)','Conjuro con maleficio de élite. Durante 5...20 segundos, el enemigo objetivo se mueve un 50% más lento y sufre una degeneración de salud de -2...6.','Conjuro con maleficio de élite. (5...20 segundos). El enemigo objetivo se mueve un 50% más lento y tiene -2...6 de degeneración de salud.'],
3156=>['Actitud del soldado (PvP)','Actitud de élite. Durante 4...10 segundos, atacas un 33% más deprisa si estás bajo los efectos de un grito o cántico.','Actitud de élite. (4...10 segundos). Atacas un 33% más deprisa si estás bajo los efectos de un grito o cántico.'],
3157=>['Destructora sea Glaive (PvP)','Conjuro con objeto de élite. Llevas las cenizas de Glaive durante 30...60 segundos. Mientras las lleves, todas las habilidades de Ritualista tienen 10% de penetración de armadura. Cuando las sueltes, todos los enemigos de la zona reciben 15...85 de daño de relámpago.','Conjuro con objeto de élite. (30...60 segundos). Tus habilidades de Ritualista tienen un 10% de penetración de armadura. Efecto al soltarse: hace 15...85 de daño de relámpago a los enemigos de la zona.'],
3179=>['Mantra de sellos (PvP)','Actitud. Durante 10...40 segundos, tienes +3 de armadura por cada sello que lleves. Cada vez que utilizas un sello, ganas 5...60 de salud.','Actitud. (10...40 segundos). Tienes +3 de armadura por cada sello. Ganas 5...60 de salud cada vez que utilizas un sello.'],
3180=>['Destruir ilusiones (PvP)','Conjuro. Quitas un maleficio de hipnotizador al enemigo objetivo. Si lo haces, el enemigo recibe 15...75 de daño y todos los adyacentes sufren un 75 % de ese daño.','Conjuro. Quita un maleficio de hipnotizador del enemigo objetivo. Efecto de eliminación: hace 15...75 de daño al objetivo y un 75 % de ese daño a todos los enemigos adyacentes.'],
3181=>['Equipo de armamento irreal (PvP)','Conjuro con encantamiento de élite. Durante 30 segundos, tus ataques cuerpo a cuerpo no impactan ni fallan. En su lugar, el Armamento irreal hace 20...60 de daño a los objetivos con cada ataque cuerpo a cuerpo.','Conjuro con encantamiento de élite. (30 segundos). Hace 20...60 de daño a enemigos en lugar de otros daños o efectos de los ataques cuerpo a cuerpo. Tus ataques cuerpo a cuerpo no impactan ni fallan.'],
3183=>['Migraña (PvP)','Conjuro con maleficio de élite. Durante 4...16 segundos, el enemigo objetivo sufre una degeneración de salud de -1...8 y tardará un 100% más en activar sus habilidades.','Conjuro con maleficio de élite. (4...16 segundos). Causa -1...8 de degeneración de salud y dobla el tiempo de activación de habilidades.'],
3184=>['Dolor acumulado (PvP)','Conjuro. El enemigo objetivo recibe 10...35 de daño. Si estaba padeciendo 2 o más maleficios, sufrirá una herida grave durante 5...20 segundos.','Conjuro. Hace 10...35 de daño. Causa una herida grave (5...20 segundos) si el enemigo objetivo tiene 2 o más maleficios.'],
3185=>['Inestabilidad psíquica (PvP)','Conjuro de élite. Interrumpe la acción del enemigo objetivo. Si ésta es una habilidad, el enemigo objetivo y todos los adyacentes son derribados durante 2...3 segundos. (50% de posibilidades de fallar con lanzamiento de conjuros rápido 4 o inferior.)','Conjuro de élite. Interrumpe una acción. Efecto de interrupción: si la acción es una habilidad, causa el derribo del enemigo objetivo y todos los enemigos adyacentes durante 2...3 segundos. 50% de posibilidades de fallar a menos que tengas lanzamiento de conjuros rápido 5 o superior.'],
3186=>['Carga compartida (PvP)','Conjuro con maleficio de élite. Durante 5...20 segundos, el enemigo objetivo y todos los que estén en la zona atacarán, lanzarán conjuros y se moverán un 33 % más despacio.','Conjuro con maleficio de élite. También se aplica el maleficio a los enemigos en la zona de tu objetivo (5...20 segundos). Estos enemigos atacan, lanzan conjuros y se mueven un 33 % más despacio.'],
3187=>['Velocidad robada (PvP)','Conjuro con maleficio de élite. Durante 1...10 segundos, el enemigo objetivo y los adyacentes necesitarán 100% más de tiempo para lanzar conjuros. Los conjuros que dirijas a estos enemigos tardan 50% menos en lanzarse.','Conjuro con maleficio de élite. También afecta a los enemigos adyacentes (1...10 segundos). Dobla el tiempo de lanzamiento. Tus conjuros dirigidos sobre enemigos que tengan un maleficio tardan un -50% en lanzarse.'],
3188=>['Sello antinatural (PvP)','Sello. El enemigo objetivo recibe 10...60 de daño. Si el enemigo se encuentra bajo los efectos de un maleficio o un encantamiento, los enemigos adyacentes al objetivo reciben 10...60 de daño. Todas tus habilidades que no sean de Hipnotizador, excepto los sellos, quedan desactivadas durante 10 segundos.','Sello. Causa 10...60 de daño. Hace 10...60 de daño a otros enemigos adyacentes si el objetivo tiene un maleficio o un encantamiento. Tus habilidades que no sean de Hipnotizador, excepto los sellos, quedan desactivadas (10 segundos).'],
3189=>['Dolor espiritual (PvP)','Conjuro. El enemigo objetivo recibe 5...40 de daño. Todas las criaturas hostiles invocadas que se encuentren en la zona del enemigo reciben 25...125 de daño.','Conjuro. Causa 5...40 de daño. Hace 25...125 de daño a las criaturas hostiles invocadas que se encuentran en la zona del enemigo objetivo.'],
3190=>['Frustración (PvP)','Conjuro con maleficio. Durante 5...20 segundos, el enemigo objetivo lanza los conjuros un 50% más despacio y recibe 5...50 de daño cada vez que se le interrumpa.','Conjuro con maleficio. (5...20 segundos). Hace que los conjuros tarden un 50% más en lanzarse. El enemigo objetivo recibe 5...50 de daño cada vez que se le interrumpa.'],
3191=>['Recelo (PvP)','Conjuro con maleficio. Durante 6 segundos, el siguiente conjuro que el enemigo objetivo lance sobre uno de tus aliados falla y haces 10...60 de daño a este enemigo y un 75 % de ese daño a todos los enemigos adyacentes.','Conjuro con maleficio. (6 segundos). El siguiente conjuro que el enemigo objetivo lance sobre uno de tus aliados falla y haces 10...60 de daño a este enemigo y un 75 % de ese daño a todos los enemigos cercanos.'],
3192=>['Enigma del encantador (PvP)','Conjuro con maleficio de élite. Durante 10 segundos, el enemigo objetivo lanzará los encantamientos un 100...200 % más lento. Si el enemigo objetivo no está bajo los efectos de ningún encantamiento cuando este maleficio se active, el enemigo sufre 10...100 de daño y todos los enemigos adyacentes reciben un 75 % de ese daño.','Conjuro con maleficio de élite. Hace que los encantamientos tarden un 100...200 % más en lanzarse (10 segundos). Efecto inicial: causa 10...100 de daño al enemigo objetivo y un 75 % de ese daño a todos los enemigos adyacentes si el objetivo no tiene ningún encantamiento.'],
3193=>['Sello de torpeza (PvP)','Sello. Si el enemigo objetivo está atacando, interrumpirás su acción y la de los enemigos adyacentes a él, y recibirán 15...60 de daño. Todos los enemigos que estén utilizando habilidades de ataque son derribados.','Sello. Interrumpe un ataque del enemigo objetivo y los enemigos adyacentes a él. Efecto de interrupción: hace 15...60 de daño; derriba a los enemigos usando habilidades de ataque.'],
3194=>['Espejo del desencantamiento (PvP)','Conjuro. Eliminas un encantamiento del enemigo objetivo. Todos los miembros del grupo del enemigo objetivo también pierden ese encantamiento.','Conjuro. Elimina un encantamiento del enemigo objetivo. Los miembros del grupo del enemigo objetivo también pierden ese encantamiento.'],
3195=>['Ojo errante (PvP)','Conjuro con maleficio. Durante 4 segundos, la próxima vez que el enemigo objetivo ataque, le interrumpirás y todos los enemigos cercanos recibirán 10...92 de daño.','Conjuro con maleficio. (4 segundos). Interrumpe el próximo ataque del enemigo objetivo. Efecto de interrupción: 10...92 de daño a los enemigos cercanos.'],
3196=>['Riesgo calculado (PvP)','Conjuro con maleficio. Durante 3...12 segundos, los ataques del enemigo objetivo hacen +10 de daño, pero hay un 50% de posibilidades de que dicho enemigo reciba el daño realizado con cada ataque. (Máximo 15...60 de daño.)','Conjuro con maleficio. El enemigo objetivo hace +10 de daño con los ataques (3...12 segundos). Cada ataque tiene 50% de posibilidades de que el enemigo reciba el daño realizado con cada ataque (máximo 15...60).'],
3204=>['Desafiar al dolor (PvP)','Actitud de élite. Durante 20 segundos tienes 90...300 de salud adicional y 20 de armadura adicional.','Actitud de élite. (20 segundos). Tienes +90...300 de salud máxima y +20 de armadura.'],
3232=>['Curar grupo (PvP)','Conjuro. Curas 30...75 de salud a todo el grupo.','Conjuro. Cura 30...75 de salud a todo el grupo.'],
3233=>['Aguafiestas (PvP)','Conjuro con maleficio de élite. Durante 3...15 segundos, siempre que el enemigo objetivo ataque o lance un conjuro sobre una criatura con menos salud, perderá 15...75 de salud.','Conjuro con maleficio de élite. (3...15 segundos.) Hace perder 15...75 de salud cada vez que el enemigo objetivo ataca o lanza conjuros sobre una criatura con menos salud.'],
3234=>['Visiones de arrepentimiento (PvP)','Conjuro con maleficio de élite. Durante 10 segundos, el enemigo objetivo y los enemigos adyacentes reciben 10...30 de daño cada vez que utilicen una habilidad y 5...40 de daño adicional si no están bajo los efectos de ningún otro maleficio de Hipnotizador.','Conjuro con maleficio de élite. También afecta a los enemigos cercanos al objetivo (10 segundos). Estos enemigos reciben 10...30 de daño cada vez que utilicen una habilidad y 5...40 de daño adicional si no están bajo los efectos de ningún otro maleficio de Hipnotizador.'],
3251=>['Colmillos de zorro (PvP)','Ataque complementario. Debe seguir a un ataque inicial. Los Colmillos de Zorro no pueden bloquearse y hacen +10...25 de daño si aciertan.','Ataque complementario. Hace +10...25 de daño. No se puede bloquear. Debe seguir a un ataque inicial.'],
3252=>['Golpe salvaje (PvP)','Ataque complementario. Debe seguir a un ataque inicial. Si acierta, este ataque hace +10...35 de daño y anula cualquier actitud que esté usando el enemigo objetivo. Este ataque no puede bloquearse.','Ataque complementario. Hace +10...35 de daño. Elimina la actitud del enemigo objetivo. No se puede bloquear. Debe seguir a un ataque inicial.'],
3263=>['Golpe del destierro (PvP)','Ataque cuerpo a cuerpo. Si impacta, este ataque hace 10...60 de daño sagrado. Causa el doble de daño a las criaturas invocadas.','Ataque cuerpo a cuerpo. Hace 10...60 de daño sagrado. Causa el doble de daño a las criaturas invocadas.'],
3264=>['Barrido de la doble luna (PvP)','Ataque cuerpo a cuerpo. Pierdes un encantamiento de Derviche y ganas 10...20 de salud. Si se pierde un encantamiento de esta manera, tus ataques no se pueden bloquear, golpeas dos veces haciendo con cada golpe un 25% menos de daño de los normal y ganas 10...30 de salud adicional.','Ataque cuerpo a cuerpo. Elimina uno de tus encantamientos de Derviche. Ganas 10...20 de salud. Efecto de eliminación: no se puede bloquear, golpeas dos veces haciendo con cada golpe un 25% menos de daño de los normal y ganas 10...30 de salud adicional.'],
3265=>['Barrido irresistible (PvP)','Ataque con guadaña. Haces +3...15 de daño y pierdes un encantamiento de Derviche. Si pierdes un encantamiento de esta manera, Barrido irresistible no se puede bloquear y elimina una actitud.','Ataque con guadaña. Hace +3...15 de daño. Elimina uno de tus encantamientos de Derviche. Efecto de eliminación: no se puede bloquear, elimina una actitud.'],
3266=>['Asalto piadoso (PvP)','Ataque cuerpo a cuerpo. Quita un encantamiento de Derviche. Si se quitó un encantamiento de Derviche, esta habilidad se recarga un 75% más rápido y los enemigos adyacentes reciben 15...40 de daño.','Ataque cuerpo a cuerpo. Quita uno de tus encantamientos de Derviche. Efecto de eliminación: esta habilidad se recarga un 75% más rápido y los enemigos adyacentes reciben 15...40 de daño.'],
3269=>['Manos guiadoras (PvP)','Conjuro con encantamiento. Durante 20 segundos, tus próximos 0...3 ataques no se pueden bloquear. Cuando se activa, esta habilidad quita la ceguera.','Conjuro con encantamiento. (20 segundos). Tus próximos 0...3 ataques no se pueden bloquear. Efecto inicial: quita la ceguera.'],
3270=>['Avatar de Dwayna (PvP)','Transformación["Transformaciones"] de élite. Durante 10...90 segundos, tus ataques hacen daño sagrado. Cada vez que utilizas una habilidad de ataque de Derviche, pierdes un maleficio. Cada vez que pierdes un encantamiento de Derviche, te curas 5...50 de salud. La habilidad queda desactivada durante 45 segundos.','Transformación["Transformaciones"] de élite. (10...90 segundos.) Hace daño sagrado. Pierdes un maleficio cada vez que utilizas una habilidad de ataque de Derviche. Te curas un 5...50 de salud cada vez que pierdes un encantamiento de Derviche. La habilidad queda desactivada durante 45 segundos.'],
3271=>['Avatar de Melandru (PvP)','Transformación["Transformaciones"] de élite. Durante 10...90 segundos, tienes +100 de salud, +30 de armadura contra daño de los elementos y tus ataques infligen daño de tierra. Cada vez que pierdes un encantamiento de Derviche, pierdes dos condiciones. Esta habilidad está desactivada durante 45 segundos.','Transformación["Transformaciones"] de élite. (10...90 segundos). Tienes +100 de salud máxima, +30 de armadura contra daño de los elementos y tus ataques infligen daño de tierra. Curas dos de tus condiciones cada vez que pierdes un encantamiento de Derviche. Esta habilidad está desactivada durante 45 segundos.'],
3272=>['Regeneración mística (PvP)','Conjuro. Cura 5...65 de salud. También cura 5...65 de salud a todos tus compañeros encantados.','Conjuro. Te curas 5...65 de salud. Cura 5...65 de salud a todos tus compañeros encantados.'],
3273=>['Sello de retención piadosa (PvP)','Sello. Pierdes un encantamiento de Derviche y el enemigo objetivo queda lisiado durante 5...15 segundos. Si se quitó un encantamiento, esta habilidad se recarga un 50% más rápido.','Sello. (5...15 segundos.) Causa lisiadura en el enemigo objetivo y elimina uno de tus encantamientos de Derviche. Efecto de eliminación: se recarga un 50% más rápido.'],
3289=>['Sueños febriles (PvP)','Conjuro con maleficio de élite. Durante 5...15 segundos, siempre que el objetivo enemigo sufra una nueva condición, todos los enemigos de la zona también sufrirán la misma.','Conjuro con maleficio de élite. (5...15 segundos). Los enemigos de la zona también padecerán las nuevas condiciones que el enemigo objetivo adquiera.'],
3346=>['Aura de espinas (PvP)','Conjuro con encantamiento de destello. Todos los enemigos cercanos sufren hemorragia durante 5...15 segundos. Durante 30 segundos, este encantamiento no tiene ningún efecto. Cuando termina este encantamiento, todos los enemigos adyacentes quedan lisiados durante 3...8 segundos.','Conjuro con encantamiento de destello. (30 segundos). Efecto inicial: causa hemorragia (5...15 segundos) a los enemigos cercanos. Efecto final: causa lisiadura (3...8 segundos) a los enemigos cercanos.'],
3347=>['Manto polvoriento (PvP)','Conjuro con encantamiento de destello. Los enemigos cercanos reciben 10...40 de daño de tierra. Durante 30 segundos, tus ataques hacen daño de tierra. Cuando termina este encantamiento, todos los enemigos adyacentes quedan cegados durante 1...4 segundos.','Conjuro con encantamiento de destello. (30 segundos). Tus ataques hacen daño de tierra. Efecto inicial: hace 10...40 de daño de tierra a los enemigos cercanos. Efecto final: causa ceguera (1...4 segundos) a los enemigos cercanos.'],
3348=>['Premura de Lyssa (PvP)','Conjuro con encantamiento de destello. Durante 3...15 segundos, tus encantamientos de Derviche se recargarán un 33% más rápido. Cuando activas este encantamiento, interrumpes a todos los enemigos adyacentes. Cuando termina este encantamiento, interrumpes a todos los enemigos adyacentes. 50% de posibilidades de fallar a menos que tengas plegarias de viento 5 o superior.','Conjuro con encantamiento de destello. (3...15 segundos). Tus encantamientos de Derviche se recargan un 33% más rápido. Efecto inicial: interrumpe a todos los enemigos adyacentes. Efecto final: interrumpe a todos los enemigos adyacentes. (50% de posibilidades de fallar a menos que tengas plegarias de viento 5 o superior).'],
3365=>['Acometida (PvP)','Conjuro con encantamiento de destello de élite. Durante 2...8 segundos, atacas y acumulas adrenalina un 25% más rápido.','Conjuro con encantamiento de destello de élite. (2...8 segundos). Atacas y acumulas adrenalina un 25% más rápido.'],
3366=>['Corazón de furia (PvP)','Actitud. Durante 2...10 segundos, atacas un 25% más rápido.','Actitud. (2...10 segundos). Atacas un 25% más rápido.'],
3367=>['Golpe hiriente (PvP)','Ataque con guadaña de élite. Si este ataque impacta, el enemigo objetivo sufre hemorragia durante 5...20 segundos y pierdes un encantamiento de Derviche. Si se quitó un encantamiento, el enemigo objetivo también padecerá herida grave durante 5...20 segundos.','Ataque con guadaña de élite. Causa hemorragia (5...20 segundos). Quita un encantamiento de Derviche. Efecto de eliminación: causa una herida grave (5...20 segundos).'],
3368=>['Furia piadosa (PvP)','Actitud. Quita un encantamiento de Derviche. Durante 1...5 segundos, atacas un 25% más rápido. Si se quitó un encantamiento, esta actitud dura el doble de tiempo.','Actitud. (1...5 segundos)Atacas un 25% más rápido y pierdes uno de tus encantamientos de Derviche. Efecto de eliminación: esta actitud dura el doble de tiempo.'],
3373=>['Ilusión de velocidad (PvP)','Conjuro con encantamiento. Te mueves un 33% más rápido durante 5...11 segundos. Cuando termine la Ilusión de velocidad, estarás lisiado durante 3 segundos.','Conjuro con encantamiento. (5...11 segundos). Te mueves un 33% más rápido. Efecto final: quedas lisiado (3 segundos).'],
3374=>['Ilusión de dolor (PvP)','Conjuro con maleficio. Durante 8 segundos, el enemigo objetivo sufre -3...10 de degeneración de salud y recibe 3...10 de daño por segundo. Cuando la Ilusión de dolor termine o se reactive, el enemigo se cura 36...120 de salud.','Conjuro con maleficio. (8 segundos). Causa -3...10 de degeneración de salud y el enemigo objetivo recibe 3...10 de daño por segundo. Efecto final: el enemigo se cura 36...120 de salud. Termina si se reactiva.'],
3375=>['Aura de restauración (PvP)','Conjuro con encantamiento. Durante 60 segundos, ganas 0...1 de energía y te curas un 200...400% del coste de energía cada vez que lances un conjuro.','Conjuro con encantamiento. (60 segundos.) Ganas 0...1 de energía y te curas un 200...400% del coste de energía cada vez que lances un conjuro.'],
3386=>['Red interruptora (PvP)','Conjuro con maleficio. Interrumpe al enemigo objetivo. Durante 10 segundos, el enemigo sufre el maleficio de la Red interruptora. Cuando el maleficio termine, ese enemigo vuelve a ser interrumpido.','Conjuro con maleficio. (10 segundos.) Efecto inicial: interrumpe una habilidad. Efecto final: interrumpe una habilidad.'],
3396=>['Martillo de relámpago (PvP)','Conjuro. El enemigo objetivo recibe 10...100 de daño de relámpago. Martillo de relámpago tiene un 25% de penetración de armadura.','Conjuro. Causa 10...100 de daño de relámpago. 25% de penetración de armadura.'],
3397=>['Llama elemental (PvP)','Conjuro con encantamiento. Durante 5...20 segundos, siempre que apliques un maleficio elemental a un enemigo, arderá durante 1...2 segundos.','Conjuro con encantamiento. (5...20 segundos.) Causa quemadura (1...2 segundos) cuando se lanza un maleficio elemental al objetivo.'],
3398=>['Suelo resbaladizo (PvP)','Conjuro. Si el enemigo objetivo está cegado o moviéndose, es derribado. (50% de probabilidad de fallar con magia de agua de nivel 4 o inferior).','Conjuro. Si el enemigo está cegado o moviéndose, es derribado. 50% de probabilidad de fallar a menos que tengas magia de agua de nivel 5 o superior.'],
3422=>['Defensa de tiempo','Conjuro de protección de élite. Creas una Defensa de tiempo en tu ubicación actual. Durante 6...20 segundos, los aliados que no sean espíritus y que estén en el área lanzarán los hechizos un 15...20 % más rápido y recargarán las habilidades un 15...20 % más rápido. Habilidad de PvE','Conjuro de protección de élite. (6...20 segundos). Los aliados protegidos por esta defensa lanzan los hechizos un 15...20 % más rápido y recargan las habilidades un 15...20 % más rápido. No afecta a espíritus aliados. Habilidad de PvE'],
3423=>['Entrega del alma','Conjuro con encantamiento de élite. Durante 3...30 segundos, tus ataques sacrificarán 15...20 de salud e infligirán 15...20 más de daño. Habilidad de PvE','Conjuro con encantamiento de élite. (3...30 segundos). Los ataques infligen +15...20 de daño y sacrifican 15...20 de salud. Habilidad de PvE'],
3424=>['Más allá del límite','Conjuro con encantamiento de élite. Mientras mantengas este encantamiento, lanzarás tus hechizos un 20...50 % más rápido y los recargarás un 40...80 % más rápido, pero sufrirás agotamiento de forma constante. Habilidad de PvE','Conjuro con encantamiento de élite. Los hechizos se lanzan un 20...50 % más rápido y se recargan un 40...80 % más rápido. Sufrirás agotamiento de forma constante mientras permanezca activo. Habilidad de PvE'],
3425=>['Golpe del juicio','Ataque cuerpo a cuerpo de élite. Atacas al objetivo y a los enemigos adyacentes. Cada ataque que impacte infligirá +13...30 de daño sagrado y derribará a los enemigos que ataquen. Habilidad de PvE','Ataque cuerpo a cuerpo de élite. Atacas al objetivo y a los enemigos adyacentes e infliges +13...30 de daño sagrado. Derribas a los enemigos que ataquen. Habilidad de PvE'],
3426=>['Postura de las siete armas','Actitud de élite. Durante 3...20 segundos, los atributos de tus armas aumentarán en 1...15 y atacarás 33 % más rápido. Habilidad de PvE','Actitud de élite. (3...20 segundos). Los atributos de las armas aumentan en 1...15. Atacas 33 % más rápido. Habilidad de PvE'],
3427=>['"¡Todos a una!"','Grito de élite. Durante 3...15 segundoss, todos los miembros de tu grupo que estén cerca de ti o de tu mascota infligirán +5...15 de daño adicional al atacar y obtendrán +1...7 de regeneración de salud. Habilidad de PvE','Grito de élite. Durante 3...15 segundoss, todos los miembros de tu grupo que estén cerca de ti o de tu mascota infligirán +5...15 de daño adicional al atacar y obtendrán +1...7 de regeneración de salud. Habilidad de PvE'],
3428=>['Robo sombrío','Habilidad de élite. Das un paso sombrío hasta el enemigo objetivo. Durante 5...20 segundos, los atributos de ese enemigo se reducirán en 1...5 y los tuyos aumentarán en 1...5. Esta habilidad cuenta como ataque inicial. Habilidad de PvE','Habilidad de élite. Das un paso sombrío hasta el enemigo objetivo. Durante 5...20 segundos, los atributos de ese enemigo se reducirán en 1...5 y los tuyos aumentarán en 1...5. Cuenta como ataque inicial. Habilidad de PvE'],
3429=>['Armas de las tres forjas','Conjuro con arma de élite. Durante 3...20 segundos, todos los aliados que no sean espíritus y puedan oírte ganarán el efecto de un hechizo de arma al azar. Habilidad de PvE','Conjuro con arma de élite. (3...20 segundos). Los aliados que puedan oírte ganan el efecto de un hechizo de arma al azar. No afecta a espíritus aliados. Habilidad de PvE'],
3430=>['Voto de la revolución','Conjuro con encantamiento de élite. Durante 3...10 segundos ganarás +1...6 de regeneración de energía. Esta habilidad se volverá a aplicar sola cada vez que uses una habilidad que no sea de derviche. Habilidad de PvE','Conjuro con encantamiento de élite. (3...10 segundos). Ganas +1...6 de regeneración de energía. Renovación: cada vez que usas una habilidad que no sea de derviche. Habilidad de PvE'],
3431=>['Estribillo heroico','Eco de élite. Durante 3...15 segundos, el aliado objetivo que no sea un espíritu ganará +1...3 en todos los atributos. Este eco volverá a aplicarse cada vez que termine un cántico o un grito que afecte a ese aliado. Habilidad de PvE','Eco de élite. (3...15 segundos). El aliado objetivo gana +1...3 a todos los atributos. Renovación: cada vez que termina un cántico o un grito que afecta a este aliado. No afecta a espíritus aliados. Habilidad de PvE'],
3437=>['Guadaña de granjero (PvP)','Ataque con guadaña. Si impacta, este ataque hará +5...35 de daño. Si alcanzas a más de un enemigo, se recargará de forma instantánea.','Ataque con guadaña. Hace +5...35 de daño. Se recarga al instante si alcanzas a más de un enemigo.'],
3442=>['Lanzamiento poderoso (PvP)','Ataque con lanza. Tu lanza vuela tres veces más rápido. Si impacta, hará +10...40 de daño.','Ataque con lanza. Hace +10...40 de daño. Esta lanza vuela tres veces más rápido.'],
3443=>['Frenesí','Actitud. Durante 8 segundos, atacas un 33 % más rápido, pero recibes 200...150 % de daño.','Actitud. (8 segundos). Atacas un 33 % más rápido. Recibes 200...150 % de daño.'],
3444=>['Cien espadas','Habilidad de élite. Durante 15 segundos, siempre que ataques con una espada, todos los enemigos adyacentes reciben 10...30 de daño perforante.','Habilidad de élite. (15 segundos.) Hace 10...30 de daño cortante a todos los enemigos que se encuentren a tu alrededor al atacar con una espada.'],
3445=>['Renovación de la naturaleza','Ritual de la naturaleza. Create a level 1...10 spirit. For 30...240 seconds, enchantments and hexes cast by non-spirit creatures take 50...75% longer to cast, and it costs twice as much Energy to maintain enchantments. This spirit dies after 30...240 seconds.','Ritual de la naturaleza. Creates a level 1...10 spirit (30...240 second lifespan). For creatures in range, enchantments and Hexes take 50...75% longer to cast and it costs twice as much Energy to maintain enchantments. Does not affect spirits.'],
3446=>['Soul Ignition','Conjuro con encantamiento. While you maintain this enchantment, reduce Overcast at a rate of 1...2 per second. You and all adjacent foes are afflicted with burning while this enchantment is active.','Conjuro con encantamiento. Reduce Overcast by 1...2 per second. You and all adjacent foes are afflicted with burning.'],
3447=>['Preocupación del gandul','Conjuro con maleficio. Después de 3 segundos, el enemigo objetivo recibe 20...100 de daño y todos los adyacentes sufren un 75 % de ese daño. Si ese enemigo utiliza una habilidad con éxito, la Preocupación del gandul finalizará prematuramente y no hará ningún daño.','Conjuro con maleficio. (3 segundos). Efecto final: hace 20...100 de daño al enemigo objetivo y un 75 % de ese daño a los enemigos adyacentes. No tiene ningún efecto y termina antes de lo previsto si el enemigo objetivo utiliza una habilidad.'],
3448=>['Paz y armonía','Conjuro con encantamiento de élite. El aliado objetivo pierde 0...4 condición["condiciones"] y maleficios. Durante 1...3 segundos, las condiciones y maleficios que ese aliado tenga acaban un 90% antes. Todas tus plegarias de ataque quedan desactivadas durante 20 segundos.','Conjuro con encantamiento de élite. El aliado objetivo pierde 0...4 condición["condiciones"] y maleficios. Las condiciones y maleficios que ese aliado tenga acaban un 90% antes (1...3 segundos). Se desactivan tus plegarias de ataque (20 segundos).'],
3449=>['Golpe del protector','Ataque cuerpo a cuerpo. Si este ataque golpea a un enemigo en movimiento, le harás 10...40 de daño adicional.','Ataque cuerpo a cuerpo. Hace +10...40 de daño si el objetivo se está moviendo.'],
3450=>['Disparo lesionador','Ataque con arco de élite. Si el Disparo lesionador impacta, tu objetivo quedará lisiado durante 4...14 segundos. Este ataque no puede bloquearse.','Ataque con arco de élite. No se puede bloquear. Causa lisiadura (4...14 segundos).'],
3451=>['Grito de Otyugh','Grito. Durante 5...15 segundos, tu compañero animal gana +24 de armadura y no se le puede bloquear.','Grito. (5...15 segundos). Tu mascota tiene +24 de armadura y no la pueden bloquear.'],
3452=>['Mortaja sombría','Conjuro con maleficio de élite. Durante 2...7 segundos, al enemigo objetivo no le podrán echar encantamientos.','Conjuro con maleficio de élite. (2...7 segundos). Al enemigo objetivo no le podrán echar encantamientos.'],
3453=>['Brío','Actitud. Durante 3 segundos, corres un 50 % más rápido. Cada 2 puntos de artes sombrías se reduce la carga en 1 segundos (6 segundos máx.).','Actitud. (3 segundos). Te mueves un 50 % más rápido. Cada 2 puntos de artes sombrías reduce la carga en 1 segundos (6 segundos máx.).'],
3454=>['Guardián de acero','Conjuro con encantamiento. Durante 1...4 segundos, todos los miembros del equipo al alcance del oído tendrán un 75% de posibilidades de bloquear ataques. Si se bloquea un ataque, todos los aliados al alcance del oído se curarán 10...35 de salud y el Guardián de acero terminará.','Conjuro con encantamiento. (1...4 segundos). Los miembros del equipo al alcance del oído tienen un 75% de posibilidades de bloquear ataques. Efecto al bloquear: Los aliados al alcance del oído se curarán 10...35 de salud y el Guardián de acero terminará.'],
3455=>['Golpe auspiciante','Ataque con martillo. Si el Golpe auspiciante impacta, haces +5...20 de daño y ganas 2...4 de energía. Si el enemigo objetivo está sufriendo debilitamiento, este ataque no se puede bloquear.','Ataque con martillo. Hace +5...20 de daño y ganas adrenalina y 2...4 de energía. No se puede bloquear si el enemigo objetivo está debilitado.'],
3456=>['"¡Cobarde!"','Grito de élite. Si el enemigo objetivo se está moviendo, es derribado.','Grito de élite. Causa derribo si el enemigo objetivo está en movimiento.'],
3457=>['Defensa del protector','Habilidad. Durante 4...8 segundos, los aliados adyacentes tienen un 75% de probabilidades de bloquear ataques. La Defensa del protector acaba cuando te muevas.','Habilidad. (4...8 segundos). Los aliados adyacentes tienen un 75% de probabilidades de bloquear. Acaba si te mueves.'],
3458=>['Furia primitiva','Actitud de élite. Durante 1...9 segundos, atacas un 33 % más rápido y te mueves un 33 % más rápido, pero recibes 200...150 % de daño.','Actitud de élite. (1...9 segundos). Atacas un 33 % más rápido y te mueves un 33 % más rápido, pero recibes 200...150 % de daño. Recibes 200...150 % de daño.'],
3459=>['Disparo de Melandru','Ataque con arco de élite. Si el Disparo de Melandru impacta, tu objetivo sufrirá una hemorragia durante 5...25 segundos. Si impacta en un enemigo que se está moviendo o ha sido derribado, le harás +10...25 de daño y quedará lisiado durante 5...15 segundos.','Ataque con arco de élite. Causa hemorragia (5...25 segundos). Hace +10...25 de daño y causa lisiadura (5...15 segundos) si el enemigo objetivo estaba moviéndose o había sido derribado.'],
3460=>['Tranquilidad','Ritual de la naturaleza. Creas un espíritu de nivel 1...10. Los encantamientos lanzados por criaturas no espíritus dentro de su radio se acaban un 10...30% más rápido. Morirá a los 15...120 segundos.','Ritual de la naturaleza. Crea un espíritu de nivel 1...10 (15...120 segundos de vida). Los encantamientos que tengan las criaturas de la zona acaban un 10...30% antes. No afecta a los espíritus.'],
3461=>['Almas unidas','Habilidad de élite. Durante 5...45 segundos, tus rituales de encadenamiento cuestan 15 menos de energía (mínimo 5) y se recargan un 25...50 % más rápido. Almas unidas acaba después de 1...3 rituales de encadenamiento.','Habilidad de élite. (5...45 segundos). Tus rituales de encadenamiento cuestan 15 menos de energía (mínimo 5) y se recargan un 25...50 % más rápido. Acaba después de 1...3 rituales de encadenamiento.'],
3462=>['Arma dirigida','Conjuro con arma. Durante 4...10 segundos, los ataques de objetivo (un aliado o tú mismo) no pueden bloquearse.','Conjuro con arma. (4...10 segundos). Los ataques no se pueden bloquear.'],
3463=>['Bromista','Conjuro de élite. Si el enemigo objetivo está utilizando una habilidad, ese enemigo y los de la zona serán interrumpidos y tú robarás 0...5 de energía de todos ellos.','Conjuro de élite. Interrumpe una habilidad. Efecto de interrupción: también interrumpe a otros enemigos de la zona y robas 0...5 de energía a todos ellos.'],
3464=>['Flagelo','Actitud. Durante 1...15 segundos, atacas un 33 % más rápido pero te mueves un 33 % más despacio. Acaba si usas una habilidad de ataque a distancia.','Actitud. (1...15 segundos). Atacas un 33 % más rápido. Acaba si usas una habilidad de ataque a distancia. Te mueves un 33 % más despacio.'],
3465=>['Ataque en embestida','Actitud de élite. Durante 1...10 segundos, corres un 33% más deprisa. Tu siguiente ataque cuerpo a cuerpo hará +10...80 de daño y esta actitud terminará. También acabará si usas alguna habilidad.','Actitud de élite. (1...10 segundos). Te mueves un 33% más deprisa y haces +10...80 de daño con tu próximo golpe cuerpo a cuerpo. Acaba si golpeas o usas una habilidad.'],
3466=>['Calor indignante','Ritual de la naturaleza de élite. Create a level 1...10 spirit. Non-spirit creatures within its range gain adrenaline 33...66% as fast. This spirit dies after 30...120 seconds.','Ritual de la naturaleza de élite. Creates a level 1...10 spirit (30...120 second lifespan). Adrenaline gain increased by 33...66% for creatures in range.'],
3467=>['Corrupción mística','Conjuro con encantamiento de destello. Todos los enemigos adyacentes sufren enfermedad durante 2...6 segundos. Durante 20 segundos, no ocurre nada. La duración de la enfermedad se dobla si estás encantado cuando activas esta habilidad. Cuando termina este encantamiento, todos los miembros del grupo que estén al alcance del oído se curan de la enfermedad.','Conjuro con encantamiento de destello. (20 segundos). Efecto inicial: todos los enemigos cercanos sufren enfermedad (2...6 segundos). Si ya estás encantado, la duración se dobla. Efecto final: los miembros del grupo al alcance del oído pierden la enfermedad.'],
3468=>['Garra del hostigador','Conjuro con encantamiento de destello. Durante 5...20 segundos, los ataques cuerpo a cuerpo contra los enemigos en movimiento también los dejarán lisiados durante 2...9 segundos. Cuando lanzas este encantamiento, pierdes la lisiadura y otra condición más. Este encantamiento termina después de causar lisiadura 1...3 veces.','Conjuro con encantamiento de destello. (5...20 segundos). Los ataques cuerpo a cuerpo a los enemigos en movimiento los dejan lisiados. Efecto inicial: pierdes la lisiadura y otra condición más. Termina después de causar lisiadura 1...3 veces.'],
3469=>['Manto milagroso','Conjuro con encantamiento de destello. Durante 1...7 segundos, tienes un 30...60% de probabilidad de bloquear ataques. Cuando lanzas este encantamiento, todos los enemigos cercanos reciben 10...40 de daño de tierra.','Conjuro con encantamiento de destello. (1...7 segundos). Tienes un 30...60% de probabilidad de bloquear. Efecto inicial: hace 10...40 de daño de tierra a los enemigos cercanos.'],
3470=>['Estabilidad pasajera','Conjuro con encantamiento de destello. Durante 2...8 segundos, no te pueden derribar y te mueves un 25% más deprisa. Este encantamiento termina prematuramente si evita un derribo.','Conjuro con encantamiento de destello. (2...8 segundos). No te pueden derribar y te mueves un 25% más deprisa. Termina si evita un derribo.'],
3471=>['Restauración piadosa','Conjuro. Ganas 80...150 de salud y pierdes 1 encantamiento de Derviche. Si se elimina un encantamiento de este modo, también pierdes 1 maleficios.','Conjuro. Ganas 80...150 de salud y pierdes 1 encantamiento de Derviche. Efecto de eliminación: pierdes 1 maleficios.'],
3472=>['Torbellino de asalto','Conjuro con encantamiento de destello. Durante 1...6 segundos, te mueves un 33% más rápido de lo normal. La próxima vez que golpees a un enemigo, todos los demás enemigos cercanos recibirán 10...50 de daño frío y este encantamiento terminará.','Conjuro con encantamiento de destello. (1...6 segundos). Te mueves un 33% más rápido. Harás 10...50 de daño frío al resto de enemigos cercanos la próxima vez que golpees a un enemigo y este encantamiento terminará.'],
3473=>['Rebanador de auras','Ataque cuerpo a cuerpo. Si este ataque impacta, causarás hemorragia durante 5...15 segundos. Si estás encantado, también causas armadura rota durante 1...10 segundos.','Ataque cuerpo a cuerpo. Causa hemorragia (5...15 segundos). También causa armadura rota (1...10 segundos) si estás encantado.'],
];}
